local config = {
  str_homestory_800601001_0_dialog_content = "Carleen…",
  str_homestory_800601001_1_dialog_content = "Halo, PlayerName.",
  str_homestory_800601001_2_dialog_content = "Kau sedang apa, Carleen?",
  str_homestory_800601001_3_dialog_content = "Aku sedang bergumam sendiri.",
  str_homestory_800601001_4_dialog_content = "Maksudmu, \"berdoa\"?",
  str_homestory_800601001_5_dialog_content = "...",
  str_homestory_800601001_6_dialog_content = "Iya. Tolong jangan mengejekku.",
  str_homestory_800601001_7_dialog_content = "Lho, kenapa aku harus mengejekmu? Berdoa kan hal yang wajar.",
  str_homestory_800601001_8_dialog_content = "Anak-anak yang tak bisa menggunakan pedang berdoa agar orang dewasa melindungi mereka.",
  str_homestory_800601001_9_dialog_content = "Pasien yang sekarat berdoa agar punya tubuh yang sehat.",
  str_homestory_800601001_10_dialog_content = "Tapi, kalau orangnya mampu, kenapa harus bergantung pada \"doa\"?",
  str_homestory_800601001_11_dialog_content = "(Setuju)",
  str_homestory_800601001_12_dialog_content = "Meskipun kedengarannya kasar, tapi omonganmu ada benarnya, sih...",
  str_homestory_800601001_13_dialog_content = "Kalau orang bisa menentukan sendiri takdirnya, dia tak perlu bergantung pada siapa pun.",
  str_homestory_800601001_14_dialog_content = "Tapi, ada begitu banyak hal di dunia ini yang di luar kendali kita. Rupanya kau memahami perkataanku, PlayerName.",
  str_homestory_800601001_15_dialog_content = "Takdir.",
  str_homestory_800601001_16_dialog_content = "Kita beranggapan bahwa \"takdir\" tak bisa diubah. Ini membuat kita merasa lebih baik.",
  str_homestory_800601001_17_dialog_content = "Tapi, bagiku, takdir bisa diubah.",
  str_homestory_800601001_18_dialog_content = "(Tidak setuju)",
  str_homestory_800601001_19_dialog_content = "Bukankah berdoa kepada God of Light adalah hal yang lumrah di Lumopolis?",
  str_homestory_800601001_20_dialog_content = "Kupikir semua orang melakukannya, termasuk kau.",
  str_homestory_800601001_21_dialog_content = "Ya, kami memang sering mencurahkan hati dan memohon kepada God of Light.",
  str_homestory_800601001_22_dialog_content = "Tapi, bagiku, itu hanya cara mencari kenyamanan dan ketenteraman spiritual.",
  str_homestory_800601001_23_dialog_content = "Setelah berdoa, kesulitan di hadapanku pun tak kunjung hilang, menunggu untuk diselesaikan. Ini tak pernah berubah.",
  str_homestory_800601001_24_dialog_content = "...",
  str_homestory_800601001_25_dialog_content = "Hmm... Kalau dipikir-pikir, aku merasa cukup beruntung.",
  str_homestory_800601001_26_dialog_content = "Beruntung? Kenapa begitu?",
  str_homestory_800601001_27_dialog_content = "Karena aku tidak menghadapi musuh seorang diri.",
  str_homestory_800601001_28_dialog_content = "Aku sangat bersyukur karena punya banyak teman.",
  str_homestory_800601001_29_dialog_content = "Setuju sekali! Kita beruntung karena saling memiliki dalam perjalanan ini.",
  str_homestory_800601001_30_dialog_content = "Benar.",
  str_homestory_800601001_31_dialog_content = "Hari ini, kau terlihat agak sentimental, ya?",
  str_homestory_800601001_32_dialog_content = "Kurasa gara-gara tempat ini... Cocok untuk merenung.",
  str_homestory_800601001_33_dialog_content = "Tak ada perang. Tak ada pangeran dan bangsawan payah. Semuanya sangat damai dan tenang.",
  str_homestory_800601001_34_dialog_content = "Kalau begitu, aku pergi dulu. Selamat menikmati kesunyian ini.",
  str_homestory_800601001_35_dialog_content = "Terima kasih, PlayerName.",
  str_homestory_800601001_36_dialog_content = "Sama-sama, Carleen.",
  str_homestory_800201001_0_dialog_content = "Salam, Commander Hiiro.",
  str_homestory_800201001_1_dialog_content = "Kenapa kau kemari?",
  str_homestory_800201001_2_dialog_content = "Kau juga mau berdoa?",
  str_homestory_800201001_3_dialog_content = "Ah, ya.",
  str_homestory_800201001_4_dialog_content = "Karena melihatmu di sini, aku datang untuk menyapa.",
  str_homestory_800201001_5_dialog_content = "Bagus.",
  str_homestory_800201001_6_dialog_content = "Kau sedang... meditasi?",
  str_homestory_800201001_7_dialog_content = "Aku sedang berdoa.<sprite=emo_mojing size=60 />",
  str_homestory_800201001_8_dialog_content = "…!",
  str_homestory_800201001_9_dialog_content = "Sepertinya kau terkejut.",
  str_homestory_800201001_10_option_content = "Akui",
  str_homestory_800201001_11_dialog_content = "Aku... aku tak mengira kau bakal berdoa.",
  str_homestory_800201001_12_option_content = "Bantah",
  str_homestory_800201001_13_dialog_content = "Aku cenderung syok ketimbang terkejut...",
  str_homestory_800201001_14_dialog_content = "Kau kan sangat kuat... Tak kusangka kau melakukan hal remeh-temeh begini.",
  str_homestory_800201001_15_dialog_content = "Kuanggap itu pujian.",
  str_homestory_800201001_16_dialog_content = "Aku berdoa kepada diriku sendiri, bukan kepada dewa mana pun.",
  str_homestory_800201001_17_dialog_content = "Berdoa kepada diri sendiri?",
  str_homestory_800201001_18_dialog_content = "Aku agak bingung...",
  str_homestory_800201001_19_dialog_content = "Kudengar banyak orang kemari untuk berdoa.",
  str_homestory_800201001_20_dialog_content = "Kurasa, dengan berdoa, kita jadi lebih tahu apa yang sebenarnya diinginkan hati kita.",
  str_homestory_800201001_21_dialog_content = "Dengan kata lain, berdoa di sini bisa membantu kita mencari tahu hasrat kita.",
  str_homestory_800201001_22_dialog_content = "Ah... Aku paham.",
  str_homestory_800201001_23_dialog_content = "Seperti mencari \"misi yang benar-benar ingin kita selesaikan\"?",
  str_homestory_800201001_24_dialog_content = "Benar sekali.",
  str_homestory_800201001_25_dialog_content = "Nah... Apa sekarang kau sudah menemukannya?",
  str_homestory_800201001_26_dialog_content = "Sudah.",
  str_homestory_800201001_27_dialog_content = "Tak seperti dugaanku, \"doa\" tak lantas membuatnya lebih jelas... Tapi, aku menemukan jalanku.",
  str_homestory_800201001_28_dialog_content = "Memangnya dulu kau tak tahu jalan mana yang harus kautempuh?",
  str_homestory_800201001_29_dialog_content = "Aku selalu tahu jalan mana yang harus kutempuh.",
  str_homestory_800201001_30_dialog_content = "Tapi, aku tak yakin jalan mana yang ingin ditempuh atau diharapkan oleh hatiku.",
  str_homestory_800201001_31_dialog_content = "Sekarang aku paham betul kenapa orang-orang sangat tekun berdoa.",
  str_homestory_800201001_32_dialog_content = "Ya...",
  str_homestory_800201001_33_dialog_content = "Untuk orang kuat seperti dirimu, Commander Hiiro, berdoa bisa membantumu untuk memahami hal-hal yang sebenarnya hatimu inginkan...",
  str_homestory_800201001_34_dialog_content = "Bagi orang yang kesulitan mencari nafkah, doa adalah nafkah spiritual mereka.",
  str_homestory_800201001_35_dialog_content = "Jadi, itu sebabnya Fountain of Hope sangat penting.",
  str_homestory_800201001_36_dialog_content = "Kau dan Vice sudah bekerja keras untuk tempat ini.",
  str_homestory_800201001_37_dialog_content = "(Percakapan ini tiba-tiba berubah menjadi nasihat kepada bawahan...)",
  str_homestory_800201001_38_dialog_content = "Aku tak mau membuang-buang waktumu yang berharga lagi. Silakan berdoa, PlayerName.",
  str_homestory_800201001_39_dialog_content = "Dah.",
  str_homestory_800201001_40_dialog_content = "Ah... Baiklah, Commander Hiiro.",
  str_homestory_802501001_0_dialog_content = "Dia membaca puisi?",
  str_homestory_802501001_1_dialog_content = "Lumayan juga...",
  str_homestory_802501001_2_dialog_content = "Lumayan juga?",
  str_homestory_802501001_3_dialog_content = "Hmm. Harus kuakui...",
  str_homestory_802501001_4_dialog_content = "Lumayan juga! Panggung ini sama sekali tidak buruk!<sprite=emo_yinfu size=60 />",
  str_homestory_802501001_5_dialog_content = "Panggung?",
  str_homestory_802501001_6_dialog_content = "Hei, PlayerName. Kebetulan.",
  str_homestory_802501001_7_dialog_content = "Lihat! Alun-alun kecil di luar Hyacinth Tower itu...",
  str_homestory_802501001_8_dialog_content = "Bukankah itu cocok untuk drama panggung yang menggetarkan hati?",
  str_homestory_802501001_9_dialog_content = "PlayerName, jangan sia-siakan cahaya dan ruang ini.",
  str_homestory_802501001_10_dialog_content = "Tolong beri aku kesempatan untuk mengadakan pertunjukan legendaris di sini!",
  str_homestory_802501001_11_option_content = "Setuju",
  str_homestory_802501001_12_dialog_content = "Baiklah... Tapi, jangan sampai terlalu gaduh, ya...",
  str_homestory_802501001_13_dialog_content = "Tidak mungkin!",
  str_homestory_802501001_14_dialog_content = "Kereta api! Api! Cangkir bernoda darah! Musik heavy metal! Dan speaker!",
  str_homestory_802501001_15_dialog_content = "Akan kupastikan penampilanku menjangkau setiap sudut pulau ini!",
  str_homestory_802501001_16_dialog_content = "... Apa ini tak akan mengganggu warga?",
  str_homestory_802501001_17_dialog_content = "Mengganggu warga? Memangnya mereka tak tahu cara mengapresiasi seni?",
  str_homestory_802501001_18_dialog_content = "Ah-ha-ha! Bukan begitu masalahnya!",
  str_homestory_802501001_19_dialog_content = "Karya indie sering kali hanya diapresiasi oleh segelintir orang yang punya minat khusus!",
  str_homestory_802501001_20_dialog_content = "Tapi, aku yakin pertunjukanmu akan lebih bagus kalau diadakan pada malam hari.",
  str_homestory_802501001_21_dialog_content = "Dengar, Charon...",
  str_homestory_802501001_22_option_content = "Tolak",
  str_homestory_802501001_23_dialog_content = "Apa yang harus kulakukan?",
  str_homestory_802501001_24_dialog_content = "Penolakanmu yang dingin baru saja memberiku ide baru!",
  str_homestory_802501001_25_dialog_content = "Ide-ide yang saling terjalin berteriak dan merobek sanubariku layaknya kuda liar!",
  str_homestory_802501001_26_dialog_content = "Suara apa itu yang menggeram? Seni! Suatu pertunjukan di luar kendali...",
  str_homestory_802501001_27_dialog_content = "Nah, sekaranglah saatnya! Biarkan pertunjukan ini menggema di seluruh Eraveil!",
  str_homestory_802501001_28_dialog_content = "(Sepertinya penolakanku gagal total...)",
  str_homestory_802501001_29_dialog_content = "Bagaimana kalau lain kali saja?",
  str_homestory_802501001_30_dialog_content = "... Lain kali?",
  str_homestory_802501001_31_dialog_content = "Ah... Tiba-tiba hatiku dipenuhi kesedihan.",
  str_homestory_802501001_32_dialog_content = "PlayerName, kau sudah belajar mengabaikan orang lain.",
  str_homestory_802501001_33_dialog_content = "Baiklah, aku akan memberimu \"peran yang dingin dan terpisah\" dalam pertunjukanku.",
  str_homestory_802501001_34_dialog_content = "...",
  str_homestory_810501001_0_dialog_content = "Kau sibuk sekali, Eve!",
  str_homestory_810501001_1_dialog_content = "Senang bertemu denganmu, Navigator!<sprite=emo_aixin size=60 />",
  str_homestory_810501001_2_dialog_content = "Sebentar, ya. Sekarang, aku harus memikirkan apa lagi yang kuperlukan...",
  str_homestory_810501001_3_dialog_content = "Ah... Jangan khawatir!",
  str_homestory_810501001_4_dialog_content = "Kalau kau mencari sesuatu, mungkin aku bisa membantu.",
  str_homestory_810501001_5_dialog_content = "Wah... Kau benar-benar menyiapkan segalanya untuk kami!",
  str_homestory_810501001_6_dialog_content = "Aku ingin membuat hadiah.",
  str_homestory_810501001_7_dialog_content = "Tadinya aku sedang memikirkan warna apa yang lebih cocok untuk sulaman bunga atau tempat cangkir.",
  str_homestory_810501001_8_dialog_content = "Sulaman bunga? Tempat cangkir?",
  str_homestory_810501001_9_dialog_content = "Iya.",
  str_homestory_810501001_10_dialog_content = "Aku membuat baju atasan untuk Dawn<sprite=emo_qunzi size=60 />. Aku ingin menambahkan beberapa dawn flower di baju itu...",
  str_homestory_810501001_11_dialog_content = "Hmm... Tempat cangkir... Kau tahu kakakku selalu membawakanku sebotol air...",
  str_homestory_810501001_12_dialog_content = "Tempat cangkir yang manis bakal jadi hadiah yang cocok untuknya.",
  str_homestory_810501001_13_dialog_content = "Heheh. Navigator, bagaimana menurutmu?",
  str_homestory_810501001_14_dialog_content = "Luar biasa!",
  str_homestory_810501001_15_dialog_content = "Hadiah-hadiahmu sangat penuh perhatian. Dawn dan kakakmu pasti akan sangat senang.",
  str_homestory_810501001_16_dialog_content = "Iya! Senang mendengarnya...",
  str_homestory_810501001_17_dialog_content = "Jadi... Sebaiknya warna apa yang kupilih?",
  str_homestory_810501001_18_dialog_content = "Biasanya, dawn flower kan berwarna putih, tapi mungkin bagus juga kalau menggunakan warna lain...",
  str_homestory_810501001_19_dialog_content = "Untuk tempat cangkirnya, aku bingung lebih cocok warna merah atau hitam. Kakakmu lebih suka warna apa?",
  str_homestory_810501001_20_dialog_content = "Ahh... Keputusan yang sulit.",
  str_homestory_810501001_21_dialog_content = "Hmm…",
  str_homestory_810501001_22_dialog_content = "Memangnya apa warna baju atasan yang kaubuat untuk Dawn?",
  str_homestory_810501001_23_dialog_content = "Hitam!",
  str_homestory_810501001_24_dialog_content = "Kurasa dawn flower warna putih akan sangat cocok pada baju hitam.",
  str_homestory_810501001_25_dialog_content = "Nah, coba kaubuat pola timbul di atas kainnya agar Dawn bisa merasakan dawn flower itu dengan tangannya.",
  str_homestory_810501001_26_dialog_content = "Dawn flower warna putih dengan pola timbul...",
  str_homestory_810501001_27_dialog_content = "Wah... Idemu sangat bagus!",
  str_homestory_810501001_28_dialog_content = "Aku senang bisa membantu.",
  str_homestory_810501001_29_dialog_content = "Bagaimana dengan tempat cangkir untuk kakakku? Navigator, kau punya ide, tidak?",
  str_homestory_810501001_30_option_content = "Ya",
  str_homestory_810501001_31_dialog_content = "Kalau bingung soal warnanya, bagaimana kalau kaubuat pola kotak-kotak hitam dan merah?",
  str_homestory_810501001_32_dialog_content = "Tapi, Eve...",
  str_homestory_810501001_33_option_content = "Tidak juga",
  str_homestory_810501001_34_dialog_content = "Sebenarnya, Eve...",
  str_homestory_810501001_35_dialog_content = "Sinsa bakal senang mendapat hadiah darimu, apa pun itu.",
  str_homestory_810501001_36_dialog_content = "Kalau hadiahmu hanya berupa sebarang daun atau segenggam pasir sekalipun, dia pasti bakal memamerkannya seperti harta karun paling langka.",
  str_homestory_810501001_37_dialog_content = "Hmm…",
  str_homestory_810501001_38_dialog_content = "Ya, aku setuju denganmu...",
  str_homestory_810501001_39_dialog_content = "Kalau begitu, aku akan memilih warna kesukaanku. Heheh.",
  str_homestory_810501001_40_dialog_content = "Hmm... Boleh juga.",
  str_homestory_810501001_41_dialog_content = "Eve... Kau berusaha keras membuat hadiah untuk Dawn dan Sinsa. Kalau untukmu sendiri bagaimana?",
  str_homestory_810501001_42_dialog_content = "Hmm? Maaf, Navigator. Aku tak paham...",
  str_homestory_810501001_43_dialog_content = "Apa yang harus kusiapkan untuk diriku sendiri?",
  str_homestory_810501001_44_dialog_content = "Ah... Maksudku...",
  str_homestory_810501001_45_dialog_content = "Begini. Beberapa waktu lalu, kau bertanya kepadaku tentang tanah subur dan benih dawn flower. Itu untuk Dawn, 'kan?",
  str_homestory_810501001_46_dialog_content = "Jadi, dia bisa menanam bunga dengan gembira di sini.",
  str_homestory_810501001_47_dialog_content = "Nah, kau juga mendapat beberapa camilan Rediesel Wrench dari Vice karena kau khawatir Sinsa mungkin tak punya makanan yang cocok disantap dengan minumannya.",
  str_homestory_810501001_48_dialog_content = "Ah... Navigator, kau memang serbatahu...",
  str_homestory_810501001_49_dialog_content = "Kau benar.",
  str_homestory_810501001_50_dialog_content = "Tapi...",
  str_homestory_810501001_51_dialog_content = "Bagaimana kalau kau juga mempersiapkan sesuatu untuk diri sendiri?",
  str_homestory_810501001_52_dialog_content = "Hmm... Aku menyiapkan ini untuk Dawn dan kakakku agar mereka bisa lebih kerasan di sini.",
  str_homestory_810501001_53_dialog_content = "Aku sudah sangat senang bisa selalu bersama mereka.",
  str_homestory_810501001_54_dialog_content = "Ah... Bersamamu dan Vice juga!",
  str_homestory_810501001_55_dialog_content = "Keberadaan kalian membuatku senang!",
  str_homestory_810501001_56_dialog_content = "Aku tak perlu menyiapkan apa pun untuk diri sendiri.",
  str_homestory_810501001_57_dialog_content = "Begitu, ya?",
  str_homestory_810501001_58_dialog_content = "Kau memang perhatian dan manis...",
  str_homestory_810501001_59_dialog_content = "Kau juga begitu, Navigator!",
  str_homestory_810501001_60_dialog_content = "Huu-huu...",
  str_homestory_810501001_61_dialog_content = "Ada apa?",
  str_homestory_810501001_62_dialog_content = "Navigator, kenapa tiba-tiba kau tersedu-sedu begitu?",
  str_homestory_810501001_63_dialog_content = "*Terisak* Aku ingin punya adik seperti dirimu, Eve...<sprite=emo_daku size=60 />",
  str_homestory_811201001_0_dialog_content = "Smokey?",
  str_homestory_811201001_1_dialog_content = "Apa yang terjadi, Smokey?",
  str_homestory_811201001_2_dialog_content = "Kelihatannya kau sangat marah.",
  str_homestory_811201001_3_dialog_content = "Hei, Navigator.",
  str_homestory_811201001_4_dialog_content = "Menurutmu, bukankah pilihan produk yang ditawarkan toko ini terlalu sedikit?<sprite=emo_shengqi size=60 />",
  str_homestory_811201001_5_dialog_content = "Ah! Jadi, kau marah gara-gara ini, ya?",
  str_homestory_811201001_6_dialog_content = "Apa ada suatu barang yang tak bisa kautemukan di sini? Katakan saja.",
  str_homestory_811201001_7_dialog_content = "Kau yakin mau tahu?",
  str_homestory_811201001_8_dialog_content = "Iya. Bilang saja.",
  str_homestory_811201001_9_dialog_content = "Kalau begitu, langsung ke intinya saja, ya.",
  str_homestory_811201001_10_dialog_content = "Pertama, tak ada detergen aksesori sama sekali.",
  str_homestory_811201001_11_dialog_content = "Lalu, kancing yang dijual di toko itu juga sangat jelek!",
  str_homestory_811201001_12_dialog_content = "Percayalah. Tak ada yang mau memasang kancing seperti itu pada pakaian mereka.",
  str_homestory_811201001_13_dialog_content = "Maaf. Orang-orang Illumina itu mungkin akan menyukainya.",
  str_homestory_811201001_14_dialog_content = "Kancing... Yah, selama bisa berfungsi...",
  str_homestory_811201001_15_dialog_content = "Apa boleh buat. Lagi pula, kau kan memang tak paham soal mode.",
  str_homestory_811201001_16_dialog_content = "Jangan memandang rendah dirimu sendiri. Tenang saja, ada aku.",
  str_homestory_811201001_17_dialog_content = "Terima kasih…",
  str_homestory_811201001_18_dialog_content = "Selain itu, tempat ini lebih panas dan cerah ketimbang Umbraton.",
  str_homestory_811201001_19_dialog_content = "Kulihat ada payung di sini, tapi di mana kacamata hitam dan tabir suryanya? Tidak ada!",
  str_homestory_811201001_20_dialog_content = "Kau benar...",
  str_homestory_811201001_21_dialog_content = "(Aurorian yang kesulitan mencari barang kebutuhannya di sini pasti bukan hanya Smokey seorang.)",
  str_homestory_811201001_22_dialog_content = "(Bagaimana ini? Butuh waktu lama kalau harus menanyai mereka satu per satu...)",
  str_homestory_811201001_23_dialog_content = "Hei, kau bergumam apa, sih?",
  str_homestory_811201001_24_dialog_content = "Aku terlalu rewel ya? Kau stres memikirkan bakal ada orang lain yang rewel seperti aku?",
  str_homestory_811201001_25_option_content = "Mengangguk",
  str_homestory_811201001_26_dialog_content = "Bagus. Kejujuran adalah emas.",
  str_homestory_811201001_27_dialog_content = "Aku justru lebih cemas ketimbang stres...",
  str_homestory_811201001_28_option_content = "Menggelengkan kepala",
  str_homestory_811201001_29_dialog_content = "Tidak, Smokey. Aku sama sekali tidak stres, kok...",
  str_homestory_811201001_30_dialog_content = "Sebenarnya, masalahnya bukan stres atau tidak...",
  str_homestory_811201001_31_dialog_content = "Mungkin orang lain juga punya masalah yang sama denganmu, tapi aku tak tahu bagaimana solusinya...",
  str_homestory_811201001_32_dialog_content = "... Kau perlu mengembangkan Sistem Pemesanan Eraveil.",
  str_homestory_811201001_33_dialog_content = "Semua orang bisa mencatatkan produk yang mereka perlukan ke dalam sistem secara berkala. Lalu, pesanan mereka akan dipasang di seluruh Astra dengan benar.",
  str_homestory_811201001_34_dialog_content = "Pengantaran... Kau pasti bisa memikirkan teknologi khusus untuk itu, 'kan?",
  str_homestory_811201001_35_dialog_content = "Courier Union<sprite=emo_gezitou size=60 />, Firefly, dan sebagainya.",
  str_homestory_811201001_36_dialog_content = "Ah... Ide bagus...",
  str_homestory_811201001_37_dialog_content = "Nah, kalau begini kan kau tak perlu bicara kepada kami satu per satu. Kau juga tak bakal mendengar keluhan lain seperti keluhanku.",
  str_homestory_811201001_38_dialog_content = "Kau pasti tahu 'kan, ada beberapa orang Aurorian yang agak \"istimewa\"?",
  str_homestory_811201001_39_dialog_content = "Ada yang suka peti mati, berbagai jenis kuas lukis, atau serangga-serangga aneh...",
  str_homestory_811201001_40_dialog_content = "Dan ada juga yang tak bisa hidup tanpa gin.",
  str_homestory_811201001_41_dialog_content = "Sebentar... Kaubilang \"gin\"?",
  str_homestory_811201001_42_dialog_content = "Maksudmu... Genevieve?",
  str_homestory_811201001_43_dialog_content = "Memangnya dia saja yang suka minum-minum?",
  str_homestory_811201001_44_dialog_content = "... Aku tak paham dengan cara kerja otakmu!",
  str_homestory_811201001_45_dialog_content = "Baiklah... Rupanya bukan dia yang kaumaksud. Ada orang lain yang sangat menyukai gin!",
  str_homestory_811201001_46_dialog_content = "Benar! Ada banyak orang yang suka minum-minum, tahu?<sprite=emo_nuhuo size=60 />",
  str_homestory_811201001_47_dialog_content = "Baiklah... Jangan marah, dong! Dan jangan bakar apa pun, ya...",
  str_homestory_811201001_48_dialog_content = "Hmph.",
  str_homestory_811201001_49_dialog_content = "Terima kasih, Smokey!",
  str_homestory_811201001_50_dialog_content = "Nasihatmu sangat berguna!",
  str_homestory_811201001_51_dialog_content = "Aku pergi dulu, ya. Sampai jumpa.",
  str_homestory_811201001_52_dialog_content = "Sampai jumpa!",
  str_homestory_807101001_0_dialog_content = "Layang-layang Taki...",
  str_homestory_807101001_1_dialog_content = "Ehem... Taki...",
  str_homestory_807101001_2_dialog_content = "Hah? PlayerName?",
  str_homestory_807101001_3_dialog_content = "Eh... Tadi aku melihat layang-layangmu...",
  str_homestory_807101001_4_dialog_content = "Benda itu tergeletak di atas tanah.",
  str_homestory_807101001_5_dialog_content = "... Oh.",
  str_homestory_807101001_6_dialog_content = "Tapi, aku langsung memungutnya.",
  str_homestory_807101001_7_dialog_content = "...<sprite=emo_yihuo size=60 />",
  str_homestory_807101001_8_dialog_content = "(Bukan itu intinya...)",
  str_homestory_807101001_9_dialog_content = "Baiklah. Karena itu, aku jadi merasa kemampuan menerbangkan layang-layangmu...",
  str_homestory_807101001_10_option_content = "Cukup bagus!",
  str_homestory_807101001_11_dialog_content = "Nak, kau mau coba-coba menghiburku, ya?",
  str_homestory_807101001_12_dialog_content = "Ehem... Aku kan hanya mau bersikap suportif...",
  str_homestory_807101001_13_dialog_content = "Aku mengerti, tapi aku tak butuh pujian palsu.",
  str_homestory_807101001_14_dialog_content = "Baiklah. Asalkan kau tak jadi lesu, sih...",
  str_homestory_807101001_15_option_content = "Tidak bakal!",
  str_homestory_807101001_16_dialog_content = "Aku akan mengajarimu dengan senang hati.",
  str_homestory_807101001_17_dialog_content = "Baiklah. Kalau begitu, ajari aku.",
  str_homestory_807101001_18_dialog_content = "Hah? Mudah sekali membujukmu.",
  str_homestory_807101001_19_dialog_content = "Tentu saja.",
  str_homestory_807101001_20_dialog_content = "Belajar dari orang yang lebih ahli bukanlah hal yang memalukan.",
  str_homestory_807101001_21_dialog_content = "Kalau mau mengakui bahwa kita tidak paham, komunikasi akan jadi lebih efektif. Ini terutama berlaku untuk pengusaha mana pun.",
  str_homestory_807101001_22_dialog_content = "Wah, pemilik Odd Jobs memang tak pernah gagal membuatku terkesan!",
  str_homestory_807101001_23_dialog_content = "Nah, apa trik untuk menerbangkan layang-layang? Katakan.",
  str_homestory_807101001_24_dialog_content = "Pertama, kau harus memastikan kau membelakangi angin.",
  str_homestory_807101001_25_dialog_content = "Dengan begini, layang-layangnya akan tertiup angin.",
  str_homestory_807101001_26_dialog_content = "Lalu, mulai lepaskan talinya untuk membantu layang-layang itu terbang lebih tinggi ke angkasa. Kalau anginnya kurang, kau harus bergegas menggulung talinya.",
  str_homestory_807101001_27_dialog_content = "Berlarilah pelan-pelan sambil menerbangkan layang-layang itu. Awasi terus posisinya.",
  str_homestory_807101001_28_dialog_content = "Kalau layang-layang itu sudah terbang dengan mantap di langit...",
  str_homestory_807101001_29_dialog_content = "Kau bisa mengikat talinya di pohon atau papan arah, lalu mencari tempat yang nyaman untuk melihatnya terbang.",
  str_homestory_807101001_30_dialog_content = "Baiklah... Arah angin... Kekuatan angin... Lari pelan-pelan... Dan berinteraksi dengan layang-layang itu...<sprite=emo_wuyu size=60 />",
  str_homestory_807101001_31_dialog_content = "Ah? Kau menguraikannya satu per satu?",
  str_homestory_807101001_32_dialog_content = "Aku bisa mengulangi penjelasanku barusan kalau kau mau...",
  str_homestory_807101001_33_dialog_content = "Tak perlu. Aku sudah mengingat semuanya.",
  str_homestory_807101001_34_dialog_content = "Hmm? Kalau begitu, kenapa kau masih menggumamkannya?",
  str_homestory_807101001_35_dialog_content = "Eh... Maksudku... Bagaimana kalau kaucoba saja?",
  str_homestory_807101001_36_dialog_content = "Aku berencana untuk mencetak buku \"Cara Menerbangkan Layang-Layang\" demi mendongkrak penjualan.",
  str_homestory_807101001_37_dialog_content = "... Hah?",
  str_homestory_807101001_38_dialog_content = "Coba bayangkan. Kalau Odd Jobs mulai menjual layang-layang dan meningkatkan iklannya...",
  str_homestory_807101001_39_dialog_content = "Beli layang-layang dan dapatkan sesi latihan gratis untuk waktu terbatas.",
  str_homestory_807101001_40_dialog_content = "Bagaimana kalau ada orang yang tidak bisa menerbangkan layang-layang setelah mengikuti sesi latihan? Beli buku \"Cara Menerbangkan Layang-Layang\".",
  str_homestory_807101001_41_dialog_content = "Nah, nanti kita jual berbagai macam layang-layang. Mungkin kita pakai foto kepala Shadowlord sekalian...",
  str_homestory_807101001_42_dialog_content = "Woah, s-sebentar!",
  str_homestory_807101001_43_dialog_content = "Jadi, kau menerbangkan layang-layang di sini dan belajar menerbangkannya dariku...",
  str_homestory_807101001_44_dialog_content = "Untuk menghasilkan uang?",
  str_homestory_807101001_45_dialog_content = "Ya.",
  str_homestory_807101001_46_dialog_content = "Nak, aku ini pengusaha.",
  str_homestory_807101001_47_dialog_content = "Memangnya ada masalah?",
  str_homestory_807101001_48_dialog_content = "Tidak. Sama sekali tidak...",
  str_homestory_807101001_49_dialog_content = "Aku mengagumi kemampuanmu untuk melihat peluang bisnis!",
  str_homestory_807101001_50_dialog_content = "Kalau tahu cara menghasilkan uang dari hal-hal di sekitarku, aku tak bakal melampaui anggaran setiap hari...",
  str_homestory_807101001_51_dialog_content = "Hmm... Kau cemas soal uang, ya.",
  str_homestory_807101001_52_dialog_content = "Dengar. Karena aku mendapat inspirasi bisnis ini darimu...",
  str_homestory_807101001_53_dialog_content = "Sebagian keuntungannya akan jadi milikmu kalau rencana ini benar-benar terwujud di Odd Jobs.",
  str_homestory_807101001_54_dialog_content = "?!",
  str_homestory_807101001_55_dialog_content = "Kau serius?",
  str_homestory_807101001_56_dialog_content = "Iya, tapi jangan senang dulu.",
  str_homestory_807101001_57_dialog_content = "Bisnis ini bisa jadi gagal total.",
  str_homestory_807101001_58_dialog_content = "Bukan masalah. Taki, aku percaya padamu!",
  str_homestory_807101001_59_dialog_content = "Baiklah. Aku harus berlatih menerbangkan layang-layang dulu sekarang.",
  str_homestory_807101001_60_dialog_content = "Nak, kau pasti sibuk. Sana, lanjutkan kegiatanmu.",
  str_homestory_807101001_61_dialog_content = "Kau pasti bisa! Taki!",
  str_homestory_807101001_62_dialog_content = "(... Ya! Aku sudah memutuskan!)",
  str_homestory_807101001_63_dialog_content = "(Demi setengah keuntungan yang jadi bagianku... akan kupastikan Taki berlatih dan meningkatkan kemampuannya setiap hari!)<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_0_dialog_content = "Vice?",
  str_homestory_803301001_1_dialog_content = "Tarik napas... Vice, kau pasti bisa!",
  str_homestory_803301001_2_dialog_content = "Tarik napas dalam-dalam... Embuskan...<sprite=emo_tanqi size=60 />",
  str_homestory_803301001_3_dialog_content = "Embuskan?",
  str_homestory_803301001_4_dialog_content = "Vice, kau... Kau berlatih pernapasan?",
  str_homestory_803301001_5_dialog_content = "Ahh! PlayerName?",
  str_homestory_803301001_6_dialog_content = "... Berlatih pernapasan?",
  str_homestory_803301001_7_dialog_content = "Tidak, kok...",
  str_homestory_803301001_8_dialog_content = "Lalu, kau sedang apa?",
  str_homestory_803301001_9_dialog_content = "Aku sedang mencatat keuangan.",
  str_homestory_803301001_10_dialog_content = "Ah... Pengeluaran keuangan membuatku pusing.",
  str_homestory_803301001_11_dialog_content = "Kuharap ini semudah latihan bernapas...",
  str_homestory_803301001_12_dialog_content = "Setidaknya bernapas tak butuh uang.",
  str_homestory_803301001_13_option_content = "Tanyai Vice",
  str_homestory_803301001_14_dialog_content = "Ada yang bisa kubantu?",
  str_homestory_803301001_15_dialog_content = "Semalam, aku memeriksa buku besar kita.",
  str_homestory_803301001_16_dialog_content = "Meski tak terlalu mahir dalam pembukuan, aku mau membantu.",
  str_homestory_803301001_17_option_content = "Diam saja",
  str_homestory_803301001_18_dialog_content = "Kenapa kau diam saja?",
  str_homestory_803301001_19_dialog_content = "Ahh... Aku tak bermaksud menyalahkanmu, kok...",
  str_homestory_803301001_20_dialog_content = "Aku tahu. Aku hanya memikirkan bantuan macam apa yang bisa kuberikan.",
  str_homestory_803301001_21_dialog_content = "Semalam, aku memeriksa buku besar kita. Rupanya kita sedikit melampaui anggaran...",
  str_homestory_803301001_22_dialog_content = "Ah... Vice... Terima kasih atas segalanya!",
  str_homestory_803301001_23_dialog_content = "Biar kuingat-ingat dulu apa yang kulihat di buku besar tadi malam...",
  str_homestory_803301001_24_dialog_content = "\"Hanya komponen untuk Fountain of Hope, alun-alun, dan batuannya saja akan menghabiskan banyak uang.\"",
  str_homestory_803301001_25_dialog_content = "\"Apalagi material yang dibutuhkan untuk Dorm dan museum\"...",
  str_homestory_803301001_26_dialog_content = "\"Kita harus mempertimbangkan preferensi setiap teman...\"",
  str_homestory_803301001_27_dialog_content = "\"Misalnya, kuda-kudaan, kursi gantung, dan patung...\"",
  str_homestory_803301001_28_dialog_content = "\"Benda-benda ini tidak terlalu mahal harganya, tapi jumlahnya membengkak dalam sekejap.\"",
  str_homestory_803301001_29_dialog_content = "\"Ada banyak hal yang harus dipelajari tentang cara berkomunikasi dengan para pengrajin. Pemasangannya pun bisa jadi menantang.\"",
  str_homestory_803301001_30_dialog_content = "\"Tapi... kurasa seluruh kerja kerasku dan PlayerName tak akan sia-sia kalau para tamu bisa tinggal dengan nyaman.\"",
  str_homestory_803301001_31_dialog_content = "Ah... Kau membaca semuanya, ya.",
  str_homestory_803301001_32_dialog_content = "Iya... Aku tak bisa menghilangkan kebiasaan menuliskan unek-unekku... Hahah.",
  str_homestory_803301001_33_dialog_content = "Vice, serius, deh. Kau ini sangat keren!",
  str_homestory_803301001_34_dialog_content = "Navigator, kenapa tiba-tiba kau memujiku setinggi langit?",
  str_homestory_803301001_35_dialog_content = "Aku serius!",
  str_homestory_803301001_36_dialog_content = "Begini. Kau menggambar rencana konstruksi, mengatur jadwal proyek, dan membuat perencanaan wilayah...",
  str_homestory_803301001_37_dialog_content = "Aku? Aku sama sekali tak bisa membantu. Jangankan menggambar, membuat perencanaan dan mengatur juga tak bisa.",
  str_homestory_803301001_38_dialog_content = "Cloud Gardens berutang segalanya kepadamu.",
  str_homestory_803301001_39_dialog_content = "... Ah... Benar juga, sih...",
  str_homestory_803301001_40_dialog_content = "Tapi, tak perlu berterima kasih begitu!",
  str_homestory_803301001_41_dialog_content = "Aku hanya ingin menghiburmu.",
  str_homestory_803301001_42_dialog_content = "Ayo bekerja sama agar kita terlepas dari utang.",
  str_homestory_803301001_43_dialog_content = "Ya! Kau benar!",
  str_homestory_803301001_44_dialog_content = "Ah... Karena membeli barang di Cloud Gardens cukup sulit...",
  str_homestory_803301001_45_dialog_content = "Bagaimana kalau kita meningkatkan harga jual semua barang menjadi sepuluh kali lipat?<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_46_dialog_content = "... Eh... Kurasa tak perlu sampai begitu...",
  str_homestory_803301001_47_dialog_content = "Heheh. Navigator, aku kan hanya bercanda!",
  str_homestory_803301001_48_dialog_content = "Serius, nih. Bagaimana cara menghasilkan uang? Biar kupikirkan dulu...",
  str_homestory_804101001_0_dialog_content = "Ms. Blanc...",
  str_homestory_804101001_1_dialog_content = "Hei, PlayerName.",
  str_homestory_804101001_2_dialog_content = "Hari yang indah<sprite=emo_pugongying size=60 />, Ms. Blanc.",
  str_homestory_804101001_3_dialog_content = "Iya.",
  str_homestory_804101001_4_dialog_content = "Kau sedang jalan-jalan atau mau pergi ke suatu tempat?",
  str_homestory_804101001_5_option_content = "Hanya jalan-jalan",
  str_homestory_804101001_6_dialog_content = "Pilihan bagus.",
  str_homestory_804101001_7_dialog_content = "Tempat ini indah, ada banyak fasilitas hiburannya...",
  str_homestory_804101001_8_dialog_content = "Dan ada banyak orang yang belum pernah kujumpai sebelumnya.",
  str_homestory_804101001_9_option_content = "Memancing",
  str_homestory_804101001_10_dialog_content = "Ah. Kau pandai memancing?",
  str_homestory_804101001_11_option_content = "Sangat pandai",
  str_homestory_804101001_12_dialog_content = "Sungguh?",
  str_homestory_804101001_13_dialog_content = "Nanti aku akan datang untuk melihat.",
  str_homestory_804101001_14_dialog_content = "Selamat datang!",
  str_homestory_804101001_15_dialog_content = "Heheh. Anak muda yang sangat percaya diri!",
  str_homestory_804101001_16_option_content = "Biasa-biasa saja...",
  str_homestory_804101001_17_dialog_content = "Memancing butuh banyak kesabaran.",
  str_homestory_804101001_18_dialog_content = "Tadinya kupikir kau terlalu muda untuk ini.",
  str_homestory_804101001_19_dialog_content = "Hmm... Memancing justru membantuku berkonsentrasi.",
  str_homestory_804101001_20_dialog_content = "Anu...",
  str_homestory_804101001_21_dialog_content = "Hanya orang yang \"kesulitan berkonsentrasi\" yang perlu melakukan hal-hal untuk meningkatkan konsentrasi.",
  str_homestory_804101001_22_dialog_content = "Tapi, kau akan merasakan manfaatnya seiring waktu.",
  str_homestory_804101001_23_dialog_content = "Ya…",
  str_homestory_804101001_24_dialog_content = "Ms. Blanc, kenapa kau berdiri di bawah papan kayu ini?",
  str_homestory_804101001_25_dialog_content = "Aku sedang mengamati.",
  str_homestory_804101001_26_dialog_content = "Mengamati?",
  str_homestory_804101001_27_dialog_content = "Mau bagaimana lagi.",
  str_homestory_804101001_28_dialog_content = "Semua bangunan dan jalan ini... Aku ingin mengingat segalanya dalam kepalaku.",
  str_homestory_804101001_29_dialog_content = "Begitu rupanya.",
  str_homestory_804101001_30_dialog_content = "Jalanan di sini tidak rumit. Mungkin saja kau bisa sedikit bersantai, Ms. Blanc.",
  str_homestory_804101001_31_dialog_content = "Bersantai?",
  str_homestory_804101001_32_dialog_content = "Itu sangat mewah...",
  str_homestory_804101001_33_dialog_content = "Tapi, aku harus mengikuti saranmu.",
  str_homestory_804101001_34_dialog_content = "PlayerName, selamat beristirahat.",
  str_homestory_804101001_35_dialog_content = "Terlalu banyak bekerja bisa membuatmu cepat tua, lho.<sprite=emo_guilian size=60 />",
  str_homestory_804101001_36_dialog_content = "Baiklah…",
  str_homestory_804101001_37_dialog_content = "Kuharap begitu! Ms. Blanc!",
  str_homestory_813801001_0_dialog_content = "Siobhan!",
  str_homestory_813801001_1_dialog_content = "PlayerName?",
  str_homestory_813801001_2_dialog_content = "Ah... Syukurlah kau kemari...<sprite=emo_tanqi size=60 />",
  str_homestory_813801001_3_dialog_content = "Ada apa, Siobhan? Kau kelihatan lelah.",
  str_homestory_813801001_4_dialog_content = "Karena... Aku bergadang semalaman untuk memandangi benda koleksi di museum.",
  str_homestory_813801001_5_dialog_content = "Benda-benda koleksi itu adalah catatan sempurna mengenai masa lalu Eraveil dan segala teknologi yang kaum Caelestite kembangkan...",
  str_homestory_813801001_6_dialog_content = "Harus kuakui, aku kagum dengan kecakapan ilmiah kalian.",
  str_homestory_813801001_7_dialog_content = "Terima kasih. Illumina juga sangat hebat dalam sains dan teknologi.",
  str_homestory_813801001_8_dialog_content = "Entah kenapa aku tak bisa menghilangkan perasaan ini...",
  str_homestory_813801001_9_dialog_content = "Teknologi Caelestite tidak seperti Illumina.",
  str_homestory_813801001_10_dialog_content = "Teknologi tinggi Illumina didasarkan pada jaringan mekanis rumit yang dikembangkan dengan pengetahuan dan ketelitian yang solid...",
  str_homestory_813801001_11_dialog_content = "Tapi, kalau teknologi Caelestite... Semuanya terasa sangat segar dan berbeda.",
  str_homestory_813801001_12_dialog_content = "Dalam beberapa hal mirip dengan teknologi kaum Ancient.",
  str_homestory_813801001_13_dialog_content = "Hmm... Aku tak tahu apa-apa soal ini...",
  str_homestory_813801001_14_dialog_content = "Hoam...",
  str_homestory_813801001_15_dialog_content = "Tiba-tiba mengantuk...<sprite=emo_xuanyun size=60 />",
  str_homestory_813801001_16_dialog_content = "Tunggu apa lagi? Sana, pulang lalu tidur saja.",
  str_homestory_813801001_17_dialog_content = "Aku mencoba untuk mencocokkan benda-benda koleksi ini dengan dokumen yang pernah kubaca dulu. Semoga ada penemuan menarik.",
  str_homestory_813801001_18_dialog_content = "Pada zaman dulu, mungkin saja ada kaum Caelestite di suatu tempat lain di benua ini...",
  str_homestory_813801001_19_dialog_content = "Orang-orang tak tahu bahwa mereka sebenarnya adalah kaum Caelestite dan salah mengira teknologi mereka adalah teknologi kaum Ancient.",
  str_homestory_813801001_20_dialog_content = "... Hahahah. Lupakan saja.",
  str_homestory_813801001_21_dialog_content = "Omonganku mulai tak masuk akal. Sebaiknya aku tidur.",
  str_homestory_813801001_22_dialog_content = "Siobhan, aku mencemaskanmu.",
  str_homestory_813801001_23_dialog_content = "Kenapa kau harus menyelesaikannya sekarang?",
  str_homestory_813801001_24_dialog_content = "Kalau keadaanmu begini, sepertinya pekerjaanmu bakal terganggu...",
  str_homestory_813801001_25_dialog_content = "Bukankah kau menjamu beberapa orang Lumopolis di sini?",
  str_homestory_813801001_26_dialog_content = "Walau ada Caelestite sepertimu di sini, aku tak yakin mereka akan berani menghancurkan museum itu...",
  str_homestory_813801001_27_dialog_content = "Aku... aku hanya khawatir.",
  str_homestory_813801001_28_dialog_content = "Rasanya aku harus segera mencatat dan menganalisis semuanya.",
  str_homestory_813801001_29_dialog_content = "Siapa tahu apa pendapat para pembenci teknologi itu tentang tempat ini?",
  str_homestory_813801001_30_dialog_content = "Oh, begitu…",
  str_homestory_813801001_31_dialog_content = "Tenang saja. Setahuku, ada banyak museum di Lumopolis.",
  str_homestory_813801001_32_dialog_content = "Mereka tamuku di sini. Apa pun yang kau cemaskan tak akan terjadi.",
  str_homestory_813801001_33_dialog_content = "Aku terlalu memikirkannya, ya?",
  str_homestory_813801001_34_dialog_content = "Apa aku jadi terlalu memikirkannya gara-gara kebanyakan kerja?<sprite=emo_sikao size=60 />",
  str_homestory_813801001_35_dialog_content = "Kurasa kau hanya capek, kok.",
  str_homestory_813801001_36_dialog_content = "Bagaimana kalau kita istirahat sebentar dan membicarakannya lagi nanti?",
  str_homestory_813801001_37_dialog_content = "Baiklah. Kurasa juga begitu... PlayerName.",
  str_homestory_813801001_38_dialog_content = "Aku mau tidur. Bagaimana denganmu?",
  str_homestory_813801001_39_dialog_content = "Sepertinya kau sendiri juga butuh tidur.",
  str_homestory_813801001_40_option_content = "Setuju",
  str_homestory_813801001_41_dialog_content = "Iya, aku juga capek.",
  str_homestory_813801001_42_dialog_content = "Tapi...",
  str_homestory_813801001_43_option_content = "Keberatan",
  str_homestory_813801001_44_dialog_content = "Mungkin tubuhku memang lelah, tapi semangatku terasa berkobar!",
  str_homestory_813801001_45_dialog_content = "Aku tak keberatan kalau memang harus bersusah payah. Yang penting, semua orang bisa bersenang-senang di sini.",
  str_homestory_813801001_46_dialog_content = "Meski masih muda, kemampuan memimpinmu sangat bagus.",
  str_homestory_813801001_47_dialog_content = "Terima kasih…",
  str_homestory_813801001_48_dialog_content = "Entah kenapa aku terus-terusan ingin pergi ke sungai, tapi aku sangat mengantuk.",
  str_homestory_813801001_49_dialog_content = "Kita bicarakan teknologi Caelestite lagi setelah aku tidur siang, PlayerName.",
  str_homestory_813801001_50_dialog_content = "Selamat beristirahat, Siobhan.",
  str_homestory_814501001_0_dialog_content = "Dia lihat apa, sih?",
  str_homestory_814501001_1_dialog_content = "Amemori?",
  str_homestory_814501001_2_dialog_content = "Hush.<sprite=emo_baiyan size=60 />",
  str_homestory_814501001_3_dialog_content = "?",
  str_homestory_814501001_4_dialog_content = "Sedang apa kau?",
  str_homestory_814501001_5_dialog_content = "Mengamati.",
  str_homestory_814501001_6_dialog_content = "Aku sedang memeriksa tempat ini dengan hati-hati dan saksama.",
  str_homestory_814501001_7_dialog_content = "Apa ada yang tidak lazim di tempat ini?",
  str_homestory_814501001_8_dialog_content = "Bukankah desain untuk Cloud Gardens ini sangat rumit?",
  str_homestory_814501001_9_dialog_content = "Saat masih muda dulu, aku membayangkan bisa membangun tempat semacam ini.",
  str_homestory_814501001_10_dialog_content = "Tempat yang mudah untuk melancarkan serangan, mudah untuk dipertahankan, dan merupakan tempat pertemuan bagus untuk orang-orang yang berpikiran sama.",
  str_homestory_814501001_11_dialog_content = "Oh!",
  str_homestory_814501001_12_dialog_content = "Kau sudah membuat rencana jangka panjang sejak masih kecil, ya, Amemori?",
  str_homestory_814501001_13_dialog_content = "Yah, mimpiku saat itu mungkin hanya dorongan untuk \"terus hidup\".",
  str_homestory_814501001_14_dialog_content = "Tapi, bisa tinggal di sini sekarang ternyata tidak buruk.",
  str_homestory_814501001_15_dialog_content = "Eh, maaf.",
  str_homestory_814501001_16_dialog_content = "Mau kuajak berkeliling?",
  str_homestory_814501001_17_dialog_content = "Tak perlu.",
  str_homestory_814501001_18_dialog_content = "Aku sudah tahu tata letaknya pada hari pertamaku di sini.",
  str_homestory_814501001_19_dialog_content = "Wow, kau peka juga!",
  str_homestory_814501001_20_dialog_content = "Itulah keahlian ninja.",
  str_homestory_814501001_21_dialog_content = "Sebenarnya, siapa yang mendesain tempat ini?",
  str_homestory_814501001_22_dialog_content = "Navigator, kau tahu, tidak?",
  str_homestory_814501001_23_option_content = "Tahu",
  str_homestory_814501001_24_dialog_content = "Vice merancangnya berdasarkan saran dariku dan para pengrajin.",
  str_homestory_814501001_25_option_content = "Tidak",
  str_homestory_814501001_26_dialog_content = "Aku bisa menanyakannya kalau kau mau.",
  str_homestory_814501001_27_dialog_content = "Aku mencoba-coba rencana aslinya, tapi dia yang lebih tahu.",
  str_homestory_814501001_28_dialog_content = "Amemori, kenapa kau benar-benar ingin tahu?",
  str_homestory_814501001_29_dialog_content = "Kau tertarik untuk membangun Cloud Gardens lain di Cloud Island, ya?",
  str_homestory_814501001_30_dialog_content = "Tadinya aku memang berpikir begitu.",
  str_homestory_814501001_31_dialog_content = "Coba bayangkan. Begitu Cloud Island punya hunian sehebat ini, orang-orang akan hidup lebih makmur.",
  str_homestory_814501001_32_dialog_content = "Tentu saja, itu baru awalnya...",
  str_homestory_814501001_33_dialog_content = "Kalau kami benar-benar mempelajari teknologi yang canggih ini, mempertahankan diri dari musuh pasti akan lebih mudah.",
  str_homestory_814501001_34_dialog_content = "Teknologi Caelestite dengan konsep dan perencanaan yang luar biasa... Pantas untuk dicermati.",
  str_homestory_814501001_35_dialog_content = "Begitu rupanya.",
  str_homestory_814501001_36_dialog_content = "Akan kucarikan jawabannya untukmu!",
  str_homestory_814501001_37_dialog_content = "Terima kasih, Navigator.",
  str_homestory_814601001_0_dialog_content = "Menggelengkan kepala...",
  str_homestory_814601001_1_dialog_content = "Semua Aurorian...",
  str_homestory_814601001_2_dialog_content = "Melewati Cloud Gardens.",
  str_homestory_814601001_3_dialog_content = "?",
  str_homestory_814601001_4_dialog_content = "Gerbangnya muncul dari tanah yang rata...",
  str_homestory_814601001_5_dialog_content = "Dengan roti isi di tangan!<sprite=emo_yaosu size=60 />",
  str_homestory_814601001_6_dialog_content = "...",
  str_homestory_814601001_7_dialog_content = "Yao, kau sedang membaca puisi, ya?",
  str_homestory_814601001_8_dialog_content = "Hoi, Navigator!",
  str_homestory_814601001_9_dialog_content = "Aku tidak sedang membaca, kok.",
  str_homestory_814601001_10_dialog_content = "Tapi, mengarang! Bagaimana menurutmu?",
  str_homestory_814601001_11_option_content = "Bagus!",
  str_homestory_814601001_12_dialog_content = "Bagus sekali!",
  str_homestory_814601001_13_dialog_content = "Yao, kau berbakat jadi penyair!",
  str_homestory_814601001_14_option_content = "Lumayan juga",
  str_homestory_814601001_15_dialog_content = "Menurutku, puisi ini seperti gabungan karya Charon dan Vice.",
  str_homestory_814601001_16_dialog_content = "Tak terlalu berlebihan atau terlalu realistis, itu mengungkapkan keinginan si Penyair yang sebenarnya...",
  str_homestory_814601001_17_dialog_content = "Ehem... Tapi, apa hubungannya gerbang dengan roti isi?",
  str_homestory_814601001_18_dialog_content = "Lihat saja pemanah ini. Kau tidak lihat toko roti isi masa depanku?",
  str_homestory_814601001_19_dialog_content = "Masih berpikir mau membuka toko roti isi, ya?",
  str_homestory_814601001_20_dialog_content = "Bosan menegakkan keadilan dan membantu yang lemah?",
  str_homestory_814601001_21_dialog_content = "Aku ingin melakukan keduanya, kok.",
  str_homestory_814601001_22_dialog_content = "Pensiun dari kehidupan bela diri dan membuka toko roti isi saat sudah tua nanti sepertinya menyenangkan, 'kan?",
  str_homestory_814601001_23_dialog_content = "Tahu, 'kan? Para prajurit legendaris sering memilih pensiun di suatu pasar yang ramai...",
  str_homestory_814601001_24_dialog_content = "Orang-orang bisa terus mendengarkan legenda peninggalan mereka!",
  str_homestory_814601001_25_dialog_content = "Memangnya para prajurit itu tak punya kegiatan yang lebih bermutu, ya?",
  str_homestory_814601001_26_dialog_content = "Lupakan saja mereka. Sini, lihat rencanaku!",
  str_homestory_814601001_27_dialog_content = "Katakan saja. Aku siap menyimak.",
  str_homestory_814601001_28_dialog_content = "Pertama, toko roti isinya harus terdiri dari tiga lantai.",
  str_homestory_814601001_29_dialog_content = "Setengah dari lantai pertama akan digunakan oleh Anzu dan Momo untuk menjual makanan lezat buatan mereka. Setengahnya lagi untuk makanan lezat buatanku!",
  str_homestory_814601001_30_dialog_content = "Lantai kedua akan difungsikan sebagai kedai agar teman-temanku tak perlu repot soal urusan akomodasi kalau kami mengobrol sampai larut malam!",
  str_homestory_814601001_31_dialog_content = "Nah, lantai ketiganya akan kujadikan tempat tinggalku!",
  str_homestory_814601001_32_dialog_content = "Akan ada kamar untukku, Amemori, dan Rinne. Untuk Navigator dan Vice juga ada...",
  str_homestory_814601001_33_dialog_content = "Lalu Kayano. Dan teman-temanku dari klan Lin, saudari tersumpahku, dan orang tuaku...",
  str_homestory_814601001_34_dialog_content = "Apa perlu kusediakan kamar untuk Taki, ya? Tapi, mungkin dia tak bakal suka kalau dikelilingi banyak gadis.<sprite=emo_sikao size=60 />",
  str_homestory_814601001_35_dialog_content = "Lalu Dayna dan Robyn?",
  str_homestory_814601001_36_dialog_content = "Sebentar... Yao, sepertinya kau tak bakal bisa dapat uang dengan cara begini...",
  str_homestory_814601001_37_dialog_content = "Menyiapkan semua kamar untuk teman-temanmu kan butuh banyak uang.",
  str_homestory_814601001_38_dialog_content = "Beberapa orang lebih suka menyendiri. Kehidupan komune semacam ini tidak cocok untuk semua orang...",
  str_homestory_814601001_39_dialog_content = "Uang tak akan jadi masalah!",
  str_homestory_814601001_40_dialog_content = "Hmm... Tapi, selera pribadi adalah masalahnya...",
  str_homestory_814601001_41_dialog_content = "Pokoknya, orang-orang itu adalah teman-temanku dan aku akan menyiapkan kamar mereka.",
  str_homestory_814601001_42_dialog_content = "Tapi, terserah mereka saja sih mau datang atau tidak.",
  str_homestory_814601001_43_dialog_content = "Heheh. Dengan begitu kan semua orang jadi senang. Tak ada yang keberatan, tak perlu kompromi.",
  str_homestory_814601001_44_dialog_content = "Ya, kau benar...",
  str_homestory_814601001_45_dialog_content = "Ini adalah solusi khusus untuk orang yang kaya raya...",
  str_homestory_816301001_0_dialog_content = "Kau sedang menggambar, ya?",
  str_homestory_816301001_1_dialog_content = "Waow! <sprite=emo_wuzui size=60 />Ada PlayerName, si Airship Boss!",
  str_homestory_816301001_2_dialog_content = "Akhirnya! Aku sudah mencarimu ke mana-mana...",
  str_homestory_816301001_3_dialog_content = "Eh... Ada yang bisa kubantu?",
  str_homestory_816301001_4_dialog_content = "Saat sedang berkeliling untuk membuat rencana dengan orang-orang yang mau berkontribusi, aku melihat papan gambar ini...",
  str_homestory_816301001_5_dialog_content = "Kata Vice, kau membeli papan gambar ini meski banyak yang menentangmu.",
  str_homestory_816301001_6_dialog_content = "Bolehkah kusimpulkan bahwa...",
  str_homestory_816301001_7_dialog_content = "Akhirnya kau setuju untuk membuat karya seni untuk Al***my St**s?<sprite=emo_yaosu size=60 />",
  str_homestory_816301001_8_option_content = "Konfirmasi",
  str_homestory_816301001_9_dialog_content = "Ya, aku sudah memikirkan ide ini.",
  str_homestory_816301001_10_dialog_content = "Wow! Akhirnya kau bersedia memanfaatkan bakatmu!",
  str_homestory_816301001_11_dialog_content = "Eh... Aku harus melakukan sesuatu untuk menyelesaikan krisis keuangan.",
  str_homestory_816301001_12_dialog_content = "Kemampuanku juga tak bakal meningkat dalam waktu dekat.",
  str_homestory_816301001_13_dialog_content = "Aku lebih suka menyerahkannya kepada orang yang benar-benar suka menggambar, sepertimu...",
  str_homestory_816301001_14_option_content = "Bantah",
  str_homestory_816301001_15_dialog_content = "Ehem... Aku sadar diri kok soal kemampuanku...",
  str_homestory_816301001_16_dialog_content = "Papan ini adalah untuk orang yang suka menggambar.",
  str_homestory_816301001_17_dialog_content = "Airship Boss, coba letakkan tanganmu di dada.",
  str_homestory_816301001_18_dialog_content = "Rasakan detak jantungmu dengan kecintaan akan menggambar.",
  str_homestory_816301001_19_dialog_content = "Bicara soal kecintaan akan menggambar, kau tak ada duanya.",
  str_homestory_816301001_20_dialog_content = "Tourdog.",
  str_homestory_816301001_21_dialog_content = "…!",
  str_homestory_816301001_22_dialog_content = "Seharian kau membujuk orang agar mereka mau berkontribusi pada permainanmu. Kapan terakhir kalinya kau bisa tidur nyenyak?",
  str_homestory_816301001_23_dialog_content = "Demi permainanku, aku tak perlu tidur atau makan.",
  str_homestory_816301001_24_dialog_content = "Lalu, sudah berapa lama kau tidak menggambar dengan bebas?",
  str_homestory_816301001_25_dialog_content = "Waow…",
  str_homestory_816301001_26_dialog_content = "Kau sungguh ingin aku menggambar di papanmu?<sprite=emo_yihuo size=60 />",
  str_homestory_816301001_27_dialog_content = "Kalau Tourdog, pesohor Astra, mau menggambar sesuatu di sini...",
  str_homestory_816301001_28_dialog_content = "Pasti menyenangkan!",
  str_homestory_816301001_29_dialog_content = "Pertama, temukan titik lemah target dan bicaralah dengan semangat. Kemudian, puji target sebelum mengutarakan permintaanmu.<sprite=emo_sikao size=60 />",
  str_homestory_816301001_30_dialog_content = "Jadi, begini caramu bermain-main dengan pikiran seseorang?",
  str_homestory_816301001_31_dialog_content = "Setelah meminta banyak kontribusi, aku hampir jatuh dalam perangkapmu. Menarik!",
  str_homestory_816301001_32_dialog_content = "Protagonis yang dipilih oleh para investor memang mengagumkan!",
  str_homestory_816301001_33_dialog_content = "Plot permainan ini tak akan membosankan selama kau masih ada di sini.",
  str_homestory_816301001_34_option_content = "Tanyakan tentang investor",
  str_homestory_816301001_35_dialog_content = "Investor?",
  str_homestory_816301001_36_dialog_content = "Sekelompok bos yang cakap dan sangat percaya kepadamu.",
  str_homestory_816301001_37_dialog_content = "Kau tak perlu tahu siapa mereka.",
  str_homestory_816301001_38_option_content = "Tanyakan tentang protagonis",
  str_homestory_816301001_39_dialog_content = "Protagonis?",
  str_homestory_816301001_40_dialog_content = "Tokoh utama di permainan ini, bintang yang dicintai semua orang.",
  str_homestory_816301001_41_dialog_content = "Tak semua orang bisa mengisi posisi ini.",
  str_homestory_816301001_42_dialog_content = "Aku bingung.",
  str_homestory_816301001_43_dialog_content = "Intinya, Airship Boss.",
  str_homestory_816301001_44_dialog_content = "Aku bersedia membuatkanmu lukisan gulung bergambar Cloud Gardens secara cuma-cuma!",
  str_homestory_816301001_45_dialog_content = "Sebagai biaya pelajaranku atas permainan pikiran unikmu dengan tujuan meminta kontribusi.",
  str_homestory_816301001_46_dialog_content = "Aku tak sabar bekerja denganmu.<sprite=emo_guilian size=60 />",
  str_homestory_816301001_47_dialog_content = "Eh... Begitu juga denganku...",
  str_homestory_816301001_48_dialog_content = "Bagus. Aku harus merencanakan komposisi gambar ini.",
  str_homestory_816301001_49_dialog_content = "Biasanya, tak butuh waktu lebih dari 3 detik untuk menggambar, tapi aku harus berusaha sebaik mungkin untuk Airship Boss.",
  str_homestory_816301001_50_dialog_content = "Hmm…",
  str_homestory_816301001_51_dialog_content = "Mulai dari mana, ya?",
  str_homestory_816301001_52_dialog_content = "Baiklah, kuserahkan padamu, ya...",
  str_homestory_816301001_53_dialog_content = "(Sepertinya dia tak mendengarku.)",
  str_homestory_816301001_54_dialog_content = "(Aku pergi dulu, ah...)",
  str_homestory_814801001_0_dialog_content = "Dia di sini?",
  str_homestory_814801001_1_dialog_content = "Azure…",
  str_homestory_814801001_2_dialog_content = "Hah?",
  str_homestory_814801001_3_dialog_content = "Tampang manis siapa ini? Imutnya bukan main.",
  str_homestory_814801001_4_dialog_content = "Kemarilah. Biar kurasakan kelembutannya.",
  str_homestory_814801001_5_dialog_content = "Ah<sprite=emo_yundao size=60 />... Sebentar!",
  str_homestory_814801001_6_dialog_content = "Ini aku... PlayerName.",
  str_homestory_814801001_7_dialog_content = "PlayerName? Kedengarannya tidak asing.",
  str_homestory_814801001_8_dialog_content = "Ah! Hahahah. Sekarang aku ingat!",
  str_homestory_814801001_9_dialog_content = "Rupanya ini pacarku, si Caelestite kecil!",
  str_homestory_814801001_10_option_content = "Akui",
  str_homestory_814801001_11_dialog_content = "... Iya. Ini aku.",
  str_homestory_814801001_12_dialog_content = "Wow! Kau mengakuinya?",
  str_homestory_814801001_13_dialog_content = "Kalau begitu, sebaiknya kau tanggung jawab.",
  str_homestory_814801001_14_option_content = "Bantah",
  str_homestory_814801001_15_dialog_content = "Azure, tolong jangan bercanda begitu...",
  str_homestory_814801001_16_dialog_content = "Orang lain bisa jadi salah paham...",
  str_homestory_814801001_17_dialog_content = "Oh? Kau takut apa, sih?",
  str_homestory_814801001_18_dialog_content = "Kau tak mau gadis Illumina berekor naga itu sampai dengar, ya?",
  str_homestory_814801001_19_dialog_content = "Atau kau memikirkan putri antisosial dari Lumopolis itu?",
  str_homestory_814801001_20_dialog_content = "...",
  str_homestory_814801001_21_dialog_content = "Aduh, kalau tersipu begitu kau jadi tambah imut. Hahahah.",
  str_homestory_814801001_22_dialog_content = "Aku... aku harus pergi...<sprite=emo_hanshui size=60 />",
  str_homestory_814801001_23_dialog_content = "Sudah, sudah. Aku berhenti, deh.",
  str_homestory_814801001_24_dialog_content = "Tadi kau mencariku, ya?",
  str_homestory_814801001_25_dialog_content = "Aku hanya ingin tanya bagaimana kabarmu di sini...",
  str_homestory_814801001_26_dialog_content = "Aduh... Caelestite kecilku memang penuh perhatian. Aku benar-benar merasa tersentuh.",
  str_homestory_814801001_27_dialog_content = "Berkat dirimu, aku bisa bersenang-senang di sini.",
  str_homestory_814801001_28_dialog_content = "Sangat berbeda dengan gurun yang terik dan tandus itu, tempat ini begitu hijau.",
  str_homestory_814801001_29_dialog_content = "Tidak panas. Tidak kering. Bahkan anginnya sangat lembut.",
  str_homestory_814801001_30_dialog_content = "Sampahnya jauh lebih sedikit.",
  str_homestory_814801001_31_dialog_content = "Tempat dengan keindahan alami...",
  str_homestory_814801001_32_dialog_content = "Menurutmu, sekarang aku lebih cantik, tidak?",
  str_homestory_814801001_33_option_content = "Konfirmasi",
  str_homestory_814801001_34_dialog_content = "Iya, kecantikanmu sudah mencapai puncaknya....",
  str_homestory_814801001_35_option_content = "Bantah",
  str_homestory_814801001_36_dialog_content = "Mana mungkin kau bisa bertambah cantik? Kau kan sudah sangat cantik.",
  str_homestory_814801001_37_dialog_content = "Dari mana kau belajar merayu seperti ini?",
  str_homestory_814801001_38_dialog_content = "Kalau begitu, aku akan tinggal lebih lama untuk menikmati keramahan yang hangat ini.",
  str_homestory_814801001_39_dialog_content = "Caelestite Kecil, kau ingin aku tetap di sini?",
  str_homestory_814801001_40_option_content = "Konfirmasi",
  str_homestory_814801001_41_dialog_content = "Tentu saja... Kau boleh tetap di sini selama yang kaumau.",
  str_homestory_814801001_42_dialog_content = "Pintunya selalu terbuka untukmu.",
  str_homestory_814801001_43_option_content = "Bantah",
  str_homestory_814801001_44_dialog_content = "Aku... aku tak berani berharap...",
  str_homestory_814801001_45_dialog_content = "Kau, dan semua orang, boleh datang dan pergi semau kalian...",
  str_homestory_814801001_46_dialog_content = "Kalau begitu, aku akan mencoba kerasan di sini.",
  str_homestory_814801001_47_dialog_content = "Minta tokomu untuk memesan anggur yang lezat, ya.",
  str_homestory_814801001_48_dialog_content = "Aku sudah tak sabar lagi. Mengerti?",
  str_homestory_814801001_49_dialog_content = "Ya…",
  str_homestory_814801001_50_dialog_content = "Tunggu apa lagi?<sprite=emo_emo size=60 />",
  str_homestory_814801001_51_dialog_content = "Siap!",
  str_homestory_815001001_0_dialog_content = "Benar-benar diam tak bergerak...",
  str_homestory_815001001_1_dialog_content = "Halo, PlayerName.<sprite=emo_heimao size=60 />",
  str_homestory_815001001_2_dialog_content = "Lenore sangat senang bertemu denganmu.",
  str_homestory_815001001_3_dialog_content = "Lenore, kenapa kau berdiri mematung di sini?",
  str_homestory_815001001_4_dialog_content = "Mau jalan-jalan?",
  str_homestory_815001001_5_dialog_content = "Jalan-jalan?",
  str_homestory_815001001_6_dialog_content = "Ini perintah baru dari PlayerName?",
  str_homestory_815001001_7_dialog_content = "Aku harus pergi ke mana?",
  str_homestory_815001001_8_dialog_content = "Lenore, ini bukan perintah, kok. Anggap saja itu hanya sekadar nasihat.",
  str_homestory_815001001_9_dialog_content = "Memangnya, apa bedanya perintah dan nasihat?",
  str_homestory_815001001_10_dialog_content = "Hmm… Coba kupikir dulu.",
  str_homestory_815001001_11_dialog_content = "Perintah adalah sesuatu yang harus kaulakukan.",
  str_homestory_815001001_12_dialog_content = "Nah, nasihat hanya saran yang tak perlu kauturuti.",
  str_homestory_815001001_13_dialog_content = "Aku mengerti.",
  str_homestory_815001001_14_dialog_content = "PlayerName menasihati Lenore agar berjalan-jalan. Itu nasihat.",
  str_homestory_815001001_15_dialog_content = "Lenore boleh memilih untuk jalan-jalan atau tidak.",
  str_homestory_815001001_16_dialog_content = "Pintar sekali! Rupanya kau paham!",
  str_homestory_815001001_17_dialog_content = "Terima kasih atas pujianmu, PlayerName.",
  str_homestory_815001001_18_dialog_content = "Sama-sama.",
  str_homestory_815001001_19_dialog_content = "...",
  str_homestory_815001001_20_dialog_content = "...",
  str_homestory_815001001_21_dialog_content = "...",
  str_homestory_815001001_22_dialog_content = "Eh... Lenore?",
  str_homestory_815001001_23_dialog_content = "Kau tak mau jalan-jalan, ya?",
  str_homestory_815001001_24_dialog_content = "Bukankah itu hanya nasihat?",
  str_homestory_815001001_25_dialog_content = "Lenore tak harus melakukannya.",
  str_homestory_815001001_26_dialog_content = "Ahh...",
  str_homestory_815001001_27_dialog_content = "Aku menanam banyak bunga dan pohon yang indah. Beberapa fasilitas hiburan baru juga sudah dipasang!",
  str_homestory_815001001_28_dialog_content = "Memangnya kau tak ingin melihatnya?",
  str_homestory_815001001_29_dialog_content = "Apa Lenore harus ingin melihatnya?",
  str_homestory_815001001_30_option_content = "Beri perintah",
  str_homestory_815001001_31_dialog_content = "Hmm... Tak ada cara lain. Baiklah. Kuperintahkan Lenore untuk melihat-lihat.",
  str_homestory_815001001_32_dialog_content = "Ya. Lenore akan menyelesaikan misi ini.",
  str_homestory_815001001_33_option_content = "Beri saran",
  str_homestory_815001001_34_dialog_content = "Aku tahu ini kedengarannya menyombong, tapi hasil kerja kerasku boleh juga, lho.",
  str_homestory_815001001_35_dialog_content = "Jadi... Kurasa sebaiknya kau melihatnya.",
  str_homestory_815001001_36_dialog_content = "Karena PlayerName bilang begitu, Lenore akan pergi.",
  str_homestory_815001001_37_dialog_content = "Ya. Sana pergi. Bersenang-senanglah.",
  str_homestory_815001001_38_dialog_content = "Tapi, Lenore harus pergi ke mana?",
  str_homestory_815001001_39_dialog_content = "PlayerName, kau punya nasihat untuk Lenore?",
  str_homestory_815001001_40_dialog_content = "Ah!",
  str_homestory_815001001_41_dialog_content = "Kenapa, PlayerName?",
  str_homestory_815001001_42_dialog_content = "Bukan apa-apa…",
  str_homestory_815001001_43_dialog_content = "Lenore, kau benar-benar sudah memahami arti kata \"nasihat\", ya.",
  str_homestory_815001001_44_dialog_content = "Aku jadi agak terharu...",
  str_homestory_801901001_0_dialog_content = "Victoria...",
  str_homestory_801901001_1_dialog_content = "Hai, PlayerName.",
  str_homestory_801901001_2_dialog_content = "Victoria, senang bertemu denganmu.",
  str_homestory_801901001_3_dialog_content = "Aku sedang mengagumi sungai-sungai yang indah ini. Mau ikut?",
  str_homestory_801901001_4_dialog_content = "Mengagumi sungai?",
  str_homestory_801901001_5_dialog_content = "Maaf, nih... Tapi, apa istimewanya sungai yang melintasi kebun batu?",
  str_homestory_801901001_6_dialog_content = "Tanpa sadar, airnya sudah mengalami siklus yang tak berujung.",
  str_homestory_801901001_7_dialog_content = "Menurutmu, bukankah ini sangat mirip dengan kita, para Aurorian?",
  str_homestory_801901001_8_option_content = "Mengangguk",
  str_homestory_801901001_9_dialog_content = "Iya, sih. Sedikit...",
  str_homestory_801901001_10_dialog_content = "Tapi, aku tak benar-benar memahami ucapanmu...",
  str_homestory_801901001_11_option_content = "Menggelengkan kepala",
  str_homestory_801901001_12_dialog_content = "Maaf, Victoria...",
  str_homestory_801901001_13_dialog_content = "Aku agak bingung.",
  str_homestory_801901001_14_dialog_content = "Tak perlu dipikirkan. Komentarku tidak penting.",
  str_homestory_801901001_15_dialog_content = "Memangnya apa yang kaupikirkan, Victoria?",
  str_homestory_801901001_16_dialog_content = "Air ini tak tahu bahwa ia mengikuti siklus.",
  str_homestory_801901001_17_dialog_content = "Karena ia mengalir tanpa tujuan.",
  str_homestory_801901001_18_dialog_content = "Air ini tak tahu kenapa ia mengalir, bagaimana cara melarikan diri dari siklus ini, atau di mana ujungnya.",
  str_homestory_801901001_19_dialog_content = "Seperti inilah cara hidup sebagian besar dari kita. Iya, 'kan?",
  str_homestory_801901001_20_dialog_content = "Bukannya aku mengkritik atau mengasihani.",
  str_homestory_801901001_21_dialog_content = "Cara hidup seseorang sudah tak ada bedanya bagiku.",
  str_homestory_801901001_22_dialog_content = "Aku hanya mencoba berpikir.",
  str_homestory_801901001_23_dialog_content = "... Mencoba berpikir?",
  str_homestory_801901001_24_dialog_content = "Ya.",
  str_homestory_801901001_25_dialog_content = "Kita harus menghormati pikiran. Apa pun yang mendorongmu untuk berpikir ada di luar pemahamanmu saat ini.",
  str_homestory_801901001_26_dialog_content = "... Maksudmu... kita harus menghormati sesuatu yang tak diketahui?",
  str_homestory_801901001_27_dialog_content = "Kurang lebih begitulah, Sayang.",
  str_homestory_801901001_28_dialog_content = "Sungai ini mungkin tampak gembira. Mereka tak butuh pendapat kita dalam alirannya.",
  str_homestory_801901001_29_dialog_content = "Merasa senang dan bahagia atas siklus ini adalah hal yang baik.",
  str_homestory_801901001_30_dialog_content = "Jadi... Mereka tak akan protes pada hal-hal semacam ini seperti yang kaulakukan?",
  str_homestory_801901001_31_dialog_content = "Heheh. Siapa tahu?",
  str_homestory_801901001_32_dialog_content = "Omong-omong... Matahari di sini sangat terik<sprite=emo_taiyang size=60 />.",
  str_homestory_801901001_33_dialog_content = "Eh... Ada payung di sebelah sana. Victoria, kau mau bergeser?",
  str_homestory_801901001_34_dialog_content = "Terima kasih atas kepedulianmu, PlayerName. Aku butuh istirahat.",
  str_homestory_801901001_35_dialog_content = "Semoga Truth memberkatimu!",
  str_homestory_800901001_0_dialog_content = "Faust?",
  str_homestory_800901001_1_dialog_content = "Navigator yang terhormat, senang bertemu denganmu lagi.",
  str_homestory_800901001_2_dialog_content = "Begitu juga denganku.",
  str_homestory_800901001_3_dialog_content = "Sebenarnya, aku tak menyangka bakal bertemu denganmu saat siang.",
  str_homestory_800901001_4_dialog_content = "Tolong jangan salah paham. Aku sendiri lebih suka malam, tapi aku tak keberatan dengan energi siang hari.",
  str_homestory_800901001_5_dialog_content = "Sepertinya Wispy senang di sini.",
  str_homestory_800901001_6_dialog_content = "... Sebentar. Wispy senang di sini?",
  str_homestory_800901001_7_dialog_content = "Memangnya ada kesedihan dan penderitaan di tempat ini?",
  str_homestory_800901001_8_dialog_content = "Aku masih ingat koper spesial itu meneteskan liurnya saat melihatku tak berdaya...",
  str_homestory_800901001_9_dialog_content = "Wispy bisa merasa terhibur dengan banyak hal.",
  str_homestory_800901001_10_dialog_content = "Kenangan sedih, mimpi buruk, keyakinan putus asa, atau air dingin...",
  str_homestory_800901001_11_dialog_content = "Hah?!",
  str_homestory_800901001_12_dialog_content = "(Kalau kuingat-ingat lagi waktu yang kuhabiskan saat menjaga Wispy...<sprite=emo_sikao size=60 />)",
  str_homestory_800901001_13_dialog_content = "(Orang-orang merasa sedih dan mengalami mimpi buruk di sini?)",
  str_homestory_800901001_14_dialog_content = "Navigator yang terhormat, tolong jangan terlalu dipikirkan.",
  str_homestory_800901001_15_dialog_content = "Hiburan Wispy...",
  str_homestory_800901001_16_dialog_content = "Mungkin berasal dari masa lalu Aurorian, bukan perasaan mereka saat ini.",
  str_homestory_800901001_17_dialog_content = "Setahuku, banyak dari kita memiliki masa lalu yang pahit dan menyakitkan.",
  str_homestory_800901001_18_dialog_content = "Kalau menurutmu begitu...",
  str_homestory_800901001_19_dialog_content = "Ya... Itu benar.",
  str_homestory_800901001_20_dialog_content = "Semoga semua orang merasa gembira di sini.",
  str_homestory_800901001_21_dialog_content = "Kadang memori dan emosi ada di luar kendali kita, Navigator yang terhormat.",
  str_homestory_800901001_22_dialog_content = "Tidak terlalu mencemaskan orang lain adalah kebiasaan baik.",
  str_homestory_800901001_23_dialog_content = "Biar alam yang menentukan jalannya.",
  str_homestory_800901001_24_dialog_content = "… Oke.",
  str_homestory_800901001_25_dialog_content = "Lalu, untuk apa kau kemari?",
  str_homestory_800901001_26_option_content = "Mau menyebarkan Truth?",
  str_homestory_800901001_27_dialog_content = "Tidak, Navigator yang terhormat.",
  str_homestory_800901001_28_option_content = "Memberi makan Wispy?",
  str_homestory_800901001_29_dialog_content = "Iya, Navigator Sayang.",
  str_homestory_800901001_30_dialog_content = "Ini tempat yang cocok untuk memberi makan Wispy...",
  str_homestory_800901001_31_dialog_content = "Wispy bisa bebas merasakan orang yang lewat.",
  str_homestory_800901001_32_dialog_content = "Biarkan Wispy merasakan dengan bebas...",
  str_homestory_800901001_33_dialog_content = "Eh... Apa ada banyak rasa sakit yang sangat dalam di hati mereka?",
  str_homestory_800901001_34_dialog_content = "Aku pun tak tahu jawabannya, Navigator Sayang.",
  str_homestory_800901001_35_dialog_content = "Tapi, ada satu hal yang aku tahu pasti.",
  str_homestory_800901001_36_dialog_content = "Ya?",
  str_homestory_800901001_37_dialog_content = "Wispy minum banyak air dingin sebelum kami berangkat.",
  str_homestory_800901001_38_dialog_content = "?",
  str_homestory_800901001_39_dialog_content = "Jadi, hiburan Wispy bisa jadi dari air es yang dia minum?",
  str_homestory_800901001_40_dialog_content = "Berarti tak ada banyak kesedihan, rasa sakit, atau perasaan negatif lainnya.",
  str_homestory_800901001_41_dialog_content = "Kau menipuku!",
  str_homestory_800901001_42_dialog_content = "Sepertinya begitu, Navigator Sayang.",
  str_homestory_800901001_43_dialog_content = "Tapi, aku melakukannya agar pikiranmu teralih dari segala pekerjaan dan tekanan.",
  str_homestory_800901001_44_dialog_content = "Tak semuanya harus sempurna, 'kan?",
  str_homestory_800901001_45_dialog_content = "Semoga Truth memberkatimu!",
  str_homestory_800901001_46_dialog_content = "Apa-apaan kau…!<sprite=emo_shengqi size=60 />",
  str_homestory_815101001_0_dialog_content = "Lagu anak-anak ini...",
  str_homestory_815101001_1_dialog_content = "Ada seekor domba hitam bernama Isaac. Bulu yang menakutkan bisa membakar lenganmu!",
  str_homestory_815101001_2_dialog_content = "Hai, Giles!",
  str_homestory_815101001_3_dialog_content = "Ah. Navigator Sayang.",
  str_homestory_815101001_4_dialog_content = "Aku hampir lupa. Kau pasti pernah mendengar lagu anak-anak ini.",
  str_homestory_815101001_5_dialog_content = "Apa sudah waktunya menyanyikan yang baru?",
  str_homestory_815101001_6_dialog_content = "Sebuah karya baru yang agak bertema ramalan dan berpusat pada Caelestite yang menarik...<sprite=emo_baimao size=60 />",
  str_homestory_815101001_7_dialog_content = "Eh…",
  str_homestory_815101001_8_dialog_content = "Sepertinya kau enggan, ya, Navigator?",
  str_homestory_815101001_9_dialog_content = "Aduh, aku jadi sedih...",
  str_homestory_815101001_10_dialog_content = "Kau bilang kau suka lagu anak-anak yang kunyanyikan...",
  str_homestory_815101001_11_dialog_content = "(.... Masa, sih?)",
  str_homestory_815101001_12_option_content = "Kau sudah selesai membuat lagu baru?",
  str_homestory_815101001_13_dialog_content = "Tak butuh waktu lama kalau ada inspirasi.",
  str_homestory_815101001_14_dialog_content = "Bagus. Sumber inspirasinya tepat di depan mataku...",
  str_homestory_815101001_15_option_content = "Tunggu sebentar, ya?",
  str_homestory_815101001_16_dialog_content = "Kau bahkan tak mau repot-repot mencari alasan.",
  str_homestory_815101001_17_dialog_content = "Bagiku, ini jelas penolakan.",
  str_homestory_815101001_18_dialog_content = "Dengan pesona dan kelincahannya, si Caelestite bisa dengan mudah mencuri hatimu...",
  str_homestory_815101001_19_dialog_content = "... Sudah mulai, nih?",
  str_homestory_815101001_20_dialog_content = "La la la! La la la! Rumah indah yang penuh bunga.",
  str_homestory_815101001_21_dialog_content = "Ikan dan udang juga menyebutnya rumah.",
  str_homestory_815101001_22_dialog_content = "Dia tinggal di sini dengannya. Bersama-sama mereka mendekap Caelestite pemberani.",
  str_homestory_815101001_23_dialog_content = "Tik tik... Tik tik... Gerimis hujan waktu.",
  str_homestory_815101001_24_dialog_content = "Bangun menara tinggi. Perkuat dengan batu bata dan ubin. Cari cara jadi lebih kuat.",
  str_homestory_815101001_25_dialog_content = "La la la! La la la! Di mana Caelestite itu sekarang?",
  str_homestory_815101001_26_dialog_content = "Kini rumahnya besar dan tinggi. Lihat Caelestite di atas awan, tak berkedip.",
  str_homestory_815101001_27_dialog_content = "La la la! La la la! Rumah indah yang penuh bunga....",
  str_homestory_815101001_28_dialog_content = "... Ini ramalanmu?",
  str_homestory_815101001_29_dialog_content = "Ini hanya lagu anak-anak sederhana, Navigator.",
  str_homestory_815101001_30_dialog_content = "Kau takut, ya? Ini hanya karya buatanku...",
  str_homestory_815101001_31_dialog_content = "Iya, aku tahu.",
  str_homestory_815101001_32_dialog_content = "Kadang lagumu memang sederhana, tapi tak jelas.",
  str_homestory_815101001_33_dialog_content = "Lagu anak-anak tak lebih dari sekadar lagu anak-anak.",
  str_homestory_815101001_34_dialog_content = "Navigator, tolong jangan terlalu dipikirkan.",
  str_homestory_815101001_35_dialog_content = "Baiklah. Kita kembali ke kehidupan nyata...",
  str_homestory_815101001_36_dialog_content = "Bagaimana kabarmu di sini?",
  str_homestory_815101001_37_dialog_content = "Aku dan Isaac sangat menyukainya.",
  str_homestory_815101001_38_dialog_content = "Aku jadi punya hasrat kuat untuk menulis lebih banyak... Hahah!",
  str_homestory_815101001_39_dialog_content = "Baik pejalan kaki yang lewat maupun Navigator, semuanya jadi sumber inspirasiku.<sprite=emo_emo size=60 />",
  str_homestory_815101001_40_dialog_content = "Baguslah kalau begitu...",
  str_homestory_815101001_41_dialog_content = "Mbeeek... Mbeeek...",
  str_homestory_815101001_42_dialog_content = "Sebentar, ya. Aku harus mengurus Isaac. Permisi, Navigator.",
  str_homestory_815101001_43_dialog_content = "Sampai jumpa, ya?",
  str_homestory_815101001_44_dialog_content = "Baiklah... Sampai jumpa.",
  str_homestory_815301001_0_dialog_content = "Grand Marshal?",
  str_homestory_815301001_1_dialog_content = "Infrastrukturmu bagus.<sprite=emo_dianzan size=60 />",
  str_homestory_815301001_2_dialog_content = "Terima kasih atas pujianmu, Grand Marshal!",
  str_homestory_815301001_3_dialog_content = "Aku sangat terbiasa melihat kotak-kotak rapi dan seragam di Illumina. Yang ini berbeda dan segar.",
  str_homestory_815301001_4_dialog_content = "Orang-orang memandang rendah Illumina karena selera seni kami yang buruk dan standar keindahan yang rendah.",
  str_homestory_815301001_5_dialog_content = "Sayangnya, banyak tempat yang mengejar kesempurnaan seni itu sebenarnya kesulitan memberi makan rakyat.",
  str_homestory_815301001_6_dialog_content = "Hal-hal yang terstruktur dengan baik butuh biaya lebih rendah dan berfungsi dengan lebih efisien. Ini mudah untuk dimengerti.",
  str_homestory_815301001_7_dialog_content = "Tapi, harus kuakui tempat ini memang indah.",
  str_homestory_815301001_8_dialog_content = "Bagus dan rapi. Kau dan Vice pasti berusaha keras untuk mengerjakan ini.",
  str_homestory_815301001_9_option_content = "Mengangguk",
  str_homestory_815301001_10_dialog_content = "Sebagian besar karena Vice... Aku tak begitu paham tentang semua ini.",
  str_homestory_815301001_11_dialog_content = "Mengakui kekurangan diri sendiri adalah hal yang baik.",
  str_homestory_815301001_12_option_content = "Menggelengkan kepala",
  str_homestory_815301001_13_dialog_content = "Lumayan juga. Firefly banyak membantu. Begitu juga dengan teman-teman kami dari Courier Union.",
  str_homestory_815301001_14_dialog_content = "Kami senang melakukannya asalkan semua orang merasa gembira di sini.",
  str_homestory_815301001_15_dialog_content = "Ini memang karakter paling mulia yang kalian berdua miliki, ya?",
  str_homestory_815301001_16_dialog_content = "Menurutku, merasa senang karena bisa melayani orang lain adalah anugerah istimewa.",
  str_homestory_815301001_17_dialog_content = "Karena kalian sudah mengatur semuanya dengan penuh perhatian...",
  str_homestory_815301001_18_dialog_content = "Aku bisa menempati kamar yang seperti milik Vice. Dan kita juga menyantap makanan yang sama setiap hari.",
  str_homestory_815301001_19_dialog_content = "Kalian memperlakukanku dengan lebih baik ketimbang kebanyakan orang.",
  str_homestory_815301001_20_dialog_content = "Tidak mudah melayani semua orang terlepas dari status dan jabatan mereka.",
  str_homestory_815301001_21_dialog_content = "(Tak kusangka Grand Marshal memandang segala sesuatunya dari sudut ini...)",
  str_homestory_815301001_22_dialog_content = "(Apa aku harus jujur, ya?)",
  str_homestory_815301001_23_dialog_content = "(Baiklah... Sebaiknya aku jujur saja...)",
  str_homestory_815301001_24_dialog_content = "Sebenarnya, Grand Marshal...",
  str_homestory_815301001_25_dialog_content = "Kami tak sanggup menyediakan kamar yang lebih bagus...",
  str_homestory_815301001_26_dialog_content = "Aku tahu.",
  str_homestory_815301001_27_dialog_content = "Ini bukan masalah seberapa besar anggaranmu, tapi rencana penggunaan uangnya.",
  str_homestory_815301001_28_dialog_content = "Sepertinya aku paham maksudmu...",
  str_homestory_815301001_29_dialog_content = "Bagus.",
  str_homestory_815301001_30_dialog_content = "Aku mau mengunjungi kawan Illumina-ku dulu.",
  str_homestory_815301001_31_dialog_content = "Sampai jumpa, PlayerName.",
  str_homestory_815301001_32_dialog_content = "Suatu kehormatan bisa bicara denganmu, Grand Marshal!",
  str_homestory_803801001_0_dialog_content = "Mau main lagi?",
  str_homestory_803801001_1_dialog_content = "Hai, PlayerName!",
  str_homestory_803801001_2_dialog_content = "Heheh... Mau bermain?",
  str_homestory_803801001_3_dialog_content = "Ah, tidak.",
  str_homestory_803801001_4_dialog_content = "Aku hanya ingin tanya bagaimana kabarmu di sini.",
  str_homestory_803801001_5_dialog_content = "Anu...",
  str_homestory_803801001_6_dialog_content = "Lumayan juga, sih. Tapi, aku butuh lebih banyak fasilitas hiburan.",
  str_homestory_803801001_7_dialog_content = "Hmm. Aku mengerti! PlayerName yang sangat manis pasti kemari untuk membantuku agar tidak bosan. Iya, 'kan?",
  str_homestory_803801001_8_dialog_content = "Eh... Aku...",
  str_homestory_803801001_9_dialog_content = "Heheh. Ayo main suatu permainan sederhana...",
  str_homestory_803801001_10_dialog_content = "Ini sangat mudah. Kita tak butuh perangkat apa pun, kok!",
  str_homestory_803801001_11_dialog_content = "Maksudmu... Suit?",
  str_homestory_803801001_12_dialog_content = "Bukan! Kuis!",
  str_homestory_803801001_13_dialog_content = "Siap? Permainan segera dimulai!",
  str_homestory_803801001_14_dialog_content = "Baiklah... Habis kau ngotot begini.",
  str_homestory_803801001_15_dialog_content = "Pertanyaan 1! Jawab benar atau salah!",
  str_homestory_803801001_16_dialog_content = "Pengungkapan asal-usul misterius Illumina Tech Officer Gronru... Dia sebenarnya adalah android!",
  str_homestory_803801001_17_option_content = "Benar",
  str_homestory_803801001_18_dialog_content = "Apa-apaan kau ini? Aku kan bukan android!",
  str_homestory_803801001_19_option_content = "Salah",
  str_homestory_803801001_20_dialog_content = "Mantap! Benar!<sprite=emo_dianzan size=60 />",
  str_homestory_803801001_21_dialog_content = "Pertanyaan 2!",
  str_homestory_803801001_22_dialog_content = "Raphael pernah mengalahkan Gronru dalam Emperor's Cup!",
  str_homestory_803801001_23_option_content = "Benar",
  str_homestory_803801001_24_dialog_content = "Hei! Tak ada yang bisa mengalahkanku, tahu?",
  str_homestory_803801001_25_dialog_content = "Aku bahkan membantunya untuk menyempurnakan gawainya.",
  str_homestory_803801001_26_option_content = "Salah",
  str_homestory_803801001_27_dialog_content = "Benar! Bagus sekali!",
  str_homestory_803801001_28_dialog_content = "Pertanyaan 3!",
  str_homestory_803801001_29_dialog_content = "PlayerName akan mentransfer izin sistem operasi tempat ini kepada Gronru!",
  str_homestory_803801001_30_dialog_content = "Benar...",
  str_homestory_803801001_31_dialog_content = "Sebentar! Pertanyaan semacam ini seharusnya tak boleh dimasukkan ke dalam kuis apa pun!",
  str_homestory_803801001_32_dialog_content = "Aduh... Tidak boleh, ya?",
  str_homestory_803801001_33_dialog_content = "Eh... Tentu saja tidak boleh, Gronru!",
  str_homestory_803801001_34_dialog_content = "Hmm! Kau menolakku, nih?",
  str_homestory_803801001_35_dialog_content = "Kau pasti sudah kerasukan Final Boss!",
  str_homestory_803801001_36_dialog_content = "Kerasukan? Kok kau bisa bilang begitu?",
  str_homestory_803801001_37_dialog_content = "Caelestite sejati tak boleh menolak permintaanku!",
  str_homestory_803801001_38_dialog_content = "Dulu, Caelestite yang sangat ramah tak pernah menolak satu pun permintaanku!",
  str_homestory_803801001_39_dialog_content = "Pfft...",
  str_homestory_803801001_40_dialog_content = "Mungkin aku bakal memberikan apa pun kepadamu kecuali izin atas Colossus dan tempat ini, Gronru.",
  str_homestory_803801001_41_dialog_content = "Ahh... Dasar membosankan...",
  str_homestory_803801001_42_dialog_content = "Tapi...",
  str_homestory_803801001_43_dialog_content = "Karena kau menolak permintaan penelitianku, aku akan melakukannya secara diam-diam!",
  str_homestory_803801001_44_dialog_content = "Suatu hari nanti... Heheh! Suatu hari nanti! Akan kucari tahu cara sistem ini beroperasi!",
  str_homestory_803801001_45_dialog_content = "Baiklah.",
  str_homestory_803801001_46_dialog_content = "Semoga berhasil, ya.",
  str_homestory_803801001_47_dialog_content = "Permainan baru sudah dimulai! Menarik sekali...<sprite=emo_yaosu size=60 />",
  str_homestory_802601001_0_dialog_content = "Uriel...",
  str_homestory_802601001_1_dialog_content = "...",
  str_homestory_802601001_2_dialog_content = "...",
  str_homestory_802601001_3_dialog_content = "K-kau mau apa?",
  str_homestory_802601001_4_dialog_content = "Ah... Tidak, kok. Aku hanya ingin menemuimu.",
  str_homestory_802601001_5_dialog_content = "Aku mencemaskan keadaanmu di sini. Aku ingat dulu kau sering tak bisa tidur di Colossus.",
  str_homestory_802601001_6_dialog_content = "Tak ada yang tak baik-baik saja...",
  str_homestory_802601001_7_dialog_content = "Lagi pula, dua hal yang sangat kupedulikan adalah Ring of Fire dan Phoenix Coat...",
  str_homestory_802601001_8_dialog_content = "Eh... Kalau begitu, ada yang bisa kubantu carikan?",
  str_homestory_802601001_9_dialog_content = "Makanan, mainan, apa pun?",
  str_homestory_802601001_10_dialog_content = "Bilang saja kepadaku!",
  str_homestory_802601001_11_dialog_content = "Aku tak mau apa-apa...",
  str_homestory_802601001_12_dialog_content = "Nanti aku malah membakar<sprite=emo_nuhuo size=60 /> semuanya sampai hangus...",
  str_homestory_802601001_13_dialog_content = "Tak mungkin, Uriel.",
  str_homestory_802601001_14_dialog_content = "Aku sudah memasang fasilitas pencegahan kebakaran di sini. Kau tak perlu mencemaskan apa pun!",
  str_homestory_802601001_15_dialog_content = "Begitu rupanya...",
  str_homestory_802601001_16_dialog_content = "Ya!",
  str_homestory_802601001_17_dialog_content = "Butuh sesuatu?",
  str_homestory_802601001_18_dialog_content = "...",
  str_homestory_802601001_19_dialog_content = "... Tidak.",
  str_homestory_802601001_20_dialog_content = "Kegembiraan dari mainan dan fasilitas hiburan tak bisa bertahan lama...",
  str_homestory_802601001_21_dialog_content = "Hanya sesaat dan palsu...",
  str_homestory_802601001_22_dialog_content = "Sebenarnya, kegembiraan sementara semacam itu sering diiringi dengan rasa sakit yang tak berujung...",
  str_homestory_802601001_23_dialog_content = "Pikirkan saja penderitaan yang akan kau tanggung saat terbakar hanya demi kebahagiaan sesaat ini...",
  str_homestory_802601001_24_dialog_content = "Lebih baik tidak...",
  str_homestory_802601001_25_dialog_content = "Selain itu... Tak selalu ada kegembiraan setelah rasa sakit...",
  str_homestory_802601001_26_dialog_content = "Justru sebaliknya, kegembiraan sesaat bisa menyesatkan, menciptakan ilusi bahwa penderitaanmu selalu terbayar...",
  str_homestory_802601001_27_dialog_content = "Tapi, itu sama sekali tidak benar karena penderitaan tak ada habisnya dan \"kegembiraan\" itu terbatas...<sprite=emo_xinsui size=60 />",
  str_homestory_802601001_28_dialog_content = "... Kau setuju, 'kan, PlayerName?",
  str_homestory_802601001_29_dialog_content = "(Semuanya memang terdengar masuk akal, tapi aku tak begitu bisa mengikuti logikanya...)",
  str_homestory_802601001_30_option_content = "Ya",
  str_homestory_802601001_31_dialog_content = "Kau mungkin benar dalam beberapa hal, Uriel.",
  str_homestory_802601001_32_option_content = "Tidak",
  str_homestory_802601001_33_dialog_content = "Aku paham alasanmu, tapi tak setuju denganmu...",
  str_homestory_802601001_34_dialog_content = "(Sekarang yang penting aku harus menenangkannya...)",
  str_homestory_802601001_35_dialog_content = "Uriel percaya bahwa kegembiraan setelah rasa sakit itu palsu dan hanya sesaat...",
  str_homestory_802601001_36_dialog_content = "Tapi, banyak orang menyukai kegembiraan sesaat ini.",
  str_homestory_802601001_37_dialog_content = "Kadang, kebahagiaan kecil setelah menderita adalah harapan.",
  str_homestory_802601001_38_dialog_content = "Dan harapan inilah yang membuat kita terus bertahan hingga kegembiraan berikutnya...",
  str_homestory_802601001_39_dialog_content = "Tapi, betapa singkat dan kecilnya kegembiraan itu setiap kali, hal ini membuat kita lega.",
  str_homestory_802601001_40_dialog_content = "Kebahagiaan bukanlah imbalan atas rasa sakit yang kita alami.",
  str_homestory_802601001_41_dialog_content = "Justru sebaliknya, itulah nutrisi yang sangat kita perlukan untuk terus menahan rasa sakit.",
  str_homestory_802601001_42_dialog_content = "...",
  str_homestory_802601001_43_dialog_content = "... Nutrisi...",
  str_homestory_802601001_44_dialog_content = "... Mungkin...",
  str_homestory_802601001_45_dialog_content = "(Sepertinya dia belum percaya...)",
  str_homestory_802601001_46_dialog_content = "Ahh... Pokoknya, jangan anggap kebahagiaan sebagai beban, Uriel!",
  str_homestory_802601001_47_dialog_content = "... Baiklah...",
  str_homestory_802601001_48_dialog_content = "... Aku paham, PlayerName...",
  str_homestory_802601001_49_dialog_content = "... Terima kasih atas kepedulianmu...",
  str_homestory_802601001_50_dialog_content = "Bukan masalah...",
  str_homestory_802601001_51_dialog_content = "Ahh... Bicara soal kebahagiaan...",
  str_homestory_802601001_52_dialog_content = "(Aku ingat dia cukup suka membaca, terutama karya sastra populer di Umbraton...)",
  str_homestory_802601001_53_dialog_content = "Uriel, bagaimana kalau kupinjamkan beberapa buku untukmu?",
  str_homestory_802601001_54_dialog_content = "Kau bisa membacanya kalau sedang bosan.",
  str_homestory_802601001_55_dialog_content = "Tenang saja. Sekarang, banyak sekali yang tinggal di sini. Aku punya beberapa salinan untuk setiap buku...",
  str_homestory_802601001_56_dialog_content = "... Buku...",
  str_homestory_802601001_57_dialog_content = "...",
  str_homestory_802601001_58_dialog_content = "... Kedengarannya bagus...",
  str_homestory_802601001_59_dialog_content = "Aku mau membaca...",
  str_homestory_802601001_60_dialog_content = "Fyuh... Bagus sekali.",
  str_homestory_804401001_0_dialog_content = "Vivian?",
  str_homestory_804401001_1_dialog_content = "Ayunannya sangat menyenangkan, PlayerName!",
  str_homestory_804401001_2_dialog_content = "Iya! Aku setuju.",
  str_homestory_804401001_3_dialog_content = "Angin meniup mukaku dengan lembut. Tak ada satu hal pun yang kucemaskan...<sprite=emo_pugongying size=60 />",
  str_homestory_804401001_4_dialog_content = "Ayunan itu mendorongku pelan ke dalam dekapan angin...",
  str_homestory_804401001_5_dialog_content = "Ajaib. Stresku langsung hilang.",
  str_homestory_804401001_6_dialog_content = "Aku senang kalau kau bisa relaks saat bermain ayunan.",
  str_homestory_804401001_7_dialog_content = "Hmm... Satu-satunya kekurangan kegiatan hiburan ini adalah...",
  str_homestory_804401001_8_dialog_content = "Rambutku jadi agak kusut setelahnya. Hahah.",
  str_homestory_804401001_9_dialog_content = "Benar sekali!",
  str_homestory_804401001_10_dialog_content = "Wah, pantas saja Vice bersikeras merapikan rambutnya setiap kali dia turun dari ayunan!",
  str_homestory_804401001_11_dialog_content = "Jadi... Siapa yang punya ide memasang ayunan? Kau atau Vice?",
  str_homestory_804401001_12_option_content = "Aku.",
  str_homestory_804401001_13_dialog_content = "Sejujurnya, aku tidak bermain ayunan saat masih kecil dulu...",
  str_homestory_804401001_14_dialog_content = "Jadi, kupikir akan menyenangkan kalau kupasang ayunan di sini.",
  str_homestory_804401001_15_option_content = "Vice.",
  str_homestory_804401001_16_dialog_content = "Vice yang sangat menginginkannya!",
  str_homestory_804401001_17_dialog_content = "Awalnya, aku tidak yakin, tapi dia tetap meneruskan pembuatan gambar konstruksinya dengan percaya diri meski aku ragu. Kukira...",
  str_homestory_804401001_18_dialog_content = "Tak ada salahnya memasang ayunan di sini. Beberapa dari kalian mungkin menyukainya.",
  str_homestory_804401001_19_dialog_content = "Ahh...",
  str_homestory_804401001_20_dialog_content = "Ini keputusan yang bagus!",
  str_homestory_804401001_21_dialog_content = "Heheh... Terima kasih atas pujianmu, Vivian.",
  str_homestory_804401001_22_dialog_content = "Bicara soal ayunan...",
  str_homestory_804401001_23_dialog_content = "Tak banyak jumlahnya di Illumina.",
  str_homestory_804401001_24_dialog_content = "Hmm... Benarkah?",
  str_homestory_804401001_25_dialog_content = "Mungkin itu sebabnya Vice dan Vivian sangat menyukai ayunan ini.",
  str_homestory_804401001_26_dialog_content = "Iya. Hal-hal yang jarang terlihat justru lebih menarik.",
  str_homestory_804401001_27_dialog_content = "Hmm... Benar juga...",
  str_homestory_804401001_28_dialog_content = "Eh? Apa yang kaupikirkan?",
  str_homestory_804401001_29_dialog_content = "Ahh… Bukan apa-apa.",
  str_homestory_804401001_30_dialog_content = "Aku sedang menghitung seberapa perlu biaya <sprite=emo_baiyebi size=60 />ini.",
  str_homestory_804401001_31_dialog_content = "Biaya?",
  str_homestory_804401001_32_dialog_content = "Biaya apa?",
  str_homestory_804401001_33_dialog_content = "Aku jadi penasaran berapa besar biaya yang dibutuhkan untuk membuat ayunan...",
  str_homestory_804401001_34_dialog_content = "Di setiap panti asuhan, sekolah, dan pangkalan di Illumina.",
  str_homestory_804401001_35_dialog_content = "Ah, begitu.",
  str_homestory_804401001_36_dialog_content = "Sepertinya anggaran kami tak cukup untuk membiayai proyek ini...",
  str_homestory_804401001_37_dialog_content = "Kecuali anggaran untuk proyek lain bisa dipangkas.",
  str_homestory_804401001_38_dialog_content = "Hmm... Itu sulit.",
  str_homestory_804401001_39_dialog_content = "Bagaimana kalau jumlah ayunannya dikurangi?",
  str_homestory_804401001_40_dialog_content = "Jumlah ayunan lebih sedikit di lokasi-lokasi yang lebih baik?",
  str_homestory_804401001_41_dialog_content = "Misalnya...",
  str_homestory_804401001_42_dialog_content = "Di suatu tempat yang bakal dilewati banyak orang!",
  str_homestory_804401001_43_dialog_content = "Misalnya, di persimpangan antara Undercity, dan di tengah-tengah beberapa panti asuhan dan sekolah...",
  str_homestory_804401001_44_dialog_content = "Wah, kau genius juga, PlayerName Kecil!",
  str_homestory_804401001_45_dialog_content = "Senang bisa membantu.",
  str_homestory_804401001_46_dialog_content = "Tapi...",
  str_homestory_804401001_47_dialog_content = "Kenapa kau jadi sangat gugup saat aku menyinggung soal anggaran tadi?",
  str_homestory_804401001_48_dialog_content = "Hah... Ah hah...",
  str_homestory_804401001_49_dialog_content = "Kau terdengar seperti Vice kalau dia sedang memeriksa buku besar...",
  str_homestory_804401001_50_dialog_content = "Mungkin itu respons yang dikondisikan, ya!",
  str_homestory_804401001_51_dialog_content = "Aww... Rupanya Vice Kecil dan PlayerName Kecil sangat akrab...<sprite=emo_guilian size=60 />",
  str_homestory_808501001_0_dialog_content = "Jane?",
  str_homestory_808501001_1_dialog_content = "Halo, PlayerName.",
  str_homestory_808501001_2_dialog_content = "Ah, Jane!",
  str_homestory_808501001_3_dialog_content = "Kau... mencatat berbagai hal tentang Cloud Gardens?",
  str_homestory_808501001_4_dialog_content = "Iya, akan kucatat apa pun yang terjadi di sini.",
  str_homestory_808501001_5_dialog_content = "Tapi, sekarang aku tak sedang mencatat. Ini saatnya untuk benar-benar membiarkannya.<sprite=emo_pugongying size=60 />",
  str_homestory_808501001_6_dialog_content = "Membiarkannya?",
  str_homestory_808501001_7_dialog_content = "Apa yang terjadi? Apa ada yang mengusik pikiranmu?",
  str_homestory_808501001_8_dialog_content = "Atau tekanannya terlalu besar?",
  str_homestory_808501001_9_dialog_content = "Sepertinya keduanya.",
  str_homestory_808501001_10_dialog_content = "PlayerName, sebagai Witness profesional, aku tak boleh mencampuri hal-hal tertentu.",
  str_homestory_808501001_11_dialog_content = "Ya, aku juga dengar tentang itu.",
  str_homestory_808501001_12_dialog_content = "Hmm…",
  str_homestory_808501001_13_dialog_content = "Kalau jadi Witness, apa kau bakal membantu korban pertarungan geng?",
  str_homestory_808501001_14_option_content = "Tentu saja.",
  str_homestory_808501001_15_dialog_content = "Witness hanya pekerjaan...",
  str_homestory_808501001_16_option_content = "Tidak.",
  str_homestory_808501001_17_dialog_content = "Bagiku, bukan masalah kalau tetap bersikap benar-benar objektif...",
  str_homestory_808501001_18_dialog_content = "Mungkin aku akan segera minta bantuan.",
  str_homestory_808501001_19_dialog_content = "Jadi, kau ingin membantu, tapi tak mau terlibat?",
  str_homestory_808501001_20_dialog_content = "Benar sekali.",
  str_homestory_808501001_21_dialog_content = "Bagaimana denganmu, Jane?",
  str_homestory_808501001_22_dialog_content = "Pertanyaanmu barusan sangat spesifik. Pikiranmu terusik karena hal semacam ini, ya?",
  str_homestory_808501001_23_dialog_content = "Iya. Baru-baru ini aku membantu seorang gadis kecil.",
  str_homestory_808501001_24_dialog_content = "Saat itu, aku masih bingung dengan keputusan yang kuambil.",
  str_homestory_808501001_25_dialog_content = "Apa yang membuatmu khawatir?",
  str_homestory_808501001_26_dialog_content = "Bagaimana kalau gangguanku justru mengubah hal-hal yang seharusnya akan terjadi?",
  str_homestory_808501001_27_dialog_content = "Kalau Witness mengalami keraguan, kesaksiannya jadi tak netral lagi.",
  str_homestory_808501001_28_dialog_content = "Mungkin sudah jadi takdir gadis itu untuk meninggal. Dan itu yang seharusnya jadi konsekuensi pertarungan geng.",
  str_homestory_808501001_29_dialog_content = "Nah, karena aku menyelamatkannya...",
  str_homestory_808501001_30_dialog_content = "... Kesaksianku yang berat sebelah jadi tak ada artinya.",
  str_homestory_808501001_31_dialog_content = "Pertama-tama, kau adalah orang yang punya perasaan. Lalu, kau juga Witness yang berusaha sebaik mungkin untuk tetap netral.",
  str_homestory_808501001_32_dialog_content = "Aku paham.",
  str_homestory_808501001_33_dialog_content = "...",
  str_homestory_808501001_34_dialog_content = "... Begitu rupanya.",
  str_homestory_808501001_35_dialog_content = "Bagaimana kalau kau melibatkan diri dalam kesaksian ini?",
  str_homestory_808501001_36_dialog_content = "Melibatkan diri?",
  str_homestory_808501001_37_dialog_content = "Iya, tuliskan seluruh kronologinya dengan sebenar-benarnya.",
  str_homestory_808501001_38_dialog_content = "Karena merasa tergerak saat melihat TKP, seorang Witness turut campur tangan setelah pertarungan geng itu... Tindakan ini mungkin ada pengaruhnya.",
  str_homestory_808501001_39_dialog_content = "... Pokoknya semacam itu.",
  str_homestory_808501001_40_dialog_content = "...",
  str_homestory_808501001_41_dialog_content = "Kau benar.",
  str_homestory_808501001_42_dialog_content = "Akan kucoba mencatat insidennya dengan cara ini.",
  str_homestory_808501001_43_dialog_content = "Terima kasih.",
  str_homestory_808801001_0_dialog_content = "Maggie!",
  str_homestory_808801001_1_dialog_content = "Navigator... Kau juga kemari untuk mendengar kisah itu?<sprite=emo_wuzui size=60 />",
  str_homestory_808801001_2_dialog_content = "Hah? Kisah? Kisah apa?",
  str_homestory_808801001_3_dialog_content = "Tadinya aku mau mengajakmu mengobrol. Tapi, sekarang aku jadi tertarik dengan kisah yang kausebut barusan.",
  str_homestory_808801001_4_dialog_content = "Aduh... Aku kelepasan, deh...",
  str_homestory_808801001_5_dialog_content = "Hmm? Kau tak ingin aku tahu, ya, Maggie?",
  str_homestory_808801001_6_dialog_content = "Bukan begitu, sih...",
  str_homestory_808801001_7_dialog_content = "Baiklah... Toh, ini sudah bukan rahasia lagi...",
  str_homestory_808801001_8_dialog_content = "Ada apa?",
  str_homestory_808801001_9_dialog_content = "Hmm... Beberapa hari lalu, aku sedang menjelajahi gurun...",
  str_homestory_808801001_10_dialog_content = "Saat bertemu dengan beberapa anak secara kebetulan.",
  str_homestory_808801001_11_dialog_content = "Mereka kabur dari rumah dan malah tersesat di gurun yang luas...",
  str_homestory_808801001_12_dialog_content = "Karena kulihat mereka berjalan berputar-putar, aku pun menawarkan bantuan.",
  str_homestory_808801001_13_dialog_content = "Setelah kuantar mereka ke tempat yang aman, mereka menanyakan siapa namaku dan ingin mengunjungiku kapan-kapan untuk berterima kasih.",
  str_homestory_808801001_14_dialog_content = "Tapi, sebelum aku sempat memperkenalkan diri, mereka melihat ekorku... Lalu mereka...",
  str_homestory_808801001_15_option_content = "Mereka mengejekmu?",
  str_homestory_808801001_16_dialog_content = "Tidak...",
  str_homestory_808801001_17_dialog_content = "Mereka bilang ekorku sangat lucu!",
  str_homestory_808801001_18_dialog_content = "Wah, itu bagus, 'kan?",
  str_homestory_808801001_19_option_content = "Mereka mengenalimu?",
  str_homestory_808801001_20_dialog_content = "Tidak...",
  str_homestory_808801001_21_dialog_content = "Aku tidak sepopuler Fleur...",
  str_homestory_808801001_22_dialog_content = "Tapi, mereka...",
  str_homestory_808801001_23_dialog_content = "Mereka salah mengiraku sebagai naga!",
  str_homestory_808801001_24_dialog_content = "?",
  str_homestory_808801001_25_dialog_content = "Aku juga terkejut mendengarnya...",
  str_homestory_808801001_26_dialog_content = "Menurutku, mereka sudah keterlaluan!",
  str_homestory_808801001_27_dialog_content = "Mereka bilang belum pernah melihat naga dengan ekor berbulu sebelumnya...",
  str_homestory_808801001_28_dialog_content = "Mereka meminta izin untuk menyentuh ekorku...",
  str_homestory_808801001_29_dialog_content = "Aku jadi sangat marah!<sprite=emo_wuyun size=60 />",
  str_homestory_808801001_30_dialog_content = "Lho, kenapa? Kenapa tak kaujelaskan saja pada mereka?",
  str_homestory_808801001_31_dialog_content = "Aku tak keberatan kalau mereka salah mengiraku sebagai makhluk lain, tapi sikap mereka menjengkelkan!",
  str_homestory_808801001_32_dialog_content = "\"Kami boleh pegang ekormu, tidak?\"",
  str_homestory_808801001_33_dialog_content = "Permintaan macam apa itu?",
  str_homestory_808801001_34_dialog_content = "Kepada siapa kau akan mengatakan hal semacam itu selain kepada hewan peliharaan?",
  str_homestory_808801001_35_dialog_content = "Aku... aku marah sekali...",
  str_homestory_808801001_36_dialog_content = "Aku ingin membakar semuanya<sprite=emo_nuhuo size=60 />! Sekarang!",
  str_homestory_808801001_37_dialog_content = "(Jangan lagi!)",
  str_homestory_808801001_38_dialog_content = "Tenangkan dirimu, Maggie!",
  str_homestory_808801001_39_dialog_content = "Bagaimana kalau mereka memang benar-benar menganggap ekormu sangat lucu?",
  str_homestory_808801001_40_dialog_content = "S-selama ini, menurutku juga begitu!",
  str_homestory_808801001_41_dialog_content = "... Sebenarnya, aku tak bisa membayangkanmu tanpa ekor manismu itu, Maggie.",
  str_homestory_808801001_42_dialog_content = "...",
  str_homestory_808801001_43_dialog_content = "... Sungguh?",
  str_homestory_808801001_44_dialog_content = "(Fyuh... Sepertinya sekarang kemarahannya sudah mereda...)",
  str_homestory_808801001_45_dialog_content = "Iya, Maggie! Aku bersumpah!",
  str_homestory_808801001_46_dialog_content = "... Baiklah...",
  str_homestory_808801001_47_dialog_content = "Ah! Omong-omong...",
  str_homestory_808801001_48_dialog_content = "Tadi kau bilang ini bukan rahasia lagi?",
  str_homestory_808801001_49_dialog_content = "Kurasa tak banyak yang tahu soal insiden ini...",
  str_homestory_808801001_50_dialog_content = "Karena…",
  str_homestory_808801001_51_dialog_content = "Jomu menyertakan ini dalam kumpulan kisah-kisah pendek terbaru...",
  str_homestory_808801001_52_dialog_content = "... Hmm... Seharusnya ini sudah kuperkirakan...",
  str_homestory_800801001_0_dialog_content = "Brock?",
  str_homestory_800801001_1_dialog_content = "Hahah! Senang bertemu denganmu.<sprite=emo_yaosu size=60 />",
  str_homestory_800801001_2_dialog_content = "Kaulihat itu? Keren juga, 'kan?",
  str_homestory_800801001_3_dialog_content = "Eh... Apa maksudmu, Brock?",
  str_homestory_800801001_4_dialog_content = "Pukulanku! Mantap! Keren!",
  str_homestory_800801001_5_dialog_content = "Eh... Lumayan, sih...",
  str_homestory_800801001_6_dialog_content = "Lumayan? Hanya lumayan?",
  str_homestory_800801001_7_dialog_content = "Sudahlah. Kau kan memang tak tahu apa-apa soal bertinju. Kau pasti merasa sangat iri sekarang.",
  str_homestory_800801001_8_dialog_content = "?",
  str_homestory_800801001_9_dialog_content = "Tenang saja, PlayerName! Meski sekarang kau iri padaku, aku akan tetap bersikap baik padamu, kok!",
  str_homestory_800801001_10_dialog_content = "Tapi, aku kan tidak iri padamu...",
  str_homestory_800801001_11_dialog_content = "Ssst... Iya, iya. Aku paham.",
  str_homestory_800801001_12_dialog_content = "Saat masih seusiamu, aku ingin jadi pria sejati seperti diriku yang sekarang!<sprite=emo_mojing size=60 />",
  str_homestory_800801001_13_dialog_content = "Dengar, PlayerName! Tak ada yang tak mungkin asalkan kau bertekad!",
  str_homestory_800801001_14_dialog_content = "... Baiklah. Brock.",
  str_homestory_800801001_15_dialog_content = "Sama-sama. Lagi pula sudah jadi tanggung jawabku untuk jadi pengobar semangat Cloud Gardens.",
  str_homestory_800801001_16_dialog_content = "Kalau soal menjaga anak-anak muda, tak seorang pun bisa melakukannya lebih baik dariku.",
  str_homestory_800801001_17_dialog_content = "Eh, sebentar... Tanggung jawab apa? Pengobar semangat apa?",
  str_homestory_800801001_18_dialog_content = "Lho, kau tak menyadari pengorbananku untukmu?",
  str_homestory_800801001_19_dialog_content = "... Coba jelaskan.",
  str_homestory_800801001_20_dialog_content = "Dengar, ya. Beberapa hari lalu, aku mengunjungi Odi untuk mengecat ulang Brock punyaku dengan warna pelangi.",
  str_homestory_800801001_21_dialog_content = "Dia kelihatan sangat cemas dan memintaku untuk membantumu.",
  str_homestory_800801001_22_dialog_content = "Membantu apa?",
  str_homestory_800801001_23_dialog_content = "Odi bilang...",
  str_homestory_800801001_24_dialog_content = "Ada mesin panas yang terpasang dalam boneka goyangmu.",
  str_homestory_800801001_25_dialog_content = "?",
  str_homestory_800801001_26_dialog_content = "Mesin ini adalah sumber tenaga seluruh Cloud Gardens!",
  str_homestory_800801001_27_dialog_content = "Singkatnya, Cloud Gardens ini bisa beroperasi setiap hari berkat ribuan tinjuku.",
  str_homestory_800801001_28_dialog_content = "Hahah! Kok mukamu bingung begitu, sih? Aku senang kok bisa membantumu!",
  str_homestory_800801001_29_dialog_content = "Pokoknya, aku senang bisa membantu!",
  str_homestory_800801001_30_dialog_content = "... Eh... Brock... Sepertinya...",
  str_homestory_800801001_31_option_content = "Kau sudah diperdaya.",
  str_homestory_800801001_32_dialog_content = "Boneka goyang ini tak ada mesinnya, hanya kapas biasa...",
  str_homestory_800801001_33_dialog_content = "Pada dasarnya, itu tak ada hubungannya dengan beroperasinya Cloud Gardens.",
  str_homestory_800801001_34_dialog_content = "Tapi!",
  str_homestory_800801001_35_dialog_content = "Latihan tinju setiap hari bagus untuk kesehatan fisik dan mentalmu.",
  str_homestory_800801001_36_option_content = "Aku menghargainya!",
  str_homestory_800801001_37_dialog_content = "Tapi...",
  str_homestory_800801001_38_dialog_content = "Kurasa Odi tak begitu memahami struktur Cloud Gardens.",
  str_homestory_800801001_39_dialog_content = "Maksudku...",
  str_homestory_800801001_40_dialog_content = "Boneka goyang ini tak ada mesinnya, hanya kapas biasa...",
  str_homestory_800801001_41_dialog_content = "Oh! Benarkah?",
  str_homestory_800801001_42_dialog_content = "Hahah. Kurasa Odi tak selalu benar!",
  str_homestory_800801001_43_dialog_content = "Hmm... Brock...",
  str_homestory_800801001_44_dialog_content = "Kau mungkin sudah ditipu.",
  str_homestory_800801001_45_dialog_content = "Sepertinya begitu. Ini bukan pertama kalinya.",
  str_homestory_800801001_46_dialog_content = "Kau tak marah?",
  str_homestory_800801001_47_dialog_content = "Kenapa harus marah?",
  str_homestory_800801001_48_dialog_content = "Mereka suka mengerjaiku karena sangat menyukaiku!",
  str_homestory_800801001_49_dialog_content = "... Hmm... Mungkin kau benar.",
  str_homestory_800801001_50_dialog_content = "Setidaknya...",
  str_homestory_800801001_51_dialog_content = "Mereka menggodaku sebagai cara menunjukkan kekaguman dan kepercayaan padaku.",
  str_homestory_800801001_52_dialog_content = "... Kekaguman? Kau yakin, nih?",
  str_homestory_800801001_53_dialog_content = "Kenapa mereka tak pernah mengolok-olok Sinsa? Coba kaupikir.",
  str_homestory_800801001_54_dialog_content = "Kemampuanku untuk bergaul dengan orang biasa tak ada tandingannya! Hahahahah!<sprite=emo_dianzan size=60 />",
  str_homestory_806501001_0_dialog_content = "Tweety?",
  str_homestory_806501001_1_dialog_content = "Wow! Navigator! Senang bertemu denganmu.",
  str_homestory_806501001_2_dialog_content = "Ada apa, Tweety? Kenapa kau gugup sekali saat melihatku?",
  str_homestory_806501001_3_dialog_content = "Eh... Aku?",
  str_homestory_806501001_4_dialog_content = "Coba lihat. Barang-barangmu berserakan di mana-mana.",
  str_homestory_806501001_5_dialog_content = "Ah! Di mana?",
  str_homestory_806501001_6_dialog_content = "Bulu putih di dekat kakimu...",
  str_homestory_806501001_7_dialog_content = "Ah... Biaw kuwihat...",
  str_homestory_806501001_8_dialog_content = "Wow! Itu buwu-buwu Tweety?",
  str_homestory_806501001_9_dialog_content = "Huhu... Seharusnya aku tidak nakaw.",
  str_homestory_806501001_10_dialog_content = "Nakal?",
  str_homestory_806501001_11_dialog_content = "Pantas saja hari ini ekormu terkulai.",
  str_homestory_806501001_12_dialog_content = "Hmm…",
  str_homestory_806501001_13_dialog_content = "Apa yang terjadi? Coba ceritakan padaku.",
  str_homestory_806501001_14_dialog_content = "Sebaiknya kuberi tahu Navigator...",
  str_homestory_806501001_15_dialog_content = "Tadi, Tweety datang untuk mengantar surat...",
  str_homestory_806501001_16_dialog_content = "Baiklah. Suratnya sudah di kantor pos? Aku akan segera ke sana!",
  str_homestory_806501001_17_dialog_content = "Tapi... Tunggu duwu!",
  str_homestory_806501001_18_dialog_content = "Suratnya... Aku tak mengantarnya ke kantor pos.",
  str_homestory_806501001_19_dialog_content = "Tweety wihat Cloud Gardens sudah banyak berubah!",
  str_homestory_806501001_20_dialog_content = "Aku mewihat-wihat ke sana kemari sampai-sampai wupa dengan suratnya...",
  str_homestory_806501001_21_dialog_content = "Ini yang kau maksud dengan \"nakal\" tadi?",
  str_homestory_806501001_22_option_content = "Marah",
  str_homestory_806501001_23_dialog_content = "Melalaikan tugas bisa jadi masalah besar.",
  str_homestory_806501001_24_dialog_content = "Sebagai pemilik Cloud Gardens, apa aku harus menghukummu?",
  str_homestory_806501001_25_dialog_content = "Aduh! Menghukumku?",
  str_homestory_806501001_26_dialog_content = "Buluku akan lebih banyak lagi yang wontok...",
  str_homestory_806501001_27_dialog_content = "Baiklah... Aku akan menghukummu...",
  str_homestory_806501001_28_option_content = "Hibur dia",
  str_homestory_806501001_29_dialog_content = "Jangan khawatir. Ini tak mendesak, kok.",
  str_homestory_806501001_30_dialog_content = "Aku senang sekali kau ternyata suka dengan perubahan yang kulakukan di sini.",
  str_homestory_806501001_31_dialog_content = "Tewima kasih, Navigator. Kau sangat baik!",
  str_homestory_806501001_32_dialog_content = "Nah, siapa yang mengirimkan surat itu?",
  str_homestory_806501001_33_dialog_content = "Biar kulihat.",
  str_homestory_806501001_34_dialog_content = "Oke! Couwier Union tak pewnah gagal mengantawkan kiwiman!",
  str_homestory_806501001_35_dialog_content = "Waduh! Mana suwatnya?",
  str_homestory_806501001_36_dialog_content = "Tak ada di tasku...",
  str_homestory_806501001_37_dialog_content = "Tak ada di topiku!",
  str_homestory_806501001_38_dialog_content = "Tenanglah. Apa suratnya terjatuh entah di mana?",
  str_homestory_806501001_39_dialog_content = "Tadi kau ke mana saja, Tweety?",
  str_homestory_806501001_40_dialog_content = "Ke semua tempat... Aku pewgi ke semua tempat.",
  str_homestory_806501001_41_dialog_content = "... Kalau begitu, sulit mencarinya.",
  str_homestory_806501001_42_dialog_content = "Tweety tak mau jadi sepewti Dove...",
  str_homestory_806501001_43_dialog_content = "Hmm? Barusan ada yang jatuh dari ekormu...",
  str_homestory_806501001_44_dialog_content = "Ada lagi bulu yang wontok dawi ekowku? Tak lama lagi, bisa-bisa Tweety gundul, nih!",
  str_homestory_806501001_45_dialog_content = "Tidak, sepertinya bukan bulu...",
  str_homestory_806501001_46_dialog_content = "Eh…",
  str_homestory_806501001_47_dialog_content = "Ah! Ini suwatnya!",
  str_homestory_806501001_48_dialog_content = "Tewnyata tewsembunyi di ekowku!",
  str_homestory_805501001_0_dialog_content = "Itu...",
  str_homestory_805501001_1_dialog_content = "Pittman?",
  str_homestory_805501001_2_dialog_content = "…!",
  str_homestory_805501001_3_dialog_content = "Pittman?",
  str_homestory_805501001_4_dialog_content = "Ehem... Kau pasti salah lihat.",
  str_homestory_805501001_5_dialog_content = "Hah? Tapi, setelanmu sangat formal... dan ada lingkaran hitam di wajahmu!",
  str_homestory_805501001_6_dialog_content = "Kau pasti Pittman.",
  str_homestory_805501001_7_dialog_content = "Psst…",
  str_homestory_805501001_8_dialog_content = "Jangan keras-keras. Jangan sampai ada orang yang mendengarmu...",
  str_homestory_805501001_9_option_content = "Tanyai dia",
  str_homestory_805501001_10_dialog_content = "Hmm? Hakim dari Lumopolis takut dikenali orang-orang?",
  str_homestory_805501001_11_option_content = "Maklumi permintaannya",
  str_homestory_805501001_12_dialog_content = "Oke.",
  str_homestory_805501001_13_dialog_content = "Kau tak mau orang tahu keberadaanmu!",
  str_homestory_805501001_14_dialog_content = "Apa kau sedang jadi buron di Lumopolis?",
  str_homestory_805501001_15_dialog_content = "Aku orang yang adil dan terhormat, tak berat sebelah, pengikut taat God of Light, dan pelayan setia Lumopolis.",
  str_homestory_805501001_16_dialog_content = "Mana mungkin aku jadi buron?",
  str_homestory_805501001_17_dialog_content = "Mungkin saja...",
  str_homestory_805501001_18_dialog_content = "Mungkin saja kau diam-diam naik kuda-kudaan untuk bersenang-senang!",
  str_homestory_805501001_19_dialog_content = "Kau... kau melihatnya?<sprite=emo_daomei size=60 />",
  str_homestory_805501001_20_dialog_content = "Ah hah! Ternyata kau memang naik kuda-kudaan itu!",
  str_homestory_805501001_21_dialog_content = "Ehem. Aku hanya ingin memastikan kuda-kudaan itu masih bagus.",
  str_homestory_805501001_22_dialog_content = "Sekarang ini, banyak sekali beredar kuda-kudaan palsu di pasaran.",
  str_homestory_805501001_23_dialog_content = "Para hakim seperti kami harus menanggulangi para penjual licik seperti itu.",
  str_homestory_805501001_24_dialog_content = "Tapi, jangan khawatir. Kuda-kudaanmu kuat, dan hasil pengerjaannya pun sempurna. Kuda-kudaan ini bisa menanggung beban sampai setidaknya 84 kg.",
  str_homestory_805501001_25_dialog_content = "Kau bisa menungganginya tanpa harus khawatir.",
  str_homestory_805501001_26_dialog_content = "Err... Terima kasih...",
  str_homestory_805501001_27_dialog_content = "Aku memasang kuda-kudaan ini di sini supaya semua orang bisa menungganginya.",
  str_homestory_805501001_28_dialog_content = "Tak usah pakai sembunyi-sembunyi begitu!",
  str_homestory_805501001_29_dialog_content = "Kautahu dari mana?",
  str_homestory_805501001_30_dialog_content = "Raut wajahmu membuatku bisa tahu dengan mudah.",
  str_homestory_805501001_31_dialog_content = "Kau tak lihai berbohong. Hahahah.",
  str_homestory_805501001_32_dialog_content = "… Oke.",
  str_homestory_805501001_33_dialog_content = "Cukup kita berdua saja yang tahu, ya.",
  str_homestory_805501001_34_dialog_content = "Kenapa? Ini kan tak perlu dirahasiakan...",
  str_homestory_805501001_35_dialog_content = "Aku sendiri juga suka menungganginya, kok.",
  str_homestory_805501001_36_dialog_content = "Untuk menegakkan keadilan, hakim harus selalu bisa memengaruhi dan meyakinkan orang-orang.",
  str_homestory_805501001_37_dialog_content = "Kalau orang-orang sampai tahu sisi diriku yang kekanak-kanakan ini...",
  str_homestory_805501001_38_dialog_content = "Mereka tak akan percaya pada penilaianku saat di pengadilan.",
  str_homestory_805501001_39_dialog_content = "Benarkah?",
  str_homestory_805501001_40_dialog_content = "Nah, PlayerName, apa kau bisa menjaga rahasia?",
  str_homestory_805501001_41_dialog_content = "Baiklah. Tapi, tetap saja aku tak paham apa hubungan antara menunggangi kuda-kudaan dan menjadi hakim dalam sidang...",
  str_homestory_805501001_42_dialog_content = "Aku janji, aku tak akan bilang kepada siapa pun!",
  str_homestory_805501001_43_dialog_content = "Terima kasih atas pengertianmu!",
  str_homestory_805501001_44_dialog_content = "Satu lagi…",
  str_homestory_805501001_45_dialog_content = "Kalau kau sampai jadi korban barang dagangan palsu, akan kutegakkan keadilan untukmu!<sprite=emo_qingsong size=60 />",
  str_homestory_815501001_0_dialog_content = "Sepertinya barusan itu suara pedang disarungkan?",
  str_homestory_815501001_1_dialog_content = "Eraveil sungguh menakjubkan, PlayerName!",
  str_homestory_815501001_2_dialog_content = "Lumayan juga... menurutku...",
  str_homestory_815501001_3_dialog_content = "Berapa banyak lagi rahasia yang disembunyikan Caelestite ini dari kita?",
  str_homestory_815501001_4_dialog_content = "... Aku tak sabar ingin mengungkapnya.",
  str_homestory_815501001_5_dialog_content = "Hmm... Tempatmu ini nyaman sekali, nak.",
  str_homestory_815501001_6_dialog_content = "Sangat lengkap, lokasinya strategis, dan sulit diakses.",
  str_homestory_815501001_7_dialog_content = "Saat terjadi perang, tempat ini bisa dengan mudah difungsikan sebagai markas tempur!",
  str_homestory_815501001_8_dialog_content = "Wah... Pemikiranmu sangat jauh di depanku, Barton, setidaknya sepuluh kali lipat.",
  str_homestory_815501001_9_dialog_content = "Tentu saja!",
  str_homestory_815501001_10_dialog_content = "Terus-menerus mengejar kekuatan dan merencanakan segala milikmu secara rasional adalah hal yang sama-sama pentingnya.",
  str_homestory_815501001_11_dialog_content = "(Hari ini Barton terdengar tak seperti biasanya...)",
  str_homestory_815501001_12_dialog_content = "Sayang sekali... seandainya saja aku mengetahuinya lebih awal...",
  str_homestory_815501001_13_dialog_content = "... Bagaimana menurutmu, Nak?",
  str_homestory_815501001_14_dialog_content = "Menurutmu, mana yang lebih penting: tumbuh makin kuat atau merencanakan semua sumber dayamu secara rasional?<sprite=emo_sikao size=60 />",
  str_homestory_815501001_15_option_content = "Tumbuh makin kuat",
  str_homestory_815501001_16_dialog_content = "Kalau aku hanya punya 10 Nightium, perencanaan pun tak akan ada gunanya...",
  str_homestory_815501001_17_dialog_content = "Aku harus bertambah kuat terlebih dulu. Dengan kata lain, aku harus menambah kekayaanku terlebih dulu.",
  str_homestory_815501001_18_option_content = "Perencanaan rasional",
  str_homestory_815501001_19_dialog_content = "Kalau aku hanya punya 10 Nightium, aku harus mencari cara untuk bertahan hidup, barulah aku bisa memikirkan cara menambah penghasilan...",
  str_homestory_815501001_20_dialog_content = "Hah? Serius, nih?",
  str_homestory_815501001_21_dialog_content = "Kau hanya punya 10 Nightium?",
  str_homestory_815501001_22_dialog_content = "... Itu hanya contoh!",
  str_homestory_815501001_23_dialog_content = "Baiklah.",
  str_homestory_815501001_24_dialog_content = "Padahal kalau kau memang sebangkrut itu, tadi aku berniat menawarkan perjanjian sewa.",
  str_homestory_815501001_25_dialog_content = "Dalam hal ini, Illumina cukup bagus. Setidaknya banyak hal diberikan secara gratis.",
  str_homestory_815501001_26_dialog_content = "?",
  str_homestory_815501001_27_dialog_content = "Maaf. Aku melantur...",
  str_homestory_815501001_28_dialog_content = "Aku akhirnya yakin bahwa mengejar kekuatan dan merencanakan sumber daya bisa dilakukan bersamaan.",
  str_homestory_815501001_29_dialog_content = "Kita tak harus memilih salah satunya saja.",
  str_homestory_815501001_30_dialog_content = "Dulu, aku mencurahkan perhatianku sepenuhnya untuk menambah kekuatanku. Dalam prosesnya, banyak hal penting justru jadi terlupakan.",
  str_homestory_815501001_31_dialog_content = "Dengan merencanakan apa yang sudah kita miliki, kita bisa menggambarkan masa depan dengan lebih jelas!",
  str_homestory_815501001_32_dialog_content = "Pemahaman yang menyeluruh tentang diri kita sendiri memungkinkan kita untuk melangkah maju dengan lancar dalam perjalanan ini sekaligus menambah kekuatan.",
  str_homestory_815501001_33_dialog_content = "Kalau lebih kuat, kuasa kita juga akan lebih besar.",
  str_homestory_815501001_34_dialog_content = "Hmm... Bisa dibilang, aku cukup setuju denganmu.",
  str_homestory_815501001_35_dialog_content = "Jadi, kau bersedia menyewakan tempat tinggalmu ini untuk kujadikan markas tempur?",
  str_homestory_815501001_36_dialog_content = "?!",
  str_homestory_815501001_37_dialog_content = "Aku tak pernah bilang setuju!",
  str_homestory_815501001_38_dialog_content = "Konsep markas tempur sepertinya tak sesuai untuk Cloud Gardens!",
  str_homestory_815501001_39_dialog_content = "Hahah. Siapa tahu? Tak seorang pun bisa menjamin bahwa kedamaian ini akan bertahan selamanya.",
  str_homestory_815501001_40_dialog_content = "Eh! Tolong jangan bilang begitu!<sprite=emo_shengqi size=60 />",
  str_homestory_815501001_41_dialog_content = "Tak ada bedanya. Kita harus siap menghadapi segala kemungkinan risiko!",
  str_homestory_815501001_42_dialog_content = "Benar. Kita harus segera melakukan simulasi perang beberapa kali lagi.",
  str_homestory_815501001_43_dialog_content = "Dan semua ide di kepalaku ini... aku akan menyampaikannya kepada Vivian besok.",
  str_homestory_815501001_44_dialog_content = "Hmm... Aku tak punya waktu untuk mencari dokumen laporan tertulis!",
  str_homestory_815501001_45_dialog_content = "(Kuputuskan akan kutarik kata-kataku barusan...)",
  str_homestory_815501001_46_dialog_content = "(Ternyata Barton sama sekali belum berubah.)",
  str_homestory_801101001_0_dialog_content = "Sharona!",
  str_homestory_801101001_1_dialog_content = "Pak…",
  str_homestory_801101001_2_dialog_content = "Apa kau sedang berlatih gerakan baru?",
  str_homestory_801101001_3_dialog_content = "Ya.",
  str_homestory_801101001_4_dialog_content = "Sungguh tekun.<sprite=emo_yaling size=60 />. Pantas saja kau ditugaskan mengomando pasukan tempur utama Illumina, 1st Legion...",
  str_homestory_801101001_5_dialog_content = "Kurasa ada kesalahpahaman, PlayerName.",
  str_homestory_801101001_6_dialog_content = "Aku tak bermaksud memasukkan gerakan-gerakan baru ini ke dalam latihan militer kami.",
  str_homestory_801101001_7_dialog_content = "Ini sebenarnya skill baru yang belum lama ini kupelajari dari sebuah novel.",
  str_homestory_801101001_8_dialog_content = "Kau... kau membaca novel?",
  str_homestory_801101001_9_dialog_content = "Sebentar... Kau berlatih gerakan baru dari novel?",
  str_homestory_801101001_10_dialog_content = "Ini... ini sama sekali tak seperti Officer Sharona yang biasanya!",
  str_homestory_801101001_11_dialog_content = "Kau tak menyangkanya?",
  str_homestory_801101001_12_option_content = "Mengangguk",
  str_homestory_801101001_13_dialog_content = "Kukira kau selalu sibuk mengurus hal-hal besar. Membaca novel...",
  str_homestory_801101001_14_dialog_content = "Jangan salah paham. Bukannya aku tak suka membaca!",
  str_homestory_801101001_15_option_content = "Menggelengkan kepala",
  str_homestory_801101001_16_dialog_content = "Kalau dipikir-pikir, mestinya kita tak menilai seseorang dari penampilan luarnya saja...",
  str_homestory_801101001_17_dialog_content = "Menurutku, Officer Sharona selalu terlihat sibuk. Aku tak mengira kau punya waktu luang untuk membaca novel.",
  str_homestory_801101001_18_dialog_content = "Kau benar. Aku memang tak terlalu banyak membaca.",
  str_homestory_801101001_19_dialog_content = "Tapi, ada satu judul buku yang menarik perhatianku: The Millennia Entanglement of Two Rebellious Dragons.",
  str_homestory_801101001_20_dialog_content = "...",
  str_homestory_801101001_21_dialog_content = "Dari mana kaudapat buku ini?",
  str_homestory_801101001_22_dialog_content = "Jangan bilang kau membelinya dari seorang Aurorian!",
  str_homestory_801101001_23_dialog_content = "Ya, seorang saudagar di Umbraton menjualnya kepadaku.",
  str_homestory_801101001_24_dialog_content = "Kau tampak tenang...",
  str_homestory_801101001_25_dialog_content = "Kurasa ceritanya tak terlalu berlebihan.",
  str_homestory_801101001_26_dialog_content = "Dia memberitahuku bahwa inti cerita dalam buku ini adalah...",
  str_homestory_801101001_27_dialog_content = "Skill rahasia Dragon yang sudah lama hilang dan kisah cinta dari suatu garis keturunan kuno...",
  str_homestory_801101001_28_dialog_content = "Apa? Memangnya kau tak marah karenanya?",
  str_homestory_801101001_29_dialog_content = "Tidak terlalu.",
  str_homestory_801101001_30_dialog_content = "Lagi pula, aku tak bisa berbuat banyak tentang hal ini.",
  str_homestory_801101001_31_dialog_content = "Buku itu dicetak dan dijual di Umbraton, di luar wilayah kewenanganku.",
  str_homestory_801101001_32_dialog_content = "Bagiku, isi buku ini tak terlalu penting.",
  str_homestory_801101001_33_dialog_content = "Tapi, bagi para penulisnya, bisa saja buku adalah satu-satunya sumber penghidupan mereka.",
  str_homestory_801101001_34_dialog_content = "... Ya, benar sekali...",
  str_homestory_801101001_35_dialog_content = "Sharona... Kau memang Officer yang cerdas!",
  str_homestory_801101001_36_dialog_content = "Nah, skill rahasia Dragon yang diceritakan dalam buku ini terdengar agak konyol...",
  str_homestory_801101001_37_dialog_content = "Tapi, ini bisa membuat latihanku sedikit lebih seru.",
  str_homestory_801101001_38_dialog_content = "Mau coba?",
  str_homestory_801101001_39_dialog_content = "Seperti yang tertulis dalam buku ini, kita mulai dengan lompat jongkok 200 kali, lalu disusul dengan...",
  str_homestory_801101001_40_dialog_content = "Tidak, tidak…",
  str_homestory_801101001_41_dialog_content = "Kurasa aku harus benar-benar fokus pada kemampuan Caelestite saja, Officer Sharona.",
  str_homestory_801101001_42_dialog_content = "Kau saja yang berlatih, ya... Dah!",
  str_homestory_801101001_43_dialog_content = "Dah.",
  str_homestory_810301001_0_dialog_content = "Apa itu Eicy?",
  str_homestory_810301001_1_dialog_content = "Eicy, mau lihat ke dalam?",
  str_homestory_810301001_2_dialog_content = "Seingatku, kau suka berbelanja.",
  str_homestory_810301001_3_dialog_content = "PlayerName, kau tahu hobiku...",
  str_homestory_810301001_4_dialog_content = "Tapi, bisa-bisanya kau bertindak kikir dan hanya membangun satu toko saja?",
  str_homestory_810301001_5_dialog_content = "Anu... Ada banyak alasan...",
  str_homestory_810301001_6_dialog_content = "Sebutkan.",
  str_homestory_810301001_7_dialog_content = "Seandainya ingatanmu tiba-tiba hilang, aku bisa melepas penutup mataku...",
  str_homestory_810301001_8_dialog_content = "Hollow Gaze <sprite=emo_baimao size=60 />dari mataku bisa membantumu.",
  str_homestory_810301001_9_option_content = "Jelaskan",
  str_homestory_810301001_10_dialog_content = "Baiklah. Tunggu sebentar!",
  str_homestory_810301001_11_dialog_content = "Alasan utamanya adalah karena anggaran kami sangat terbatas...",
  str_homestory_810301001_12_dialog_content = "Banyak sekali yang harus kami bangun. Tak mungkin kami bisa membuat semuanya sempurna sejak awal.",
  str_homestory_810301001_13_option_content = "Jawab agak berbelit-belit",
  str_homestory_810301001_14_dialog_content = "Interogasi tak akan ada gunanya dalam hal ini...",
  str_homestory_810301001_15_dialog_content = "Anggaran kami sangat terbatas. Kami tak mampu membangun toko lagi...",
  str_homestory_810301001_16_dialog_content = "Menurutku... satu saja sudah lebih baik daripada tak punya sama sekali!",
  str_homestory_810301001_17_dialog_content = "Kata-katamu sangat tegas dan lugas.",
  str_homestory_810301001_18_dialog_content = "Tapi, walau hanya satu, toko kami ini menyediakan semua kebutuhanmu!",
  str_homestory_810301001_19_dialog_content = "Aku sudah bekerja keras membangun kerja sama dengan berbagai Guild di Umbraton...",
  str_homestory_810301001_20_dialog_content = "Pasokan barang dikirimkan secara rutin melalui Courier Union.",
  str_homestory_810301001_21_dialog_content = "Bagaimana kalau kau masuk dan lihat-lihat dulu? Kalau ada yang ingin kaupesan, beri tahu saja aku.",
  str_homestory_810301001_22_dialog_content = "Tak usah repot-repot. Aku sudah melakukannya.",
  str_homestory_810301001_23_dialog_content = "Sebenarnya, aku memborong semua stokmu sebagai wujud dukungan untukmu.",
  str_homestory_810301001_24_dialog_content = "Semuanya?",
  str_homestory_810301001_25_dialog_content = "Ya.",
  str_homestory_810301001_26_dialog_content = "Termasuk ikan yang baru saja kami tangkap kemarin dari sungai?",
  str_homestory_810301001_27_dialog_content = "Yang warna-warni itu? Ya. Ikan-ikan itu imut sekali.",
  str_homestory_810301001_28_dialog_content = "Aku tak bisa menemukan akuarium untuk memelihara mereka, jadi kulepaskan saja mereka ke sungai di dekat sini.",
  str_homestory_810301001_29_dialog_content = "Termasuk sepatu kulit lusuh yang tak laku-laku itu?",
  str_homestory_810301001_30_dialog_content = "Sepatu lusuh? Ya. Memangnya itu bukan pot bunga model terbaru, ya?",
  str_homestory_810301001_31_dialog_content = "Aku sudah menghubungi Courier Union untuk mengembalikannya kepada True Order.",
  str_homestory_810301001_32_dialog_content = "Bagaimana dengan... peta Eraveil yang kugambar dengan tangan?",
  str_homestory_810301001_33_dialog_content = "Maksudmu gambar labirin bengkok-bengkok itu?",
  str_homestory_810301001_34_dialog_content = "Kau yang menggambarnya? Aku harus membingkai dan memasangnya di dindingku.",
  str_homestory_810301001_35_dialog_content = "Terima kasih, Eicy... Kau pelanggan paling murah hati yang pernah kutemui!",
  str_homestory_810301001_36_dialog_content = "Tak usah sungkan. Tujuan berbelanja kan memang untuk buang-buang uang!",
  str_homestory_810301001_37_dialog_content = "Aku jengkel karena tak ada toko lain, jadi aku tak bisa berbelanja lebih banyak lagi.",
  str_homestory_810301001_38_dialog_content = "Eicy, kau bisa melihat-lihat dulu.",
  str_homestory_810301001_39_dialog_content = "Di sebelah sana ada museum, dan Fountain of Hope...",
  str_homestory_810301001_40_dialog_content = "Aku berani jamin, kau tak akan menemukan benda-benda ini di tempat lain mana pun!",
  str_homestory_810301001_41_dialog_content = "Tentu. Sepertinya menarik.",
  str_homestory_810301001_42_dialog_content = "Aku punya ide. Kuputuskan, aku akan membeli <sprite=emo_baiyebi size=60 />dirimu.",
  str_homestory_810301001_43_dialog_content = "Hah? Membeliku?",
  str_homestory_810301001_44_dialog_content = "Sehari saja. Kau bisa mengantarku berkeliling.",
  str_homestory_810301001_45_dialog_content = "Sebut saja berapa harga yang menurutmu pantas untuk mengganti waktumu.",
  str_homestory_810301001_46_dialog_content = "Setuju! Aku sangat senang bisa melayanimu!",
  str_homestory_802301001_0_dialog_content = "Connolly...",
  str_homestory_802301001_1_dialog_content = "Cahaya lembut itu...",
  str_homestory_802301001_2_dialog_content = "Connolly, apa katamu?",
  str_homestory_802301001_3_dialog_content = "Na-Navigator! <sprite=emo_wuzui size=60 />",
  str_homestory_802301001_4_dialog_content = "Aku hanya menggumam, kok. Tak usah hiraukan aku...",
  str_homestory_802301001_5_dialog_content = "... Tidak, bukan hanya itu!",
  str_homestory_802301001_6_dialog_content = "Kau juga bisa memperhatikanku sedikit... Aku... aku sedang berlatih desensitisasi...",
  str_homestory_802301001_7_dialog_content = "Berlatih desensitisasi?",
  str_homestory_802301001_8_dialog_content = "Ya... Vice memberitahuku tentang latihan ini...",
  str_homestory_802301001_9_dialog_content = "Aku kesulitan menyesuaikan diri dengan cahaya di sini...",
  str_homestory_802301001_10_dialog_content = "Vice menemukanku saat aku bersembunyi di pojokan...",
  str_homestory_802301001_11_dialog_content = "Dia sadar kau butuh bantuan?",
  str_homestory_802301001_12_dialog_content = "Ya…",
  str_homestory_802301001_13_dialog_content = "Dia menyuruhku untuk mencoba melakukan hal-hal yang kusuka dan mengabaikan orang lain saja...",
  str_homestory_802301001_14_dialog_content = "Atau berpura-pura ini adalah Holiday Cafe dan kalian semua adalah pelanggan...",
  str_homestory_802301001_15_dialog_content = "Aku sungguh berusaha keras...",
  str_homestory_802301001_16_option_content = "Bagaimana kondisimu?",
  str_homestory_802301001_17_dialog_content = "Agak mendingan...",
  str_homestory_802301001_18_dialog_content = "Di Colossus juga ada banyak orang...",
  str_homestory_802301001_19_option_content = "Jangan terlalu memaksakan diri.",
  str_homestory_802301001_20_dialog_content = "Kalau memang merasa lebih nyaman di kamarmu sendiri, kau tak harus keluar, kok.",
  str_homestory_802301001_21_dialog_content = "Sebenarnya, ada yang ingin kukatakan kepadamu, Navigator...",
  str_homestory_802301001_22_dialog_content = "Hmm? Apa?",
  str_homestory_802301001_23_dialog_content = "Aku mengikuti saran Vice dan memainkan sebuah lagu bersama Anton di sini<sprite=emo_yinfu size=60 />...",
  str_homestory_802301001_24_dialog_content = "Aku sama sekali tak menyangka... seorang gadis yang mengenakan pakaian bergaya Lumopolis memujiku...",
  str_homestory_802301001_25_dialog_content = "Aku…",
  str_homestory_802301001_26_dialog_content = "Ah... Tiba-tiba saja, tempat yang terang ini tak terasa buruk lagi, 'kan?",
  str_homestory_802301001_27_dialog_content = "Kadang, pujian memang bisa mendongkrak semangat.",
  str_homestory_802301001_28_dialog_content = "Connolly, menurutku, kau ini fenomenal!",
  str_homestory_802301001_29_dialog_content = "Kopi buatanmu adalah yang paling enak, dan kau juga manis tapi mahir bertarung...",
  str_homestory_802301001_30_dialog_content = "Terima kasih atas pujianmu, Navigator. Aku... aku tak tahu harus bilang apa...",
  str_homestory_802301001_31_dialog_content = "Tapi, pujian dari gadis itu... terasa berbeda dari pujianmu!",
  str_homestory_802301001_32_dialog_content = "Navigator dan Vice adalah sahabat Connolly...",
  str_homestory_802301001_33_dialog_content = "Wajar saja kalau kalian selalu mendukung, menghibur, dan memujiku...",
  str_homestory_802301001_34_dialog_content = "Tapi, gadis itu kan sama sekali tak kenal denganku!",
  str_homestory_802301001_35_dialog_content = "Pujian darinya sungguh tulus dan terasa lebih meyakinkan bagi Connolly.",
  str_homestory_802301001_36_dialog_content = "Ya... Memang begitulah yang kurasakan...",
  str_homestory_802301001_37_dialog_content = "Navigator, bisakah kauberi tahu Vice bahwa aku sangat berterima kasih atas bantuannya?",
  str_homestory_802301001_38_dialog_content = "Kalau bukan berkat bantuannya, pasti sekarang aku masih bersembunyi di dalam kamarku...",
  str_homestory_802301001_39_dialog_content = "Siap, laksanakan!",
  str_homestory_802301001_40_dialog_content = "Terima kasih, Navigator!",
  str_homestory_802301001_41_dialog_content = "Aku berencana akan berlatih memainkan lagu itu lagi dengan Anton...",
  str_homestory_802301001_42_dialog_content = "Kau juga bisa mencoba lagu baru.",
  str_homestory_802301001_43_dialog_content = "Aku yakin gadis misterius itu pasti senang mendengarnya.",
  str_homestory_802301001_44_dialog_content = "Ah! Kau benar...",
  str_homestory_802301001_45_dialog_content = "Baiklah! Navigator, aku akan berlatih!",
  str_homestory_802301001_46_dialog_content = "Kau pasti bisa!",
  str_homestory_803001001_0_dialog_content = "Sinsa…",
  str_homestory_803001001_1_dialog_content = "Halo, Sinsa!",
  str_homestory_803001001_2_dialog_content = "Ya, ya<sprite=emo_yaosu size=60 />! Senang melihatmu, PlayerName, si Caelestite terakhir!",
  str_homestory_803001001_3_dialog_content = "Apa kabar?",
  str_homestory_803001001_4_dialog_content = "Baik-baik saja. Kau sendiri bagaimana? Baik-baik saja di sini?",
  str_homestory_803001001_5_dialog_content = "Lumayan.",
  str_homestory_803001001_6_dialog_content = "Kau tak butuh waktu lama untuk sepenuhnya menyulap tempat payah ini...",
  str_homestory_803001001_7_dialog_content = "Kau memang sesuai dengan harapan Sinsa. Ah hahahah.",
  str_homestory_803001001_8_dialog_content = "Nah, apa kau sudah memutuskan?",
  str_homestory_803001001_9_dialog_content = "Kapan kau mau bergabung ke Rediesel Wrench?",
  str_homestory_803001001_10_dialog_content = "Anu.. Err...",
  str_homestory_803001001_11_dialog_content = "Menurut standar Rediesel Wrench...",
  str_homestory_803001001_12_dialog_content = "Tempat ini benar-benar butuh area khusus untuk bertarung dan balapan!",
  str_homestory_803001001_13_option_content = "Tolak",
  str_homestory_803001001_14_dialog_content = "Aku lebih suka kalau di sini tak ada konflik...",
  str_homestory_803001001_15_dialog_content = "Di sini tak ada tempat untuk kekerasan.",
  str_homestory_803001001_16_dialog_content = "Sayang sekali... Aku sampai sudah lupa berapa kali kau menolak tawaranku.",
  str_homestory_803001001_17_dialog_content = "Tapi, PlayerName, idemu itu terdengar agak kekanak-kanakan.",
  str_homestory_803001001_18_dialog_content = "Percayalah padaku. Hal-hal yang tak kauinginkan itu pasti akan terjadi.",
  str_homestory_803001001_19_dialog_content = "Tak usah tanya dari mana aku tahu...",
  str_homestory_803001001_20_dialog_content = "...",
  str_homestory_803001001_21_option_content = "Setuju",
  str_homestory_803001001_22_dialog_content = "Hmm... Ini bukan bagian dari rencana awal kita...",
  str_homestory_803001001_23_dialog_content = "Tapi, pertarungan dan balapan tak jelas mungkin saja akan mengakibatkan kerusakan pada rumah-rumah yang sudah susah payah kubangun.",
  str_homestory_803001001_24_dialog_content = "Sebaiknya ada area khusus...",
  str_homestory_803001001_25_dialog_content = "Hahahah. Kau sudah dewasa, Nak.",
  str_homestory_803001001_26_dialog_content = "Sekarang kau tahu kapan kau harus mendengarkan saran orang lain!",
  str_homestory_803001001_27_dialog_content = "Bisakah kautunjukkan asrama putri Cloud Gardens?",
  str_homestory_803001001_28_dialog_content = "Hah?!",
  str_homestory_803001001_29_dialog_content = "Kenapa tatapanmu tampak ngeri begitu?",
  str_homestory_803001001_30_dialog_content = "Kurasa kau pasti mau ke sana karena ada alasan tertentu?",
  str_homestory_803001001_31_dialog_content = "Sudah saatnya berkunjung ke sana.",
  str_homestory_803001001_32_dialog_content = "Berkunjung?",
  str_homestory_803001001_33_dialog_content = "Ya<sprite=emo_qingsong size=60 />, aku harus memastikan asrama itu cukup bagus untuk Eve.",
  str_homestory_803001001_34_dialog_content = "Fiuh... Begitu, ya.",
  str_homestory_803001001_35_dialog_content = "Aku harus memeriksa apakah kasurnya cukup empuk...",
  str_homestory_803001001_36_dialog_content = "Apakah lampu tidurnya tak terlalu menyilaukan mata...",
  str_homestory_803001001_37_dialog_content = "Apakah seprainya berhias pola kesukaan Eve...",
  str_homestory_803001001_38_dialog_content = "Apakah ada lemari pakaian yang cocok untuk gaun-gaun cantik Eve...",
  str_homestory_803001001_39_dialog_content = "Ah! Yang terpenting, apakah ada cangkir termos di kamarnya!",
  str_homestory_803001001_40_option_content = "Setuju",
  str_homestory_803001001_41_dialog_content = "Akan kusuruh Vice memeriksa ulang semuanya...",
  str_homestory_803001001_42_dialog_content = "Hahahah! Itu baru namanya adikku!",
  str_homestory_803001001_43_option_content = "Tidak setuju",
  str_homestory_803001001_44_dialog_content = "Sinsa, kurasa sudah saatnya kau menghormati kehidupan pribadi Eve.",
  str_homestory_803001001_45_dialog_content = "Apa katamu?",
  str_homestory_803001001_46_dialog_content = "Tak usah dipikirkan! Akan kusuruh Vice memeriksa ulang semuanya...",
  str_homestory_811601001_0_dialog_content = "Benar-benar membingungkan!",
  str_homestory_811601001_1_dialog_content = "Navigator, apa ada barangmu yang perlu diperbaiki?",
  str_homestory_811601001_2_dialog_content = "Pas sekali! Hari ini, aku belum dapat tugas apa pun!",
  str_homestory_811601001_3_dialog_content = "Diperbaiki?",
  str_homestory_811601001_4_dialog_content = "Kau menulis pesanan... di depo kargo?",
  str_homestory_811601001_5_dialog_content = "Ya, aku mencari pelanggan di sini, lalu kuperbaiki barang mereka di kamarku.",
  str_homestory_811601001_6_dialog_content = "Ah, jangan khawatir. Tak pakai uang, kok.",
  str_homestory_811601001_7_dialog_content = "Kalau begitu, kenapa kau...",
  str_homestory_811601001_8_dialog_content = "Kenapa kau menawarkan jasa reparasi gratis?",
  str_homestory_811601001_9_dialog_content = "Ya. Biasanya kan kau sibuk dengan hobimu sendiri...",
  str_homestory_811601001_10_dialog_content = "Meneliti suku cadang, komponen, dan semacamnya.",
  str_homestory_811601001_11_dialog_content = "Karena orang-orang di sini berasal dari berbagai tempat.<sprite=emo_sikao size=60 />",
  str_homestory_811601001_12_dialog_content = "Barang-barang mereka yang perlu diperbaiki sangat beragam dan menarik.",
  str_homestory_811601001_13_dialog_content = "Charon pernah memintaku untuk membuat fonograf miliknya menghasilkan suara<sprite=emo_yinfu size=60 /> lebih kencang...",
  str_homestory_811601001_14_dialog_content = "Waktu itu, kukira itu fonograf dari Illumina, dan aku tak terlalu memperhatikannya.",
  str_homestory_811601001_15_dialog_content = "Tapi, tahu tidak? Ternyata itu fonograf antik yang asalnya tak diketahui!",
  str_homestory_811601001_16_dialog_content = "Hahah. Berkali-kali kupelajari fonograf itu luar dalam!",
  str_homestory_811601001_17_dialog_content = "Anu... apa kau benar-benar membuat suaranya jadi lebih kencang?",
  str_homestory_811601001_18_dialog_content = "Yah, sedikit, sih. Itu bayaran dariku karena aku bisa mendapatkan kesempatan langka untuk mempelajari perangkat baru...",
  str_homestory_811601001_19_dialog_content = "Tapi, aku ini juga korban suara musiknya yang kencang itu. Sumpah, aku hanya membuat suaranya lebih kencang sedikit saja!",
  str_homestory_811601001_20_dialog_content = "Baiklah... Sepertinya kau suka tinggal di sini.",
  str_homestory_811601001_21_dialog_content = "Suka sekali!",
  str_homestory_811601001_22_dialog_content = "Ada banyak sekali teknologi yang berbeda, komponen baru, dan perangkat yang bisa dipelajari... Tempat ini ibarat surga!<sprite=emo_aixin size=60 />",
  str_homestory_811601001_23_dialog_content = "Baiklah, asalkan kau merasa nyaman tinggal di sini.",
  str_homestory_811601001_24_dialog_content = "Cukup nyaman, kok. Tak lama lagi, aku bisa membuat Mecha baru!",
  str_homestory_811601001_25_dialog_content = "... Mulai lagi, deh!",
  str_homestory_811601001_26_dialog_content = "Jangan begitu, dong! Aku sangat peduli kepadamu! Barusan, aku memeriksa struktur depo kargo ini untukmu.",
  str_homestory_811601001_27_dialog_content = "Dengan kunci pas dan obengku, terbukti bahwa Pavilion ini sangat stabil dan tak perlu kureparasi.",
  str_homestory_811601001_28_dialog_content = "Pavilion ini dibangun dengan material dari Eraveil.",
  str_homestory_811601001_29_dialog_content = "Lihat, kan? Di sini, aku bahkan bisa mengakses material dari Eraveil. Luar biasa!",
  str_homestory_811601001_30_dialog_content = "Baiklah kalau begitu, sepertinya kau boleh... menerima pesanan di sini?",
  str_homestory_811601001_31_dialog_content = "Kau sama sekali tak menggangguku. Kau bahkan boleh tetap di sini dan menerima pesanan bersamaku.",
  str_homestory_811601001_32_option_content = "Setuju",
  str_homestory_811601001_33_dialog_content = "Baiklah... Aku penasaran apa saja yang butuh direparasi di sini.",
  str_homestory_811601001_34_dialog_content = "Bagus sekali!",
  str_homestory_811601001_35_dialog_content = "... Hari ini, sama sekali tak banyak yang bisa kukerjakan.",
  str_homestory_811601001_36_dialog_content = "... Bagaimana kalau tak ada orang yang butuh jasa reparasimu?",
  str_homestory_811601001_37_option_content = "Tolak",
  str_homestory_811601001_38_dialog_content = "Jangan hari ini. Ada pekerjaan yang harus kulakukan...",
  str_homestory_811601001_39_dialog_content = "Ah! Omong-omong...",
  str_homestory_811601001_40_dialog_content = "Bagaimana kalau tak ada orang yang butuh jasa reparasimu?",
  str_homestory_811601001_41_dialog_content = "Apa kau akan terus hilir mudik di sini?",
  str_homestory_811601001_42_dialog_content = "Benar.",
  str_homestory_811601001_43_dialog_content = "Tapi, Navigator, ada satu hal yang harus kuluruskan.",
  str_homestory_811601001_44_dialog_content = "Aku bukannya hilir mudik tak jelas di sini. Ada perang Mecha sengit yang terus-menerus berlangsung di dalam kepalaku.",
  str_homestory_811601001_45_dialog_content = "Sebelum kau datang, aku sedang berpikir keras tentang siapa yang akan menang seandainya Mecha PlayerName dan Mecha Odi bertarung.",
  str_homestory_811601001_46_dialog_content = "Mecha PlayerName terkenal berkat serangannya yang tangkas dan ringan, sedangkan Mecha Odi punya peralatan lebih lengkap...",
  str_homestory_811601001_47_dialog_content = "Perang ini sengit sekali!",
  str_homestory_811601001_48_dialog_content = "Baiklah... aku sudah tak punya urusan lagi di sini...",
  str_homestory_811701001_0_dialog_content = "Gram?",
  str_homestory_811701001_1_dialog_content = "Gram, sedang apa kau di toko?",
  str_homestory_811701001_2_dialog_content = "Anu... Apa kau sedang merenung?",
  str_homestory_811701001_3_dialog_content = "Atau kau sedang mencari sesuatu di sini tapi tak bisa menemukannya?",
  str_homestory_811701001_4_dialog_content = "Nak.",
  str_homestory_811701001_5_dialog_content = "Aku butuh beberapa bahan untuk membuat sate dari daging ransum yang hampir kedaluwarsa.",
  str_homestory_811701001_6_dialog_content = "Daging kedaluwarsa<sprite=emo_rou size=60 />...",
  str_homestory_811701001_7_dialog_content = "Hampir, bukan sudah kedaluwarsa. Masih aman dimakan, kok.",
  str_homestory_811701001_8_dialog_content = "Lagi pula, enak atau tidaknya makanan sepenuhnya ditentukan oleh keterampilan sang koki, bukan kualitas bahannya.",
  str_homestory_811701001_9_dialog_content = "Kau benar, Gram!",
  str_homestory_811701001_10_dialog_content = "Kalau diingat-ingat, aku belum pernah mencicipi sate buatanmu...",
  str_homestory_811701001_11_dialog_content = "Nanti kau bisa mencicipinya.",
  str_homestory_811701001_12_dialog_content = "Sate mudah sekali dibuat, kok.",
  str_homestory_811701001_13_dialog_content = "... Mudah?",
  str_homestory_811701001_14_dialog_content = "Sudah kuduga. Gram, kau memang sangat berbakat...",
  str_homestory_811701001_15_dialog_content = "Koki berbakat? Tak ada yang namanya koki berbakat.",
  str_homestory_811701001_16_dialog_content = "Hmm! Generasi muda memang selalu menggembar-gemborkan bakat!",
  str_homestory_811701001_17_dialog_content = "Sebagian besar pencapaian hanya bisa dicapai dengan kerja keras dan belajar tekun. Bakat saja tak cukup!",
  str_homestory_811701001_18_dialog_content = "Aku mahir memasak karena aku sudah bekerja bertahun-tahun di dapur.",
  str_homestory_811701001_19_dialog_content = "Keterampilan memasak hampir-hampir tak ada hubungannya dengan bakat.",
  str_homestory_811701001_20_option_content = "Aku agak tak paham.",
  str_homestory_811701001_21_dialog_content = "Aku berusaha memasak dan menuruti resep sebaik mungkin...",
  str_homestory_811701001_22_dialog_content = "Tapi, hasilnya tak bagus.",
  str_homestory_811701001_23_option_content = "Ini mulai terasa masuk akal",
  str_homestory_811701001_24_dialog_content = "Keterampilan memasak bisa ditingkatkan dengan berlatih?",
  str_homestory_811701001_25_dialog_content = "Segala hal bisa ditingkatkan dengan latihan yang cukup.",
  str_homestory_811701001_26_dialog_content = "Untuk memasak sajian yang lezat, kau harus bisa merasakannya dalam hatimu.",
  str_homestory_811701001_27_dialog_content = "Merasakannya?",
  str_homestory_811701001_28_dialog_content = "Jadi, masakan Vice...",
  str_homestory_811701001_29_dialog_content = "Kau tak banyak pakai perasaan, atau justru harus banyak pakai perasaan?",
  str_homestory_811701001_30_dialog_content = "Jelas, perasaannya hilang karena dia terlalu terpaku pada instruksi memasaknya.",
  str_homestory_811701001_31_dialog_content = "Bisa dibilang, dia terhalang oleh pertimbangannya sendiri tentang untung-rugi.",
  str_homestory_811701001_32_dialog_content = "Hmm... Bisa dibilang, aku pun begitu...",
  str_homestory_811701001_33_dialog_content = "Aku takut akan menimbulkan kekacauan, tapi aku juga sangat bersemangat ingin membuat sesuatu yang baru. Gara-gara itu, aku jadi bingung dan frustrasi...",
  str_homestory_811701001_34_dialog_content = "Coba kuberi contoh sederhana.",
  str_homestory_811701001_35_dialog_content = "Saat masih bekerja di unit logistik, aku selalu membayangkan diriku ditugaskan ke baris depan, tapi setiap hari pun aku tetap bisa menghasilkan masakan yang enak. Alasannya hanya satu.",
  str_homestory_811701001_36_dialog_content = "Aku ingin semua rekan seperjuanganku bisa makan enak agar mereka kuat bertarung.",
  str_homestory_811701001_37_dialog_content = "Sekarang, aku memasak di sini pun karena alasan yang sama.",
  str_homestory_811701001_38_dialog_content = "Aku ingin kalian, generasi muda ini, makan enak sehingga kalian punya tenaga cukup untuk bertarung!",
  str_homestory_811701001_39_dialog_content = "Memasak sajian lezat sangatlah mudah.",
  str_homestory_811701001_40_dialog_content = "Ikuti saja instruksinya dan kesampingkan segala pikiran tak jelas.",
  str_homestory_811701001_41_dialog_content = "Makin kaupikir, kau justru akan makin banyak berbuat salah. Paham?",
  str_homestory_811701001_42_dialog_content = "Ya! Kali ini aku paham!",
  str_homestory_811701001_43_dialog_content = "Kau benar sekali, Gram!",
  str_homestory_811701001_44_dialog_content = "Jujur saja, menurutku mestinya kau menulis buku tentang teknik memasak.",
  str_homestory_811701001_45_dialog_content = "Para anggota Rediesel Desert saja menerbitkan buku... Kau pasti bisa!",
  str_homestory_811701001_46_dialog_content = "Aku bisa mengenalkanmu dengan beberapa penerbit di Umbraton.",
  str_homestory_811701001_47_dialog_content = "Jangan sekarang. Biar kupikirkan dulu.",
  str_homestory_811701001_48_dialog_content = "Kalau sateku sudah matang, apa kau mau mencicipinya, Nak?",
  str_homestory_811701001_49_dialog_content = "Tentu!",
  str_homestory_807701001_0_dialog_content = "Yang Mulia?",
  str_homestory_807701001_1_dialog_content = "Yang Mulia...",
  str_homestory_807701001_2_dialog_content = "Hai, kau yang memegang masa depan.",
  str_homestory_807701001_3_option_content = "Selamat datang.",
  str_homestory_807701001_4_dialog_content = "Suatu kehormatan karena kau mau tinggal di sini.",
  str_homestory_807701001_5_dialog_content = "PlayerName, jangan terlalu formal begitu.",
  str_homestory_807701001_6_dialog_content = "Aku sedang memandangi Hyacinth Tower ini.",
  str_homestory_807701001_7_option_content = "Apa aku mengganggu?",
  str_homestory_807701001_8_dialog_content = "Kau tampak sangat serius...",
  str_homestory_807701001_9_dialog_content = "Ya, aku sedang memandangi Hyacinth Tower ini.",
  str_homestory_807701001_10_dialog_content = "Hyacinth Tower? Memangnya ada apa?",
  str_homestory_807701001_11_dialog_content = "Hmm... Hyacinth Tower ini sangat berarti bagi kaum Caelestite.",
  str_homestory_807701001_12_dialog_content = "Ya! Bangunan itu sangat besar.",
  str_homestory_807701001_13_dialog_content = "Kau mungkin tak bisa melihatnya dengan jelas dari sini, tapi sebenarnya bangunannya sangat besar. Di dalamnya pun cukup luas!",
  str_homestory_807701001_14_dialog_content = "Di bangunan inilah Colossus diproduksi dan direparasi.",
  str_homestory_807701001_15_dialog_content = "Menurut informasi yang ada, banyak Caelestite juga berlatih di sini.",
  str_homestory_807701001_16_dialog_content = "Bisa dibilang, ini adalah tempat kelahiran para Navigator.",
  str_homestory_807701001_17_dialog_content = "Tempat kelahiran?",
  str_homestory_807701001_18_dialog_content = "Lihat betapa terang dan bercahayanya di bawah langit.",
  str_homestory_807701001_19_dialog_content = "Tempat ini lebih menyerupai... totem spiritual bagi kaum Caelestite.",
  str_homestory_807701001_20_dialog_content = "PlayerName, tahukah kau bagaimana orang-orang saling terikat satu sama lain?",
  str_homestory_807701001_21_dialog_content = "Ah, kau membuatku bingung...",
  str_homestory_807701001_22_dialog_content = "Aku belum pernah memikirkannya. Maaf.",
  str_homestory_807701001_23_dialog_content = "Jangan khawatir. Dulu, pertanyaan ini memang tak penting untukmu.",
  str_homestory_807701001_24_dialog_content = "Tapi, sekarang keadaan sudah berbeda. Kau harus melindungi benua ini dari sudut pandang yang baru.",
  str_homestory_807701001_25_dialog_content = "Semua orang di sini, tinggi maupun pendek, kuat maupun lemah, tua maupun muda...",
  str_homestory_807701001_26_dialog_content = "Asalkan mereka yakin dan percaya pada hal yang sama...",
  str_homestory_807701001_27_dialog_content = "Mereka terikat satu sama lain.",
  str_homestory_807701001_28_dialog_content = "Kita tak mungkin bisa menaklukkan alam jika sendirian saja.",
  str_homestory_807701001_29_dialog_content = "Kita tak punya cakar atau taring tajam. Kulit kita tak sekeras batu, dan lengan kita tak bisa dikepakkan untuk terbang.",
  str_homestory_807701001_30_dialog_content = "Tapi, kalau kita bertarung sebagai kesatuan, kekuatan kita jadi tak terbayangkan...",
  str_homestory_807701001_31_dialog_content = "Kalau menurutmu begitu...",
  str_homestory_807701001_32_dialog_content = "Yang Mulia, justru kaulah totem spiritual bagi kami.",
  str_homestory_807701001_33_dialog_content = "...",
  str_homestory_807701001_34_dialog_content = "Hmm... Benar.",
  str_homestory_807701001_35_dialog_content = "Mereka mencariku karena mereka percaya, mengagumi, atau mengharapkan perlindungan dariku.",
  str_homestory_807701001_36_dialog_content = "Ini bukan hal buruk...",
  str_homestory_807701001_37_dialog_content = "Kelompok yang bersatu padu selalu lebih kuat daripada setumpuk pasir yang berurai.",
  str_homestory_807701001_38_dialog_content = "Baik Illumina maupun Lumopolis menjaga persatuan ini dengan caranya masing-masing.",
  str_homestory_807701001_39_dialog_content = "Ya... aku sudah tahu tentang itu.",
  str_homestory_807701001_40_dialog_content = "Kau sudah dewasa, Caelestite yang memegang masa depan.",
  str_homestory_807701001_41_dialog_content = "White Tower ini, totem bagi kaum Caelestite, sama sepertimu...",
  str_homestory_807701001_42_dialog_content = "Kau maupun menara ini sama-sama punya kekuatan untuk mempersatukan.",
  str_homestory_807701001_43_dialog_content = "Aku punya kekuatan untuk menyatukan orang dan membela Eraveil...? Oh, Yang Mulia, bolehkah aku bertanya?",
  str_homestory_807701001_44_dialog_content = "Silakan.",
  str_homestory_807701001_45_dialog_content = "Apakah kau melihat Eraveil pada masa ini dalam gambaran masa depan yang kaulihat tadi?",
  str_homestory_807701001_46_dialog_content = "... Tentu saja. Dan masih ada lagi.",
  str_homestory_804201001_0_dialog_content = "Barton!",
  str_homestory_804201001_1_dialog_content = "Hoi, Navigator!",
  str_homestory_804201001_2_dialog_content = "Barton...",
  str_homestory_804201001_3_dialog_content = "Shh... Lihatlah saja bersamaku.<sprite=emo_mojing size=60 />",
  str_homestory_804201001_4_dialog_content = "... Hah?",
  str_homestory_804201001_5_dialog_content = "Apa yang sedang kaulihat?",
  str_homestory_804201001_6_dialog_content = "Di sini ada cukup banyak orang berbakat! Navigator!",
  str_homestory_804201001_7_dialog_content = "Bisa-bisanya aku tak menyadari keberadaan mereka di Colossus ini ya?",
  str_homestory_804201001_8_dialog_content = "Hmm... Sepertinya mereka tak punya cukup ruang untuk mengembangkan sayap mereka sepenuhnya di Colossus ini!",
  str_homestory_804201001_9_dialog_content = "... Orang berbakat?",
  str_homestory_804201001_10_dialog_content = "Kau sedang merekrut orang untuk Illumina?",
  str_homestory_804201001_11_dialog_content = "Merekrut? Tidak, mereka tak harus bergabung.",
  str_homestory_804201001_12_dialog_content = "PlayerName, apa kau tahu legiun mana yang kupimpin?",
  str_homestory_804201001_13_option_content = "2nd Legion",
  str_homestory_804201001_14_dialog_content = "Benar sekali!",
  str_homestory_804201001_15_option_content = "4th Legion",
  str_homestory_804201001_16_dialog_content = "Yang benar saja! <sprite=emo_shengqi size=60 />Bung, pasukanku jauh lebih besar daripada pasukan gadis itu!",
  str_homestory_804201001_17_dialog_content = "Hmm! Pasukan elite cadangan Wrath sekalipun tak akan bisa membendung satu serangan saja dari kami!",
  str_homestory_804201001_18_dialog_content = "Aku memimpin 2nd Legion, legiun paling besar. Camkan itu.",
  str_homestory_804201001_19_dialog_content = "Ya…",
  str_homestory_804201001_20_dialog_content = "Apa kau tahu apa tanggung jawab khusus yang diberikan kepadaku oleh Grand Marshal!?",
  str_homestory_804201001_21_option_content = "Dukungan cepat?",
  str_homestory_804201001_22_dialog_content = "... Itu tugas Hiiro dan Vice.",
  str_homestory_804201001_23_dialog_content = "Hoi! Otakmu ketinggalan di rumah, ya?",
  str_homestory_804201001_24_dialog_content = "Aku memimpin pasukan garnisun, tahu!",
  str_homestory_804201001_25_dialog_content = "... Nah, paham kan sekarang?",
  str_homestory_804201001_26_dialog_content = "Ya…",
  str_homestory_804201001_27_option_content = "Pertahanan dan keamanan.",
  str_homestory_804201001_28_dialog_content = "Benar! Sekarang kau mulai paham!",
  str_homestory_804201001_29_dialog_content = "Dengan pengetahuan ini, mestinya kau paham apa yang kulakukan di sini.",
  str_homestory_804201001_30_dialog_content = "Kau berhasil mengumpulkan begitu banyak orang berbakat yang punya skill unik di sini...",
  str_homestory_804201001_31_dialog_content = "Dari waktu ke waktu, terkadang mereka akan saling berkelahi...",
  str_homestory_804201001_32_dialog_content = "Serangan diam-diam! Senjata tersembunyi! Hantaman Taijutsu!",
  str_homestory_804201001_33_dialog_content = "Cih... Luar biasa.",
  str_homestory_804201001_34_dialog_content = "Aku tak ingin mereka bergabung ke Illumina. Paham, tidak?",
  str_homestory_804201001_35_dialog_content = "Menyaksikan serangan dan pertahanan mereka saja sudah cukup.",
  str_homestory_804201001_36_dialog_content = "Aku mempelajari berbagai teknik dari banyak orang. Setelah itu, akan kuajarkan semua kemampuan itu kepada para prajuritku!",
  str_homestory_804201001_37_dialog_content = "Ini pelajaran berharga!",
  str_homestory_804201001_38_dialog_content = "Begitu rupanya...",
  str_homestory_804201001_39_dialog_content = "Sebentar. Kenapa mereka berkelahi?",
  str_homestory_804201001_40_dialog_content = "Bukankah memang sudah umum bahwa Aurorian saling tak suka satu sama lain?",
  str_homestory_804201001_41_dialog_content = "Kukira kau sudah terbiasa menyaksikannya di Colossus ini.",
  str_homestory_804201001_42_dialog_content = "Tapi...",
  str_homestory_804201001_43_dialog_content = "Anggap saja mereka sedang latih tanding!",
  str_homestory_804201001_44_dialog_content = "Sekarang, aku harus melatih gerakan yang kulihat kemarin...",
  str_homestory_804201001_45_dialog_content = "Bagaimana caranya menerima tendangan dari gadis itu, ya?",
  str_homestory_804201001_46_dialog_content = "Hmm... Begitu aku berhasil menguasai tekniknya, Wrath pun tak akan berani memancing amarahku lagi!",
  str_homestory_804201001_47_dialog_content = "Hoi! Hah!<sprite=emo_nuhuo size=60 />",
  str_homestory_804201001_48_dialog_content = "... Baiklah. Semoga berhasil, Barton...",
  str_homestory_807601001_0_dialog_content = "Kleken...",
  str_homestory_807601001_1_dialog_content = "Ah! Si pahlawan pengelana akhirnya mendarat juga.",
  str_homestory_807601001_2_dialog_content = "Hai, Kleken.",
  str_homestory_807601001_3_dialog_content = "Yang Mulia sangat suka Waterfall Rock ini, ya? Aku sering melihat Yang Mulia berjalan-jalan di sekitar sini...",
  str_homestory_807601001_4_dialog_content = "Sungai ini sangat menakjubkan!",
  str_homestory_807601001_5_dialog_content = "Sungai dan mata air ini membuatku tersentuh sampai-sampai ingin menangis<sprite=emo_hanshui size=60 />.",
  str_homestory_807601001_6_dialog_content = "Omonganmu itu sarkasme, bukan?",
  str_homestory_807601001_7_dialog_content = "Yang ada di sini kan hanya beberapa sungai hiasan...",
  str_homestory_807601001_8_dialog_content = "Tak ada apa-apanya dibandingkan dengan \"samudra\" dan \"tenggelam\" seperti yang sering kausebutkan itu.",
  str_homestory_807601001_9_dialog_content = "Aku ingin berterima kasih kepadamu.",
  str_homestory_807601001_10_dialog_content = "... Untuk apa?",
  str_homestory_807601001_11_dialog_content = "Sebentar lagi, kau akan menyaksikan Gaze Technique milikku mencapai kesempurnaan.",
  str_homestory_807601001_12_dialog_content = "Aku akan bisa mengetahui apa yang belakangan ini membuat kepala kecilmu itu sibuk...",
  str_homestory_807601001_13_dialog_content = "Satu tatapan saja ke dalam mata indahmu itu, aku sudah bisa tahu jawabnya.",
  str_homestory_807601001_14_dialog_content = "Terima kasih sudah menjadi saksi pertamaku.",
  str_homestory_807601001_15_dialog_content = "Eh…",
  str_homestory_807601001_16_option_content = "Gaze Technique?",
  str_homestory_807601001_17_dialog_content = "Rupanya kau penasaran, Nak...",
  str_homestory_807601001_18_option_content = "Apa aku bisa menolak?",
  str_homestory_807601001_19_dialog_content = "Tentu.",
  str_homestory_807601001_20_dialog_content = "Tapi, makhluk-makhluk kecil dan gesit di belakangku ini tak akan membiarkanku lepas.",
  str_homestory_807601001_21_dialog_content = "Mereka suka mengamati sementara kau tidur, PlayerName...",
  str_homestory_807601001_22_dialog_content = "(... Apa-apaan ini?)",
  str_homestory_807601001_23_dialog_content = "Baiklah... Jangan lama-lama. Aku ada urusan lain.",
  str_homestory_807601001_24_dialog_content = "Nah, jadi Gaze Technique ini seperti apa?",
  str_homestory_807601001_25_dialog_content = "Biar kujelaskan, Prajurit.",
  str_homestory_807601001_26_dialog_content = "Sepertinya belum lama ini kau pergi ke Umbraton.",
  str_homestory_807601001_27_dialog_content = "Kau sedang berjalan-jalan santai di jalanan, lalu kau melihat seorang gadis kecil yang tampak sedih.",
  str_homestory_807601001_28_dialog_content = "Dia memintamu membantunya mencari harga makanan di restoran di jalan itu...",
  str_homestory_807601001_29_dialog_content = "Dia hanya punya uang sedikit, jadi dia tak bisa asal masuk saja dan memesan makanan.",
  str_homestory_807601001_30_dialog_content = "Dia tak mau dipandang dengan tatapan sinis dari pelayan restoran itu kalau dia hanya memesan sepotong roti saja.",
  str_homestory_807601001_31_dialog_content = "Kau menemaninya masuk ke restoran satu per satu dan menanyakan harga makanan di sana.",
  str_homestory_807601001_32_dialog_content = "Setiap kali tahu harganya, dia selalu menggelengkan kepala.",
  str_homestory_807601001_33_dialog_content = "Pada akhirnya, kau memutuskan untuk membelikannya makanan enak...",
  str_homestory_807601001_34_dialog_content = "Setelah menyantapnya, dia langsung pergi setelah berterima kasih kepadamu, dan meninggalkan uang di atas meja, cukup untuk membayar semua tagihan makanan kalian.",
  str_homestory_807601001_35_dialog_content = "... Bagaimana kau bisa tahu?",
  str_homestory_807601001_36_dialog_content = "(Bagaimana mungkin Gaze Technique bisa jadi luar biasa begini?)",
  str_homestory_807601001_37_dialog_content = "... Tapi, ada satu hal yang tak kupahami.",
  str_homestory_807601001_38_dialog_content = "Kalau dia sebenarnya punya uang cukup, kenapa dia tak langsung masuk saja ke restoran dan menikmati makanannya?",
  str_homestory_807601001_39_dialog_content = "Seperti katamu tadi... dia memeriksa harga makanan di setiap restoran di Umbraton!",
  str_homestory_807601001_40_dialog_content = "Hahah... Hahahah<sprite=emo_guilian size=60 />.",
  str_homestory_807601001_41_dialog_content = "Karena akulah yang menyuruhnya untuk melakukannya.",
  str_homestory_807601001_42_dialog_content = "Ini tugas dari Lord Istvan...",
  str_homestory_807601001_43_dialog_content = "Mempelajari harga makanan di Umbraton.",
  str_homestory_807601001_44_dialog_content = "Aku sebenarnya membantu gadis itu. Dengan memberinya kesempatan untuk sedikit membantuku, gadis itu jadi merasa dirinya berguna...",
  str_homestory_807601001_45_dialog_content = "Omong-omong, waktu itu, si Caelestite ini kan tak punya urusan lain yang penting. Jadi, kenapa tak sekalian saja kulibatkan dalam tugas ini?",
  str_homestory_807601001_46_dialog_content = "Belakangan ini, berjalan-jalan saja sudah cukup membuatku lelah.",
  str_homestory_807601001_47_dialog_content = "...",
  str_homestory_807601001_48_dialog_content = "Nah, paham, 'kan? Inilah Gaze Technique yang sebenarnya, PlayerName.",
  str_homestory_807601001_49_dialog_content = "Kau tampak kecewa... Menarik sekali!",
  str_homestory_804601001_0_dialog_content = "Itu dia.",
  str_homestory_804601001_1_dialog_content = "Navigator datang, Navigator pergi ♪",
  str_homestory_804601001_2_dialog_content = "Navigator tersenyum kepada Pierre, tapi Pierre hanya ingin membuat onar.",
  str_homestory_804601001_3_dialog_content = "Kau sedang berbelanja, ya?",
  str_homestory_804601001_4_dialog_content = "Berbelanja. Navigator mengira aku sedang berbelanja<sprite=emo_yinfu size=60 />",
  str_homestory_804601001_5_dialog_content = "Dian pasti akan bilang tidak, Kara pasti akan bilang, \"Benar sekali!\", Niel pasti akan bilang, \"Kira-kira begitulah...\", tapi Pierre hanya akan tertawa kecil.<sprite=emo_muji size=60 />",
  str_homestory_804601001_6_dialog_content = "Jadi, menurutmu, kira-kira apa yang akan kukatakan?",
  str_homestory_804601001_7_dialog_content = "...%^&",
  str_homestory_804601001_8_dialog_content = "Sudahlah. Aku sedang tak berminat main teka-teki.",
  str_homestory_804601001_9_dialog_content = "Aku ingin menanyakan kabarmu di sini...",
  str_homestory_804601001_10_dialog_content = "Aku lega melihatmu tetap cerdas dan usil seperti biasanya.",
  str_homestory_804601001_11_dialog_content = "Navigator peduli dengan Keating. Pierre merasa terhormat ♪",
  str_homestory_804601001_12_dialog_content = "Navigator, memangnya kau tak ingin tahu siapa yang belum lama ini kutemui?",
  str_homestory_804601001_13_dialog_content = "... Perasaanku jadi tak enak, nih...<sprite=emo_tanqi size=60 />",
  str_homestory_804601001_14_dialog_content = "Jadi, kau bertemu dengan siapa?",
  str_homestory_804601001_15_dialog_content = "Kawan-kawan kecilmu itu harus lebih hati-hati di sini. Tak baik mencibir orang lain...",
  str_homestory_804601001_16_dialog_content = "Ini bukan Lumopolis. Sebagian Aurorian mudah marah, tahu!",
  str_homestory_804601001_17_dialog_content = "Ada juga Aurorian yang sangat sensitif. Kata-katamu yang kejam itu mungkin saja membuat mereka menangis...",
  str_homestory_804601001_18_dialog_content = "Navigator mengkhawatirkan kami. Navigator peduli dengan teman-temannya ♪",
  str_homestory_804601001_19_dialog_content = "Kami bertemu dengan seorang tukang reparasi berekor panjang, dan dia membuatkan lengan robot untuk kami untuk menangkap ayam.",
  str_homestory_804601001_20_dialog_content = "Kami bertemu dengan seekor burung gemuk dan dia memberi kami banyak bola salju.",
  str_homestory_804601001_21_dialog_content = "Kami bertemu dengan seekor anjing yang mengenakan setelan jas. Dia sedih karena tak seorang pun tertarik dengan lukisan palsunya.",
  str_homestory_804601001_22_dialog_content = "Pierre bertemu dengan seorang Navigator berbadan pendek gendut, yang sedang berdiri di hadapanku dan mengkhawatirkan teman-temannya.",
  str_homestory_804601001_23_dialog_content = "... Fyuh... Lebih baik dari dugaanku.",
  str_homestory_804601001_24_dialog_content = "Jujur saja, ini mungkin adalah kata-kata paling lembut yang pernah kauucapkan.",
  str_homestory_804601001_25_dialog_content = "Orang jadi lembut karena alasan tertentu.",
  str_homestory_804601001_26_dialog_content = "Di rak buku, ada buku yang disukai Dian.",
  str_homestory_804601001_27_dialog_content = "Di kamar, ada lap kacamata yang dibutuhkan Niel.",
  str_homestory_804601001_28_dialog_content = "Di ruang makan, ada gantungan topi untuk Kara.",
  str_homestory_804601001_29_dialog_content = "Di atas rumput, ada camilan kesukaan Gege dan Pierre♪",
  str_homestory_804601001_30_dialog_content = "Navigator yang penuh perhatian adalah kawan karib kami.",
  str_homestory_804601001_31_dialog_content = "Navigator adalah bintang masa depan.",
  str_homestory_804601001_32_dialog_content = "Bintang yang akan tumbuh makin tinggi♪",
  str_homestory_804601001_33_dialog_content = "... Sajaknya bagus, kecuali baris terakhir.",
  str_homestory_804601001_34_dialog_content = "Navigator, apa rencanamu?",
  str_homestory_804601001_35_option_content = "Kembali untuk beristirahat",
  str_homestory_804601001_36_dialog_content = "Aku mau tidur siang.",
  str_homestory_804601001_37_option_content = "Berkeliling",
  str_homestory_804601001_38_dialog_content = "Aku mau memeriksa apa yang sedang dilakukan orang-orang lain.",
  str_homestory_804601001_39_dialog_content = "Paham. Pierre paham.",
  str_homestory_804601001_40_dialog_content = "Tapi, Pierre tak terlalu peduli. Ini sebaris sajak untuk sang Master.",
  str_homestory_804601001_41_dialog_content = "Gege sedang menaburkan pupuk di dekat taman. Menaburkan pupuk♪",
  str_homestory_804601001_42_dialog_content = "?!",
  str_homestory_804601001_43_dialog_content = "Menaburkan pupuk?",
  str_homestory_804601001_44_dialog_content = "Pierre sangat baik. Kalau ada waktu, periksalah ke sana ♪",
  str_homestory_804601001_45_dialog_content = "... Terima kasih atas perhatianmu!",
  str_homestory_805701001_0_dialog_content = "Ini... bulu kucing?",
  str_homestory_805701001_1_dialog_content = "Huahm—",
  str_homestory_805701001_2_dialog_content = "Hmm? Philyshy?",
  str_homestory_805701001_3_dialog_content = "Hah... Hah...<sprite=emo_kun size=60 />",
  str_homestory_805701001_4_dialog_content = "... Philyshy?",
  str_homestory_805701001_5_dialog_content = "Fyuh... Meong!",
  str_homestory_805701001_6_dialog_content = "Apa-apaan, sih! Ini PlayerName, meong.",
  str_homestory_805701001_7_dialog_content = "Memangnya kau tak lihat aku sedang tidur, meong?",
  str_homestory_805701001_8_dialog_content = "Kembalilah kalau aku sudah bangun dari tidur siang, meong.",
  str_homestory_805701001_9_dialog_content = "Aku akan mimpi indah di tumpukan jerami yang empuk ini, meong...",
  str_homestory_805701001_10_dialog_content = "Sebentar, Philyshy! Ada yang ingin kusampaikan kepadamu!",
  str_homestory_805701001_11_dialog_content = "Hah... Hah... Meong!",
  str_homestory_805701001_12_dialog_content = "Hmm... Apa yang mau kausampaikan, meong?",
  str_homestory_805701001_13_dialog_content = "Semoga saja hal yang penting, meong!",
  str_homestory_805701001_14_dialog_content = "Anu... Ada beberapa orang Aurorian yang mendatangiku...",
  str_homestory_805701001_15_dialog_content = "Philyshy, apa kau...",
  str_homestory_805701001_16_option_content = "Merasa tak enak badan?",
  str_homestory_805701001_17_dialog_content = "Gatal-gatal?",
  str_homestory_805701001_18_dialog_content = "Kehilangan nafsu makan?",
  str_homestory_805701001_19_dialog_content = "Apa sih maksudmu, meong?",
  str_homestory_805701001_20_dialog_content = "Philyshy tak paham.",
  str_homestory_805701001_21_option_content = "Musim bulu rontok?",
  str_homestory_805701001_22_dialog_content = "Rontok apa... meong?",
  str_homestory_805701001_23_dialog_content = "Apa itu?",
  str_homestory_805701001_24_dialog_content = "(Aktingnya payah sekali!)",
  str_homestory_805701001_25_dialog_content = "Sudahlah, Philyshy tak merasakan apa pun, kok!",
  str_homestory_805701001_26_dialog_content = "(Mengelus ekor Philyshy)",
  str_homestory_805701001_27_dialog_content = "Meong!",
  str_homestory_805701001_28_dialog_content = "PlayerName, berani-beraninya kau menyentuh ekor seorang gadis?",
  str_homestory_805701001_29_dialog_content = "Rasanya menyenangkan. Tidak, meong!",
  str_homestory_805701001_30_dialog_content = "Philyshy, saat kau menggoyangkan badanmu, banyak sekali bulumu yang rontok!",
  str_homestory_805701001_31_dialog_content = "Ti-tidak, kok...!",
  str_homestory_805701001_32_dialog_content = "Huuhuu... Meong. Aku tak bisa menghentikannya!",
  str_homestory_805701001_33_dialog_content = "Ini musim bulu rontok... Tidak, meong!",
  str_homestory_805701001_34_dialog_content = "Buluku menyerap cukup banyak sinar matahari agar bisa berevolusi, meong!",
  str_homestory_805701001_35_dialog_content = "Kalau musim bulu rontoknya sudah selesai... aku akan berubah jadi Super Philyshy, meong!",
  str_homestory_805701001_36_dialog_content = "Tapi... kalau bulumu beterbangan ke mana-mana...",
  str_homestory_805701001_37_dialog_content = "Mungkin saja ada Aurorian yang alergi bulu kucing.",
  str_homestory_805701001_38_dialog_content = "Hmm... Kalau begitu, apa yang harus kulakukan?",
  str_homestory_805701001_39_dialog_content = "Ini di luar kendali Philyshy.<sprite=emo_tanqi size=60 />",
  str_homestory_805701001_40_dialog_content = "Kau benar... Biar kupikirkan dulu...",
  str_homestory_805701001_41_dialog_content = "Bagaimana kalau... kumandikan saja kau!",
  str_homestory_805701001_42_dialog_content = "Bulumu akan jadi lebih lembut dan mulus. Tak ada lagi bulu rontok.",
  str_homestory_805701001_43_dialog_content = "Istvan mengajariku cara melakukannya.",
  str_homestory_805701001_44_dialog_content = "Baiklah... Tapi, ini semata karena kau sudah menyiapkan tumpukan jerami yang nyaman ini di Eraveil.",
  str_homestory_805701001_45_dialog_content = "Permintaan untuk memandikanku dikabulkan, meong!",
  str_homestory_803601001_0_dialog_content = "Hydrad?",
  str_homestory_803601001_1_dialog_content = "Sedang apa kau?",
  str_homestory_803601001_2_dialog_content = "Memangnya kau tak lihat?",
  str_homestory_803601001_3_dialog_content = "Aku sedang berdiri.",
  str_homestory_803601001_4_dialog_content = "... Itu sih aku tahu.",
  str_homestory_803601001_5_dialog_content = "...",
  str_homestory_803601001_6_dialog_content = "...",
  str_homestory_803601001_7_dialog_content = "Hei.",
  str_homestory_803601001_8_dialog_content = "Ya?",
  str_homestory_803601001_9_dialog_content = "Kemarin aku terluka.",
  str_homestory_803601001_10_dialog_content = "?!",
  str_homestory_803601001_11_option_content = "Kau baik-baik saja?",
  str_homestory_803601001_12_dialog_content = "Masih sehat saja, sih.",
  str_homestory_803601001_13_option_content = "Memangnya kemarin kau pergi ke mana?",
  str_homestory_803601001_14_dialog_content = "Aku tahu apa yang kaucemaskan.",
  str_homestory_803601001_15_dialog_content = "Kejadiannya bukan di sini.",
  str_homestory_803601001_16_dialog_content = "Aku... aku hanya khawatir tentang kesehatanmu.",
  str_homestory_803601001_17_dialog_content = "Bagaimana kondisimu? Sudah mendingan?",
  str_homestory_803601001_18_dialog_content = "Yah, kurang lebih begitu.",
  str_homestory_803601001_19_dialog_content = "Aku bisa pulih dengan cepat berkat Shadow Wolf.",
  str_homestory_803601001_20_dialog_content = "Baiklah. Bisa ceritakan kepadaku apa yang terjadi?",
  str_homestory_803601001_21_dialog_content = "Jangan bilang kau malah menyukainya.",
  str_homestory_803601001_22_dialog_content = "Aku bertarung demi sesuatu.",
  str_homestory_803601001_23_dialog_content = "Di Black Market di Umbraton.",
  str_homestory_803601001_24_dialog_content = "Memangnya ada hal penting apa?",
  str_homestory_803601001_25_dialog_content = "Sepertinya suatu produk dari peradaban kuno.",
  str_homestory_803601001_26_dialog_content = "Sepertinya?",
  str_homestory_803601001_27_dialog_content = "Kau sendiri belum yakin?",
  str_homestory_803601001_28_dialog_content = "Kalau belum dicoba, mana kutahu.",
  str_homestory_803601001_29_dialog_content = "... Memangnya, produk apa itu?",
  str_homestory_803601001_30_dialog_content = "Semacam alat yang bisa sepenuhnya mewujudkan Illusion atau Shadow magic.",
  str_homestory_803601001_31_dialog_content = "Anu... Tapi, Shadow Wolf kan selama ini selalu ada di sampingmu.",
  str_homestory_803601001_32_dialog_content = "Ya, tapi aku tetap ingin bisa mengelus bulu mereka setiap hari.",
  str_homestory_803601001_33_dialog_content = "Bulu sungguhan yang tumbuh di kulit mereka, bukan bulu-bulu yang rontok dari tubuh mereka.",
  str_homestory_803601001_34_dialog_content = "Begitu rupanya...",
  str_homestory_803601001_35_dialog_content = "(Hydrad... mungkin sedikit merasa kesepian?)",
  str_homestory_803601001_36_dialog_content = "Menurutku, produk itu palsu.",
  str_homestory_803601001_37_dialog_content = "Perangkat itu?",
  str_homestory_803601001_38_dialog_content = "Ya.",
  str_homestory_803601001_39_dialog_content = "Aku belum pernah dengar ada perangkat seperti itu.",
  str_homestory_803601001_40_dialog_content = "(Apa dia akan merasa lebih baik kalau perangkat itu ternyata memang palsu?)",
  str_homestory_803601001_41_dialog_content = "Aku setuju denganmu.",
  str_homestory_803601001_42_dialog_content = "Benda seperti itu mestinya jadi barang pusaka yang tak ternilai...",
  str_homestory_803601001_43_dialog_content = "Tak mungkin ada di pasar gelap.",
  str_homestory_803601001_44_dialog_content = "... Benar.",
  str_homestory_803601001_45_dialog_content = "Karena kau juga berpikir begitu.",
  str_homestory_803601001_46_dialog_content = "Sebaiknya aku pergi.",
  str_homestory_803601001_47_dialog_content = "Sampai jumpa!",
  str_homestory_803601001_48_dialog_content = "(Kalau perangkat itu ternyata memang nyata, apa yang akan kulakukan dengannya?)",
  str_homestory_811401001_0_dialog_content = "Kuda ini...",
  str_homestory_811401001_1_dialog_content = "Ah, Navigator yang terhormat.",
  str_homestory_811401001_2_dialog_content = "Apa Anna sedang akan menemuimu?",
  str_homestory_811401001_3_dialog_content = "Atau kau kemari untuk menemuiku?",
  str_homestory_811401001_4_dialog_content = "Maaf, aku tinggal di sini lama sekali. Bunga-bunga ini sungguh harum...",
  str_homestory_811401001_5_dialog_content = "Tak perlu dipikirkan. Nikmati saja bunga-bunganya.",
  str_homestory_811401001_6_dialog_content = "Cepat sekali. Bunga-bunga ini...",
  str_homestory_811401001_7_dialog_content = "Lebih banyak daripada yang kukira.",
  str_homestory_811401001_8_dialog_content = "Hmm? Ada apa, Navigator?",
  str_homestory_811401001_9_dialog_content = "Ah... Aku hanya bergumam kepada diriku sendiri tentang bunga-bunga ini.",
  str_homestory_811401001_10_dialog_content = "Aku baru saja memesannya dari Courier Union<sprite=emo_gezitou size=60 /> beberapa hari lalu.",
  str_homestory_811401001_11_dialog_content = "Beberapa orang menyarankan kita untuk menambahkan bebungaan ke semua batuan dan pepohonan.",
  str_homestory_811401001_12_dialog_content = "Oh? Aku juga berpikir begitu!",
  str_homestory_811401001_13_dialog_content = "Kemarin aku baru bilang kepada Anna bahwa kita butuh lebih banyak bunga.",
  str_homestory_811401001_14_dialog_content = "Ya. Itulah sebabnya aku menghubungi Courier Union.",
  str_homestory_811401001_15_dialog_content = "Tapi, jumlahnya agak lebih banyak dari yang kukira...",
  str_homestory_811401001_16_dialog_content = "Aku juga membeli beberapa bunga setelah menuntaskan tugas terakhirku.",
  str_homestory_811401001_17_dialog_content = "Oh, begitu rupanya...",
  str_homestory_811401001_18_dialog_content = "Navigator, tempatmu ini sangat nyaman.",
  str_homestory_811401001_19_dialog_content = "Aku melihat-lihat toko dan menemukan gin kesukaanku di sana...",
  str_homestory_811401001_20_dialog_content = "Begitu pula semua herba, sirup, dan rempah untuk membuat koktail lezat.",
  str_homestory_811401001_21_dialog_content = "Hahah. Aku kaget, tapi senang!",
  str_homestory_811401001_22_dialog_content = "Kau jadi makin penuh pertimbangan.",
  str_homestory_811401001_23_dialog_content = "Penuh pertimbangan...",
  str_homestory_811401001_24_dialog_content = "Ada kejadian apa sampai bocah cuek ini bisa berubah jadi manis dan penuh perhatian?",
  str_homestory_811401001_25_dialog_content = "Genevieve masih bicara tentang stok gin di tokoku, ya?",
  str_homestory_811401001_26_dialog_content = "Bukan hanya itu. Kau juga memesan bunga untuk para gadis di sini.",
  str_homestory_811401001_27_dialog_content = "Yah... Sebenarnya...",
  str_homestory_811401001_28_dialog_content = "Orang yang menyuruhku untuk menyimpan stok gin dan memesan bunga adalah...",
  str_homestory_811401001_29_dialog_content = "... Smokey.",
  str_homestory_811401001_30_dialog_content = "... Oh?",
  str_homestory_811401001_31_dialog_content = "Masih banyak lagi yang dimintanya, jadi kurasa dia melakukannya bukan untukmu...",
  str_homestory_811401001_32_dialog_content = "Karena kau sendiri menyebutkannya... Waktu itu, saat aku bicara dengan Anna, aku memang merasakan ada udara panas di sekitarku.",
  str_homestory_811401001_33_dialog_content = "Aku sama sekali tak berpikir tentang dia, karena di sini memang ada beberapa orang yang suka main api<sprite=emo_nuhuo size=60 />.",
  str_homestory_811401001_34_dialog_content = "... Dia itu...",
  str_homestory_811401001_35_dialog_content = "Mungkin dia tak ingin aku tahu tentang ini.",
  str_homestory_811401001_36_dialog_content = "Anu... Menurutku...",
  str_homestory_811401001_37_option_content = "Sepertinya memang dia berharap begitu.",
  str_homestory_811401001_38_dialog_content = "Kalau tidak, mestinya dia bisa membeli gin dan bunga itu sendiri.",
  str_homestory_811401001_39_dialog_content = "Maksudku... Mestinya dia tak perlu menyuruhku.",
  str_homestory_811401001_40_option_content = "Dia memang tak ingin kau tahu",
  str_homestory_811401001_41_dialog_content = "Sebenarnya aku menanyainya apakah gin ini untukmu. Tapi, dia bilang bukan...",
  str_homestory_811401001_42_dialog_content = "Benarkah?",
  str_homestory_811401001_43_dialog_content = "Agak aneh.",
  str_homestory_811401001_44_dialog_content = "Omong-omong, Navigator, percakapan hari ini cukup kita berdua saja yang tahu, ya.",
  str_homestory_811401001_45_dialog_content = "Aku memang akhirnya tahu tentang kebaikannya, tapi jangan sampai ada yang menyebutkan hal ini langsung di depannya...",
  str_homestory_811401001_46_dialog_content = "Untuk menutupi rasa malunya, biasanya dia akan menyalakan api atau berbuat onar.",
  str_homestory_811401001_47_dialog_content = "Aku mengerti…",
  str_homestory_811401001_48_dialog_content = "Kau memang sangat memahaminya!",
  str_homestory_811401001_49_dialog_content = "Begitukah menurutmu? Aku malah tak tahu soal itu.",
  str_homestory_801801001_0_dialog_content = "Aura ini...",
  str_homestory_801801001_1_dialog_content = "Bodoh amat!",
  str_homestory_801801001_2_dialog_content = "Dan... jangan buang-buang napas!",
  str_homestory_801801001_3_dialog_content = "Terlalu banyak orang tolol di dunia ini! Api! Bakar!<sprite=emo_nuhuo size=60 />",
  str_homestory_801801001_4_dialog_content = "(Dia benar-benar murka!)",
  str_homestory_801801001_5_dialog_content = "Hoi, Regina!",
  str_homestory_801801001_6_dialog_content = "Navigator, apa pendapatmu tentang demo baruku ini?",
  str_homestory_801801001_7_dialog_content = "Lho, kukira tadi kau mengumpat...",
  str_homestory_801801001_8_dialog_content = "Kau mendengarnya?",
  str_homestory_801801001_9_dialog_content = "Ya!",
  str_homestory_801801001_10_dialog_content = "Oh... Padahal aku sudah berusaha agar tak terlalu vulgar!",
  str_homestory_801801001_11_dialog_content = "Tapi, ternyata kau tetap bisa mendengarnya, ya?",
  str_homestory_801801001_12_dialog_content = "Kau terlalu banyak bergaul dengan anak-anak nakal!",
  str_homestory_801801001_13_dialog_content = "?",
  str_homestory_801801001_14_dialog_content = "Ehem... Tak pernah, kok...",
  str_homestory_801801001_15_dialog_content = "Sudahlah. Bodoh amat!",
  str_homestory_801801001_16_dialog_content = "Lagu baruku belum selesai? Ada saran? Bilang saja!",
  str_homestory_801801001_17_dialog_content = "Tema? Lirik? Melodi?",
  str_homestory_801801001_18_dialog_content = "Kemampuan musikku payah.",
  str_homestory_801801001_19_dialog_content = "Memangnya kenapa? Tak ada yang sangat kubenci selain orang-orang tua renta yang bersikeras menentukan berbagai aturan untuk musik!",
  str_homestory_801801001_20_dialog_content = "Katakan saja sesuatu, apa saja!",
  str_homestory_801801001_21_dialog_content = "...",
  str_homestory_801801001_22_option_content = "Barbara adalah penyanyi terbaik",
  str_homestory_801801001_23_dialog_content = "Hah? Apa-apaan katamu barusan?",
  str_homestory_801801001_24_dialog_content = "Oh, aku paham. Sarkasme.",
  str_homestory_801801001_25_option_content = "Metal selamanya!",
  str_homestory_801801001_26_dialog_content = "Benar sekali!",
  str_homestory_801801001_27_dialog_content = "Akan kutulis!",
  str_homestory_801801001_28_dialog_content = "Hah! Lagu baru yang dikarang dengan bantuan Caelestite pasti akan keren jadinya!",
  str_homestory_801801001_29_dialog_content = "Ah. Kau bersaing dengan Barbara dalam segala hal, begitu pula dengan rekan-rekanmu sesama pencinta musik metal?",
  str_homestory_801801001_30_dialog_content = "Ya ampun. Memangnya ada musisi yang setulusnya saling menghormati?<sprite=emo_shengqi size=60 />",
  str_homestory_801801001_31_dialog_content = "Terutama di genre yang kugeluti. Sebagian besar dari mereka itu bebal dan penuh kepura-puraan!",
  str_homestory_801801001_32_dialog_content = "Merasa paling paham musik rock dan lebih senior dibanding lainnya, padahal belum tentu mereka pernah mengarang satu lagu pun!",
  str_homestory_801801001_33_dialog_content = "Hmm! Seandainya aku bisa, akan kubakar mereka semua...",
  str_homestory_801801001_34_dialog_content = "Membahas musik rock dengan mereka justru lebih menjengkelkan daripada mendengarkan lagu baru Barbara!",
  str_homestory_801801001_35_dialog_content = "... Lho, kukira kau benar-benar tak menyukai Barbara?",
  str_homestory_801801001_36_dialog_content = "Dua detik.",
  str_homestory_801801001_37_dialog_content = "?",
  str_homestory_801801001_38_dialog_content = "Aku hanya bisa tahan mendengarkan lagu Barbara selama 2 detik saja.",
  str_homestory_801801001_39_dialog_content = "Ahh...",
  str_homestory_809201001_0_dialog_content = "Itu...",
  str_homestory_809201001_1_dialog_content = "Hoi, Pact.",
  str_homestory_809201001_2_dialog_content = "Siapa lagi, sih?<sprite=emo_baiyan size=60 />",
  str_homestory_809201001_3_dialog_content = "Ehem. Ayunan ini banyak disukai orang-orang.",
  str_homestory_809201001_4_dialog_content = "Jadi... kau suka main ayunan ini?",
  str_homestory_809201001_5_dialog_content = "Pertanyaanmu tak tersusun dengan baik.",
  str_homestory_809201001_6_dialog_content = "Pertama, coba jelaskan apa arti \"suka\"?",
  str_homestory_809201001_7_option_content = "Jelaskan",
  str_homestory_809201001_8_dialog_content = "Menurutku, kalau kita suka sesuatu, kita pasti ingin sering-sering melakukannya.",
  str_homestory_809201001_9_dialog_content = "Kalau begitu, apa tolok ukur \"sering\"? Itu kan juga tak jelas.",
  str_homestory_809201001_10_dialog_content = "Apakah terus-menerus?",
  str_homestory_809201001_11_dialog_content = "Atau hanya saat aku punya waktu luang?",
  str_homestory_809201001_12_dialog_content = "Atau barangkali, aku tak sering memikirkannya. Tapi, saat aku memikirkannya, aku langsung bertindak?",
  str_homestory_809201001_13_dialog_content = "(Ya ampun! Padahal niatku kan hanya ingin mengobrol santai dengan Pact...)",
  str_homestory_809201001_14_dialog_content = "Menurutku, tolok ukur \"sering\" adalah melakukannya saat punya waktu luang.",
  str_homestory_809201001_15_option_content = "(Tak usah berikan penjelasan)",
  str_homestory_809201001_16_dialog_content = "Memangnya ada orang yang butuh penjelasan arti kata \"suka\"?",
  str_homestory_809201001_17_dialog_content = "Kalau punya waktu, aku suka berjalan-jalan.",
  str_homestory_809201001_18_dialog_content = "Sesuatu yang ingin kulakukan saat aku punya waktu luang?",
  str_homestory_809201001_19_dialog_content = "Aku mengerti.",
  str_homestory_809201001_20_dialog_content = "Dalam hal ini, aku suka duduk-duduk di ayunan ini.",
  str_homestory_809201001_21_dialog_content = "Kursi gantung semacam ini memberikan sensasi seakan-akan tak ada gravitasi...",
  str_homestory_809201001_22_dialog_content = "Ayunan ini memberiku perasaan sukacita yang tak bisa dijelaskan dengan kata-kata.",
  str_homestory_809201001_23_dialog_content = "Benarkah? Baguslah kalau begitu!",
  str_homestory_809201001_24_dialog_content = "Awalnya, aku tak yakin apa ayunan ini ide yang bagus.",
  str_homestory_809201001_25_dialog_content = "Aku senang kalau kau menyukainya!",
  str_homestory_809201001_26_dialog_content = "Tapi, ada masalah juga.",
  str_homestory_809201001_27_dialog_content = "Hunting Stone kesulitan mencari jumlah kekuatan yang pas untuk mendorong ayunan ini untukku.",
  str_homestory_809201001_28_dialog_content = "Sekali waktu, aku bahkan sampai jatuh!",
  str_homestory_809201001_29_dialog_content = "Hahahah...",
  str_homestory_809201001_30_dialog_content = "Kau menertawaiku, nih?<sprite=emo_shengqi size=60 />",
  str_homestory_809201001_31_option_content = "Bantah",
  str_homestory_809201001_32_dialog_content = "Mana mungkin…",
  str_homestory_809201001_33_dialog_content = "Yang benar? Kalau begitu, kenapa ujung bibirmu tersungging begitu?",
  str_homestory_809201001_34_option_content = "Akui",
  str_homestory_809201001_35_dialog_content = "Maaf…",
  str_homestory_809201001_36_dialog_content = "Aku bisa membayangkannya...",
  str_homestory_809201001_37_dialog_content = "Ehem... Waktu itu, apa kau terluka?",
  str_homestory_809201001_38_dialog_content = "Memangnya kaukira aku seringkih itu?",
  str_homestory_809201001_39_dialog_content = "Syukurlah! Karena kau sangat suka ayunan ini...",
  str_homestory_809201001_40_dialog_content = "Boleh kudorongkan?",
  str_homestory_809201001_41_dialog_content = "Hmm? Kau mau mendorongnya untukku?",
  str_homestory_809201001_42_dialog_content = "Yah, kalau kau tak keberatan, sih. Kekuatanku tak ada apa-apanya dibandingkan Hunting Stone.",
  str_homestory_809201001_43_dialog_content = "Itu tergantung pada makna \"keberatan\" menurutmu.",
  str_homestory_809201001_44_dialog_content = "Eh…",
  str_homestory_809201001_45_dialog_content = "Sudahlah. Ini saatnya main ayunan!",
  str_homestory_809201001_46_dialog_content = "Baiklah... Karena kau begitu tulus... Ayo sajalah.",
  str_homestory_809901001_0_dialog_content = "Areia...",
  str_homestory_809901001_1_dialog_content = "Ah, PlayerName...",
  str_homestory_809901001_2_dialog_content = "Terima kasih sudah mengundangku kemari. Aku senang sekali!",
  str_homestory_809901001_3_dialog_content = "Sama-sama!",
  str_homestory_809901001_4_dialog_content = "Sepertinya kau belum terbiasa dengan area ini. Apa perlu kuantar berkeliling?",
  str_homestory_809901001_5_dialog_content = "PlayerName, memangnya kau sungguh punya waktu luang untuk melakukannya?",
  str_homestory_809901001_6_dialog_content = "Tentu saja. Tak ada orang yang hafal tempat ini sebaik diriku.",
  str_homestory_809901001_7_dialog_content = "Tapi...",
  str_homestory_809901001_8_dialog_content = "Aku... sebaiknya aku kembali saja ke kamarku.",
  str_homestory_809901001_9_dialog_content = "Hah? Areia, kau tak suka pemandangan di luar sana, ya?",
  str_homestory_809901001_10_dialog_content = "Justru sebaliknya! Aku suka pemandangan di sini!",
  str_homestory_809901001_11_dialog_content = "Baru sekali ini aku tinggal di tempat yang terpencil dan nyaman seperti ini.",
  str_homestory_809901001_12_option_content = "Ucapkan terima kasih",
  str_homestory_809901001_13_dialog_content = "Aku senang sekali kau suka tinggal di sini!",
  str_homestory_809901001_14_dialog_content = "Di sini, suasananya damai dan tenang, tapi juga seru dan meriah.",
  str_homestory_809901001_15_dialog_content = "Ayo kuantar kau berkeliling.",
  str_homestory_809901001_16_dialog_content = "Tapi, aku takut...",
  str_homestory_809901001_17_option_content = "Tanyai dia",
  str_homestory_809901001_18_dialog_content = "Kenapa terburu-buru kembali ke kamarmu?",
  str_homestory_809901001_19_dialog_content = "Aku takut...",
  str_homestory_809901001_20_dialog_content = "Bagaimana kalau kutukan dan duri-duri gelap di tubuhku ini malah merusak keindahan di sini?",
  str_homestory_809901001_21_dialog_content = "Pasti nanti PlayerName jadi kerepotan...",
  str_homestory_809901001_22_dialog_content = "Areia, kau sungguh sangat perhatian.",
  str_homestory_809901001_23_dialog_content = "Tapi, menurutku, kau tak akan merusak keindahan tempat ini.",
  str_homestory_809901001_24_dialog_content = "Hmm?",
  str_homestory_809901001_25_dialog_content = "Kita sudah cukup lama saling kenal. Kutukanmu sama sekali tak berpengaruh padaku.",
  str_homestory_809901001_26_dialog_content = "Tapi, duri-duri gelapku ini...",
  str_homestory_809901001_27_dialog_content = "Bukankah duri-duri itu adalah kawanmu yang melindungimu dari kutukan itu?",
  str_homestory_809901001_28_dialog_content = "Ya…",
  str_homestory_809901001_29_dialog_content = "Kawan Areia berarti juga kawanku!",
  str_homestory_809901001_30_dialog_content = "Lagi pula...",
  str_homestory_809901001_31_dialog_content = "Seingatku, selama ini kan kau juga berusaha mencari cara untuk menghilangkan kutukan itu.",
  str_homestory_809901001_32_dialog_content = "Cobalah berjalan-jalan ke sekitar. Siapa tahu kau bisa menemukan sesuatu.",
  str_homestory_809901001_33_dialog_content = "Hah... Aku sulit memercayainya, bahkan kalaupun PlayerName sekalipun yang bilang begitu.",
  str_homestory_809901001_34_dialog_content = "Sudah bertahun-tahun. Memangnya ada kemungkinan aku bisa menemukan solusinya di sini?",
  str_homestory_809901001_35_dialog_content = "Kalau begitu, selain untuk bekerja, kau tak banyak keluar dari kamarmu, ya?",
  str_homestory_809901001_36_dialog_content = "Ya…",
  str_homestory_809901001_37_dialog_content = "Kalau banyak menghabiskan waktu di tengah alam, suasana hati kita akan ikut membaik.",
  str_homestory_809901001_38_dialog_content = "Kalau tak dicoba, mana kita tahu, 'kan? Siapa tahu, suasana hati yang gembira bisa melemahkan kutukan itu!",
  str_homestory_809901001_39_dialog_content = "...",
  str_homestory_809901001_40_dialog_content = "Hahahah...",
  str_homestory_809901001_41_dialog_content = "Terima kasih. Aku sudah merasa lebih baik sekarang.<sprite=emo_aixin size=60 />",
  str_homestory_809901001_42_dialog_content = "Baiklah kalau begitu... Bolehkah aku pergi ke tambang?",
  str_homestory_809901001_43_dialog_content = "Hmm?",
  str_homestory_801601001_0_dialog_content = "Kafka?",
  str_homestory_801601001_1_dialog_content = "Sebentar, Kafka... Noda air<sprite=emo_hanshui size=60 /> di tanah ini apa?",
  str_homestory_801601001_2_dialog_content = "Ah... Maaf. Itu air liur<sprite=emo_goutou size=60 /> Franz. Aku baru saja mengepelnya.",
  str_homestory_801601001_3_dialog_content = "Kalau sedang senang, dia jadi lebih banyak berliur. Aku sudah berusaha keras mengatasi masalah baru ini.",
  str_homestory_801601001_4_dialog_content = "Anu... Setidaknya dia jadi tak terlalu sering membuat kasurku basah dengan liurnya, sih.",
  str_homestory_801601001_5_dialog_content = "Dia pantas diberi hadiah... Selama ini Franz selalu bersikap baik, 'kan?",
  str_homestory_801601001_6_dialog_content = "Dia bakalan kegirangan mendengar pujianmu itu.",
  str_homestory_801601001_7_dialog_content = "Aku tahu dia sangat senang di sini.",
  str_homestory_801601001_8_dialog_content = "Hmm? Karena di sini dia punya ruang lebih luas daripada di Colossus?",
  str_homestory_801601001_9_dialog_content = "Atau karena dia terus saja bertemu dengan orang-orang aneh...",
  str_homestory_801601001_10_dialog_content = "Kau kan tahu sendiri, dia suka hal-hal aneh.",
  str_homestory_801601001_11_dialog_content = "Misalnya?",
  str_homestory_801601001_12_dialog_content = "Mestinya tadi aku bilang \"makhluk-makhluk aneh\".",
  str_homestory_801601001_13_dialog_content = "Makhluk aneh...",
  str_homestory_801601001_14_dialog_content = "Aku paham! Yang kaumaksud pastilah... dia...",
  str_homestory_801601001_15_option_content = "Tourdog?",
  str_homestory_801601001_16_dialog_content = "Hmm... Kurang lebih begitulah. Aku tak banyak bicara dengannya.",
  str_homestory_801601001_17_dialog_content = "Tapi, ekor Franz bergoyang-goyang tak karuan setiap kali dia melihat Tourdog. Sekali waktu, Franz bahkan berusaha menggigit telinga Tourdog.",
  str_homestory_801601001_18_dialog_content = "Ah? Memangnya apa yang dilakukan Tourdog?",
  str_homestory_801601001_19_dialog_content = "Bukan apa-apa, sih. Dia hanya menatap Franz sebentar sambil memegang panci. Sepertinya dia ingin mengatakan sesuatu.",
  str_homestory_801601001_20_dialog_content = "(... Mungkin saja dia sebenarnya berniat meminta Franz menggambarkan sesuatu untuknya!)",
  str_homestory_801601001_21_dialog_content = "Akhirnya, dia menatap cakar Franz dan pergi sambil menggeleng-gelengkan kepala.",
  str_homestory_801601001_22_dialog_content = "Fiuh... Syukurlah...",
  str_homestory_801601001_23_dialog_content = "Omong-omong, telinganya tampak sangat lemas.",
  str_homestory_801601001_24_dialog_content = "Lain kali, sebaiknya coba kupegang saja...",
  str_homestory_801601001_25_option_content = "Hachi dan Gin?",
  str_homestory_801601001_26_dialog_content = "Dua begundal gendut yang berusaha tampak dewasa.",
  str_homestory_801601001_27_dialog_content = "Setiap kali mereka melihat Franz, mereka bakal berteriak, \"Wah! Anjing sungguhan!\"",
  str_homestory_801601001_28_dialog_content = "Kelihatannya Franz juga suka kepada mereka, dan terus-menerus berusaha mengejar ekor mereka.",
  str_homestory_801601001_29_dialog_content = "Kok aneh...",
  str_homestory_801601001_30_dialog_content = "Entah kenapa, aku jadi ingin melihatnya sendiri...",
  str_homestory_801601001_31_dialog_content = "Intinya, Franz bahagia tinggal di sini.",
  str_homestory_801601001_32_dialog_content = "Tapi... apa belakangan ini kau menghabiskan banyak waktu bersama Franz?",
  str_homestory_801601001_33_dialog_content = "Hmm? Seingatku sih tidak.",
  str_homestory_801601001_34_dialog_content = "Tapi, aku bisa mencium baumu di tubuh Franz!",
  str_homestory_801601001_35_dialog_content = "Mungkin saja dia pernah menyelinap ke kamarmu.",
  str_homestory_801601001_36_dialog_content = "Hmm... Mungkin juga, sih.",
  str_homestory_801601001_37_dialog_content = "Tunggu...",
  str_homestory_801601001_38_dialog_content = "Apa kaubilang?",
  str_homestory_801601001_39_dialog_content = "Sekarang Franz tak terlalu sering membuat kasurmu basah<sprite=emo_hanshui size=60 /> dengan liurnya?",
  str_homestory_801601001_40_dialog_content = "Ehh... Jangan bilang...",
  str_homestory_801601001_41_dialog_content = "... Pantas saja belakangan ini kasurku terasa lembap!",
  str_homestory_801601001_42_dialog_content = "Rupanya begitu...",
  str_homestory_801601001_43_dialog_content = "Kurasa Franz sangat menyukaimu.",
  str_homestory_801601001_44_dialog_content = "... Apa sekarang aku harus merasa senang?",
  str_homestory_801601001_45_dialog_content = "Kau mau minta nasihat dariku, nih?",
  str_homestory_801601001_46_dialog_content = "Yah... Kalau jadi dirimu, aku akan langsung pulang untuk mencuci sepraiku.",
  str_homestory_804501001_0_dialog_content = "Suara apa itu?",
  str_homestory_804501001_1_dialog_content = "Nails?",
  str_homestory_804501001_2_dialog_content = "Ssst... Tunggu sebentar...",
  str_homestory_804501001_3_dialog_content = "Ah! Wajahmu cerah dan bersih seperti piring keramik yang memantulkan tubuhku yang jorok ini...",
  str_homestory_804501001_4_dialog_content = "Matamu seperti langit malam yang kelam, menembus jauh hingga ke dalam hatiku...",
  str_homestory_804501001_5_dialog_content = "Kumohon, ampunilah dosaku...",
  str_homestory_804501001_6_dialog_content = "Atau, akankah kau jadi ternoda kalau mengampuniku?",
  str_homestory_804501001_7_dialog_content = "...",
  str_homestory_804501001_8_dialog_content = "Maaf membuatmu menunggu, PlayerName!",
  str_homestory_804501001_9_dialog_content = "Apa aku mengganggumu?",
  str_homestory_804501001_10_dialog_content = "Aku minta maaf dengan setulus hati! Suaraku ini tak enak didengar siapa pun karena penuh dosa...",
  str_homestory_804501001_11_dialog_content = "Tolong, jangan terlalu keras pada dirimu sendiri. Aku sama sekali tak terganggu, kok!",
  str_homestory_804501001_12_dialog_content = "Tapi, aku benar-benar penasaran... Tadi kau sedang bicara dengan siapa?",
  str_homestory_804501001_13_dialog_content = "Ini pasti salah paham. Tak ada orang lain di sini. Aku hanya sedang mengakui dosa-dosaku.",
  str_homestory_804501001_14_dialog_content = "Semua ini berkat dirimu!",
  str_homestory_804501001_15_dialog_content = "Terima kasih sudah memberikan tempat yang sempurna sehingga aku bisa mengakui dosa-dosaku.",
  str_homestory_804501001_16_dialog_content = "Akhirnya aku bisa mengakui dosaku tanpa harus membuat Lady Victoria terganggu.",
  str_homestory_804501001_17_option_content = "Bantah",
  str_homestory_804501001_18_dialog_content = "Seingatku, aku tak pernah membangun tempat khusus untuk pengakuan dosa...",
  str_homestory_804501001_19_dialog_content = "Kau sungguh rendah hati. Aku yakin kau pasti menghabiskan banyak waktu dan tenaga untuk membangun air terjun yang menakjubkan ini.",
  str_homestory_804501001_20_dialog_content = "Tapi, ini kan Fountain of Hope.",
  str_homestory_804501001_21_option_content = "Akui",
  str_homestory_804501001_22_dialog_content = "Sama-sama. Syukurlah kau senang...",
  str_homestory_804501001_23_dialog_content = "Sebentar... Tadi kaubilang pengakuan dosa?",
  str_homestory_804501001_24_dialog_content = "Maksudmu Fountain of Hope ini, ya?",
  str_homestory_804501001_25_dialog_content = "Fountain of Hope... Sungguh nama yang indah didengar!",
  str_homestory_804501001_26_dialog_content = "Kulihat orang-orang kemari dan mengatupkan tangan dengan khidmat dan mengaku dosa. Sekarang aku tahu namanya!",
  str_homestory_804501001_27_dialog_content = "Aku memang bersalah. Aku harus mengakui dosaku...",
  str_homestory_804501001_28_dialog_content = "Sepertinya memang bisa dibilang begitu, sih... Tapi, kurasa orang-orang kemari untuk berdoa.",
  str_homestory_804501001_29_dialog_content = "Aku juga harus mengaku dosa atas nama PlayerName...",
  str_homestory_804501001_30_dialog_content = "Hah?!",
  str_homestory_804501001_31_dialog_content = "Pengakuan dosa tak boleh diganggu...",
  str_homestory_804501001_32_dialog_content = "PlayerName, maafkan aku karena tak menjelaskannya lebih dulu.",
  str_homestory_804501001_33_dialog_content = "Wahai, kebenaran yang bersemayam di Fountain of Hope...",
  str_homestory_804501001_34_dialog_content = "Ampunilah Nails karena lagi-lagi mengusikmu!",
  str_homestory_804501001_35_dialog_content = "Aku bersalah. Aku kemari untuk mengaku dosa. Hukumlah aku...",
  str_homestory_804501001_36_option_content = "Hukum",
  str_homestory_804501001_37_dialog_content = "Astaga! Aku bisa merasakan jawaban dari Fountain of Hope!",
  str_homestory_804501001_38_dialog_content = "Jawaban? Kebenaran akhirnya muncul di sini!",
  str_homestory_804501001_39_dialog_content = "Ehem... Fountain of Hope bilang...",
  str_homestory_804501001_40_option_content = "Hibur dia",
  str_homestory_804501001_41_dialog_content = "Nails, menurutku, kau tak perlu mengakui hal-hal seperti itu.",
  str_homestory_804501001_42_dialog_content = "Daripada mengaku dosa di sini, bagaimana kalau kau menyusun rencana untuk masa depan saja?",
  str_homestory_804501001_43_dialog_content = "!",
  str_homestory_804501001_44_dialog_content = "Kok selama ini tak pernah terpikir olehku, ya?",
  str_homestory_804501001_45_dialog_content = "Sudah kuduga... aku memang manusia penuh dosa...",
  str_homestory_804501001_46_dialog_content = "Eh…",
  str_homestory_808601001_0_dialog_content = "White Blossom yang tampak familier ini...",
  str_homestory_808601001_1_dialog_content = "Navigator PlayerName.",
  str_homestory_808601001_2_dialog_content = "Aku tak menyangka, ternyata Eraveil seindah ini.",
  str_homestory_808601001_3_dialog_content = "Padang rumput tanpa batas ini... tak mungkin bisa ditemui di Lumopolis.",
  str_homestory_808601001_4_dialog_content = "Bahkan White Blossom ini pun<sprite=emo_huaduo size=60 /> senang tumbuh di Eraveil...",
  str_homestory_808601001_5_dialog_content = "Ya. Aku pun merasa takjub.",
  str_homestory_808601001_6_dialog_content = "Hmm? Bukankah kau juga penghuni Eraveil?",
  str_homestory_808601001_7_dialog_content = "Ah... Iya...",
  str_homestory_808601001_8_dialog_content = "Aku ingat sekarang... Kau terpaksa pergi dari Eraveil saat kau masih sangat kecil.",
  str_homestory_808601001_9_dialog_content = "Benar. Aku tahu tentang Eraveil dari Soroz...",
  str_homestory_808601001_10_dialog_content = "Tapi, saat menginjakkan kaki di Eraveil, aku pun terpana oleh keindahannya.<sprite=emo_pugongying size=60 />",
  str_homestory_808601001_11_dialog_content = "Dan rasa takjub ini tak pernah surut walau waktu terus berlalu.",
  str_homestory_808601001_12_dialog_content = "Mungkin, seperti inilah rasanya tinggal di kampung halaman kita sendiri. Aku tahu, ada ikatan antara diriku dan Eraveil.",
  str_homestory_808601001_13_dialog_content = "Benar... Segala yang ada di sini penuh dengan makna spiritualitas. Arsitektur karya Caelestite bisa berkembang secara harmonis dengan alam.",
  str_homestory_808601001_14_dialog_content = "Aku sering berurusan dengan orang mati. Aku bisa merasakannya...",
  str_homestory_808601001_15_dialog_content = "Tempat ini indah karena punya sumber kehidupan.",
  str_homestory_808601001_16_dialog_content = "Segala makhluk yang hidup dan yang memuja kehidupan pasti akan jatuh hati kepada Eraveil.",
  str_homestory_808601001_17_dialog_content = "Kampung halaman PlayerName sungguh indah.",
  str_homestory_808601001_18_dialog_content = "Aku senang sekali kau memilih untuk menetap di sini.",
  str_homestory_808601001_19_dialog_content = "Terima kasih, Uriah.",
  str_homestory_808601001_20_dialog_content = "Pujianmu untuk Eraveil membuatku trenyuh.",
  str_homestory_808601001_21_option_content = "Minta bantuan darinya",
  str_homestory_808601001_22_dialog_content = "Sebenarnya... Kalau kau tak keberatan, aku ingin minta bantuanmu.",
  str_homestory_808601001_23_dialog_content = "Heheh... PlayerName, tak usah sungkan begitu.",
  str_homestory_808601001_24_dialog_content = "Rasanya agak serius sekaligus romantis...",
  str_homestory_808601001_25_dialog_content = "Apa ini lebih dari sekadar ajakan kencan? Kau mau melamarku?",
  str_homestory_808601001_26_dialog_content = "Hah?",
  str_homestory_808601001_27_dialog_content = "Bukan itu!",
  str_homestory_808601001_28_dialog_content = "Heheheh... Lucunya!",
  str_homestory_808601001_29_dialog_content = "Tolong, jangan mengolokku!",
  str_homestory_808601001_30_option_content = "Sampaikan ucapan sambutan",
  str_homestory_808601001_31_dialog_content = "Kau boleh berkunjung ke Eraveil kapan pun, Uriah. Aku ingin lebih sering bertemu denganmu.",
  str_homestory_808601001_32_dialog_content = "Tentu.",
  str_homestory_808601001_33_dialog_content = "Pemandangan indah di sini sungguh menakjubkan. Lagi pula, ini kampung halamanmu.",
  str_homestory_808601001_34_dialog_content = "PlayerName, aku menantikan masa depan negeri ini, yang pasti akan cerah di bawah kepemimpinanmu.",
  str_homestory_808601001_35_dialog_content = "Terima kasih... Uriah, kau ini biarawati yang bertanggung jawab mendoakan ketenangan bagi arwah orang-orang yang sudah tiada, 'kan?",
  str_homestory_808601001_36_dialog_content = "Ya, memang itu tugasku di Lumopolis.",
  str_homestory_808601001_37_dialog_content = "... Sepertinya aku tahu apa yang ingin kauminta.",
  str_homestory_808601001_38_dialog_content = "Ya. Aku ingin berdoa bagi saudara-saudara sebangsaku agar arwah mereka tenang.",
  str_homestory_808601001_39_dialog_content = "Aku paham...",
  str_homestory_808601001_40_dialog_content = "Aku terkesan karena kau kini jadi sangat dewasa. Sekarang kau sudah bisa menerima kehidupan maupun kematian.",
  str_homestory_808601001_41_dialog_content = "Aku, Funeral Prayer, Uriah sang biarawati, akan berdoa bagi arwah para penghuni Eraveil.",
  str_homestory_808601001_42_dialog_content = "Semoga arwah mereka beristirahat dalam damai! Semoga bunga-bunga White Blossom tumbuh di seluruh Eraveil.",
  str_homestory_808601001_43_dialog_content = "Terima kasih.",
  str_homestory_810201001_0_dialog_content = "Arus listrik ini...",
  str_homestory_810201001_1_dialog_content = "Tessa?",
  str_homestory_810201001_2_dialog_content = "Kalau kau lelah, istirahatlah di Cloud Gardens Dorm.",
  str_homestory_810201001_3_dialog_content = "*Huahm*<sprite=emo_kun size=60 />",
  str_homestory_810201001_4_dialog_content = "Apa katamu? Oi, kau!",
  str_homestory_810201001_5_dialog_content = "Maaf? Aku tak dengar.",
  str_homestory_810201001_6_dialog_content = "Huft... Apa aku harus mengeluarkan lolipop ini agar kau paham kata-kataku?",
  str_homestory_810201001_7_dialog_content = "Hmm... Aku hanya tak mau kau masuk angin karena tidur di luar.",
  str_homestory_810201001_8_dialog_content = "Memangnya ada aturan bahwa kita harus tidur di dalam?",
  str_homestory_810201001_9_dialog_content = "Tak wajib, sih...",
  str_homestory_810201001_10_dialog_content = "Kalaupun memang ada aturan seperti itu, aku tak peduli.",
  str_homestory_810201001_11_dialog_content = "Aku akan tidur di mana saja sesukaku.",
  str_homestory_810201001_12_option_content = "Setuju",
  str_homestory_810201001_13_dialog_content = "Tentu saja!",
  str_homestory_810201001_14_dialog_content = "Aku iri dengan gaya hidupmu.",
  str_homestory_810201001_15_dialog_content = "Aku hanya butuh ketenangan. Kau tak perlu iri dengan apa pun.",
  str_homestory_810201001_16_option_content = "Bantah",
  str_homestory_810201001_17_dialog_content = "Aku paham dari mana Tessa berasal, tapi...",
  str_homestory_810201001_18_dialog_content = "Aku hanya butuh ketenangan. Aku tak butuh dipahami.",
  str_homestory_810201001_19_dialog_content = "Baiklah…",
  str_homestory_810201001_20_dialog_content = "Ada payung dan tenda di toko. Kalau butuh, bilang saja kepadaku.",
  str_homestory_810201001_21_dialog_content = "Aku merasa nyaman di bawah naungan pohon, kok.",
  str_homestory_810201001_22_dialog_content = "Omong-omong, apa tokomu jual lolipop?",
  str_homestory_810201001_23_dialog_content = "Lolipopku hampir habis.",
  str_homestory_810201001_24_dialog_content = "Ada, tapi...",
  str_homestory_810201001_25_dialog_content = "Apa kau sudah pernah masuk ke Cloud Gardens Dorm?",
  str_homestory_810201001_26_dialog_content = "Seperti yang kubilang, aku tak tertarik tinggal di dalam ruangan.",
  str_homestory_810201001_27_dialog_content = "Apa hubungannya itu dengan lolipop?",
  str_homestory_810201001_28_dialog_content = "Untuk menyambut Tessa...",
  str_homestory_810201001_29_dialog_content = "Aku sudah menyiapkan banyak lolipop di Dorm...",
  str_homestory_810201001_30_dialog_content = "Lolipop?",
  str_homestory_810201001_31_dialog_content = "Aku baru saja memeriksanya. Tak tersisa satu pun.",
  str_homestory_810201001_32_dialog_content = "Kukira Tessa sendiri yang mengambilnya... Sepertinya ada orang lain yang sudah lebih dulu mengambilnya.",
  str_homestory_810201001_33_dialog_content = "Yang benar? Kenapa tak bilang dari tadi?",
  str_homestory_810201001_34_dialog_content = "Kukira semua orang akan ke Cloud Gardens Dorm dulu untuk istirahat...",
  str_homestory_810201001_35_dialog_content = "Cih! Sudahlah.",
  str_homestory_810201001_36_dialog_content = "Nanti aku beli lagi saja.",
  str_homestory_810201001_37_dialog_content = "(Tumben, Tessa bisa bersikap masuk akal...)",
  str_homestory_810201001_38_dialog_content = "Apa di sini ada pekerjaan berbayar?",
  str_homestory_810201001_39_dialog_content = "Hmm? Kukira kau sedang beristirahat... Kenapa kau sekarang malah mencari kerja?",
  str_homestory_810201001_40_dialog_content = "Aku ingin berbelanja, tapi tak punya uang lagi.",
  str_homestory_810201001_41_dialog_content = "Kalau tak punya uang, aku terpaksa harus membeli dengan cara kredit..",
  str_homestory_810201001_42_dialog_content = "...",
  str_homestory_810201001_43_dialog_content = "Bisakah tolong periksa sirkuit listrik di Cloud Gardens Dorm?",
  str_homestory_810201001_44_dialog_content = "Siap!",
  str_homestory_801501001_0_dialog_content = "Baru sekali ini...",
  str_homestory_801501001_1_dialog_content = "Sebelumnya, aku belum pernah melihatmu tanpa Gin.",
  str_homestory_801501001_2_dialog_content = "Ah! PlayerName, bisakah kau menciumnya?",
  str_homestory_801501001_3_dialog_content = "Bau harum Nightium<sprite=emo_baiyebi size=60 />! Ada di mana-mana!",
  str_homestory_801501001_4_option_content = "Tunjukkan keraguanmu",
  str_homestory_801501001_5_dialog_content = "Kok aku tak menciumnya, ya?",
  str_homestory_801501001_6_dialog_content = "Memangnya bau Nightium itu seperti apa, sih?",
  str_homestory_801501001_7_dialog_content = "PlayerName, ini namanya bahasa kiasan. Intinya adalah...",
  str_homestory_801501001_8_dialog_content = "Aku punya beberapa proyek yang perlu kubahas denganmu. Salah satunya bernilai lebih dari 9 digit!",
  str_homestory_801501001_9_dialog_content = "9 digit?",
  str_homestory_801501001_10_option_content = "Tanyakan tentang bau itu",
  str_homestory_801501001_11_dialog_content = "Memangnya bau Nightium itu seperti apa?",
  str_homestory_801501001_12_dialog_content = "30% aroma manis karat dan 40% aroma asin keringat...",
  str_homestory_801501001_13_dialog_content = "Plus 50%... *Endus*",
  str_homestory_801501001_14_dialog_content = "50% aroma segar pohon buah!",
  str_homestory_801501001_15_dialog_content = "Jadinya 120%, dong.",
  str_homestory_801501001_16_dialog_content = "Sebesar ketulusanku untuk berbisnis dengan PlayerName.",
  str_homestory_801501001_17_dialog_content = "Biar jelas, ya. 120%, bukan 12%.",
  str_homestory_801501001_18_dialog_content = "Apa tawaranmu kali ini?",
  str_homestory_801501001_19_dialog_content = "Dengar. Gambar-gambarku tak dijual. Dan kau tak bisa meminjamnya untuk membuat salinannya...",
  str_homestory_801501001_20_dialog_content = "PlayerName, coba lihatlah jauh ke depan.",
  str_homestory_801501001_21_dialog_content = "Sekarang kan kau punya aula pameran di tengah alam. Jangan terpaku pada beberapa gambar saja.",
  str_homestory_801501001_22_dialog_content = "Aula pameran?",
  str_homestory_801501001_23_dialog_content = "Contoh sempurna gabungan ruang alami terbuka dan ekologi budaya.",
  str_homestory_801501001_24_dialog_content = "Ini adalah Aula Pameran alam yang sempurna.",
  str_homestory_801501001_25_dialog_content = "PlayerName, kami sangat suka<sprite=emo_aixin size=60 /> tempat ini.",
  str_homestory_801501001_26_dialog_content = "Aku baru saja mengambil keputusan sulit!",
  str_homestory_801501001_27_dialog_content = "Kuputuskan...",
  str_homestory_801501001_28_dialog_content = "Aku akan menjadi perencana pameran!",
  str_homestory_801501001_29_dialog_content = "Memangnya pekerjaan perencana pameran itu apa, sih?",
  str_homestory_801501001_30_dialog_content = "Uhuk... Singkatnya, aku bertanggung jawab mengevaluasi, mempelajari, melestarikan, dan memamerkan segala jenis karya seni...",
  str_homestory_801501001_31_dialog_content = "Aku akan menjadi manajer profesional yang bertugas merencanakan dan menyelenggarakan pameran seni di tempat-tempat tertentu.",
  str_homestory_801501001_32_dialog_content = "Aku tak paham, tapi sepertinya masuk akal juga.",
  str_homestory_801501001_33_dialog_content = "Jadi, kau setuju?",
  str_homestory_801501001_34_dialog_content = "Kalau hanya ingin berganti karier, kau tak perlu minta izin dariku.",
  str_homestory_801501001_35_dialog_content = "Asalkan kau tak merusak lingkungan kami... Aku bekerja keras untuk membangun ini semua.",
  str_homestory_801501001_36_dialog_content = "Aku mengerti.",
  str_homestory_801501001_37_dialog_content = "PlayerName tak mau aku mengubah arsitektur dan tanaman-tanaman yang ada di sini.",
  str_homestory_801501001_38_dialog_content = "Benar.",
  str_homestory_801501001_39_dialog_content = "PlayerName tak mau aku merancang atau menyelenggarakan pameran dan festival seni.",
  str_homestory_801501001_40_dialog_content = "Benar.",
  str_homestory_801501001_41_dialog_content = "PlayerName juga tak mau pameran dan festival seniku menarik perhatian wisatawan.",
  str_homestory_801501001_42_dialog_content = "Ya…",
  str_homestory_801501001_43_dialog_content = "PlayerName juga tak tertarik dengan pendapatan besar yang akan dihasilkan dari pameran semacam itu.",
  str_homestory_801501001_44_dialog_content = "Hmm…",
  str_homestory_801501001_45_dialog_content = "PlayerName tak tertarik untuk memperbaiki kondisi keuangannya yang porak-poranda.",
  str_homestory_801501001_46_dialog_content = "Ehem... Sebentar.",
  str_homestory_801501001_47_dialog_content = "Ini perlu kupertimbangkan lebih matang.",
  str_homestory_801501001_48_dialog_content = "Hahah. Akhirnya PlayerName bisa mencium bau Nightium!",
  str_homestory_815401001_0_dialog_content = "Lagi?",
  str_homestory_815401001_1_dialog_content = "Vice, belakangan ini kau banyak menghabiskan waktu di museum.",
  str_homestory_815401001_2_dialog_content = "Apa ada cara untuk mendapatkan penghasilan di sana?",
  str_homestory_815401001_3_dialog_content = "Sayang sekali...",
  str_homestory_815401001_4_dialog_content = "Kondisi keuangan kita tak bagus, tapi bukankah kita sudah sepakat soal itu?",
  str_homestory_815401001_5_dialog_content = "Museum ini adalah fasilitas layanan umum yang didedikasikan untuk menunjukkan sejarah Eraveil dan teknologi Caelestite.",
  str_homestory_815401001_6_dialog_content = "Tanpa tiket masuk, dan sifatnya pun nirlaba...",
  str_homestory_815401001_7_option_content = "Minta maaflah",
  str_homestory_815401001_8_dialog_content = "Maafkan aku, Vice.",
  str_homestory_815401001_9_dialog_content = "Aku memikirkannya belakangan ini. Kurasa sekarang aku jadi terobsesi.",
  str_homestory_815401001_10_dialog_content = "Hahahah. Santai saja! Aku sendiri pun pernah mengalaminya, kok.",
  str_homestory_815401001_11_dialog_content = "Kurasa kau hanya butuh istirahat!",
  str_homestory_815401001_12_dialog_content = "Vice, kata-kata itu lebih cocok untukmu sendiri.",
  str_homestory_815401001_13_dialog_content = "Bisa dibilang, belakangan ini kau semacam sudah pindah rumah ke museum ini. Kau tampak cemas dan khawatir...",
  str_homestory_815401001_14_dialog_content = "Sudah berapa lama kau tak beristirahat sebagaimana mestinya?",
  str_homestory_815401001_15_option_content = "Tunjukkan kepedulian",
  str_homestory_815401001_16_dialog_content = "Jangan khawatir. Aku tak akan berubah pikiran tentang hal ini!",
  str_homestory_815401001_17_dialog_content = "Sebagai Caelestite terakhir, tak akan kubiarkan peradaban bangsaku berakhir di tanganku.",
  str_homestory_815401001_18_dialog_content = "Tapi...",
  str_homestory_815401001_19_dialog_content = "Memangnya kau sedang sibuk mengurus apa sih di museum?",
  str_homestory_815401001_20_dialog_content = "Sayang sekali... Aku memang tak bisa menyembunyikan apa pun dari PlayerName.<sprite=emo_wuzui size=60 />",
  str_homestory_815401001_21_dialog_content = "Belakangan ini, aku menyelidiki benda-benda yang dipajang di museum ini.",
  str_homestory_815401001_22_dialog_content = "Menyelidiki? Apa itu tugas baru dari Illumina?",
  str_homestory_815401001_23_dialog_content = "Bukan, ini untuk diriku sendiri.",
  str_homestory_815401001_24_dialog_content = "Mungkin, sebaiknya aku tak menyebutnya penyelidikan.",
  str_homestory_815401001_25_dialog_content = "Aku hanya sedang mencari ilham.",
  str_homestory_815401001_26_dialog_content = "Tahu, 'kan... Setelah apa yang terjadi pada tubuhku...",
  str_homestory_815401001_27_dialog_content = "Banyak kepingan ingatan yang muncul kembali.",
  str_homestory_815401001_28_dialog_content = "Tapi, soal asal-usulku, aku tetap tak tahu apa-apa...",
  str_homestory_815401001_29_dialog_content = "Jadi... Kau mencari petunjuk tentang asal-usulmu?",
  str_homestory_815401001_30_dialog_content = "Heheheh. Aneh, ya?",
  str_homestory_815401001_31_dialog_content = "Aku tahu, kok. Mana mungkin aku bisa menemukan petunjuk di museum Caelestite?",
  str_homestory_815401001_32_dialog_content = "Mana kita tahu, 'kan?",
  str_homestory_815401001_33_dialog_content = "Dunia ini memang luas, tapi setiap hari selalu ada kebetulan.",
  str_homestory_815401001_34_dialog_content = "Hahahahah. Sekarang kau jadi jauh lebih optimistis.",
  str_homestory_815401001_35_dialog_content = "Apa sebaiknya kita lihat-lihat saja lagi ke seisi museum ini?",
  str_homestory_815401001_36_dialog_content = "Mungkin saja kali ini kita bisa menemukan petunjuk, misalnya surat keluarga atau semacam itu?",
  str_homestory_815401001_37_dialog_content = "Tentu!",
  str_homestory_815401001_38_dialog_content = "Tapi, bagaimana kalau ternyata aku ini kakakmu...<sprite=emo_sikao size=60 />",
  str_homestory_815401001_39_dialog_content = "Apa yang akan kaulakukan?",
  str_homestory_815401001_40_dialog_content = "Kakakku? Mustahil!",
  str_homestory_815401001_41_dialog_content = "Tapi, mungkin saja justru aku ini kakakmu!",
  str_homestory_815401001_42_dialog_content = "PlayerName…",
  str_homestory_815401001_43_dialog_content = "Hmm... Aku sungguh tak bisa membayangkannya.",
  str_homestory_815401001_44_dialog_content = "Ehem... Semoga saja bukan begitu!",
  str_homestory_805702001_0_dialog_content = "Hujan, ya?",
  str_homestory_805702001_1_dialog_content = "Meong...",
  str_homestory_805702001_2_dialog_content = "Hujan, Philyshy. Sebaknya kita berteduh.",
  str_homestory_805702001_3_dialog_content = "Tidak, aku hanya mengeringkan badanku, kok.",
  str_homestory_805702001_4_dialog_content = "Maaf, kau terkena cipratan airnya, PlayerName...",
  str_homestory_805702001_5_dialog_content = "Oh, begitu. Pantas saja kau menggelengkan kepalamu ke segala arah...",
  str_homestory_805702001_6_dialog_content = "Berhenti mengejekku, PlayerName...",
  str_homestory_805702001_7_dialog_content = "Tapi, kalau ini tidak hujan, kenapa kau bisa basah begini?",
  str_homestory_805702001_8_dialog_content = "Meong... Ini gara-gara ikan kering yang berkilau di sungai!<sprite=emo_shengqi size=60 />",
  str_homestory_805702001_9_option_content = "Berkilau?",
  str_homestory_805702001_10_dialog_content = "Bagaimana mungkin?",
  str_homestory_805702001_11_dialog_content = "Aku juga ingin tahu. Itu sebabnya aku coba menangkapnya tadi, meong.",
  str_homestory_805702001_12_option_content = "Ikan kering berkilau?",
  str_homestory_805702001_13_dialog_content = "Sebentar, mana ada ikan kering di sungai?",
  str_homestory_805702001_14_dialog_content = "Ya akan jadi ikan kering setelah kutangkap dan kujemur!",
  str_homestory_805702001_15_dialog_content = "Meski sudah mencobanya, aku tak bisa menangkapnya dan malah tercebur ke sungai.",
  str_homestory_805702001_16_dialog_content = "Hatsyiii! Sungainya sangat dingin, meong...",
  str_homestory_805702001_17_dialog_content = "Sebaiknya kau pulang ke rumah dan menghangatkan diri agar tak kena flu.",
  str_homestory_805702001_18_dialog_content = "Tapi...",
  str_homestory_805702001_19_dialog_content = "Hei, kau kan pemilik tempat ini, PlayerName...",
  str_homestory_805702001_20_dialog_content = "Coba tangkapkan ikan kering berkilau itu untukku!",
  str_homestory_805702001_21_dialog_content = "Hah?",
  str_homestory_805702001_22_dialog_content = "Jangan lupa... Dijemur... Zzz...<sprite=emo_kun size=60 />",
  str_homestory_805702001_23_dialog_content = "Nanti kau bakal masuk angin kalau tidur di sini... Philyshy?",
  str_homestory_805702001_24_dialog_content = "Zzz... Zzz... <sprite=emo_kun size=60 />Ikan kering...",
  str_homestory_814101001_0_dialog_content = "Sangat mengasyikkan...",
  str_homestory_814101001_1_dialog_content = "Hai, PlayerName. Kau sedang menjelajah juga, ya?",
  str_homestory_814101001_2_option_content = "Yap.",
  str_homestory_814101001_3_dialog_content = "Ada banyak tempat untuk dijelajahi di Cloud Gardens yang sudah dikuratori ini.",
  str_homestory_814101001_4_option_content = "Tidak.",
  str_homestory_814101001_5_dialog_content = "Aku hanya mencari udara segar.",
  str_homestory_814101001_6_dialog_content = "Cloud Gardens bisa jadi seperti sekarang ini berkat jerih payah, makanya aku senang bersantai di sini setiap kali punya kesempatan.",
  str_homestory_814101001_7_dialog_content = "Kau benar!",
  str_homestory_814101001_8_dialog_content = "Pulau yang kaubangun ini sangat indah. Aku sangat menyukainya!",
  str_homestory_814101001_9_dialog_content = "Tadi aku sedang melihat-lihat di sekitar sungai itu.",
  str_homestory_814101001_10_dialog_content = "Oh, ya? Menemukan sesuatu yang menarik, tidak?",
  str_homestory_814101001_11_dialog_content = "Heh, sudah kuduga kau bakal menanyakannya!",
  str_homestory_814101001_12_dialog_content = "Nah, begitu melihat sungai itu, aku langsung melompat masuk ke dalamnya!",
  str_homestory_814101001_13_dialog_content = "Aku menyibak alang-alangnya dan menemukan sekeping koin yang belum pernah kulihat di dasar sungai<sprite=emo_baiyebi size=60 />...",
  str_homestory_814101001_14_dialog_content = "Lalu aku menangkap seekor Betta Fish berukuran besar...",
  str_homestory_814101001_15_dialog_content = "Tak lama kemudian, aku melihat sebuah relik yang aneh!",
  str_homestory_814101001_16_dialog_content = "Nah, aku langsung mengambilnya dan membawanya ke tepi sungai. Coba tebak benda apa itu.",
  str_homestory_814101001_17_dialog_content = "A-apa itu?",
  str_homestory_814101001_18_dialog_content = "Sebuah sepatu tua dan compang-camping yang penuh alang-alang!",
  str_homestory_814101001_19_dialog_content = "Kucoba menjualnya ke toko, tapi malah tak laku! Aneh sekali!",
  str_homestory_814101001_20_dialog_content = "Bagaimana dengan ikan dan koinnya?",
  str_homestory_814101001_21_dialog_content = "Oh, iya... Tadi kutaruh di saku bajuku...",
  str_homestory_814101001_22_dialog_content = "Hmm, mungkin terjatuh waktu aku mengambil sepatu itu.",
  str_homestory_814101001_23_dialog_content = "Kalau kau tertarik, ayo kita cari!",
  str_homestory_814101001_24_dialog_content = "Tapi, sekarang ikan itu pasti sudah berenang pergi.",
  str_homestory_814101001_25_dialog_content = "Ruby, kau memang selalu optimistis, ya.",
  str_homestory_814101001_26_dialog_content = "Oh, jangan beri tahu Rouge soal ini, ya!",
  str_homestory_814101001_27_dialog_content = "Kalau tidak, dia bakal memaksaku untuk menelan obat demam yang pahit!",
  str_homestory_801001001_0_dialog_content = "Kau masih tidur?",
  str_homestory_801001001_1_dialog_content = "Kau baik-baik saja, Louise? Kelihatannya kau mengantuk.",
  str_homestory_801001001_2_dialog_content = "Oh, rupanya kau, PlayerName.",
  str_homestory_801001001_3_dialog_content = "Tadinya kukira penantianku sudah berakhir...",
  str_homestory_801001001_4_dialog_content = "Kau sedang menunggu seseorang, ya?",
  str_homestory_801001001_5_dialog_content = "Aku menunggu peri di sungai.",
  str_homestory_801001001_6_dialog_content = "Peri?",
  str_homestory_801001001_7_dialog_content = "Kau belum dengar dongeng yang sangat terkenal itu, ya, PlayerName?",
  str_homestory_801001001_8_dialog_content = "Di sebuah sungai terpencil, hiduplah seorang peri yang sangat cantik.",
  str_homestory_801001001_9_dialog_content = "Peri itu bakal terbang keluar kalau ada orang yang tak sengaja menjatuhkan sesuatu ke dalam air.",
  str_homestory_801001001_10_dialog_content = "Orang yang bisa menjawab pertanyaan sang peri dengan jujur akan dapat imbalan!",
  str_homestory_801001001_11_option_content = "Sungai terpencil...",
  str_homestory_801001001_12_dialog_content = "Menurutmu ada peri di sungai ini, Louise?",
  str_homestory_801001001_13_dialog_content = "Eh, di setiap sungai memang ada perinya, 'kan?",
  str_homestory_801001001_14_dialog_content = "Di sungai Northland hiduplah seorang peri Northland, berarti di sungai Eraveil juga ada peri Eraveil...",
  str_homestory_801001001_15_option_content = "Tadi katamu dongeng...",
  str_homestory_801001001_16_dialog_content = "Tahu tidak? Sepertinya aku pernah dengar cerita yang mirip.",
  str_homestory_801001001_17_dialog_content = "Suatu hari, ada orang yang kehilangan kapak bajanya, tapi dia malah bersikap tamak dan mengaku-ngaku bahwa kapaknya terbuat dari emas.",
  str_homestory_801001001_18_dialog_content = "Tapi, intinya...",
  str_homestory_801001001_19_dialog_content = "Apa kau kehilangan sesuatu di sungai?",
  str_homestory_801001001_20_dialog_content = "Iya! Tapi, itu bukan punyaku.",
  str_homestory_801001001_21_dialog_content = "Yang hilang adalah sekeping koin berpola rumit yang kupungut di tepi sungai.",
  str_homestory_801001001_22_dialog_content = "Koin itu menggelinding ke dalam air sebelum aku sempat mengamatinya baik-baik.",
  str_homestory_801001001_23_dialog_content = "Aku sudah menunggu lama, tapi peri itu tak kunjung muncul.",
  str_homestory_801001001_24_dialog_content = "Sepertinya sungaimu tak ada perinya, PlayerName...<sprite=emo_sikao size=60 />",
  str_homestory_801001001_25_dialog_content = "Coba biar kuambil koinnya.",
  str_homestory_801001001_26_dialog_content = "Lho, jadi kau perinya, PlayerName?!",
  str_homestory_804102001_0_dialog_content = "Kau sangat bersungguh-sungguh...",
  str_homestory_804102001_1_dialog_content = "Hai, Ms. Blanc.",
  str_homestory_804102001_2_dialog_content = "Halo, PlayerName yang terhormat.",
  str_homestory_804102001_3_dialog_content = "Kau masih memeriksa jalanan dan bangunan di Cloud Gardens, ya?",
  str_homestory_804102001_4_dialog_content = "Wah, aku senang kau masih ingat rutinitasku.",
  str_homestory_804102001_5_option_content = "Menurutku kau sangat profesional.",
  str_homestory_804102001_6_dialog_content = "Tapi...",
  str_homestory_804102001_7_option_content = "Maaf!",
  str_homestory_804102001_8_dialog_content = "Kenapa kau minta maaf?",
  str_homestory_804102001_9_dialog_content = "Aku memperluas Cloud Gardens dengan menambahkan struktur dan jalan.",
  str_homestory_804102001_10_dialog_content = "Itu tak akan mempermudah pekerjaanmu, ya?",
  str_homestory_804102001_11_dialog_content = "Jangan pernah meremehkan kemampuan seorang profesional, PlayerName.",
  str_homestory_804102001_12_dialog_content = "Asalkan koordinat dan lokasi bangunan serta jalanan utamanya sudah terpatri di benakku...",
  str_homestory_804102001_13_dialog_content = "Aku tak bakal kesulitan mengingat lebih banyak.",
  str_homestory_804102001_14_dialog_content = "Wah, ingatanmu memang luar biasa!",
  str_homestory_804102001_15_dialog_content = "Tapi, tadi kulihat dahimu berkerut. Ada masalah?",
  str_homestory_804102001_16_dialog_content = "Ups, kau melihatnya, ya, PlayerName?",
  str_homestory_804102001_17_dialog_content = "Yah, memang ada yang mengusik pikiranku. Sepertinya bukan masalah kalau kuceritakan kepadamu.",
  str_homestory_804102001_18_dialog_content = "Tadi aku sedang menulis panduan ke Cloud Gardens...",
  str_homestory_804102001_19_dialog_content = "Saat aku tiba di sungai ini.",
  str_homestory_804102001_20_dialog_content = "Ada sesuatu yang berkilau di antara bermacam-macam ikan yang berseliweran.",
  str_homestory_804102001_21_dialog_content = "Demi memastikan keakuratan deskripsinya, aku sangat ingin tahu benda apa itu...",
  str_homestory_804102001_22_dialog_content = "Kau bilang benda berkilau, ya...?",
  str_homestory_804102001_23_dialog_content = "Nah, karena kau pemilik Cloud Gardens, maukah kau memeriksanya?",
  str_homestory_804102001_24_dialog_content = "Tentu, bukan masalah!",
  str_homestory_801502001_0_dialog_content = "Mengendus-endus lagi, ya?",
  str_homestory_801502001_1_dialog_content = "Ehem, sekarang kau sedang apa, Hachi?",
  str_homestory_801502001_2_dialog_content = "Eh, ada PlayerName yang terhormat!<sprite=emo_yaosu size=60 />",
  str_homestory_801502001_3_dialog_content = "Jadi, kau sudah membuat keputusan?",
  str_homestory_801502001_4_dialog_content = "Keputusan apa?",
  str_homestory_801502001_5_dialog_content = "Oh, aku paham. Kau kan memang sibuk, ya!",
  str_homestory_801502001_6_dialog_content = "Maksudku... merombak ulang Cloud Gardens menjadi pameran alam.",
  str_homestory_801502001_7_option_content = "Sedang dipertimbangkan.",
  str_homestory_801502001_8_dialog_content = "Yah, anu, aku masih memikirkannya...",
  str_homestory_801502001_9_option_content = "Lupakan saja.",
  str_homestory_801502001_10_dialog_content = "Tujuan yang mengagumkan, tapi aku suka Cloud Gardens yang sekarang, rapi dan tenang.",
  str_homestory_801502001_11_dialog_content = "Eh. Baiklah.",
  str_homestory_801502001_12_dialog_content = "Tapi, coba kau pertimbangkan lagi, ya. Kesempatan tak bakal menunggu!",
  str_homestory_801502001_13_dialog_content = "Hmm…",
  str_homestory_801502001_14_dialog_content = "*Endus endus*",
  str_homestory_801502001_15_dialog_content = "Untuk apa kau mengendus-endus?",
  str_homestory_801502001_16_dialog_content = "Kau tak bisa menciumnya? Baunya seperti koin.",
  str_homestory_801502001_17_dialog_content = "Nightium <sprite=emo_baiyebi size=60 />lagi?",
  str_homestory_801502001_18_dialog_content = "Bukan, yang ini sangat berbeda!",
  str_homestory_801502001_19_dialog_content = "Ini sesuatu yang baru, unik, dan tak terlukiskan... *Endus*",
  str_homestory_801502001_20_dialog_content = "Baunya lebih kuat dan lembap ketimbang Nightium, juga lebih kuno...",
  str_homestory_801502001_21_dialog_content = "Dan polanya lebih rumit.",
  str_homestory_801502001_22_dialog_content = "Kau bisa mencium polanya juga?!",
  str_homestory_801502001_23_dialog_content = "Eits, jangan pernah meremehkan hidung anjing, ya.",
  str_homestory_801502001_24_dialog_content = "Entah tren bisnis atau bau koin, aku bisa menunjukkan arah yang tepat.",
  str_homestory_801502001_25_dialog_content = "Nah, kali ini, aku akan memberimu kesempatan untuk menemukan koin itu, PlayerName yang terhormat.",
  str_homestory_801502001_26_dialog_content = "Hah?",
  str_homestory_801502001_27_dialog_content = "Kuharap kau mau memikirkan kolaborasi kita!",
  str_homestory_805602001_0_dialog_content = "Constantine?",
  str_homestory_805602001_1_dialog_content = "Halo, PlayerName.",
  str_homestory_805602001_2_dialog_content = "Kali ini kau habis dari mana, Constantine?",
  str_homestory_805602001_3_dialog_content = "Aku baru pulang memancing.",
  str_homestory_805602001_4_dialog_content = "Ah, kulihat kau sering memancing beberapa hari ini.",
  str_homestory_805602001_5_dialog_content = "Sebagai pemburu yang mahir, apa kau dapat banyak ikan?",
  str_homestory_805602001_6_dialog_content = "Seekor pun tidak.",
  str_homestory_805602001_7_dialog_content = "Apa? Kau kan pemburu andal!",
  str_homestory_805602001_8_dialog_content = "Mungkin kau kira memancing itu sama dengan berburu, tapi keduanya sangat berbeda.<sprite=emo_sikao size=60 />",
  str_homestory_805602001_9_dialog_content = "Kita menaklukkan mangsa secara aktif saat berburu.",
  str_homestory_805602001_10_dialog_content = "Tapi, saat memancing, kau meminimalkan inisiatif dan membuat ikan-ikan itu datang padamu.",
  str_homestory_805602001_11_option_content = "Aku paham.",
  str_homestory_805602001_12_dialog_content = "Saat memancing, tak seorang pun tahu apa yang akan mereka tangkap.",
  str_homestory_805602001_13_dialog_content = "Tapi, kalau berburu, orang mencari targetnya dulu, lalu bertindak.",
  str_homestory_805602001_14_option_content = "Tidak.",
  str_homestory_805602001_15_dialog_content = "Lo, tapi kau bilang berburu itu butuh kesabaran. Itu kan juga diperlukan dalam memancing.",
  str_homestory_805602001_16_dialog_content = "Tak seorang pun tahu kapan ikannya akan memakan umpan.",
  str_homestory_805602001_17_dialog_content = "Ya, kau benar.",
  str_homestory_805602001_18_dialog_content = "Terus terang, aku menentang aturan itu pada awalnya...",
  str_homestory_805602001_19_dialog_content = "Aku selalu mengunci targetnya dulu, lalu mencoba untuk menangkapnya, tapi tak pernah berhasil.",
  str_homestory_805602001_20_dialog_content = "Nah, untuk mengingatkan diriku tentang pelajaran yang sudah kupetik, aku ratakan kailnya.",
  str_homestory_805602001_21_dialog_content = "Apa? Kau bisa memancing dengan kail rata seperti itu?",
  str_homestory_805602001_22_dialog_content = "Entahlah, aku tak peduli. Aku hanya ingin mengasah kesabaranku.",
  str_homestory_805602001_23_dialog_content = "Kau mau terus memancing dengan cara seperti itu?",
  str_homestory_805602001_24_dialog_content = "Aku sudah menentukan tenggat waktu untuk diriku.",
  str_homestory_805602001_25_dialog_content = "Saat koin di tepi sungai terbenam ke dalam lumpur atau hanyut... atau ada orang yang mengambilnya.",
  str_homestory_805602001_26_dialog_content = "Sampai saat itu tiba, aku akan tetap memakai kail lurusku.",
  str_homestory_805602001_27_dialog_content = "(Koin...?)",
  str_homestory_805602001_28_dialog_content = "(Aku harus mencoba untuk mengambilnya.)",
  str_homestory_808502001_0_dialog_content = "Wah, cepat sekali...",
  str_homestory_808502001_1_dialog_content = "Apa kau mencatatnya di jurnalmu, Jane?",
  str_homestory_808502001_2_dialog_content = "Iya, aku mencatat semua yang kulihat di Cloud Gardens.",
  str_homestory_808502001_3_dialog_content = "Kalau tak tahu pekerjaanmu, aku bakal mengira kau sedang menggambar.",
  str_homestory_808502001_4_dialog_content = "Tapi, tadi aku memang menggambar.",
  str_homestory_808502001_5_dialog_content = "Hah...?<sprite=emo_wuzui size=60 />",
  str_homestory_808502001_6_dialog_content = "Kita butuh lebih dari sekadar teks untuk deskripsinya. Ilustrasi juga penting.",
  str_homestory_808502001_7_dialog_content = "Kapan ilustrasinya penting?",
  str_homestory_808502001_8_dialog_content = "Sebenarnya cukup mudah. Kalau kata-kata tak cukup untuk menggambarkan sesuatu, kita bisa menggunakan ilustrasi.",
  str_homestory_808502001_9_dialog_content = "Misalnya, aku mendeskripsikan semua yang kulihat di sungai.",
  str_homestory_808502001_10_dialog_content = "Aku bisa saja menggunakan kata-kata untuk mendeskripsikan Redfin Perch, tapi para pembaca tak akan bisa membayangkan wujudnya dengan jelas.",
  str_homestory_808502001_11_dialog_content = "Tapi, kalau aku bisa menggambarkan wujud dan warnanya...",
  str_homestory_808502001_12_dialog_content = "Mereka akan langsung tahu seperti apa ikan itu.",
  str_homestory_808502001_13_dialog_content = "Jadi, begitu, ya…",
  str_homestory_808502001_14_dialog_content = "Contoh lain, saat aku menulis tentang \"Sekeping koin yang tergeletak di dasar sungai\"...",
  str_homestory_808502001_15_dialog_content = "Mereka hanya bisa membayangkan koin yang mereka gunakan sebelumnya.",
  str_homestory_808502001_16_dialog_content = "Jadi, aku harus menggambar pola koin yang belum pernah orang lihat itu.",
  str_homestory_808502001_17_dialog_content = "Nah, dengan begitu mereka jadi tahu persis jenis koin yang tergeletak di dasar sungai di Cloud Gardens.",
  str_homestory_808502001_18_dialog_content = "Jadi, sekarang di mana gerangan koin itu?",
  str_homestory_808502001_19_dialog_content = "Masih di sungai.",
  str_homestory_808502001_20_dialog_content = "Apa? Kenapa kau tak mengambilnya?",
  str_homestory_808502001_21_dialog_content = "Aku kan hanya mencatat. Aku tak mau mengganggu.",
  str_homestory_808502001_22_dialog_content = "Aku juga tak akan menghentikanmu kalau kau mau mengambil koin itu.",
  str_homestory_808502001_23_dialog_content = "Tapi, aku akan mencatat kejadiannya.",
  str_homestory_805502001_0_dialog_content = "Suasana hatimu sedang buruk, ya?",
  str_homestory_805502001_1_dialog_content = "Apa yang terjadi, Pittman? Kelihatannya kau marah.",
  str_homestory_805502001_2_dialog_content = "Wah, kebetulan sekali, PlayerName. Aku memang sedang akan mencarimu!",
  str_homestory_805502001_3_dialog_content = "Eh, memangnya ada hubungannya denganku?",
  str_homestory_805502001_4_dialog_content = "Aku tidak yakin, tapi...",
  str_homestory_805502001_5_dialog_content = "Demi White Night! Sebagai Judge di Lumopolis, dengan ini aku ingin memulai penyelidikan...",
  str_homestory_805502001_6_dialog_content = "Apa kau mencetak Nightium di Cloud Gardens?",
  str_homestory_805502001_7_option_content = "Tidak!",
  str_homestory_805502001_8_dialog_content = "Memang benar aku butuh Nightium, tapi aku tak seputus asa itu!",
  str_homestory_805502001_9_option_content = "Aku mau-mau saja.",
  str_homestory_805502001_10_dialog_content = "Tapi, mencetak Nightium itu mahal. Aku butuh banyak uang untuk membuat uang.",
  str_homestory_805502001_11_dialog_content = "Kau kan tahu uangku tak banyak!",
  str_homestory_805502001_12_dialog_content = "Kau bersumpah?",
  str_homestory_805502001_13_dialog_content = "Aku, PlayerName, belum pernah mencetak Nightium.",
  str_homestory_805502001_14_dialog_content = "Atau... kalau aku memang berbohong, terserah padamu aku mau kauapakan!",
  str_homestory_805502001_15_dialog_content = "Kalau begitu, apa kau lihat orang yang mencurigakan atau tanda-tanda yang ada hubungannya dengan itu di Cloud Gardens?",
  str_homestory_805502001_16_dialog_content = "Terutama yang dari Umbraton dan gurun?",
  str_homestory_805502001_17_dialog_content = "Mereka semua temanku, jadi aku benar-benar tak mau meragukan mereka...",
  str_homestory_805502001_18_dialog_content = "Semua orang di sini setara menurut hukum, terlepas dari identitasnya.",
  str_homestory_805502001_19_dialog_content = "Tapi, kenapa kau mencurigai mereka?",
  str_homestory_805502001_20_dialog_content = "Karena kau sudah bersumpah, akan kuberi tahu apa rahasiaku.",
  str_homestory_805502001_21_dialog_content = "Di tepi sungai, aku menemukan sekeping koin yang mirip dengan Nightium!",
  str_homestory_805502001_22_dialog_content = "Boleh kulihat?",
  str_homestory_805502001_23_dialog_content = "Saking marahnya, koin itu sampai terlepas dari genggamanku dan malah tercebur ke dalam sungai.",
  str_homestory_805502001_24_dialog_content = "Ini hanya dugaanku saja... tapi kurasa koin itu mungkin milik kami, kaum Caelestite.",
  str_homestory_805502001_25_dialog_content = "Ah... S-sungguh?",
  str_homestory_805502001_26_dialog_content = "Yah, lagi pula aku memang tak sempat memeriksanya dengan cermat...",
  str_homestory_805502001_27_dialog_content = "Kalau memang benar begitu, aku harus minta maaf karena sudah bersikap lancang.",
  str_homestory_805502001_28_dialog_content = "Maaf!",
  str_homestory_805502001_29_dialog_content = "Tidak apa-apa, aku juga tak tahu asal-usul koin itu, kok.",
  str_homestory_805502001_30_dialog_content = "Akan kuperlihatkan padamu kalau aku menemukannya.",
  str_homestory_805502001_31_dialog_content = "Terima kasih banyak, PlayerName!",
  str_homestory_815701001_0_dialog_content = "Sanae...",
  str_homestory_815701001_1_dialog_content = "Ahhhhhhhhhhh! Tuan Navigator...",
  str_homestory_815701001_2_dialog_content = "Tadi aku hanya mengagumi bunga-bunga ini<sprite=emo_huaduo size=60 />!",
  str_homestory_815701001_3_dialog_content = "Jelas, itu bukan karena aku terjatuh dan beristirahat di sini...",
  str_homestory_815701001_4_dialog_content = "Tadi kau jatuh? Apa kau terluka?",
  str_homestory_815701001_5_dialog_content = "Aku sudah terbiasa, kok... Ah, aku keceplosan, ya?",
  str_homestory_815701001_6_dialog_content = "Sanae... Kau sungguh mudah ditebak.",
  str_homestory_815701001_7_dialog_content = "Tolong, jangan pecat aku karena kecerobohanku ini...",
  str_homestory_815701001_8_dialog_content = "Tak akan terjadi, tapi... memangnya apa sih yang tadi kaupikirkan?",
  str_homestory_815701001_9_dialog_content = "Beri tahu aku kalau kau punya saran tentang pembangunan Cloud Gardens.",
  str_homestory_815701001_10_dialog_content = "Oh... bukan begitu...",
  str_homestory_815701001_11_dialog_content = "Aku bukannya membayangkan kenapa kau menanam bunga di sini, kok!",
  str_homestory_815701001_12_dialog_content = "Yah, itu sama sekali tak mencurigakan...",
  str_homestory_815701001_13_dialog_content = "Hah?",
  str_homestory_815701001_14_dialog_content = "Soal kau yang mengubur kenanganmu di sini demi mengingat orang-orang terkasihmu...",
  str_homestory_815701001_15_dialog_content = "Aku tak akan pernah tahu...",
  str_homestory_815701001_16_option_content = "Orang terkasih?",
  str_homestory_815701001_17_dialog_content = "Ya! Orang yang kautemui secara tak sengaja...",
  str_homestory_815701001_18_dialog_content = "Orang yang menembus segala batasan dunia dan menemuimu...",
  str_homestory_815701001_19_dialog_content = "Orang yang memberikan saran untuk perjalananmu di Astra...",
  str_homestory_815701001_20_dialog_content = "Oh, pasti dia gadis yang sangat baik!",
  str_homestory_815701001_21_dialog_content = "Bunga-bunga di taman ini pasti bunga kesukaannya, 'kan?",
  str_homestory_815701001_22_option_content = "Mengubur kenangan?",
  str_homestory_815701001_23_dialog_content = "Orang yang meninggalkan segalanya demi menemuimu...",
  str_homestory_815701001_24_dialog_content = "Orang yang selalu menjagamu sepanjang perjalananmu...",
  str_homestory_815701001_25_dialog_content = "Tapi, sekarang kalian berdua tak mungkin bisa bertemu lagi karena terhalang oleh batasan dunia fana.",
  str_homestory_815701001_26_dialog_content = "Jadi, untuk menunjukkan betapa besarnya rasa rindumu kepadanya...",
  str_homestory_815701001_27_dialog_content = "Kau menanam bunga-bunga kesukaannya di taman ini!",
  str_homestory_815701001_28_dialog_content = "Aku sama sekali tak paham apa maksudmu...",
  str_homestory_815701001_29_dialog_content = "Begitukah...<sprite=emo_sikao size=60 />!",
  str_homestory_815701001_30_dialog_content = "Harusnya aku sudah menduganya. Informasi ini tak bisa diberitahukan begitu saja kepada orang luar sepertiku...",
  str_homestory_815701001_31_dialog_content = "Kalau kau penasaran kenapa ada taman bunga di sini...",
  str_homestory_815701001_32_dialog_content = "Jawabanku adalah karena ini memang bagian dari desain lanskap untuk tempat ini.",
  str_homestory_815701001_33_dialog_content = "Desain lanskap? Sungguh istilah yang rumit...",
  str_homestory_815701001_34_dialog_content = "Vice sangat paham tentang gambar desain, jadi dia memberiku banyak saran saat kami merancang Cloud Gardens...",
  str_homestory_815701001_35_dialog_content = "Gabriel, Nikinis, dan Jola juga tahu banyak tentang tanaman...",
  str_homestory_815701001_36_dialog_content = "Aku meminta saran dari mereka tentang tanaman apa saja yang kira-kira tampak bagus ditanam di sini.",
  str_homestory_815701001_37_dialog_content = "Ini upaya bersama sehingga penampilan Cloud Gardens jadi seperti sekarang ini.",
  str_homestory_815701001_38_dialog_content = "Upaya bersama...",
  str_homestory_815701001_39_dialog_content = "Benar sekali! Oh, ya, jangan anggap dirimu ini \"orang luar\", Sanae.",
  str_homestory_815701001_40_dialog_content = "Sejak pertama kali datang ke sini, kau sudah langsung jadi bagian dari kami!",
  str_homestory_815701001_41_dialog_content = "Owww... Owww...",
  str_homestory_815701001_42_dialog_content = "Ahh, jangan menangis, dong. Aku tak bermaksud menyalahkanmu...",
  str_homestory_815701001_43_dialog_content = "Kau sungguh orang yang baik, Tuan Navigator...",
  str_homestory_815701001_44_dialog_content = "Aku juga... ingin berkontribusi...",
  str_homestory_815701001_45_dialog_content = "Aku punya ide! Mulai sekarang, izinkan aku merawat \"Taman Bunga Cinta<sprite=emo_aixin size=60 />\" ini!",
  str_homestory_815601001_0_dialog_content = "Aku tak percaya apa yang kulihat!",
  str_homestory_815601001_1_dialog_content = "Apa barusan Nina menaiki kuda-kudaan?",
  str_homestory_815601001_2_dialog_content = "Kuda-kudaan?",
  str_homestory_815601001_3_dialog_content = "Kukira kau benci mainan seperti itu.",
  str_homestory_815601001_4_dialog_content = "A-Aku juga tak bilang aku suka mainan itu...",
  str_homestory_815601001_5_dialog_content = "Aku hanya lelah berjalan, dan butuh tempat untuk beristirahat.",
  str_homestory_815601001_6_dialog_content = "Hal seperti itu tak akan bisa membuatku tertarik.",
  str_homestory_815601001_7_dialog_content = "Ada benarnya...",
  str_homestory_815601001_8_dialog_content = "Bukankah mestinya intinya adalah \"aku lelah berjalan tapi tak ada tempat untuk beristirahat\"?",
  str_homestory_815601001_9_option_content = "Minta maaflah",
  str_homestory_815601001_10_dialog_content = "Oh... Maafkan aku!",
  str_homestory_815601001_11_dialog_content = "Apa perlu kutaruh beberapa bangku batu lagi di sekitar sini?",
  str_homestory_815601001_12_dialog_content = "Bangku batu? Hahaha, kau pasti bercanda, 'kan?",
  str_homestory_815601001_13_dialog_content = "Mana ada orang yang mau duduk di bangku sekeras itu, 'kan?",
  str_homestory_815601001_14_dialog_content = "Kalau kau mau...",
  str_homestory_815601001_15_dialog_content = "Aku bisa merancang beberapa kursi tamu yang indah dan nyaman untukmu.",
  str_homestory_815601001_16_dialog_content = "Asalkan kau mau memberitahuku apa yang lucu dari benda kayu itu...",
  str_homestory_815601001_17_option_content = "Tanyakan suasana hatinya",
  str_homestory_815601001_18_dialog_content = "Sepertinya hari ini kau sudah berkunjung ke banyak tempat, Nina.",
  str_homestory_815601001_19_dialog_content = "Aku penasaran, apa tempatku ini membuatmu senang, Nona?",
  str_homestory_815601001_20_dialog_content = "Karena kau sendiri yang tanya, jangan salahkan aku kalau jawabanku tak enak didengar.",
  str_homestory_815601001_21_dialog_content = "Tempat ini seakan berada di antah berantah!",
  str_homestory_815601001_22_dialog_content = "Benar juga, sih...",
  str_homestory_815601001_23_dialog_content = "Tapi, pemandangan di sini sungguh indah. Bisa kumasukkan ke daftar tempat yang akan kukunjungi saat liburan.",
  str_homestory_815601001_24_dialog_content = "Kau harus tahu, kalau saja komentarku dimuat di koran Umbraton, bisa memengaruhi banyak orang.",
  str_homestory_815601001_25_dialog_content = "Asalkan... kau mau menjelaskan kepadaku apa yang menarik dari benda kayu itu...",
  str_homestory_815601001_26_dialog_content = "Kukira kau tak tertarik dengan kuda-kudaan.",
  str_homestory_815601001_27_dialog_content = "... Aku berubah pikiran.",
  str_homestory_815601001_28_dialog_content = "Mencari tahu kesukaan orang lain juga bagian dari pekerjaanku.",
  str_homestory_815601001_29_dialog_content = "Bongkahan kayu yang ringkih itu pasti bergoyang kalau diduduki.",
  str_homestory_815601001_30_dialog_content = "Jadi, kau belum pernah naik kuda-kudaan?",
  str_homestory_815601001_31_dialog_content = "Kenapa begitu?",
  str_homestory_815601001_32_dialog_content = "Tapi... yang seru dari pengalaman naik kuda-kudaan ini adalah sensasi saat kudanya bergoyang-goyang.",
  str_homestory_815601001_33_dialog_content = "Oh, begitu rupanya... Jangan salah paham! Aku sudah tahu soal itu, lho!",
  str_homestory_815601001_34_dialog_content = "Itu tadi hanya sebatas, sebatas untuk mengujimu.",
  str_homestory_815601001_35_option_content = "Percaya saja kepadanya",
  str_homestory_815601001_36_dialog_content = "Kalau begitu, pasti aku lulus dari ujianmu itu...",
  str_homestory_815601001_37_dialog_content = "Ya! Kau ternyata lebih cerdas daripada penampilanmu, PlayerName. Haha.",
  str_homestory_815601001_38_option_content = "Jangan percaya kepadanya",
  str_homestory_815601001_39_dialog_content = "Aku tak percaya.",
  str_homestory_815601001_40_dialog_content = "PlayerName memang bodoh! Huh!",
  str_homestory_815601001_41_dialog_content = "...",
  str_homestory_815601001_42_dialog_content = "Namun…",
  str_homestory_815601001_43_dialog_content = "Kenapa orang-orang mau naik kuda-kudaan dari kayu, bukannya naik kuda sungguhan?",
  str_homestory_815601001_44_dialog_content = "Aku juga tak tahu, sih...",
  str_homestory_815601001_45_dialog_content = "Tapi, kuda-kudaan menawarkan pengalaman seru yang unik, dan jelas jauh lebih aman...",
  str_homestory_815601001_46_dialog_content = "Lagi pula, kurasa tak semua orang bisa naik kuda sungguhan.",
  str_homestory_815601001_47_dialog_content = "Maksudmu... Mereka tak sanggup membeli kuda sungguhan?<sprite=emo_wuzui size=60 />",
  str_homestory_815601001_48_dialog_content = "Sayangnya, sebagian orang bahkan tak sanggup membeli kuda-kudaan.",
  str_homestory_815601001_49_dialog_content = "...",
  str_homestory_815601001_50_dialog_content = "... Aku sudah mengambil keputusan!",
  str_homestory_815601001_51_dialog_content = "Tentang apa?",
  str_homestory_815601001_52_dialog_content = "Aku ingin belajar seni pertukangan kayu dan membuat kuda-kudaan yang lebih menarik...",
  str_homestory_815601001_53_dialog_content = "Dan membagikannya kepada anak-anak yang membutuhkan!",
  str_homestory_810401001_0_dialog_content = "Dawn?",
  str_homestory_810401001_1_dialog_content = "Langkah kaki ini...",
  str_homestory_810401001_2_dialog_content = "Mungkinkah itu PlayerName?",
  str_homestory_810401001_3_dialog_content = "Ah! Kau bisa tahu langkah kakiku?",
  str_homestory_810401001_4_dialog_content = "Ya!<sprite=emo_yaosu size=60 />",
  str_homestory_810401001_5_dialog_content = "Suara di sini jauh lebih beragam dibanding di Colossus...",
  str_homestory_810401001_6_dialog_content = "Tapi, aku masih bisa mengenali suara orang-orang yang kukenal.",
  str_homestory_810401001_7_dialog_content = "Seperti PlayerName dan Eve. Cara berjalan kalian unik.",
  str_homestory_810401001_8_dialog_content = "Cara berjalan unik...",
  str_homestory_810401001_9_option_content = "Tanyakan cara berjalanku",
  str_homestory_810401001_10_dialog_content = "Kau selalu tergesa-gesa, tapi kemudian menjadi berhati-hati saat mendekatiku.",
  str_homestory_810401001_11_dialog_content = "Mungkin penjelasanku kurang bisa dipahami...",
  str_homestory_810401001_12_dialog_content = "Pokoknya, aku tahu itu kau!",
  str_homestory_810401001_13_dialog_content = "Ah! Satu lagi...",
  str_homestory_810401001_14_dialog_content = "Saat kau mendekat, aku merasa bahagia.",
  str_homestory_810401001_15_dialog_content = "Perasaan bahagia ini juga memberitahuku bahwa PlayerName akan datang.",
  str_homestory_810401001_16_option_content = "Tanyakan cara berjalan Eve",
  str_homestory_810401001_17_dialog_content = "Eve punya langkah kaki yang sangat manis!",
  str_homestory_810401001_18_dialog_content = "... Langkah kaki... manis?",
  str_homestory_810401001_19_dialog_content = "Ya! Segala sesuatu tentang Eve itu manis<sprite=emo_aixin size=60 />.",
  str_homestory_810401001_20_dialog_content = "Eh…",
  str_homestory_810401001_21_dialog_content = "Baiklah, biar kujelaskan begini. Tubuh fisik Eve itu cukup istimewa...",
  str_homestory_810401001_22_dialog_content = "Dia hampir tidak mengeluarkan suara ketika berjalan.",
  str_homestory_810401001_23_dialog_content = "Tapi, ketika Eve mendekat, aku merasa bahagia.",
  str_homestory_810401001_24_dialog_content = "Perasaan bahagia ini juga memberitahuku bahwa Eve akan datang.",
  str_homestory_810401001_25_dialog_content = "Jadi, begitu, ya…",
  str_homestory_810401001_26_dialog_content = "Luar biasa!",
  str_homestory_810401001_27_dialog_content = "Kupikir karena aku tak bisa melihat, pendengaranku menjadi sangat tajam.",
  str_homestory_810401001_28_dialog_content = "Ah! Omong-omong...",
  str_homestory_810401001_29_dialog_content = "Bagaimana dengan Sinsa?",
  str_homestory_810401001_30_dialog_content = "Aku yakin kau akrab dengannya. Seperti apa suara langkah kaki Sinsa?",
  str_homestory_810401001_31_dialog_content = "Yah, aku punya cara lebih mudah untuk mengenalinya.",
  str_homestory_810401001_32_dialog_content = "Yaitu?",
  str_homestory_810401001_33_dialog_content = "Dia itu bau.",
  str_homestory_810401001_34_dialog_content = "…?",
  str_homestory_810401001_35_dialog_content = "Dia terus bergerak... Kurasa dia banyak berkeringat.",
  str_homestory_810401001_36_dialog_content = "Oh, begitu…",
  str_homestory_810401001_37_dialog_content = "Dia jelas bukan pria terbau se-Rediesel Wrench...",
  str_homestory_810401001_38_dialog_content = "Tapi, jelas dia lebih bau darimu dan Eve.",
  str_homestory_810401001_39_dialog_content = "Aku senang baumu tidak seperti dia, Navigator.",
  str_homestory_810401001_40_dialog_content = "Err... Terima kasih...",
  str_homestory_810401001_41_dialog_content = "Tapi, kenapa... Kenapa aku tidak bisa mencium bau Sinsa?",
  str_homestory_810401001_42_dialog_content = "Tidak bisa?",
  str_homestory_810401001_43_dialog_content = "Apa aku sebegitu kesalnya karena Eve menghabiskan terlalu banyak waktu dengannya...<sprite=emo_sikao size=60 />",
  str_homestory_810401001_44_dialog_content = "... jadi aku membuat-buat bau itu?",
  str_homestory_810401001_45_dialog_content = "... Pasti itu!",
  str_homestory_810401001_46_dialog_content = "... Terserahlah! Aku yakin dia sangat bau.",
  str_homestory_810401001_47_dialog_content = "Sinsa si bau<sprite=emo_kulou size=60 />!",
  str_homestory_809001001_0_dialog_content = "Barbara?",
  str_homestory_809001001_1_dialog_content = "Apakah cinta hanyalah kebohongan yang indah? ♪",
  str_homestory_809001001_2_dialog_content = "<sprite=emo_aixin size=60 />Cinta sejati muncul hanya ketika bahan bakarnya padam. ♪",
  str_homestory_809001001_3_dialog_content = "Whoa, whoa. Cinta satu-satunya. ♪",
  str_homestory_809001001_4_dialog_content = "Kau sedang berlatih single barumu?",
  str_homestory_809001001_5_dialog_content = "Heheh, single baru? Bukan!",
  str_homestory_809001001_6_dialog_content = "Aku sedang bersiap untuk album baru!",
  str_homestory_809001001_7_option_content = "Album?",
  str_homestory_809001001_8_dialog_content = "Apakah album itu disk yang berisi banyak lagu?",
  str_homestory_809001001_9_dialog_content = "Benar.",
  str_homestory_809001001_10_option_content = "Lebih baik dari album Regina?",
  str_homestory_809001001_11_dialog_content = "Yoi! Tentu saja!",
  str_homestory_809001001_12_dialog_content = "Aku harus memberikan yang terbaik agar album ini sukses!",
  str_homestory_809001001_13_dialog_content = "Kau benar-benar pekerja keras.",
  str_homestory_809001001_14_dialog_content = "Tentu. Lagi pula, genre musik baru bermunculan di mana-mana...",
  str_homestory_809001001_15_dialog_content = "Aku tidak boleh ketinggalan!",
  str_homestory_809001001_16_dialog_content = "Kau khawatir kehilangan popularitas dan dukungan?",
  str_homestory_809001001_17_dialog_content = "Kehilangan popularitas dan dukungan? Tidak pernah!",
  str_homestory_809001001_18_dialog_content = "Aku suka melihat berbagai jenis musik dan musisi berkembang bersama.",
  str_homestory_809001001_19_dialog_content = "Lantas, apa yang kaumaksud dengan \"tidak boleh ketinggalan\"?",
  str_homestory_809001001_20_dialog_content = "Itu berarti aku harus bekerja lebih keras<sprite=emo_yinfu size=60 />.",
  str_homestory_809001001_21_dialog_content = "Aku harus membuat kemajuan bersama para artis baru dan menghadirkan lebih banyak musik yang luar biasa bagi semua orang!",
  str_homestory_809001001_22_dialog_content = "Aku benci tertinggal!",
  str_homestory_809001001_23_dialog_content = "Benar-benar menginspirasi!",
  str_homestory_809001001_24_dialog_content = "Hmm... Aku tidak terlalu mengkhawatirkan popularitasku.",
  str_homestory_809001001_25_dialog_content = "Tapi, jika para penggemar yang kukenal baik meninggalkanku demi penyanyi lain...",
  str_homestory_809001001_26_dialog_content = "Aku akan tetap merasa sedikit frustrasi!",
  str_homestory_809001001_27_dialog_content = "Penyanyi lain... Maksudmu Regina?",
  str_homestory_809001001_28_dialog_content = "PlayerName... Kau blak-blakan sekali!",
  str_homestory_809001001_29_dialog_content = "Kau peduli dengan musik Regina, bukan?",
  str_homestory_809001001_30_dialog_content = "Bagaimana cara menjelaskannya, ya?",
  str_homestory_809001001_31_dialog_content = "Bohong kalau kubilang aku sama sekali tak peduli<sprite=emo_tanqi size=60 />...",
  str_homestory_809001001_32_dialog_content = "Er... Bisa dibilang...",
  str_homestory_809001001_33_dialog_content = "Aku mendengarkan musiknya untuk mempromosikan keragaman.",
  str_homestory_809001001_34_dialog_content = "Hmm... Mungkin penggemarnya tak sebanyak penggemarku, tapi pendukungnya sangat setia.",
  str_homestory_809001001_35_dialog_content = "Musisi berbicara lewat kualitas lagu mereka, tapi aku cukup penasaran...",
  str_homestory_809001001_36_dialog_content = "Bagaimana dia mempertahankan penggemarnya?",
  str_homestory_809001001_37_dialog_content = "Kenapa tidak tanya Regina saja kalau kau benar-benar mau tahu?",
  str_homestory_809001001_38_dialog_content = "Hmm…",
  str_homestory_809001001_39_dialog_content = "Sepertinya aku akan mengikuti saranmu, PlayerName...",
  str_homestory_809001001_40_dialog_content = "Bertanya kepadanya itu bukan perkara besar!",
  str_homestory_809001001_41_dialog_content = "Hmm... Setidaknya dalam 20 tahun<sprite=emo_emo size=60 />!",
  str_homestory_809001001_42_dialog_content = "... Lebih baik katakan saja kau takkan pernah bertanya padanya!",
  str_homestory_807001001_0_dialog_content = "Leona...",
  str_homestory_807001001_1_dialog_content = "Hei, Nak.",
  str_homestory_807001001_2_dialog_content = "Ada apa?",
  str_homestory_807001001_3_dialog_content = "Maaf, aku lagi sibuk.",
  str_homestory_807001001_4_dialog_content = "Seperti yang kaulihat, aku sibuk meredakan emosi negatifku.",
  str_homestory_807001001_5_dialog_content = "Ah! Aku tak tahu meninju samsak itu bisa membantu meredakan.",
  str_homestory_807001001_6_dialog_content = "Malah sangat efektif<sprite=emo_baiyan size=60 />.",
  str_homestory_807001001_7_dialog_content = "Kau belum tahu?",
  str_homestory_807001001_8_dialog_content = "Berolahraga itu cara yang baik untuk memerangi emosi negatif.",
  str_homestory_807001001_9_dialog_content = "Aku pernah mendengarnya.",
  str_homestory_807001001_10_dialog_content = "Omong-omong emosi negatifmu...",
  str_homestory_807001001_11_option_content = "Apa penyebabnya?",
  str_homestory_807001001_12_dialog_content = "Tidak ada penyebab spesifik.",
  str_homestory_807001001_13_option_content = "Kau merasa baikan?",
  str_homestory_807001001_14_dialog_content = "Yah, kira-kira begitulah.",
  str_homestory_807001001_15_dialog_content = "Kau bisa lihat emosi negatif sebagai simpul di dalam tubuhmu.",
  str_homestory_807001001_16_dialog_content = "Simpul? Seperti simpul pada tali?",
  str_homestory_807001001_17_dialog_content = "Semacamnya.",
  str_homestory_807001001_18_dialog_content = "Setelah kausadari bahwa suasana hatimu sedang buruk...",
  str_homestory_807001001_19_dialog_content = "Kau perlu melakukan sesuatu yang kausuka untuk melepaskannya.",
  str_homestory_807001001_20_dialog_content = "Lakukan apa pun yang membuatmu rileks.",
  str_homestory_807001001_21_dialog_content = "Bagiku, inilah cara terbaik untuk rileks. Ini membuatku merasa seperti sedang bertempur.",
  str_homestory_807001001_22_dialog_content = "Saat perasaan negatif mengakar di hatimu, simpul ini makin sulit untuk dilepaskan.",
  str_homestory_807001001_23_dialog_content = "Bahkan bisa jadi ancaman bagi kesehatanmu.",
  str_homestory_807001001_24_dialog_content = "Butuh waktu lama bagiku untuk mempelajari ini.",
  str_homestory_807001001_25_dialog_content = "Saat hatimu dibutakan kebencian...",
  str_homestory_807001001_26_dialog_content = "... Maaf. Aku melantur...",
  str_homestory_807001001_27_dialog_content = "Huh... kau benar sekali.",
  str_homestory_807001001_28_dialog_content = "Cobalah lain kali.",
  str_homestory_807001001_29_dialog_content = "Tentu!",
  str_homestory_807001001_30_dialog_content = "Mungkin waktu itu Sharona ada di sini meninju samsak untuk alasan yang sama.",
  str_homestory_807001001_31_dialog_content = "Maksudmu Sharona?",
  str_homestory_807001001_32_dialog_content = "Sharona pernah meninju samsak ini?",
  str_homestory_807001001_33_dialog_content = "Ah? Hanya bercanda!",
  str_homestory_807001001_34_dialog_content = "(Ah oh... Mungkin seharusnya aku tidak bilang begitu...)",
  str_homestory_807001001_35_dialog_content = "...",
  str_homestory_807001001_36_dialog_content = "Leona, ada apa?",
  str_homestory_807001001_37_dialog_content = "Heheh. Aku lagi berbuat hal yang sama seperti adikku tersayang.",
  str_homestory_807001001_38_dialog_content = "Berusaha tidak membakar <sprite=emo_nuhuo size=60 />tempat ini...",
  str_homestory_807001001_39_dialog_content = "Mungkin aku harus segera pergi ke Umbraton.",
  str_homestory_807001001_40_dialog_content = "Dah, Nak.",
  str_homestory_807001001_41_dialog_content = "A-anu...",
  str_homestory_807001001_42_dialog_content = "Sampai nanti...",
  str_homestory_811501001_0_dialog_content = "Naroxel!",
  str_homestory_811501001_1_dialog_content = "Halo, PlayerName.",
  str_homestory_811501001_2_dialog_content = "Kekuatan alam pasti telah membimbing kita kemari sekali lagi.",
  str_homestory_811501001_3_dialog_content = "Kau lagi mengobrol dengan Olive dan Palm?",
  str_homestory_811501001_4_dialog_content = "Ya!",
  str_homestory_811501001_5_dialog_content = "Aku kagum kau masih ingat nama-nama mereka.",
  str_homestory_811501001_6_dialog_content = "Mereka senang sekali.",
  str_homestory_811501001_7_dialog_content = "Bukan apa-apa...",
  str_homestory_811501001_8_dialog_content = "Emosiku meluap-luap saat menyaksikan Eraveil kembali bangkit<sprite=emo_pugongying size=60 />.",
  str_homestory_811501001_9_dialog_content = "Kini, Cloud Gardens benar-benar makmur dan cantik.",
  str_homestory_811501001_10_dialog_content = "Terima kasih atas berkah alam dan kerja kerasmu, PlayerName.",
  str_homestory_811501001_11_dialog_content = "Tapi... Aku sedikit mengkhawatirkanmu.",
  str_homestory_811501001_12_dialog_content = "Setelah apa yang terjadi belakangan ini, apa kau baik-baik saja?",
  str_homestory_811501001_13_option_content = "Mengangguk",
  str_homestory_811501001_14_dialog_content = "Aku senang berbagi tempat ini dengan kalian semua.",
  str_homestory_811501001_15_dialog_content = "Tapi, terkadang aku merasa stres karena ekspektasi yang tinggi.",
  str_homestory_811501001_16_option_content = "Menggelengkan kepala",
  str_homestory_811501001_17_dialog_content = "Suasana hatiku tidak sedang buruk...",
  str_homestory_811501001_18_dialog_content = "Tapi, aku merasa cemas dan stres.",
  str_homestory_811501001_19_dialog_content = "Aku mengerti.",
  str_homestory_811501001_20_dialog_content = "Yuk! Sedikit bersantai bareng aku?",
  str_homestory_811501001_21_dialog_content = "Oke.",
  str_homestory_811501001_22_dialog_content = "Mari kita coba latihan pernapasan ini.",
  str_homestory_811501001_23_dialog_content = "Latihan pernapasan?",
  str_homestory_811501001_24_dialog_content = "Ya.",
  str_homestory_811501001_25_dialog_content = "Ini akan membantumu menyeimbangkan energi di dalam tubuh.",
  str_homestory_811501001_26_dialog_content = "Sederhananya...",
  str_homestory_811501001_27_dialog_content = "Ini membuat energi batin kita mengalir.",
  str_homestory_811501001_28_dialog_content = "Oh, begitu! Kita mulai sekarang?",
  str_homestory_811501001_29_dialog_content = "Tentu.",
  str_homestory_811501001_30_dialog_content = "Lemaskan bahumu. Ambil napas dalam-dalam.",
  str_homestory_811501001_31_dialog_content = "Mantap. Sekarang... pegang hidungmu.",
  str_homestory_811501001_32_dialog_content = "(Pegang hidung... Hmm...)",
  str_homestory_811501001_33_dialog_content = "Pencet sisi kanan hidung, lalu tarik napas melalui lubang hidung kiri.",
  str_homestory_811501001_34_dialog_content = "Kemudian pencet sisi kiri hidung, lalu embuskan napas melalui lubang hidung kanan...",
  str_homestory_811501001_35_dialog_content = "(Tarik... Embuskan...)",
  str_homestory_811501001_36_dialog_content = "Seperti itu. Sesuaikan pernapasanmu perlahan-lahan.",
  str_homestory_811501001_37_dialog_content = "Tarik napas dan embuskan bergantian...",
  str_homestory_811501001_38_dialog_content = "Tubuh dan pikiran kita akan langsung terasa rileks melalui latihan pernapasan ini.",
  str_homestory_811501001_39_dialog_content = "Ya... Sekarang aku merasa sangat tenang.",
  str_homestory_811501001_40_dialog_content = "Sebenarnya aku agak mengantuk<sprite=emo_kun size=60 />...",
  str_homestory_811501001_41_dialog_content = "Heheh.",
  str_homestory_811501001_42_dialog_content = "Latihan pernapasan ini bisa membuat kita tenang dan tertidur lelap.",
  str_homestory_811501001_43_dialog_content = "Coba saja lagi sebelum tidur.",
  str_homestory_811501001_44_dialog_content = "Mungkin kau akan merasa lebih baik jika selama latihan ini matamu terpejam.",
  str_homestory_811501001_45_dialog_content = "Hmm. Aku akan mencoba mengingatnya.",
  str_homestory_811501001_46_dialog_content = "Terima kasih, Naroxel!",
  str_homestory_803302001_0_dialog_content = "Halo, Vice.",
  str_homestory_803302001_1_dialog_content = "Eh, PlayerName! Apa kau sedang senggang?",
  str_homestory_803302001_2_dialog_content = "Iya, nih. Ada perlu apa?",
  str_homestory_803302001_3_dialog_content = "Saat sedang berjalan-jalan, aku menyadari ada sesuatu di air.",
  str_homestory_803302001_4_dialog_content = "Aku sudah coba mengambilnya tapi tak berhasil. Kelihatannya seperti semacam cetak biru, sih.",
  str_homestory_803302001_5_dialog_content = "Kalau berkenan, coba kau periksa.",
  str_homestory_803302001_6_dialog_content = "Tentu, bukan masalah.",
  str_homestory_803303001_0_dialog_content = "Sedang apa kau?",
  str_homestory_803303001_1_dialog_content = "Aku lagi memikirkan cara mengambil benda itu dari sana...",
  str_homestory_803303001_2_dialog_content = "Ada apa?",
  str_homestory_803303001_3_dialog_content = "Benda aneh di dasar sungai itu membuatku penasaran<sprite=emo_sikao size=60 />.",
  str_homestory_803303001_4_dialog_content = "Tapi sekuat apa pun aku mencoba, aku masih tak bisa mengambilnya... tanganku malah terasa sakit sekarang.",
  str_homestory_803303001_5_dialog_content = "Kau bisa bantu aku? Benda itu di sana.",
  str_homestory_803303001_6_dialog_content = "Baiklah, biar kucoba.",
  str_homestory_803304001_0_dialog_content = "Mencariku?",
  str_homestory_803304001_1_dialog_content = "Hei, dari mana kau tahu kalau aku mencarimu?",
  str_homestory_803304001_2_dialog_content = "Aku menemukan sesuatu yang menarik, nih!<sprite=emo_yaosu size=60 />",
  str_homestory_803304001_3_dialog_content = "Bukan tarantula atau jangkrik yang menari, 'kan?",
  str_homestory_803304001_4_dialog_content = "Bukan, ini adalah cetak biru furnitur baru!",
  str_homestory_803304001_5_dialog_content = "Tapi cetak biru itu terbenam di dasar sungai dan sulit digali.",
  str_homestory_803304001_6_dialog_content = "Yah, serahkan saja padaku. Aku jago menggali.",
  str_homestory_803304001_7_dialog_content = "Ada di sana! Ayo kutunjukkan tempatnya!",
  str_homestory_809301001_0_dialog_content = "Tatapan itu...",
  str_homestory_809301001_1_dialog_content = "Anu, ada yang bisa kubantu?",
  str_homestory_809301001_2_dialog_content = "Sejak terakhir kali kita bertemu, kau makin tumbuh tinggi, ya. Kau tahu aku ingin sesuatu darimu.",
  str_homestory_809301001_3_dialog_content = "Bulu kudukku berdiri, seperti ada seseorang yang mengawasi gerak-gerikku...",
  str_homestory_809301001_4_dialog_content = "Saat mendongak, aku melihatmu menatapku.",
  str_homestory_809301001_5_dialog_content = "\"Mendongak?\" Sepertinya kau belum tumbuh setinggi yang kukira.",
  str_homestory_809301001_6_option_content = "Aku jadi makin tinggi!",
  str_homestory_809301001_7_dialog_content = "Ya, tentu! Bagaimana mungkin aku tak menyadarinya. Mau ikut ke labku?",
  str_homestory_809301001_8_dialog_content = "Aku bisa membedahmu untuk melihat apakah tulangmu benar-benar tumbuh.",
  str_homestory_809301001_9_option_content = "Ya…",
  str_homestory_809301001_10_dialog_content = "Menyerah semudah itu? Kau memang butuh bantuanku. Mau ikut ke labku?",
  str_homestory_809301001_11_dialog_content = "Aku bisa membedahmu untuk melihat apakah tulangmu masih bisa tumbuh.",
  str_homestory_809301001_12_dialog_content = "Anu, sepertinya tidak usah...",
  str_homestory_809301001_13_dialog_content = "Tak perlu khawatir. Biarkan aku meneliti tubuhmu, lalu aku akan menyusun rencana untuk mendukung pertumbuhanmu.",
  str_homestory_809301001_14_dialog_content = "Tak perlu, biarkan seperti apa adanya saja.",
  str_homestory_809301001_15_dialog_content = "Seperti apa adanya? Yang benar saja.",
  str_homestory_809301001_16_dialog_content = "Aku tahu materi genetik pohon-pohon di Cloud Gardens ini telah dirombak.",
  str_homestory_809301001_17_dialog_content = "Dan itu dilakukan dengan cara...",
  str_homestory_809301001_18_dialog_content = "Memadukan benih dari beberapa tanaman berbeda menjadi varietas baru yang unik.",
  str_homestory_809301001_19_dialog_content = "Kau bisa tahu hanya dengan melihatnya?",
  str_homestory_809301001_20_dialog_content = "Apa kau lupa kalau aku Tech Officer dari Illumina dengan spesialisasi bioteknologi?",
  str_homestory_809301001_21_dialog_content = "Aku sering melakukan eksperimen rekayasa hayati seperti ini, terlalu sering sampai-sampai tak bisa dihitung.",
  str_homestory_809301001_22_dialog_content = "Tapi, tak kuduga kalau kau juga mahir melakukan hal ini.",
  str_homestory_809301001_23_dialog_content = "Aku hanya coba-coba. Itu bukan hal yang istimewa, kok.",
  str_homestory_809301001_24_dialog_content = "Iya, aku tahu.",
  str_homestory_809301001_25_dialog_content = "...",
  str_homestory_809301001_26_dialog_content = "Kau tak bisa meraih keberhasilan seperti ini kalau belum gagal sembilan puluh sembilan kali.",
  str_homestory_809301001_27_dialog_content = "Itulah hal yang bisa kupelajari dari upayaku selama ini. Sementara itu, kau...",
  str_homestory_809301001_28_dialog_content = "Untuk menghasilkan benih yang sangat langka itu, banyak hal yang harus dilakukan.",
  str_homestory_809301001_29_dialog_content = "\"Banyak hal\"? Aku tak paham.",
  str_homestory_809301001_30_dialog_content = "Agak mustahil bisa dilakukan kalau kau tak punya latar belakang sebagai ilmuwan. Kita lanjutkan obrolan ini nanti.",
  str_homestory_809301001_31_dialog_content = "Yah, kenapa tidak lanjutkan sekarang saja?",
  str_homestory_809301001_32_dialog_content = "Sekarang? Aku mau tidur dulu.",
  str_homestory_809301001_33_dialog_content = "...",
  str_homestory_809301001_34_dialog_content = "Oh, tunggu dulu. Aku hampir lupa, ada yang ingin kutanyakan padamu.",
  str_homestory_809301001_35_dialog_content = "Bisakah kau mengubah kamarku menjadi asrama yang dipenuhi banyak gadis cantik?",
  str_homestory_809301001_36_option_content = "Setuju",
  str_homestory_809301001_37_dialog_content = "Bisa, sih. Tapi sebelumnya aku harus membahasnya dengan semua orang.",
  str_homestory_809301001_38_option_content = "Tolak",
  str_homestory_809301001_39_dialog_content = "Aku takkan melanggar hak seseorang untuk tinggal di mana pun ia mau.",
  str_homestory_809301001_40_dialog_content = "Tapi, kalau kau bisa melakukannya sendiri sih tak masalah.",
  str_homestory_809301001_41_dialog_content = "Kedengarannya merepotkan.",
  str_homestory_809301001_42_dialog_content = "Tapi, layak dicoba, meski harus dicoba berkali-kali.",
  str_homestory_809301001_43_dialog_content = "(Masih bersikap seperti itu bahkan saat membahas hal seperti ini?)",
  str_homestory_815702001_0_dialog_content = "Lihat apa kau?",
  str_homestory_815702001_1_dialog_content = "Ahhhhhhhhhhhh!",
  str_homestory_815702001_2_dialog_content = "Maaf, apa aku mengagetkanmu lagi?",
  str_homestory_815702001_3_dialog_content = "(Eh, kenapa aku bilang \"lagi\", sih?)",
  str_homestory_815702001_4_dialog_content = "Tidak, kok. Aku cuma melamun.",
  str_homestory_815702001_5_dialog_content = "Jadi aku tak tahu kalau kau datang ke sini.",
  str_homestory_815702001_6_dialog_content = "Akulah yang seharusnya minta maaf.",
  str_homestory_815702001_7_dialog_content = "Tak apa, tak perlu cemas.",
  str_homestory_815702001_8_dialog_content = "Kau baru saja dari sungai, 'kan? Jangan bilang kalau kau memikirkan tentang...",
  str_homestory_815702001_9_option_content = "Memancing?",
  str_homestory_815702001_10_dialog_content = "Memancing... Bukannya memancing perlu peralatan mahal, ya?",
  str_homestory_815702001_11_dialog_content = "Anu, itu tak pernah terlintas dalam benakku...",
  str_homestory_815702001_12_option_content = "Berenang?",
  str_homestory_815702001_13_dialog_content = "Berenang... Bukannya kau harus memakai pakaian ketat kalau mau berenang?",
  str_homestory_815702001_14_dialog_content = "Aku agak malu.",
  str_homestory_815702001_15_dialog_content = "Sebenarnya, aku tadi memikirkan...",
  str_homestory_815702001_16_dialog_content = "Apakah petani di Eraveil bekerja sekeras petani di Cloud Island?",
  str_homestory_815702001_17_dialog_content = "Aku tak tahu juga, sih. Tapi, baik petani Eraveil maupun Cloud Island...",
  str_homestory_815702001_18_dialog_content = "Mereka gembira saat melihat hasil panen yang melimpah.",
  str_homestory_815702001_19_dialog_content = "Jadi, apa yang membuatmu memikirkan itu?",
  str_homestory_815702001_20_dialog_content = "Yah, aku melihat ada benda berkilau di tepi sungai yang tampak seperti koin<sprite=emo_baiyebi size=60 />.",
  str_homestory_815702001_21_dialog_content = "Koin berarti perdagangan, perdagangan berarti makanan, dan makanan berarti... petani!",
  str_homestory_815702001_22_dialog_content = "Kau menghubungkan semuanya begitu saja?",
  str_homestory_815702001_23_dialog_content = "Oh, jangan marah, ya!",
  str_homestory_815702001_24_dialog_content = "Aku tak bermaksud untuk menyimpan koin itu.",
  str_homestory_815702001_25_dialog_content = "Nih, kuberikan koinnya kepadamu...",
  str_homestory_815702001_26_dialog_content = "Tak apa, santai saja.",
  str_homestory_815702001_27_dialog_content = "Koin itu kusimpan di mana ya...",
  str_homestory_815702001_28_dialog_content = "Yah, hilang...",
  str_homestory_815702001_29_dialog_content = "Ah!",
  str_homestory_815702001_30_dialog_content = "Ada apa?",
  str_homestory_815702001_31_dialog_content = "Aku ingat! Aku mendengar suara cipratan air saat beranjak dari tepi sungai.",
  str_homestory_815702001_32_dialog_content = "Pasti koinnya jatuh ke sungai!",
  str_homestory_815702001_33_dialog_content = "Tenang saja. Aku akan mencarikan koin itu.",
  str_homestory_815702001_34_dialog_content = "Oh, benarkah? Terima kasih!",
  str_homestory_815602001_0_dialog_content = "Apa yang sedang Anda cari?",
  str_homestory_815602001_1_dialog_content = "Hei, ke sini!",
  str_homestory_815602001_2_dialog_content = "Nina?",
  str_homestory_815602001_3_dialog_content = "Jika saya tidak salah, Anda sedang mencari sesuatu.",
  str_homestory_815602001_4_dialog_content = "Ya.",
  str_homestory_815602001_5_dialog_content = "Pernahkah Anda melihat benda kecil yang bulat?",
  str_homestory_815602001_6_dialog_content = "Bisakah Anda lebih tepat?",
  str_homestory_815602001_7_dialog_content = "Nah ... Inilah masalahnya.",
  str_homestory_815602001_8_dialog_content = "Saya belum pernah melihat sesuatu dengan pola seperti itu ...",
  str_homestory_815602001_9_dialog_content = "Itu sebabnya aku mengepalkannya erat-erat di tanganku!",
  str_homestory_815602001_10_dialog_content = "Tapi... itu terlepas dari tanganku dan masuk ke air saat aku mengendurkan cengkeramanku...",
  str_homestory_815602001_11_dialog_content = "Tunggu, kenapa aku merasa seperti yang kau bicarakan—",
  str_homestory_815602001_12_dialog_content = "Tunggu, biarkan aku selesai.",
  str_homestory_815602001_13_dialog_content = "Kemudian saya menemukan pola aneh di telapak tangan saya!",
  str_homestory_815602001_14_option_content = "Lumina bermutasi?!",
  str_homestory_815602001_15_dialog_content = "Apakah Anda terlalu banyak membaca novel fantasi?",
  str_homestory_815602001_16_option_content = "Apakah Anda akan berubah?!",
  str_homestory_815602001_17_dialog_content = "apa gerangan yang kamu sedang bicarakan?",
  str_homestory_815602001_18_dialog_content = "Itu karena benda itu memiliki bentuk dan pola yang unik!",
  str_homestory_815602001_19_dialog_content = "Ketika saya memegangnya di telapak tangan saya, itu tercetak di kulit saya.",
  str_homestory_815602001_20_dialog_content = "Pola ini agak estetis ...",
  str_homestory_815602001_21_dialog_content = "Pikirkanlah, jika saya mendesain pakaian berdasarkan pola ini...",
  str_homestory_815602001_22_dialog_content = "Saya harus menemukan koin itu!",
  str_homestory_815602001_23_dialog_content = "Saya tahu itu koin!",
  str_homestory_815602001_24_dialog_content = "Aku akan membantu.",
  str_homestory_815602001_25_dialog_content = "T-Terima kasih—Hei, tunggu!<sprite=emo_wuzui size=60 />",
  str_homestory_815602001_26_dialog_content = "Sejak saya menemukan koin di Cloud Gardens... secara teknis itu milik Anda, kan?",
  str_homestory_815602001_27_dialog_content = "Jadi, jika saya meminjamnya dari Anda dan mempelajarinya ...",
  str_homestory_815602001_28_dialog_content = "Bukan masalah. Tapi kita harus menemukannya dulu.",
  str_homestory_815602001_29_dialog_content = "Aku terkejut kau menyetujuinya begitu cepat.",
  str_homestory_815602001_30_dialog_content = "Ahem... Bukannya aku benar-benar INGIN mempelajarinya...",
  str_homestory_815602001_31_dialog_content = "Itu hanya inspirasi untuk desain pakaian, lho!",
  str_homestory_815602001_32_dialog_content = "Anda tahu, kan?",
  str_homestory_815602001_33_dialog_content = "Saya tahu.",
  str_homestory_815602001_34_dialog_content = "Ck, itu bagus.",
  str_homestory_812601001_0_dialog_content = "Apa yang Anda pikirkan?",
  str_homestory_812601001_1_dialog_content = "Bethel?",
  str_homestory_812601001_2_dialog_content = "Kamu terlihat seperti sedang memikirkan sesuatu...",
  str_homestory_812601001_3_dialog_content = "Diam...<sprite=emo_chidai size=60 />",
  str_homestory_812601001_4_dialog_content = "Saya baru saja menangani semua pernyataan Guild itu. Aku sedang melakukan beberapa perenungan.",
  str_homestory_812601001_5_dialog_content = "Tentang apa?",
  str_homestory_812601001_6_dialog_content = "Karya fiksi terbaru saya!",
  str_homestory_812601001_7_dialog_content = "Mungkin aku harus menjalaninya bersamamu.",
  str_homestory_812601001_8_dialog_content = "Tentu, jika saya bisa membantu.",
  str_homestory_812601001_9_dialog_content = "Baiklah... Dengarkan. Begini ceritanya...",
  str_homestory_812601001_10_dialog_content = "Pemimpin pria dan wanita datang ke sungai ...",
  str_homestory_812601001_11_dialog_content = "Dan tiba-tiba, saputangan pemeran utama wanita jatuh ke dalam air!",
  str_homestory_812601001_12_dialog_content = "Jadi inilah pertanyaannya: Haruskah pemeran utama wanita mengambilnya, atau haruskah pemimpin pria?",
  str_homestory_812601001_13_option_content = "Pemeran utama wanita",
  str_homestory_812601001_14_dialog_content = "Hmm…",
  str_homestory_812601001_15_dialog_content = "Tentu, itu akan menunjukkan dia menjadi wanita yang sangat mandiri dan cakap.",
  str_homestory_812601001_16_option_content = "Pemeran utama pria",
  str_homestory_812601001_17_dialog_content = "Hmm…",
  str_homestory_812601001_18_dialog_content = "Itu akan benar-benar mendorong cerita ke depan, dan mereka dapat mulai berbicara tentang saputangan!",
  str_homestory_812601001_19_dialog_content = "Baik. Saya mendapatkannya!",
  str_homestory_812601001_20_dialog_content = "Begitulah cara saya akan menulisnya!<sprite=emo_yaosu size=60 />",
  str_homestory_812601001_21_dialog_content = "Apa yang membuatmu membayangkan plot seperti itu?",
  str_homestory_812601001_22_dialog_content = "Karena aku baru saja melihat sesuatu jatuh ke dalam air.",
  str_homestory_812601001_23_dialog_content = "Itu membuat saya berpikir bahwa itu adalah premis yang bagus...",
  str_homestory_812601001_24_dialog_content = "Tunggu apa? Apa yang jatuh ke air?",
  str_homestory_812601001_25_dialog_content = "Saya tidak melihat dengan baik. Itu adalah sesuatu yang kecil dan bulat.<sprite=emo_sikao size=60 />",
  str_homestory_812601001_26_dialog_content = "Kecil dan bulat...",
  str_homestory_812601001_27_dialog_content = "Aku tahu apa itu.",
  str_homestory_816401001_0_dialog_content = "Carleen?",
  str_homestory_816401001_1_dialog_content = "PlayerName?",
  str_homestory_816401001_2_dialog_content = "Kau sedang apa, Carleen?",
  str_homestory_816401001_3_dialog_content = "Saya berpikir.",
  str_homestory_816401001_4_dialog_content = "Apakah semua baik-baik saja? Anda terlihat agak ... ke bawah.",
  str_homestory_816401001_5_dialog_content = "Turun? Sehat...",
  str_homestory_816401001_6_dialog_content = "Karena Lumopolis dilanda beberapa bencana alam baru-baru ini.",
  str_homestory_816401001_7_dialog_content = "Saya turut berduka mendengarnya...",
  str_homestory_816401001_8_dialog_content = "Bagaimana keadaan kota sekarang? Apakah ada yang bisa saya lakukan untuk membantu?",
  str_homestory_816401001_9_dialog_content = "Terima kasih telah bertanya, PlayerName.",
  str_homestory_816401001_10_dialog_content = "Jumlah korban dan kerugian aset sedang ditangani secara resmi.",
  str_homestory_816401001_11_dialog_content = "Selain mengembalikan mayat orang mati ke keluarga mereka...",
  str_homestory_816401001_12_dialog_content = "Aku tidak benar-benar tahu apa lagi yang bisa kita lakukan untuk meringankan rasa sakit mereka.",
  str_homestory_816401001_13_dialog_content = "Aku tahu bagaimana perasaanmu, Carleen.",
  str_homestory_816401001_14_dialog_content = "Fiuh... <sprite=emo_tanqi size=60 />",
  str_homestory_816401001_15_dialog_content = "Pikiranku terasa jauh lebih jernih sekarang setelah aku memberitahumu apa yang menggangguku.",
  str_homestory_816401001_16_dialog_content = "Apakah Anda berpikir tentang bagaimana menghindari bencana ini ke depan?",
  str_homestory_816401001_17_dialog_content = "Tidak.",
  str_homestory_816401001_18_dialog_content = "Dalam menghadapi bencana alam, kita hanyalah semut.",
  str_homestory_816401001_19_dialog_content = "Saya hanya berdoa sendiri, dan untuk menegaskan kembali sesuatu pada diri saya sendiri...",
  str_homestory_816401001_20_option_content = "Iman Anda?",
  str_homestory_816401001_21_dialog_content = "Hmm…",
  str_homestory_816401001_22_option_content = "Efektivitas doa?",
  str_homestory_816401001_23_dialog_content = "Bagaimana saya harus meletakkan ini?",
  str_homestory_816401001_24_dialog_content = "Saya hanya ingin menegaskan bahwa doa masih mampu memberikan pelipur lara yang sangat saya butuhkan.",
  str_homestory_816401001_25_dialog_content = "Oh, begitu…",
  str_homestory_816401001_26_dialog_content = "Kita sering takut akan hal-hal yang tidak terduga yang tidak dapat kita kendalikan.",
  str_homestory_816401001_27_dialog_content = "Tapi tidak ada yang bisa kita lakukan selain melihat mereka terungkap.",
  str_homestory_816401001_28_dialog_content = "Dan itulah mengapa Anda merasa tidak berdaya, bukan?",
  str_homestory_816401001_29_dialog_content = "Benar.",
  str_homestory_816401001_30_dialog_content = "Saya berdoa setiap kali saya merasa kalah.",
  str_homestory_816401001_31_dialog_content = "Dan saya juga bertanya-tanya apa sebenarnya yang diberikan doa kepada saya.",
  str_homestory_816401001_32_dialog_content = "Dan setelah banyak berpikir, saya menyimpulkan bahwa itu adalah dukungan spiritual, dan...",
  str_homestory_816401001_33_dialog_content = "Motivasi untuk terus maju.",
  str_homestory_816401001_34_dialog_content = "Benar.",
  str_homestory_816401001_35_dialog_content = "Saya yakin doa Anda akan membantu Anda melewati masa-masa sulit ini.",
  str_homestory_816401001_36_dialog_content = "Dan akhirnya aku mengerti sesuatu.",
  str_homestory_816401001_37_dialog_content = "Mengapa kita memiliki kecenderungan untuk membuat dewa dari begitu banyak elemen alam?",
  str_homestory_816401001_38_dialog_content = "Karena kita memiliki terlalu banyak pertanyaan tentang dunia ini dan terlalu sedikit jawaban.",
  str_homestory_816401001_39_dialog_content = "Doa sebenarnya adalah kompromi. <sprite=emo_sikao size=60 />",
  str_homestory_816401001_40_dialog_content = "Mereka tidak memecahkan masalah atau memberikan jawaban apa pun.",
  str_homestory_816401001_41_dialog_content = "Tetapi mereka memberi Anda kedamaian batin, dan membantu Anda bangkit kembali.",
  str_homestory_816401001_42_dialog_content = "Benar... mereka memang memberikan banyak dukungan.",
  str_homestory_816401001_43_dialog_content = "Mungkin saya harus mencoba hal doa ini lain kali.",
  str_homestory_816401001_44_dialog_content = "Saya berharap untuk berbicara dengan Anda tentang hal itu.",
  str_homestory_811101001_0_dialog_content = "Beryl...",
  str_homestory_811101001_1_dialog_content = "...",
  str_homestory_811101001_2_dialog_content = "Beryl!",
  str_homestory_811101001_3_dialog_content = "Hm? Ada apa?",
  str_homestory_811101001_4_dialog_content = "Anda sedang zonasi, menatap sungai. Apakah ada yang salah?",
  str_homestory_811101001_5_dialog_content = "Oh, apakah Anda khawatir tentang saya?",
  str_homestory_811101001_6_option_content = "Yap.",
  str_homestory_811101001_7_dialog_content = "Jadi menurutmu aku tidak bahagia karena aku berdiri di tepi sungai? <sprite=emo_wuzui size=60 />",
  str_homestory_811101001_8_dialog_content = "Hmm, sebenarnya bukan itu...",
  str_homestory_811101001_9_dialog_content = "Aku hanya berjalan-jalan di tepi sungai. Maksudku, cuacanya bagus hari ini, kan?",
  str_homestory_811101001_10_dialog_content = "Raut wajahmu sangat aneh.",
  str_homestory_811101001_11_option_content = "Tidak terlalu.",
  str_homestory_811101001_12_dialog_content = "Aku hanya tidak tahu apa yang kamu lakukan, karena kamu sudah berdiri di sini untuk waktu yang lama.",
  str_homestory_811101001_13_dialog_content = "Ketika saya turun ke sungai, saya biasanya berjalan atau memancing, tetapi saya tidak tinggal diam.",
  str_homestory_811101001_14_dialog_content = "Jadi... apa yang kamu lakukan?",
  str_homestory_811101001_15_dialog_content = "Saya sedang memikirkan tentang kristal dan Cloud Gardens saya.",
  str_homestory_811101001_16_dialog_content = "kristalmu...",
  str_homestory_811101001_17_dialog_content = "Ya, Vice mengatakan Anda telah menekankan pengembangan Cloud Gardens.",
  str_homestory_811101001_18_dialog_content = "Dan tentang bagaimana Anda tidak punya banyak uang <sprite=emo_baiyebi size=60 />, jadi saya berpikir tentang bagaimana membuat Anda kaya.",
  str_homestory_811101001_19_dialog_content = "Dan saya mulai berpikir tentang kekuatan saya, kristal.",
  str_homestory_811101001_20_dialog_content = "Jika aku mengubah batu di Cloud Gardens menjadi kristal, lalu menjualnya ke toko perhiasan di Umbration...",
  str_homestory_811101001_21_dialog_content = "Kamu bisa melakukannya?",
  str_homestory_811101001_22_dialog_content = "Ya, saya mendengar bahwa Anda dapat menghancurkannya dan menjual pecahan kristal dengan harga yang mahal.",
  str_homestory_811101001_23_dialog_content = "B-benarkah?",
  str_homestory_811101001_24_dialog_content = "Tidak, tidak juga.",
  str_homestory_811101001_25_dialog_content = "Wow! Saya melihat Anda telah belajar bagaimana membuat lelucon!",
  str_homestory_811101001_26_dialog_content = "Mungkin aku berubah setelah datang ke sini. Lagi pula, ini adalah tempat yang sangat santai.",
  str_homestory_811101001_27_dialog_content = "Apalagi saat saya memandangi ikan-ikan di sungai.",
  str_homestory_811101001_28_dialog_content = "Jika ingin melihat ikan, kenapa tidak ke Fountain of Hope saja?",
  str_homestory_811101001_29_dialog_content = "Seharusnya ada banyak di sana, dan beberapa juga sangat cantik.",
  str_homestory_811101001_30_dialog_content = "Di sini... Aku hanya bisa melihat yang sangat kecil.",
  str_homestory_811101001_31_dialog_content = "Mereka adalah orang-orang yang saya telah melihat.",
  str_homestory_811101001_32_dialog_content = "Terutama cara mereka menjelajahi ganggang, atau cara mereka beristirahat di bebatuan.",
  str_homestory_811101001_33_dialog_content = "Sangat santai bagaimana mereka berbaur dengan lingkungan.",
  str_homestory_811101001_34_dialog_content = "Perhatian Anda terhadap detail benar-benar sesuatu ...",
  str_homestory_811101001_35_dialog_content = "Aku tidak percaya matamu bisa mengikuti mereka saat mereka melesat menembus air.",
  str_homestory_811101001_36_dialog_content = "Mereka tidak berenang sepanjang waktu. Bahkan, mereka menghabiskan banyak waktu untuk beristirahat di dasar sungai.",
  str_homestory_811101001_37_dialog_content = "Beberapa bahkan masuk ke celah di antara bebatuan dan hanya menjulurkan kepala.",
  str_homestory_811101001_38_dialog_content = "Beberapa mengikuti ganggang ketika mereka bergoyang di air. Rasanya begitu... membebaskan.",
  str_homestory_811101001_39_dialog_content = "Saya mengerti. Anda tidak melihat ikan, Beryl. Anda benar-benar melihat bagaimana mereka hidup.",
  str_homestory_811101001_40_dialog_content = "Bagaimana mereka hidup?",
  str_homestory_811101001_41_dialog_content = "Bagaimana mereka tidak terikat oleh apa pun dan menjalani kehidupan tanpa beban.",
  str_homestory_811101001_42_dialog_content = "Ya, saya tidak pernah merasakan ini di tempat lain.",
  str_homestory_811101001_43_dialog_content = "Itu baru terpikir olehku setelah aku tiba di Cloud Gardens dan melihat mereka di sungai.",
  str_homestory_811101001_44_dialog_content = "Apakah ini karena pesona tempat ini?",
  str_homestory_811101001_45_dialog_content = "Bukan pesonanya, tapi caranya membuat Anda rileks.",
  str_homestory_811101001_46_dialog_content = "Ya, santai <sprite=emo_pugongying size=60 />...",
  str_homestory_816501001_0_dialog_content = "Ciel...",
  str_homestory_816501001_1_dialog_content = "Hei! Punya pekerjaan untuk saya?",
  str_homestory_816501001_2_option_content = "Ya.",
  str_homestory_816501001_3_dialog_content = "Apakah mereka? Bagaimana bayarannya?",
  str_homestory_816501001_4_dialog_content = "Saya tidak yakin apakah mereka tepat untuk Anda... Mereka sedang membangun tugas dekorasi...",
  str_homestory_816501001_5_dialog_content = "Yang akan membuang-buang bakat Anda.",
  str_homestory_816501001_6_option_content = "Tidak.",
  str_homestory_816501001_7_dialog_content = "Anda benar-benar tidak punya apa-apa?",
  str_homestory_816501001_8_dialog_content = "Cloud Gardens tidak memiliki banyak pekerjaan untuk memulai, dan keluarga Chubb melakukan sebagian besar dari mereka.",
  str_homestory_816501001_9_dialog_content = "Ada yang dalam skala yang lebih besar? Seperti membuat terowongan atau menggali melalui pegunungan.",
  str_homestory_816501001_10_dialog_content = "Mecha saya dibuat untuk hal-hal itu, Anda tahu. <sprite=emo_dianzan size=60 />",
  str_homestory_816501001_11_dialog_content = "Jangan berpikir aku punya apa-apa sekarang. Omong-omong, mengapa Anda tiba-tiba mencari pekerjaan? Tidakkah Anda ingin menikmati istirahat Anda sepenuhnya?",
  str_homestory_816501001_12_dialog_content = "Saya tidak bisa istirahat karena saya butuh uang.",
  str_homestory_816501001_13_dialog_content = "Uang? Saya mendengar Illumina menjatahnya. Apakah ada sesuatu yang ingin Anda beli?",
  str_homestory_816501001_14_dialog_content = "Saya... Saya ingin kalkulator mekanik. Saya pernah melihatnya di Lab Penelitian.",
  str_homestory_816501001_15_dialog_content = "Mengapa Anda tidak membangun satu? Anda punya waktu untuk sementara Anda di sini.",
  str_homestory_816501001_16_dialog_content = "Tidak, karena mereka memiliki banyak suku cadang non-standar, dan itu terlalu rumit.",
  str_homestory_816501001_17_dialog_content = "Akan memakan waktu lama jika saya harus membuat bagian-bagiannya sendiri.",
  str_homestory_816501001_18_dialog_content = "Dan itu akan menghabiskan banyak uang untuk membuatnya.",
  str_homestory_816501001_19_dialog_content = "Tapi saya sangat menginginkannya, jadi saya mencari pekerjaan sampingan yang bisa saya lakukan.",
  str_homestory_816501001_20_dialog_content = "Omong-omong, apa yang tiba-tiba mendorong Anda untuk ingin mendapatkannya?",
  str_homestory_816501001_21_dialog_content = "Karena menurut saya ada yang salah dengan cetak birunya. Ada satu tempat di mana perhitungannya tidak cocok, bahkan setelah beberapa kali mencoba.",
  str_homestory_816501001_22_dialog_content = "Perhitungannya sangat rumit dan saya telah melakukan yang terbaik, tetapi mesin tidak akan pernah salah.",
  str_homestory_816501001_23_dialog_content = "Jadi Anda ingin memverifikasi nomornya.",
  str_homestory_816501001_24_dialog_content = "Ya! Saya baru-baru ini membangun mekanisme dinamis sesuai dengan cetak biru ini ...",
  str_homestory_816501001_25_dialog_content = "Namun karena sebuah kesalahan, mecha tersebut mogok dan hampir membuat blueprintnya hangus.",
  str_homestory_816501001_26_dialog_content = "Aku menyelamatkannya dari gedung yang terbakar, tapi...",
  str_homestory_816501001_27_dialog_content = "Ini tidak berfungsi, dan saya pikir itu karena saya mungkin kehilangan bagian dari cetak biru. <sprite=emo_daomei size=60 />",
  str_homestory_816501001_28_dialog_content = "Beberapa bagian dari mekanisme dinamis yang dibangun sesuai dengan rencana saat ini tidak berfungsi sebagaimana mestinya.",
  str_homestory_816501001_29_dialog_content = "Logikanya, jika cetak biru kehilangan bagian, Anda seharusnya tidak dapat membangun mecha sama sekali, bukan?",
  str_homestory_816501001_30_dialog_content = "Secara umum, ya.",
  str_homestory_816501001_31_dialog_content = "Jadi mungkinkah itu masalah perspektif?",
  str_homestory_816501001_32_dialog_content = "Misalnya, saya pikir salah satu koneksi di Colossus tidak beres, tapi saya tidak bisa memperbaikinya bahkan setelah mencoba untuk waktu yang lama.",
  str_homestory_816501001_33_dialog_content = "Kemudian seekor kunang-kunang datang dan langsung melihat masalahnya.",
  str_homestory_816501001_34_dialog_content = "Perspektif...",
  str_homestory_816501001_35_dialog_content = "Saya mendapatkannya! Ini seperti <sprite=emo_baiyebi size=60 /> koin!",
  str_homestory_816501001_36_dialog_content = "koin apa?",
  str_homestory_816501001_37_dialog_content = "Saya melihat koin di tepi sungai kemarin. Yah, itu bisa saja tutup botol atau hanya sepotong logam.",
  str_homestory_816501001_38_dialog_content = "Lagipula, itu tidak penting. Yang penting adalah itu memantul di sungai dengan sendirinya!",
  str_homestory_816501001_39_dialog_content = "Kalau dipikir-pikir, permukaannya tenang, tapi mungkin ada arus air di bawahnya...",
  str_homestory_816501001_40_dialog_content = "Aku mengerti. Mungkin rumusnya hanya menyarankan arah yang harus diambil oleh desain.",
  str_homestory_816501001_41_dialog_content = "Tunggu, kamu bilang kamu melihat koin di tepi sungai?",
  str_homestory_816501001_42_dialog_content = "Hm? Benar, ya. Bagaimanapun, saya akan mendesain mecha lagi. Sampai jumpa!",
  str_homestory_816501001_43_dialog_content = "Baiklah…",
  str_homestory_810001001_0_dialog_content = "Kau punya usul apa?",
  str_homestory_810001001_1_dialog_content = "Sikare?",
  str_homestory_810001001_2_dialog_content = "Oh, hai Bola Salju. Hanya siapa yang saya cari.",
  str_homestory_810001001_3_dialog_content = "Ada apa?",
  str_homestory_810001001_4_dialog_content = "Apa pendapat Anda tentang Taman Awan?",
  str_homestory_810001001_5_dialog_content = "Hah? Itu garis saya. Sekarang kau bertanya padaku, aku butuh waktu...",
  str_homestory_810001001_6_option_content = "Sebuah rumah.",
  str_homestory_810001001_7_dialog_content = "Ini, tentu saja, rumahku.",
  str_homestory_810001001_8_option_content = "Tempat untuk beristirahat.",
  str_homestory_810001001_9_dialog_content = "Tempat yang bagus untuk istirahat.",
  str_homestory_810001001_10_dialog_content = "Oh, begitu…",
  str_homestory_810001001_11_dialog_content = "Tidakkah menurutmu itu seperti penjara juga?",
  str_homestory_810001001_12_dialog_content = "Seperti Starry Crypt yang aku jaga.",
  str_homestory_810001001_13_dialog_content = "Aku tidak mengikutimu.",
  str_homestory_810001001_14_dialog_content = "Ini terlalu nyaman di sini. Sangat nyaman sehingga membuat Anda tidak ingin memikirkan hal lain.",
  str_homestory_810001001_15_dialog_content = "Saya merasa seperti orang lain telah mengatakan ini kepada saya juga.",
  str_homestory_810001001_16_dialog_content = "Ini semacam kenyamanan yang terkait dengan Astra mengatakan bahwa semua orang tahu:",
  str_homestory_810001001_17_dialog_content = "Bilah yang paling mengancam adalah tempat tidur yang nyaman, di mana banyak pahlawan telah memudar.",
  str_homestory_810001001_18_dialog_content = "Orang-orang melupakan tugasnya ketika mereka merasa nyaman, terutama orang bodoh yang hanya melihat apa yang ada di depan mereka <sprite=emo_wuyu size=60 />.",
  str_homestory_810001001_19_dialog_content = "Apa yang membuatmu memikirkan hal ini?",
  str_homestory_810001001_20_dialog_content = "Saya berada di tepi sungai kemarin, dan melihat beberapa rumput liar mengambang di air.",
  str_homestory_810001001_21_dialog_content = "Dan mungkin ada sepotong logam yang memantul di permukaan air dengan rumput liar.",
  str_homestory_810001001_22_dialog_content = "Saya pikir saya mengerti maksud Anda sekarang.",
  str_homestory_810001001_23_dialog_content = "Jika Anda dapat memikirkan analogi seperti ini, maka sangat jelas bahwa Anda bukanlah bagian dari logam itu.",
  str_homestory_810001001_24_dialog_content = "Lagi pula, kita mengendalikan tindakan apa yang kita ambil secara individu, bukan?",
  str_homestory_810001001_25_dialog_content = "Aku tahu aku tidak salah tentangmu, Snowball. Anda berbeda dari orang-orang bodoh lainnya.",
  str_homestory_816601001_0_dialog_content = "Lumayan juga...",
  str_homestory_816601001_1_dialog_content = "Sepertinya kamu sedang dalam suasana hati yang baik hari ini.",
  str_homestory_816601001_2_dialog_content = "Saya kira Anda akhirnya menetap di sini?",
  str_homestory_816601001_3_dialog_content = "Jangan mencoba menebak apa yang dipikirkan ahli ekstrozoologi!",
  str_homestory_816601001_4_dialog_content = "Aku bahkan belum mengatakan apa-apa... <sprite=emo_shengqi size=60 />",
  str_homestory_816601001_5_dialog_content = "Tetapi tindakan Anda telah menunjukkan bahwa Anda dalam suasana hati yang baik.",
  str_homestory_816601001_6_dialog_content = "Hah?",
  str_homestory_816601001_7_dialog_content = "Kurasa tidak.",
  str_homestory_816601001_8_dialog_content = "Baiklah. Saya kebetulan punya beberapa pertanyaan untuk Anda.",
  str_homestory_816601001_9_dialog_content = "Pertanyaan?",
  str_homestory_816601001_10_dialog_content = "Tanyakan, dan saya akan melihat apakah saya bisa menjawab.",
  str_homestory_816601001_11_dialog_content = "Apa yang dilakukan anjing? <sprite=emo_goutou size=60 /> lakukan saat mereka bahagia?",
  str_homestory_816601001_12_dialog_content = "Anda bahkan tidak tahu itu?",
  str_homestory_816601001_13_dialog_content = "Ketika mereka bahagia, yang sangat sering, mereka mengibaskan ekornya. Sudah jelas juga.",
  str_homestory_816601001_14_dialog_content = "Bagaimana dengan kucing? <sprite=emo_baimao size=60 />?",
  str_homestory_816601001_15_dialog_content = "Itu juga mudah.",
  str_homestory_816601001_16_dialog_content = "Mereka sangat berhati-hati, tetapi jika Anda bisa membuat mereka bahagia...",
  str_homestory_816601001_17_dialog_content = "Mereka akan mendekati Anda dan mulai mendengkur.",
  str_homestory_816601001_18_dialog_content = "Bagaimana dengan binatang yang menakjubkan seperti Kyllo?",
  str_homestory_816601001_19_dialog_content = "Sebenarnya sangat jelas ketika Kyllo bahagia.",
  str_homestory_816601001_20_dialog_content = "Aku bisa tahu bagaimana perasaan Kyllo dengan mata tertutup, sebenarnya!",
  str_homestory_816601001_21_dialog_content = "Nah, binatang yang menakjubkan atau tidak...",
  str_homestory_816601001_22_dialog_content = "Saya kira hewan menunjukkannya saat mereka bahagia.",
  str_homestory_816601001_23_dialog_content = "... Mengapa saya merasa bahwa Anda memiliki niat lain dengan pertanyaan-pertanyaan ini?",
  str_homestory_816601001_24_dialog_content = "Sama sekali tidak!",
  str_homestory_816601001_25_dialog_content = "Saya hanya ingin melihat apakah pengamatan saya terhadap Anda benar.",
  str_homestory_816601001_26_dialog_content = "Dari saya?",
  str_homestory_816601001_27_dialog_content = "Saya seorang ahli ekstrozoologi, dan biasanya saya yang mengamati...",
  str_homestory_816601001_28_dialog_content = "Jadi mengapa Anda mengamati saya?",
  str_homestory_816601001_29_dialog_content = "Mungkin saja...",
  str_homestory_816601001_30_option_content = "Karena penasaran.",
  str_homestory_816601001_31_dialog_content = "Anda menunjukkan lebih banyak emosi daripada saya, jadi saya sangat tertarik.",
  str_homestory_816601001_32_option_content = "Boredom",
  str_homestory_816601001_33_dialog_content = "Anda anak yang sangat menarik, jadi saya merasa ingin mengamati perilaku Anda.",
  str_homestory_816601001_34_dialog_content = "Dan berdasarkan apa yang saya lihat...",
  str_homestory_816601001_35_dialog_content = "Telinga kelinci Anda menjadi ceria saat Anda bahagia.",
  str_homestory_816601001_36_dialog_content = "Ahhhh! <sprite=emo_hanshui size=60 /> T-Tidak, tolong jangan lihat telingaku...",
  str_homestory_816601001_37_dialog_content = "...",
  str_homestory_816601001_38_dialog_content = "Tunggu!",
  str_homestory_816601001_39_dialog_content = "Telingaku selalu berdiri!",
  str_homestory_816601001_40_dialog_content = "Dengan menutupinya barusan, Anda telah mengakui bahwa Anda sedang dalam suasana hati yang baik.",
  str_homestory_816601001_41_dialog_content = "Jadi Anda menipu saya, PlayerName!",
  str_homestory_816601001_42_dialog_content = "Maaf.",
  str_homestory_816601001_43_dialog_content = "Untuk menunjukkan bahwa saya minta maaf, saya akan pergi ke slide dengan Anda.",
  str_homestory_816601001_44_dialog_content = "Boleh juga.",
  str_homestory_816701001_0_dialog_content = "Apa kau sudah tidur?",
  str_homestory_816701001_1_dialog_content = "Sebuah pertanyaan yang bagus.",
  str_homestory_816701001_2_dialog_content = "Jika angin adalah cara dunia bernafas...",
  str_homestory_816701001_3_dialog_content = "Maka dunia mungkin melayang menuju alam mimpi sekarang <sprite=emo_kun size=60 />.",
  str_homestory_816701001_4_dialog_content = "Ah, jadi kau sudah bangun.",
  str_homestory_816701001_5_dialog_content = "Saya pikir Anda tertidur di kursi santai.",
  str_homestory_816701001_6_dialog_content = "Lautan seperti tiran yang tidak pernah bangun.",
  str_homestory_816701001_7_dialog_content = "Jika Anda senang merasakan hembusan, seperti bilah, menyapu wajah Anda di lautan ...",
  str_homestory_816701001_8_dialog_content = "Jeno?",
  str_homestory_816701001_9_dialog_content = "Ya, pencari ramalan?",
  str_homestory_816701001_10_dialog_content = "Saya tidak yakin saya mengerti apa yang baru saja Anda katakan.",
  str_homestory_816701001_11_dialog_content = "Sebenarnya, saya tahu saya tidak mengerti sama sekali.",
  str_homestory_816701001_12_dialog_content = "Kata-kata bukan lagi milik tenggorokan yang membentuknya begitu keluar dari mulut.",
  str_homestory_816701001_13_dialog_content = "Dan kemudian mereka ditafsirkan oleh otak yang menerimanya segera setelah mereka memasuki telinga orang lain.",
  str_homestory_816701001_14_dialog_content = "Dunia ini adalah festival fantasi yang sangat besar.",
  str_homestory_816701001_15_dialog_content = "Setidaknya itu yang selalu aku pikirkan.",
  str_homestory_816701001_16_option_content = "(Tidak mengerti sama sekali)",
  str_homestory_816701001_17_dialog_content = "Itu dalam. Saya benar-benar tidak tahu apa yang Anda bicarakan.",
  str_homestory_816701001_18_option_content = "(Dipahami)",
  str_homestory_816701001_19_dialog_content = "Anda berpikir bahwa orang tidak akan pernah benar-benar memahami satu sama lain.",
  str_homestory_816701001_20_dialog_content = "Pendengarku tersayang.",
  str_homestory_816701001_21_dialog_content = "Tidak masalah, karena kita hanya perlu menikmati.",
  str_homestory_816701001_22_dialog_content = "Ahem. Aku entah bagaimana berpikir...",
  str_homestory_816701001_23_dialog_content = "Bahwa kadang-kadang Anda bahkan tidak tahu apa yang Anda bicarakan.",
  str_homestory_816701001_24_dialog_content = "Mungkin terkadang saya tidak memiliki kata-kata yang tepat.",
  str_homestory_816701001_25_dialog_content = "Tapi sihirku tidak akan pernah mengecewakan siapa pun <sprite=emo_mojing size=60 />.",
  str_homestory_816701001_26_dialog_content = "Itu benar.",
  str_homestory_816701001_27_dialog_content = "Hm? Tunggu!",
  str_homestory_816701001_28_dialog_content = "Anda tidak menciptakan ilusi untuk membodohi saya, bukan?",
  str_homestory_816701001_29_dialog_content = "Faktanya, Anda telah tidur di kursi santai sepanjang waktu!",
  str_homestory_816701001_30_dialog_content = "Ah, apakah kamu menangkapku?",
  str_homestory_816701001_31_dialog_content = "Sudah kuduga!",
  str_homestory_816701001_32_dialog_content = "Tunggu, aku belum selesai.",
  str_homestory_816701001_33_dialog_content = "Anda benar tentang satu hal: ada seseorang yang tidur di kursi santai.",
  str_homestory_816701001_34_dialog_content = "Namun…",
  str_homestory_816701001_35_dialog_content = "Bagaimana Anda tahu itu bukan ... Anda?",
  str_homestory_816701001_36_dialog_content = "Ini tidak mungkin!",
  str_homestory_816701001_37_dialog_content = "Karena aku melihatmu tidur di atasnya dari jauh!",
  str_homestory_816701001_38_dialog_content = "Apakah Anda ingat apa yang terjadi sebelum itu?",
  str_homestory_816701001_39_dialog_content = "aku...",
  str_homestory_816701001_40_dialog_content = "Tunggu, apa yang aku lakukan?",
  str_homestory_816701001_41_dialog_content = "Hahaha.",
  str_homestory_816701001_42_dialog_content = "Apakah Anda menghipnotis saya tanpa saya sadari?",
  str_homestory_816701001_43_dialog_content = "Tolong bangunkan aku... <sprite=emo_tanqi size=60 />",
  str_homestory_816701001_44_dialog_content = "Itu mudah. Tidur siang saja di kursi santai.",
  str_homestory_816701001_45_dialog_content = "Baiklah…",
  str_homestory_816801001_0_dialog_content = "Sedang apa kau?",
  str_homestory_816801001_1_dialog_content = "Ini kamu, PlayerName.",
  str_homestory_816801001_2_dialog_content = "Tempat ini terlihat sangat keren! Apalagi yang di sana...",
  str_homestory_816801001_3_dialog_content = "Ini memainkan musik saat Anda menyentuhnya <sprite=emo_yinfu size=60 />!",
  str_homestory_816801001_4_dialog_content = "Oh ya? Saya senang mendengarnya.",
  str_homestory_816801001_5_dialog_content = "Saya pikir itu mungkin memakan terlalu banyak ruang ...",
  str_homestory_816801001_6_dialog_content = "Dan tidak ada yang akan menyukainya.",
  str_homestory_816801001_7_dialog_content = "Aku suka ini!",
  str_homestory_816801001_8_dialog_content = "Tidak, aku menyukainya!",
  str_homestory_816801001_9_dialog_content = "Maukah Anda menunjukkan kepada saya bagaimana menggunakannya?",
  str_homestory_816801001_10_dialog_content = "Aku juga tidak terlalu mengenalnya.",
  str_homestory_816801001_11_dialog_content = "Ada manualnya atau gimana?",
  str_homestory_816801001_12_dialog_content = "Tidak juga…",
  str_homestory_816801001_13_dialog_content = "Jadi kita hanya harus mencari tahu sendiri?",
  str_homestory_816801001_14_dialog_content = "Namun, rasanya lebih menyenangkan seperti itu.",
  str_homestory_816801001_15_dialog_content = "Aku tidak tahu kau begitu menyukai musik.",
  str_homestory_816801001_16_dialog_content = "Saya suka hal-hal yang indah. Dan...",
  str_homestory_816801001_17_dialog_content = "Jika saya dapat mempelajari cara menggunakannya, maka terapkan dalam penampilan saya...",
  str_homestory_816801001_18_dialog_content = "Itu akan membuat aksi pembuka kami lebih menyenangkan!",
  str_homestory_816801001_19_dialog_content = "Anda selalu berpikir tentang sirkus.",
  str_homestory_816801001_20_dialog_content = "Anda harus benar-benar mencintai apa yang Anda lakukan.",
  str_homestory_816801001_21_dialog_content = "Sejujurnya, saya tidak pernah benar-benar memikirkannya <sprite=emo_wuzui size=60 />.",
  str_homestory_816801001_22_dialog_content = "Saya selalu percaya bahwa saya dilahirkan untuk melindungi Zamrud.",
  str_homestory_816801001_23_dialog_content = "Saya melakukannya dengan memperbaiki dan merawatnya saat merapat...",
  str_homestory_816801001_24_dialog_content = "Dan menembak siapa pun di dalamnya dengan niat jahat dengan Aqua Blaster saya.",
  str_homestory_816801001_25_dialog_content = "Tampil bersama sirkus agar lebih banyak yang tahu tentang Zamrud...",
  str_homestory_816801001_26_dialog_content = "adalah cara lain untuk melindunginya.",
  str_homestory_816801001_27_dialog_content = "Jadi, begitu, ya…",
  str_homestory_816801001_28_dialog_content = "Perlindungan datang dalam berbagai bentuk dan bentuk.",
  str_homestory_816801001_29_dialog_content = "Misalnya, Anda melakukan pekerjaan yang hebat dalam melindungi Cloud Gardens.",
  str_homestory_816801001_30_dialog_content = "Tapi Anda mungkin ingin segera membersihkan dasar sungai.",
  str_homestory_816801001_31_dialog_content = "Saat aku mengisi blaster dengan air tadi...",
  str_homestory_816801001_32_dialog_content = "Saya menemukan sesuatu yang berkilau di dasar sungai.",
  str_homestory_816801001_33_dialog_content = "Sesuatu yang mengkilap...?",
  str_homestory_816801001_34_dialog_content = "Berbicara tentang sungai, Anda ingin menenangkan diri?",
  str_homestory_816801001_35_option_content = "Mau sekali!",
  str_homestory_816801001_36_dialog_content = "Saya sedang bekerja, dan itu benar-benar panas.",
  str_homestory_816801001_37_dialog_content = "Itu mudah.",
  str_homestory_816801001_38_dialog_content = "Rasakan ini!",
  str_homestory_816801001_39_dialog_content = "Apa?!",
  str_homestory_816801001_40_option_content = "Tidak juga...",
  str_homestory_816801001_41_dialog_content = "Anda tidak akan meledakkan saya dengan pistol air, kan?",
  str_homestory_816801001_42_dialog_content = "Ada yang lain?",
  str_homestory_816801001_43_dialog_content = "Aku baik-baik saja, sungguh.",
  str_homestory_816801001_44_dialog_content = "Saya hanya akan berada di tepi sungai <sprite=emo_pugongying size=60 />!",
  str_homestory_801602001_0_dialog_content = "Kafka?",
  str_homestory_801602001_1_dialog_content = "Ah!",
  str_homestory_801602001_2_dialog_content = "Kamu menakuti saya, PlayerName.",
  str_homestory_801602001_3_dialog_content = "Maaf tentang itu.",
  str_homestory_801602001_4_dialog_content = "Ada apa?",
  str_homestory_801602001_5_option_content = "Hmm…",
  str_homestory_801602001_6_dialog_content = "Saya baru menyadari bahwa Anda telah berdiri di sini untuk sementara waktu.",
  str_homestory_801602001_7_dialog_content = "Dan aku takut kau akan terkena serangan panas.",
  str_homestory_801602001_8_dialog_content = "Jangan khawatir, aku hanya menjaga sesuatu.",
  str_homestory_801602001_9_option_content = "Aku baik-baik saja.",
  str_homestory_801602001_10_dialog_content = "Saya baru menyadari bahwa Anda telah berdiri di sini untuk sementara waktu.",
  str_homestory_801602001_11_dialog_content = "Jadi saya ingin tahu apa yang Anda lakukan.",
  str_homestory_801602001_12_dialog_content = "Jelas, aku menjaga sesuatu.",
  str_homestory_801602001_13_dialog_content = "Menjaga sesuatu?",
  str_homestory_801602001_14_dialog_content = "Terima kasih, tapi Cloud Gardens sangat aman...",
  str_homestory_801602001_15_dialog_content = "Anda tidak perlu begitu khawatir.",
  str_homestory_801602001_16_dialog_content = "Saya tidak melakukan ini untuk Cloud Gardens. Ini untuk...",
  str_homestory_801602001_17_dialog_content = "Sekelompok kelinci.",
  str_homestory_801602001_18_dialog_content = "Kelinci? Dimana mereka?",
  str_homestory_801602001_19_dialog_content = "Mereka kembali ke liang mereka",
  str_homestory_801602001_20_dialog_content = "Jangan khawatir, Anda tidak akan pernah menemukannya.",
  str_homestory_801602001_21_dialog_content = "aku bukan musuh mereka...",
  str_homestory_801602001_22_dialog_content = "Anda benar-benar menyukai makhluk, bukan?",
  str_homestory_801602001_23_dialog_content = "D-Apakah saya?",
  str_homestory_801602001_24_dialog_content = "Saya hanya tidak ingin mereka pergi ke tempat yang tidak seharusnya.",
  str_homestory_801602001_25_dialog_content = "Kau hampir seperti... gembala.",
  str_homestory_801602001_26_dialog_content = "Dengan anjing besarmu <sprite=emo_goutou size=60 />, mengantar hewan ke tempat yang aman...",
  str_homestory_801602001_27_dialog_content = "Gembala? Tidak, pasti tidak.",
  str_homestory_801602001_28_dialog_content = "Ngomong-ngomong, aku melihat sesuatu yang berkilau di dasar sungai.",
  str_homestory_801602001_29_dialog_content = "Apakah Anda akan mencari tahu apa itu?",
  str_homestory_801602001_30_dialog_content = "Jangan biarkan itu menakut-nakuti makhluk di daerah tersebut.",
  str_homestory_801602001_31_dialog_content = "Oke!",
  str_homestory_817001001_0_dialog_content = "Sungguh kesempatan yang langka...",
  str_homestory_817001001_1_dialog_content = "Siapa di sana?!",
  str_homestory_817001001_2_dialog_content = "Ini aku, PlayerName...",
  str_homestory_817001001_3_dialog_content = "Maaf, saya menjadi gelisah ketika mendengar langkah kaki berhenti tiba-tiba.",
  str_homestory_817001001_4_dialog_content = "Tenang, di Cloud Gardens sangat aman.",
  str_homestory_817001001_5_dialog_content = "Ya, saya pernah mendengarnya beberapa waktu lalu",
  str_homestory_817001001_6_dialog_content = "bahwa Caelestite yang muncul entah dari mana membangun tempat persembunyian yang indah di Eraveil.",
  str_homestory_817001001_7_dialog_content = "Saya tidak akan percaya jika saya tidak melihatnya sendiri.",
  str_homestory_817001001_8_dialog_content = "Saya tidak mengharapkan keterampilan manajemen seperti itu dari seseorang semuda Anda.",
  str_homestory_817001001_9_option_content = "Mengakui",
  str_homestory_817001001_10_dialog_content = "Terima kasih atas pujianmu.",
  str_homestory_817001001_11_dialog_content = "Tidak rendah hati, saya mengerti.",
  str_homestory_817001001_12_dialog_content = "Tetap saja, aku suka keberanian dalam dirimu.",
  str_homestory_817001001_13_option_content = "Bantah",
  str_homestory_817001001_14_dialog_content = "Sebenarnya, teman-teman saya banyak membantu saya.",
  str_homestory_817001001_15_dialog_content = "Benarkah?",
  str_homestory_817001001_16_dialog_content = "Jarang melihat anak muda dengan kerendahan hati seperti itu.",
  str_homestory_817001001_17_dialog_content = "Tak heran jika Cloud Gardens mampu menjaga ketenangan dan kedamaiannya.",
  str_homestory_817001001_18_dialog_content = "Tidak ada pelecehan dari Eclipsites, tidak ada perang geng.",
  str_homestory_817001001_19_dialog_content = "Ketika saya memikirkannya, saya belum memiliki kesempatan untuk menikmati hangatnya sinar matahari di kulit saya",
  str_homestory_817001001_20_dialog_content = "dalam apa yang terasa seperti seumur hidup.",
  str_homestory_817001001_21_dialog_content = "Itu sebabnya Anda harus mencoba untuk bersantai.",
  str_homestory_817001001_22_dialog_content = "Bersantai?",
  str_homestory_817001001_23_dialog_content = "Kau tahu, aku baru menyadarinya sekarang",
  str_homestory_817001001_24_dialog_content = "tetap waspada telah menjadi kebiasaan bagi saya.",
  str_homestory_817001001_25_dialog_content = "Meskipun aku telah meninggalkan Euphoria...",
  str_homestory_817001001_26_dialog_content = "kebiasaan lama saya tetap bersama saya.",
  str_homestory_817001001_27_dialog_content = "Apakah menatap ke bawah pada semua orang di dekatnya dari sudut pandang...",
  str_homestory_817001001_28_dialog_content = "kebiasaan yang Anda simpan dari waktu Anda di Euphoria juga?",
  str_homestory_817001001_29_dialog_content = "Begitu, mengawasi tamu Anda harus menjadi salah satu tugas Anda sebagai pemimpin tempat ini.",
  str_homestory_817001001_30_dialog_content = "Kurasa aku tidak bisa meremehkanmu sama sekali.",
  str_homestory_817001001_31_dialog_content = "Tidak, bukan itu yang saya maksud.",
  str_homestory_817001001_32_dialog_content = "Aku kebetulan melihatmu di menara pengawas.",
  str_homestory_817001001_33_dialog_content = "Tenang, saya tidak mencoba untuk memulai apa pun.",
  str_homestory_817001001_34_dialog_content = "Dulu saya senang berdiri tegak, menyaksikan semua kejadian Euforia terbentang di depan saya.",
  str_homestory_817001001_35_dialog_content = "Biasanya, Anda akan melihat ...",
  str_homestory_817001001_36_dialog_content = "segudang keserakahan dan keinginan terakumulasi di bawah awan hujan lebat.",
  str_homestory_817001001_37_dialog_content = "Tapi bukan disini.",
  str_homestory_817001001_38_dialog_content = "Itu tenang sejauh mata saya bisa melihat.",
  str_homestory_817001001_39_dialog_content = "Aku punya permintaan, PlayerName.",
  str_homestory_817001001_40_dialog_content = "Beri tahu saya apa yang Anda butuhkan.",
  str_homestory_817001001_41_dialog_content = "Bisakah saya membawa anak-anak dari gereja bersama saya lain kali?",
  str_homestory_817001001_42_dialog_content = "Tentu!",
  str_homestory_817001001_43_dialog_content = "Oh, dan satu hal lagi...",
  str_homestory_817001001_44_dialog_content = "Saya melihat sesuatu di tepi sungai yang mungkin menarik bagi Anda.",
  str_homestory_817001001_45_dialog_content = "Seharusnya masih ada di sana jika Anda pergi sekarang.",
  str_homestory_817001001_46_dialog_content = "Betulkah? Aku akan melihatnya!",
  str_homestory_817101001_0_dialog_content = "Casta?",
  str_homestory_817101001_1_dialog_content = "Hei, itu kamu.",
  str_homestory_817101001_2_dialog_content = "Bagaimana Anda menetap di Cloud Gardens?",
  str_homestory_817101001_3_dialog_content = "Tidak baik.",
  str_homestory_817101001_4_dialog_content = "Oh? Apa yang tampaknya menjadi masalah?",
  str_homestory_817101001_5_dialog_content = "Saya akan memperbaikinya!",
  str_homestory_817101001_6_dialog_content = "Salah satunya, kabut di sini...",
  str_homestory_817101001_7_dialog_content = "sepertinya selalu menghilang.",
  str_homestory_817101001_8_dialog_content = "Sinar matahari yang tak henti-hentinya membuat mataku terasa kering.",
  str_homestory_817101001_9_dialog_content = "Dan tidak ada preman atau hooligan yang mencari masalah.",
  str_homestory_817101001_10_dialog_content = "Saya tidak mendapatkan latihan yang layak di tempat yang damai ini.",
  str_homestory_817101001_11_dialog_content = "Jika ini terus berlanjut, akurasi saya akan menurun<sprite=emo_daomei size=60 />.",
  str_homestory_817101001_12_option_content = "Minta maaflah",
  str_homestory_817101001_13_dialog_content = "Maaf tentang itu!",
  str_homestory_817101001_14_dialog_content = "Hidup pasti membosankan bagimu di sini.",
  str_homestory_817101001_15_option_content = "Mendesah pasrah",
  str_homestory_817101001_16_dialog_content = "Namun…",
  str_homestory_817101001_17_dialog_content = "Saya tidak bisa berbuat apa-apa tentang itu ...",
  str_homestory_817101001_18_dialog_content = "Tidak bisakah Anda mengatakan bahwa saya mencoba memuji Anda?",
  str_homestory_817101001_19_dialog_content = "Hah?",
  str_homestory_817101001_20_dialog_content = "Aku sudah sangat terbiasa dengan kehidupan di daerah kumuh...",
  str_homestory_817101001_21_dialog_content = "bahwa saya tidak tahu apa yang harus dilakukan di tempat yang sebenarnya aman dan nyaman.",
  str_homestory_817101001_22_dialog_content = "Yang agak lucu, jujur.",
  str_homestory_817101001_23_dialog_content = "Nah, sebenarnya ada banyak hal menarik yang bisa dilakukan di sini!",
  str_homestory_817101001_24_dialog_content = "Ya, saya telah menemukan bahwa akhir-akhir ini.",
  str_homestory_817101001_25_dialog_content = "Papan reklame ini menarik dengan bagaimana warna dan gambar bersatu...",
  str_homestory_817101001_26_dialog_content = "Pasti iklan kasino, kan?",
  str_homestory_817101001_27_dialog_content = "...",
  str_homestory_817101001_28_dialog_content = "Ada apa dengan ekspresimu<sprite=emo_baiyan size=60 />?",
  str_homestory_817101001_29_dialog_content = "Saya hanya ingin memenangkan beberapa suvenir untuk anak-anak gereja.",
  str_homestory_817101001_30_dialog_content = "Aku tidak akan merusak bank Anda atau apa pun.",
  str_homestory_817101001_31_dialog_content = "Uh, ini hanya untuk pertunjukan.",
  str_homestory_817101001_32_dialog_content = "Kami tidak memiliki kasino di sini...",
  str_homestory_817101001_33_dialog_content = "Apa?",
  str_homestory_817101001_34_dialog_content = "Bagaimana kalau memancing?",
  str_homestory_817101001_35_dialog_content = "Memancing?",
  str_homestory_817101001_36_dialog_content = "Anda tahu, melemparkan umpan dan menunggu ikan menggigit.",
  str_homestory_817101001_37_dialog_content = "Ini adalah ujian keberuntungan seseorang!",
  str_homestory_817101001_38_dialog_content = "Nah, setiap ujian keberuntungan adalah sesuatu yang tidak bisa saya lewatkan!",
  str_homestory_817101001_39_dialog_content = "Ah, hampir lupa...",
  str_homestory_817101001_40_dialog_content = "Anda diberkati oleh Lady Luck<sprite=emo_dianzan size=60 />!",
  str_homestory_817101001_41_dialog_content = "Saya melihat hari ini adalah hari yang buruk untuk ikan...",
  str_homestory_813001001_0_dialog_content = "Terlihat bagus, bukan?",
  str_homestory_813001001_1_dialog_content = "Hah?",
  str_homestory_813001001_2_dialog_content = "Ehem...",
  str_homestory_813001001_3_dialog_content = "Oh, ternyata kau.",
  str_homestory_813001001_4_dialog_content = "Jangan terlalu keras lain kali. Apakah Anda mencoba menakut-nakuti saya sampai mati?",
  str_homestory_813001001_5_dialog_content = "Jangan bilang aku tidak pernah memperingatkanmu!",
  str_homestory_813001001_6_dialog_content = "Jika Anda memberi seseorang serangan jantung ...",
  str_homestory_813001001_7_dialog_content = "Itu bisa menjadi hukuman seumur hidup!",
  str_homestory_813001001_8_dialog_content = "Terima kasih atas peringatannya...",
  str_homestory_813001001_9_dialog_content = "Sekarang setelah Anda tahu, apakah Anda membutuhkan saya untuk sesuatu?",
  str_homestory_813001001_10_dialog_content = "Apakah Cloud Gardens membutuhkan keterampilan menilai saya?",
  str_homestory_813001001_11_dialog_content = "Eh, tidak, tidak sama sekali.",
  str_homestory_813001001_12_dialog_content = "Aku melihatmu merenung dan memberi isyarat di depan patung ini...",
  str_homestory_813001001_13_dialog_content = "Jadi saya hanya penasaran.",
  str_homestory_813001001_14_dialog_content = "Memberi isyarat? Siapa yang memberi isyarat?",
  str_homestory_813001001_15_dialog_content = "Menyebarkan gosip bertentangan dengan hukum.",
  str_homestory_813001001_16_dialog_content = "Menurut Kode Reputasi Lumopolis, mereka yang memfitnah orang lain...",
  str_homestory_813001001_17_dialog_content = "akan dijatuhi hukuman 100 hari penjara atau denda satu juta Nightium.",
  str_homestory_813001001_18_dialog_content = "Apa?",
  str_homestory_813001001_19_option_content = "Menyangkal",
  str_homestory_813001001_20_dialog_content = "Tapi kita di Cloud Gardens, bukan Lumopolis!",
  str_homestory_813001001_21_dialog_content = "PP-Tidak masuk akal!",
  str_homestory_813001001_22_dialog_content = "Bagaimana Anda bisa mentolerir tidak memiliki hukum apa pun di Cloud Gardens?",
  str_homestory_813001001_23_option_content = "Mematuhi",
  str_homestory_813001001_24_dialog_content = "Saya kira saya salah saat itu ...",
  str_homestory_813001001_25_dialog_content = "Anda harus lebih berhati-hati, PlayerName.",
  str_homestory_813001001_26_dialog_content = "Atau Anda akan dikelilingi oleh kekotoran.",
  str_homestory_813001001_27_dialog_content = "Itu akan menjadi kejatuhan kekuasaan Anda!",
  str_homestory_813001001_28_dialog_content = "Oke…",
  str_homestory_813001001_29_dialog_content = "Eh, menurutmu...",
  str_homestory_813001001_30_dialog_content = "Bagaimana kalau Anda memberi saya patung itu?",
  str_homestory_813001001_31_dialog_content = "Dan kita akan melupakan semuanya.",
  str_homestory_813001001_32_dialog_content = "Eh? Tapi...",
  str_homestory_813001001_33_dialog_content = "Patung itu sangat penting bagi saya.",
  str_homestory_813001001_34_dialog_content = "Ini mewakili leluhur Caelestite tertentu.",
  str_homestory_813001001_35_dialog_content = "Tanah tanpa hukum benar-benar tidak bisa dipahami.",
  str_homestory_813001001_36_dialog_content = "Jika Anda benar-benar menyukai patung itu...",
  str_homestory_813001001_37_dialog_content = "Aku bisa membuat replika untukmu dari lumpur.",
  str_homestory_813001001_38_dialog_content = "Hmm…",
  str_homestory_813001001_39_dialog_content = "Itu adalah solusi<sprite=emo_woshou size=60 />.",
  str_homestory_813001001_40_dialog_content = "Hanya saja, jangan membuatku menunggu.",
  str_homestory_812101001_0_dialog_content = "Paloma?",
  str_homestory_812101001_1_dialog_content = "Oh, ternyata kau.",
  str_homestory_812101001_2_dialog_content = "Maaf...",
  str_homestory_812101001_3_dialog_content = "Apa aku membangunkanmu?",
  str_homestory_812101001_4_dialog_content = "Anda tahu lebih baik daripada berpura-pura bahwa Anda peduli ketika berbicara dengan saya.",
  str_homestory_812101001_5_dialog_content = "Ludahkan saja.",
  str_homestory_812101001_6_dialog_content = "Anda ingin tahu bagaimana saya menyukai Cloud Gardens sejauh ini, bukan?",
  str_homestory_812101001_7_option_content = "Bantah",
  str_homestory_812101001_8_dialog_content = "Tidak juga...",
  str_homestory_812101001_9_dialog_content = "Hanya ingin bilang halo.",
  str_homestory_812101001_10_option_content = "Akui",
  str_homestory_812101001_11_dialog_content = "Kau benar…",
  str_homestory_812101001_12_dialog_content = "Saya peduli dengan pendapat Anda.",
  str_homestory_812101001_13_dialog_content = "Apakah Anda mengakuinya atau tidak, saya akan mengatakan ini ...",
  str_homestory_812101001_14_dialog_content = "...",
  str_homestory_812101001_15_dialog_content = "Aku tidak membenci tempat itu.",
  str_homestory_812101001_16_dialog_content = "Baiklah!",
  str_homestory_812101001_17_dialog_content = "Saya pikir Anda akan memisahkannya ...",
  str_homestory_812101001_18_dialog_content = "Apa katamu?",
  str_homestory_812101001_19_dialog_content = "Ah, maksudku...",
  str_homestory_812101001_20_dialog_content = "Saya mengharapkan kritik yang membangun dari Anda!",
  str_homestory_812101001_21_dialog_content = "Bukannya aku tidak punya apa-apa untuk dikatakan.",
  str_homestory_812101001_22_dialog_content = "Tapi karena Anda ahli dalam pengembangan, konstruksi, dan manajemen...",
  str_homestory_812101001_23_dialog_content = "Apakah Anda tertarik untuk mengusir para bangsawan dari Lumopolis dan mengambil alih Azurite?",
  str_homestory_812101001_24_dialog_content = "Apa?!",
  str_homestory_812101001_25_dialog_content = "Aku bahkan tidak pernah mempertimbangkan hal seperti itu.",
  str_homestory_812101001_26_dialog_content = "Saya telah bertemu banyak orang yang mengatakan satu hal dan melakukan yang sebaliknya...",
  str_homestory_812101001_27_dialog_content = "Satu kali terlalu banyak.",
  str_homestory_812101001_28_dialog_content = "Aku... Aku hanya mencoba melindungi rumahku sendiri.",
  str_homestory_812101001_29_dialog_content = "Saya kira orang-orang di Lumopolis juga merasakan hal yang sama tentang rumah mereka.",
  str_homestory_812101001_30_dialog_content = "Rumah?",
  str_homestory_812101001_31_dialog_content = "Saya seseorang yang diusir dari rumah mereka.",
  str_homestory_812101001_32_dialog_content = "\"Rumah\" telah lama menjadi kata yang tidak berarti bagiku.",
  str_homestory_812101001_33_dialog_content = "Ingat Paloma, Anda masih punya Cloud Gardens.",
  str_homestory_812101001_34_dialog_content = "Jika Anda ingin...",
  str_homestory_812101001_35_dialog_content = "Anda dapat memperlakukan Cloud Gardens sebagai rumah Anda!",
  str_homestory_812101001_36_dialog_content = "Jadi Anda tidak berpikir orang lain akan mencoba dan mengambilnya dari Anda?",
  str_homestory_812101001_37_dialog_content = "Itu hanya sampai di tempat ini hari ini berkat semua teman saya.",
  str_homestory_812101001_38_dialog_content = "Itu sebabnya saya ingin Cloud Gardens menjadi tempat yang aman bagi semua orang.",
  str_homestory_812101001_39_dialog_content = "Oh, Caelestite, kamu benar-benar sangat naif.<sprite=emo_baiyan size=60 />",
  str_homestory_812101001_40_dialog_content = "Mungkin saja...",
  str_homestory_812101001_41_dialog_content = "Saya dapat menambahkan definisi \"rumah\" di kamus saya.",
  str_homestory_812101001_42_dialog_content = "Yang akan...",
  str_homestory_812101001_43_dialog_content = "Taman Awan.",
  str_homestory_812001001_0_dialog_content = "Itu kamu ya Hedi.",
  str_homestory_812001001_1_dialog_content = "Aduh...",
  str_homestory_812001001_2_dialog_content = "Ada apa, Hedi?",
  str_homestory_812001001_3_dialog_content = "Demi White Night…",
  str_homestory_812001001_4_dialog_content = "Mesin itu terus menggeram jahat padaku!",
  str_homestory_812001001_5_dialog_content = "Katakan padaku, apakah itu peninggalan jahat dari Era Lama, PlayerName?",
  str_homestory_812001001_6_dialog_content = "Jika ini terus...",
  str_homestory_812001001_7_dialog_content = "Aku harus memanggil Knight of Light untuk menghancurkannya<sprite=emo_shengqi size=60 />.",
  str_homestory_812001001_8_option_content = "Menghibur",
  str_homestory_812001001_9_dialog_content = "Jangan khawatir, Hedi.",
  str_homestory_812001001_10_dialog_content = "Itu hanya mesin es krim.",
  str_homestory_812001001_11_option_content = "Minta maaflah",
  str_homestory_812001001_12_dialog_content = "Maaf, aku lupa memberitahumu.",
  str_homestory_812001001_13_dialog_content = "Ini adalah mesin es krim!",
  str_homestory_812001001_14_dialog_content = "Sebuah... mesin es krim?<sprite=emo_wuzui size=60 />",
  str_homestory_812001001_15_dialog_content = "Ya. Taruh saja cangkir di atasnya dan tekan tombolnya.",
  str_homestory_812001001_16_dialog_content = "Kemudian mesin akan membuatkan Anda es krim yang enak.",
  str_homestory_812001001_17_dialog_content = "Sebenarnya, saya sudah menebak itu adalah mesin es krim dari kepingan salju di atasnya.",
  str_homestory_812001001_18_dialog_content = "Tapi tidak ada es krim yang keluar...",
  str_homestory_812001001_19_dialog_content = "Jadi saya pikir itu bisa menjadi ciptaan jahat yang menyamar sebagai mesin es krim.",
  str_homestory_812001001_20_dialog_content = "Es krimnya habis lagi?",
  str_homestory_812001001_21_dialog_content = "\"Lagi\"?",
  str_homestory_812001001_22_dialog_content = "Nah, es krim yang dibuatnya sangat enak. . .",
  str_homestory_812001001_23_dialog_content = "Jika Anda tidak sampai di sini cukup awal, Anda tidak akan mendapatkannya.",
  str_homestory_812001001_24_dialog_content = "Sudah jauh lebih dingin beberapa hari terakhir, saya pikir lebih sedikit orang yang akan menggunakannya.",
  str_homestory_812001001_25_dialog_content = "Tapi saya kira itu masih sangat populer.",
  str_homestory_812001001_26_dialog_content = "Rasa apa yang kamu suka, Hedy?",
  str_homestory_812001001_27_dialog_content = "Aku akan pergi mendapatkan bahan-bahan untuk itu.",
  str_homestory_812001001_28_dialog_content = "Rasa es krim favorit saya...",
  str_homestory_812001001_29_dialog_content = "Ya, apa yang kamu suka?",
  str_homestory_812001001_30_dialog_content = "Vanila, coklat, matcha, jeruk, kacang merah...",
  str_homestory_812001001_31_dialog_content = "Aku mencintai mereka semua!",
  str_homestory_812001001_32_dialog_content = "Begitu banyak rasa, saya melihat ...",
  str_homestory_812001001_33_dialog_content = "Apakah Anda belum pernah makan es krim sebelumnya? Ini semua rasa dasar...",
  str_homestory_812001001_34_dialog_content = "A-Apa maksudmu?",
  str_homestory_812001001_35_dialog_content = "Tentu saja aku pernah makan es krim!",
  str_homestory_812001001_36_dialog_content = "Saya hanya berpikir semua rasa yang Anda sebutkan terlalu sederhana.",
  str_homestory_812001001_37_dialog_content = "Saya hanya pernah makan es krim rasa \"buku tebal kuno\".",
  str_homestory_812001001_38_dialog_content = "Tapi saya rasa mesin tidak bisa membuatnya.<sprite=emo_emo size=60 />",
  str_homestory_812001001_39_dialog_content = "\"Buku tebal kuno\"-rasa?!",
  str_homestory_812001001_40_dialog_content = "Tidak bisa mengatakan saya pernah mengalaminya.",
  str_homestory_812001001_41_dialog_content = "Tapi saya akan mencoba mencari resepnya!",
  str_homestory_812001001_42_dialog_content = "Oh, tidak apa-apa...",
  str_homestory_812001001_43_dialog_content = "Kok bisa?",
  str_homestory_812001001_44_dialog_content = "Saya ingin mencari tahu bagaimana...",
  str_homestory_812001001_45_dialog_content = "rasa es krim vanilla, coklat, matcha, orange, dan kacang merah.",
  str_homestory_806801001_0_dialog_content = "Wendy?",
  str_homestory_806801001_1_dialog_content = "Kau sedang apa?",
  str_homestory_806801001_2_dialog_content = "Oh, rupanya kau, PlayerName.",
  str_homestory_806801001_3_dialog_content = "Saya mencari tempat untuk berlatih penerbangan vertikal.",
  str_homestory_806801001_4_dialog_content = "Penerbangan vertikal?",
  str_homestory_806801001_5_dialog_content = "Ya, terbang lurus ke atas dan lurus ke bawah.",
  str_homestory_806801001_6_dialog_content = "Ini adalah ujian akhir dari keterampilan terbang.",
  str_homestory_806801001_7_dialog_content = "Anda tahu, saya selalu takut bahwa Anda akan jatuh dari terbang begitu tinggi.",
  str_homestory_806801001_8_dialog_content = "Dengan serius?",
  str_homestory_806801001_9_dialog_content = "Tenang, itu sepotong kue untukku.",
  str_homestory_806801001_10_dialog_content = "Atau apakah Anda lupa bahwa saya adalah rudal badai gurun<sprite=emo_mojing size=60 />?",
  str_homestory_806801001_11_option_content = "lupa",
  str_homestory_806801001_12_dialog_content = "Maka saya akan ulangi!",
  str_homestory_806801001_13_option_content = "Tidak lupa",
  str_homestory_806801001_14_dialog_content = "Bagaimana saya bisa melupakan moniker yang begitu mengesankan?",
  str_homestory_806801001_15_dialog_content = "Saya akan mengulangi semuanya, untuk berjaga-jaga!",
  str_homestory_806801001_16_dialog_content = "Aku Wendy, rudal badai gurun!",
  str_homestory_806801001_17_dialog_content = "Kecepatan adalah merek dagang saya, dan keberanian adalah nama tengah saya!",
  str_homestory_806801001_18_dialog_content = "Oke, oke, aku paham.",
  str_homestory_806801001_19_dialog_content = "Yang mengatakan, mengapa berlatih penerbangan vertikal?",
  str_homestory_806801001_20_dialog_content = "Untuk tujuan pengiriman, tentu saja!",
  str_homestory_806801001_21_dialog_content = "Menyampaikan surat?",
  str_homestory_806801001_22_dialog_content = "Pernahkah Anda melihat makhluk dengan tentakel panjang, PlayerName?",
  str_homestory_806801001_23_dialog_content = "Apakah yang Anda maksud: balon ubur-ubur",
  str_homestory_806801001_24_dialog_content = "Saya tidak peduli apa itu.",
  str_homestory_806801001_25_dialog_content = "Jika klien ingin surat dikirimkan, mereka akan mendapatkan jaminan 100%.",
  str_homestory_806801001_26_dialog_content = "Jadi Anda tahu balonnya, PlayerName?",
  str_homestory_806801001_27_dialog_content = "Maksudku, aku tahu perabotannya... jadi kurasa?",
  str_homestory_806801001_28_dialog_content = "Apakah nama balon itu Kleken?",
  str_homestory_806801001_29_dialog_content = "Nah, kalau surat itu ditujukan ke Kleken...",
  str_homestory_806801001_30_dialog_content = "Pasti ada campur aduk, karena Kleken bukan balon.",
  str_homestory_806801001_31_dialog_content = "Apa?! Betulkah?",
  str_homestory_806801001_32_dialog_content = "Pengirim mengatakan Kleken memiliki banyak tentakel yang panjang dan halus.",
  str_homestory_806801001_33_dialog_content = "Dan dia sering memakai topi hitam.",
  str_homestory_806801001_34_dialog_content = "Apakah ada topi di balon?",
  str_homestory_806801001_35_dialog_content = "Bagaimanapun, balon ubur-ubur bukanlah penerima yang Anda cari.",
  str_homestory_806801001_36_dialog_content = "Oh tidak, saya akan membuat rekor pribadi baru untuk waktu pengiriman terlama.",
  str_homestory_806801001_37_dialog_content = "Harus lari.",
  str_homestory_806801001_38_dialog_content = "Meskipun saya melihat sesuatu yang berkilau di tepi sungai dan ingin memeriksanya...",
  str_homestory_806801001_39_dialog_content = "Aku punya pengiriman untuk dilakukan!<sprite=emo_dianzan size=60 />",
  str_homestory_817201001_0_dialog_content = "Hai Lilika...",
  str_homestory_817201001_1_dialog_content = "Ayo periksa, PlayerName!",
  str_homestory_817201001_2_dialog_content = "Ada apa?",
  str_homestory_817201001_3_dialog_content = "Lihat, mainan ini sangat menyenangkan!",
  str_homestory_817201001_4_dialog_content = "Jadi, yang harus Anda lakukan adalah memukulnya dengan pemukul sampai meledak dengan semburan confetti!<sprite=emo_caitiao size=60 />",
  str_homestory_817201001_5_dialog_content = "Terkadang, permen juga bisa muncul!",
  str_homestory_817201001_6_dialog_content = "Saya tidak berpikir saya pernah melihat mainan seperti ini sebelumnya.",
  str_homestory_817201001_7_dialog_content = "Nah, itu masuk akal karena Windelion Dolls adalah ornamen tradisional khas Eraveil.",
  str_homestory_817201001_8_dialog_content = "Anda pasti tidak akan menemukannya di tempat lain.",
  str_homestory_817201001_9_dialog_content = "Boneka Windelion? Ornamen tradisional dari Eraveil...",
  str_homestory_817201001_10_dialog_content = "Sekarang setelah Anda menyebutkannya, saya pikir saya samar-samar mengingatnya!",
  str_homestory_817201001_11_dialog_content = "Bukankah mereka mengadakan festival di mana mereka akan mengisi pot tanah liat dengan benih sebelumnya...",
  str_homestory_817201001_12_dialog_content = "dan menghancurkannya pada hari itu sendiri?",
  str_homestory_817201001_13_dialog_content = "Hanya dengan begitu mereka dapat menerima berkah alam untuk panen yang melimpah tahun itu!",
  str_homestory_817201001_14_dialog_content = "Benar, 'kan?",
  str_homestory_817201001_15_dialog_content = "Wow, Lilika! Saya tidak tahu Anda tahu tradisi Eraveil dengan baik!",
  str_homestory_817201001_16_dialog_content = "Hehe, saya tidak akan pergi sejauh itu, Anda tahu?",
  str_homestory_817201001_17_dialog_content = "Saya pernah berperan sebagai guru sejarah dalam sebuah film.",
  str_homestory_817201001_18_dialog_content = "Itu bukan peran khusus atau apa pun—aku bahkan tidak mendapatkan foto close-up! Tapi saya harus tetap mengajar di latar belakang.",
  str_homestory_817201001_19_dialog_content = "Saya ingat naskah yang saya berikan menyentuh Eraveil dan tradisinya!",
  str_homestory_817201001_20_dialog_content = "Oh wow! Ternyata ada film seperti itu di luar sana?",
  str_homestory_817201001_21_dialog_content = "Apa nama filmnya?",
  str_homestory_817201001_22_dialog_content = "*Membersihkan tenggorokan* Bagaimanapun, dialog saya hanyalah bagian dari kebisingan latar belakang, tidak lebih.",
  str_homestory_817201001_23_dialog_content = "Saya ragu Anda bahkan dapat memahami apa yang saya katakan di film ...",
  str_homestory_817201001_24_option_content = "(Merasa kecewa)",
  str_homestory_817201001_25_dialog_content = "Baik-baik saja maka...",
  str_homestory_817201001_26_dialog_content = "Untuk sesaat, saya pikir saya bisa menonton film tentang Eraveil.",
  str_homestory_817201001_27_dialog_content = "Ayo, jangan terlihat kalah, PlayerName! Apa kau sudah lupa siapa aku?",
  str_homestory_817201001_28_option_content = "(Merasa bersemangat)",
  str_homestory_817201001_29_dialog_content = "Bahkan jika itu hanya kebisingan latar belakang, untuk Eraveil disebutkan dalam film...",
  str_homestory_817201001_30_dialog_content = "Mengetahui sebanyak itu membuat saya sangat bahagia!",
  str_homestory_817201001_31_dialog_content = "Ini sebenarnya bukan masalah besar, PlayerName... Selain itu, apakah Anda sudah lupa siapa saya?",
  str_homestory_817201001_32_dialog_content = "Saya adalah sutradara film yang sedang naik daun di zaman kita! Ingat?",
  str_homestory_817201001_33_dialog_content = "Kenapa aku tidak...",
  str_homestory_817201001_34_dialog_content = "merekam film yang didedikasikan sepenuhnya untuk Eraveil?",
  str_homestory_817201001_35_dialog_content = "Eh? Apakah itu tidak apa apa?",
  str_homestory_817201001_36_dialog_content = "Tentu saja, Anda dapat mengandalkan saya!",
  str_homestory_817201001_37_dialog_content = "Itu akan luar biasa! Apakah Anda sudah memiliki sesuatu dalam pikiran, Lilica?",
  str_homestory_817201001_38_dialog_content = "Hmm..mari kita lihat..<sprite=emo_sikao size=60 />",
  str_homestory_817201001_39_dialog_content = "Ah! Saya mengerti!",
  str_homestory_817201001_40_dialog_content = "Bagaimana dengan film dansa yang berlangsung di Eraveil... dengan aku sebagai bintangnya!",
  str_homestory_817201001_41_dialog_content = "Hah?",
  str_homestory_817201001_42_dialog_content = "Apakah itu masih menjadi film tentang Eraveil?",
  str_homestory_817201001_43_dialog_content = "Mengapa tidak?",
  str_homestory_817201001_44_dialog_content = "Ugh, ini pasti sakit kepala...",
  str_homestory_817201001_45_dialog_content = "Baiklah, bagaimana jika bukan saya... ANDA membintangi film dansa yang berlangsung di Eraveil! Eh? eh??",
  str_homestory_817201001_46_dialog_content = "Saya ... tidak berpikir ada orang yang mau menontonnya ...",
  str_homestory_817301001_0_dialog_content = "Minos...",
  str_homestory_817301001_1_dialog_content = "Selamat pagi, Navigator<sprite=emo_mojing size=60 />.",
  str_homestory_817301001_2_dialog_content = "Halo, Minos.",
  str_homestory_817301001_3_dialog_content = "Apakah ada yang bisa saya lakukan untuk Anda hari ini, Navigator?",
  str_homestory_817301001_4_option_content = "(Mengonfirmasi)",
  str_homestory_817301001_5_dialog_content = "Er... Sebenarnya ada sesuatu yang ingin kutanyakan padamu, Minos.",
  str_homestory_817301001_6_dialog_content = "Dengan segala cara, Pak.",
  str_homestory_817301001_7_dialog_content = "Saya harap Anda bisa sedikit rileks saat berada di sini di Cloud Gardens...",
  str_homestory_817301001_8_dialog_content = "Tidak perlu bagi Anda untuk menjadi begitu sopan dan hormat, Anda tahu?",
  str_homestory_817301001_9_option_content = "(Membantah)",
  str_homestory_817301001_10_dialog_content = "T-Tidak juga, tidak...",
  str_homestory_817301001_11_dialog_content = "Saya selalu merasa sangat nyaman setiap kali Anda berada di sini di Cloud Gardens, Minos.",
  str_homestory_817301001_12_dialog_content = "Tapi aku sangat berharap kau bisa sedikit santai saat kau di sini...",
  str_homestory_817301001_13_dialog_content = "Bagaimanapun, saya mengundang Anda untuk menjadi tamu saya di Cloud Gardens.",
  str_homestory_817301001_14_dialog_content = "Anda ada benarnya, ya.",
  str_homestory_817301001_15_dialog_content = "Sebagai tamu Anda, tentu saja tidak sopan bagi saya untuk menghilangkan Anda dari kesenangan menjamu tamu.",
  str_homestory_817301001_16_dialog_content = "Saya telah mencatat permintaan Anda, Pak.",
  str_homestory_817301001_17_dialog_content = "Sekarang, izinkan saya beberapa saat untuk membentuk diri saya menjadi tamu yang sempurna.",
  str_homestory_817301001_18_dialog_content = "Anda tidak harus keluar dari cara Anda untuk menjadi sempurna, Anda tahu?",
  str_homestory_817301001_19_dialog_content = "Tamu yang tidak sempurna, kalau begitu?",
  str_homestory_817301001_20_dialog_content = "Kedengarannya seperti sebuah tantangan.",
  str_homestory_817301001_21_dialog_content = "Hehehe... Kamu terlalu berlebihan, Minos. Bagaimanapun...",
  str_homestory_817301001_22_dialog_content = "Saya baru saja melihat lilin ini menyala segera setelah Anda mengangkat tangan.",
  str_homestory_817301001_23_dialog_content = "Itu luar biasa! Bagaimana Anda melakukannya, Minos?",
  str_homestory_817301001_24_dialog_content = "Anda memiliki keterampilan pengamatan yang tajam, Pak.",
  str_homestory_817301001_25_dialog_content = "Saya baru saja menyelesaikan pelatihan mereka ketika Anda tiba.",
  str_homestory_817301001_26_dialog_content = "Anda... melatih lilin?",
  str_homestory_817301001_27_dialog_content = "Memang. Ini adalah teknik yang hanya diketahui oleh kepala pelayan veteran yang telah mendedikasikan waktu bertahun-tahun untuk memberikan layanan...",
  str_homestory_817301001_28_dialog_content = "Tidak peduli seberapa mahal sebuah perabot, atau betapa halusnya sebuah ornamen tampak...",
  str_homestory_817301001_29_dialog_content = "Dengan teknik yang tepat, mereka semua dapat dilatih untuk melayani orang lain dengan lebih baik di ruang masing-masing.",
  str_homestory_817301001_30_dialog_content = "Ambil lilin ini, misalnya.",
  str_homestory_817301001_31_dialog_content = "Mereka memiliki mekanisme yang memungkinkan mereka menyala dan padam secara otomatis.",
  str_homestory_817301001_32_dialog_content = "Dibiarkan tidak dicentang, lilin ini hanya akan diaktifkan dan dinonaktifkan secara acak, tanpa sedikit pun urutan.",
  str_homestory_817301001_33_dialog_content = "Tapi tidak perlu khawatir. Dengan mendekati mereka dalam urutan yang tepat...",
  str_homestory_817301001_34_dialog_content = "Mereka sekarang akan dengan senang hati menyala di hadapan Anda.",
  str_homestory_817301001_35_dialog_content = "I-Itu luar biasa...",
  str_homestory_817301001_36_dialog_content = "Ah! Permintaan maaf saya...",
  str_homestory_817301001_37_dialog_content = "Sebagai tamu Anda, saya seharusnya tidak melakukan hal-hal seperti melatih furnitur Anda...",
  str_homestory_817301001_38_dialog_content = "Jangan khawatir.",
  str_homestory_817301001_39_dialog_content = "Jika bukan karena Anda, saya tidak akan pernah tahu saya bisa melakukan ini dengan lilin ini!",
  str_homestory_817301001_40_dialog_content = "Terima kasih telah mengabaikan kesalahan saya.",
  str_homestory_817301001_41_dialog_content = "Meskipun saya tidak bisa tidak merasa bersyukur atas kesalahan saya ...",
  str_homestory_817301001_42_dialog_content = "Karena itu, saya dengan sempurna mengambil peran sebagai tamu yang tidak sempurna.",
  str_homestory_817301001_43_dialog_content = "Tapi saya hanya berharap kinerja saya<sprite=emo_baimao size=60 /> telah memuaskan Anda, Navigator.",
  str_homestory_815901001_0_dialog_content = "Hei, Sadi!",
  str_homestory_815901001_1_dialog_content = "Oh itu kamu. Jangan bilang seseorang menyuruhmu mencariku?",
  str_homestory_815901001_2_dialog_content = "Nah, saya tertarik dengan musiknya<sprite=emo_yinfu size=60 /> lebih awal.",
  str_homestory_815901001_3_dialog_content = "Ritme yang menarik dan ketukan yang menggembirakan ...",
  str_homestory_815901001_4_dialog_content = "Saya tidak bisa menahan diri untuk tidak menari mengikuti musik!",
  str_homestory_815901001_5_dialog_content = "Sepertinya Anda telah jatuh cinta pada pesona hip-hop yang tak tertahankan!",
  str_homestory_815901001_6_dialog_content = "Tapi itu sangat normal karena siapa yang tidak suka hip-hop?",
  str_homestory_815901001_7_dialog_content = "Jadi ini hip-hop...?",
  str_homestory_815901001_8_dialog_content = "Jangan bilang Anda belum pernah mendengarnya sebelumnya, PlayerName?",
  str_homestory_815901001_9_option_content = "(Mengonfirmasi)",
  str_homestory_815901001_10_dialog_content = "Saya tidak terlalu mendengarkan hip-hop, jadi saya tidak bisa mengatakan bahwa saya memahaminya dengan baik.",
  str_homestory_815901001_11_option_content = "(Membantah)",
  str_homestory_815901001_12_dialog_content = "Tidak mungkin, saya suka semua jenis musik!",
  str_homestory_815901001_13_dialog_content = "Tapi satu-satunya lagu hip-hop yang pernah kudengar adalah rapmu...",
  str_homestory_815901001_14_dialog_content = "Itu sebabnya saya tidak mengerti banyak tentang genre.",
  str_homestory_815901001_15_dialog_content = "Itu juga mengapa saya tidak bisa langsung mengatakan itu hip-hop.",
  str_homestory_815901001_16_dialog_content = "Itu benar-benar memalukan. Tidak heran saya pikir ada sesuatu yang hilang ketika saya pertama kali sampai di sini.",
  str_homestory_815901001_17_dialog_content = "Segera setelah saya melihat drum ini sebelumnya, saya tiba-tiba tersadar bahwa tempat ini membutuhkan hip-hop!",
  str_homestory_815901001_18_dialog_content = "Saya tidak pernah tahu bahwa satu drum bisa membuat ketukan yang begitu mengharukan...",
  str_homestory_815901001_19_dialog_content = "Sepertinya Anda benar-benar terpesona olehnya, PlayerName.",
  str_homestory_815901001_20_dialog_content = "Saya kira seorang swashbuckler seperti saya tidak punya pilihan selain untuk membantu Anda.",
  str_homestory_815901001_21_dialog_content = "Pinjamkan aku tangan?",
  str_homestory_815901001_22_dialog_content = "Betul sekali! Saya akan mengajari Anda cara memainkan drum ini dengan benar!",
  str_homestory_815901001_23_dialog_content = "Dengan begitu, Anda dapat mendengarkan ketukan hip-hop yang manis kapan pun Anda mau!",
  str_homestory_815901001_24_dialog_content = "Eh? Tunggu, jika saya mengajari Anda cara melakukannya ...",
  str_homestory_815901001_25_dialog_content = "Bukankah itu berarti semua orang di Cloud Gardens akan mendengar ketukan hip-hop yang Anda buat?!",
  str_homestory_815901001_26_dialog_content = "Saya tidak percaya bahwa saya akan memulai tren hip-hop di Astra!",
  str_homestory_815901001_27_dialog_content = "M-Maaf mengganggu, Sadie...",
  str_homestory_815901001_28_dialog_content = "Tapi saya hanya seorang pemula dalam hal hip-hop atau drum.",
  str_homestory_815901001_29_dialog_content = "Saya tidak berpikir mengajar saya akan menjadi hal yang mudah.",
  str_homestory_815901001_30_dialog_content = "Oh, jangan khawatir tentang itu! Bagaimanapun, siswa terbaik adalah orang yang ingin belajar<sprite=emo_dianzan size=60 />!",
  str_homestory_815901001_31_dialog_content = "Sekarang, dua aspek terpenting dari hip-hop adalah ritme dan ketukan.",
  str_homestory_815901001_32_dialog_content = "Ritme akan datang secara alami selama Anda bermain sesuai irama.",
  str_homestory_815901001_33_dialog_content = "Sekarang, bayangkan diri Anda sebagai stik drum dan keluarkan ritme di dalam hati Anda.",
  str_homestory_815901001_34_dialog_content = "Bagaimanapun, hip-hop terbaik selalu datang langsung dari hati!",
  str_homestory_815901001_35_dialog_content = "Jadi maksudmu aku bisa tampil sepertimu jika aku mengikuti kata hatiku?",
  str_homestory_815901001_36_dialog_content = "Sangat! Mengapa Anda tidak mencobanya?",
  str_homestory_815901001_37_dialog_content = "Tetap pada irama dan terus bermain drum. Musik akan mengalir dengan sendirinya!",
  str_homestory_815901001_38_dialog_content = "J-Terus saja bermain drum, ya...",
  str_homestory_815901001_39_dialog_content = "Tidakkah Anda ingin membantu lebih banyak orang menyadari betapa menakjubkannya hip-hop?",
  str_homestory_815901001_40_dialog_content = "Tentu saja, tapi aku benar-benar lelah sekarang.",
  str_homestory_815901001_41_dialog_content = "Saya kira Anda masih memiliki jalan panjang sebelum menjadi superstar hip-hop, PlayerName.",
  str_homestory_815901001_42_dialog_content = "Mari kita sebut saja untuk hari ini, ya?",
  str_homestory_815901001_43_dialog_content = "T-Terima kasih...",
  str_homestory_807901001_0_dialog_content = "michenny...",
  str_homestory_807901001_1_dialog_content = "michenny?",
  str_homestory_807901001_2_dialog_content = "Halo, PlayerName.",
  str_homestory_807901001_3_dialog_content = "Heheh... Apakah Anda di sini untuk menghargai dekorasi juga?",
  str_homestory_807901001_4_dialog_content = "Sebagai Pemungut Pajak yang berpikiran logis, kata \"menghargai\" terlalu sentimentil.",
  str_homestory_807901001_5_dialog_content = "Saya hanya di sini untuk menilai nilai barang ini, tidak lebih.",
  str_homestory_807901001_6_dialog_content = "Ah... Ini bukan Lumopolis, tahu? Saya pikir bahkan Anda dapat bersantai sesekali, Michenny<sprite=emo_sikao size=60 />.",
  str_homestory_807901001_7_dialog_content = "Melatih pemikiran rasional bukanlah masalah sepele.",
  str_homestory_807901001_8_dialog_content = "Apalagi jika cita-cita seseorang adalah menjadi sarjana terkemuka di bidang hukum perpajakan.",
  str_homestory_807901001_9_dialog_content = "Saya tidak berniat menyia-nyiakan pengalaman akademis selama bertahun-tahun hanya untuk mengendur, bahkan untuk sesaat.",
  str_homestory_807901001_10_dialog_content = "Namun, bukan berarti saya tidak punya waktu luang. Jika perlu, saya dapat membantu Anda dengan pajak Cloud Gardens di waktu luang saya.",
  str_homestory_807901001_11_dialog_content = "Saya tidak berpikir kami memiliki masalah pajak di Cloud Gardens untuk saat ini...",
  str_homestory_807901001_12_dialog_content = "Nada Anda lembut, dan Anda terdengar tidak pasti. Itu tentang pajak 10 Nightium<sprite=emo_baiyebi size=60 /> jauh dari ditentukan.",
  str_homestory_807901001_13_dialog_content = "Sepertinya Anda telah menolak layanan saya sepenuhnya.",
  str_homestory_807901001_14_option_content = "Setuju",
  str_homestory_807901001_15_dialog_content = "Bukannya aku ingin menolakmu, michenny. Hanya saja... Cloud Gardens tidak mampu membayar pemungut cukai sepertimu.",
  str_homestory_807901001_16_dialog_content = "Ah, singkatnya Nightium seperti biasa, begitu.",
  str_homestory_807901001_17_dialog_content = "Anda tidak perlu khawatir tentang itu. Saya dapat memberi Anda nasihat ahli pajak, gratis.",
  str_homestory_807901001_18_dialog_content = "Bagaimanapun, menilai nilai Cloud Gardens dengan benar akan memberi saya ukuran nilai emosional juga.",
  str_homestory_807901001_19_option_content = "Bantah",
  str_homestory_807901001_20_dialog_content = "Sa-Sama sekali tidak!",
  str_homestory_807901001_21_dialog_content = "Jika Cloud Gardens membutuhkan pemungut pajak, Anda akan menjadi orang pertama yang saya hubungi, Michenny!",
  str_homestory_807901001_22_dialog_content = "Pajak harus ada di mana pun tanah dikelola dan transaksi terjadi.",
  str_homestory_807901001_23_dialog_content = "Karena Anda telah menaruh begitu banyak kepercayaan pada saya, saya akan terus menilai nilai Cloud Gardens.",
  str_homestory_807901001_24_dialog_content = "S-Tentu...",
  str_homestory_807901001_25_dialog_content = "Kembali ke pokok bahasan, beri tahu saya... Berapa banyak yang Anda ketahui tentang dekorasi ini?",
  str_homestory_807901001_26_dialog_content = "Saya membutuhkan lebih banyak informasi untuk membuat penilaian yang adil.",
  str_homestory_807901001_27_dialog_content = "Ini disebut Sarang Windelion.",
  str_homestory_807901001_28_dialog_content = "Padahal cangkang telur raksasa ini hanya hiasan bagi kita, banyak binatang<sprite=emo_gezitou size=60 /> suka menggunakannya untuk bertelur.",
  str_homestory_807901001_29_dialog_content = "Hmm. Mereka tidak menghasilkan nilai ekonomi langsung, dan mereka mengambil ruang.",
  str_homestory_807901001_30_dialog_content = "Selain itu, makhluk yang mereka pelihara pada akhirnya akan mulai mengkonsumsi sumber makanan Cloud Gardens.",
  str_homestory_807901001_31_dialog_content = "Kesimpulan saya adalah bahwa benda ini dan makhluk kecil yang tinggal di dalamnya tidak memiliki nilai apa pun.",
  str_homestory_807901001_32_dialog_content = "Sebaliknya, mereka menjadi beban ekonomi di Cloud Gardens.",
  str_homestory_807901001_33_dialog_content = "T-Tapi di dalam telur ada makhluk hidup!",
  str_homestory_807901001_34_dialog_content = "Bagaimana Anda bisa menilai nilai hidup mereka menggunakan logika?",
  str_homestory_807901001_35_dialog_content = "Jika Anda bertanya kepada saya, nyawa mereka tak ternilai harganya.",
  str_homestory_807901001_36_dialog_content = "Tak ternilai, katamu?",
  str_homestory_807901001_37_dialog_content = "Tunggu... Aku mengerti!",
  str_homestory_807901001_38_dialog_content = "Bagaimana Anda ingin merawat Windelion Nest ini, Michenny?",
  str_homestory_807901001_39_dialog_content = "Sangat baik. Apa yang harus saya lakukan?",
  str_homestory_807901001_40_dialog_content = "Tunggu saja di sini sampai anak-anak kecil ini menetas, dan awasi mereka sampai mereka dewasa!",
  str_homestory_807901001_41_dialog_content = "Saya dapat meminjamkan Anda sebuah buku yang mengajarkan Anda semua tentang merawat hewan.",
  str_homestory_807901001_42_dialog_content = "Buku teks akan sangat membantu, ya.",
  str_homestory_807901001_43_dialog_content = "Serahkan padaku. Aku berjanji tidak akan mengecewakanmu.",
  str_homestory_817601001_0_dialog_content = "Beretta!",
  str_homestory_817601001_1_dialog_content = "Apa yang kamu lakukan, Beretta?",
  str_homestory_817601001_2_dialog_content = "Hai PlayerName!",
  str_homestory_817601001_3_dialog_content = "Saya sedang berolahraga.",
  str_homestory_817601001_4_dialog_content = "Ketika saya berlari ke sini, saya pikir saya melihat Lady Raphael.",
  str_homestory_817601001_5_dialog_content = "Jadi saya berhenti untuk melihat lagi ...",
  str_homestory_817601001_6_dialog_content = "dan perhatikan fotonya di kartu ini!",
  str_homestory_817601001_7_dialog_content = "Ah, itu kartu pos yang dikirim semua orang kepadaku sebelumnya!",
  str_homestory_817601001_8_dialog_content = "Beberapa lainnya adalah oleh-oleh yang saya bawa pulang dari tempat baru.",
  str_homestory_817601001_9_dialog_content = "Saya pikir yang ini diambil saat Raphael menyeret Michael dalam perjalanan jauh.",
  str_homestory_817601001_10_dialog_content = "Saya bertanya-tanya mengapa Michael terlihat sangat kacau!<sprite=emo_wuzui size=60 />",
  str_homestory_817601001_11_dialog_content = "Anda tampaknya cukup populer.",
  str_homestory_817601001_12_dialog_content = "Anda punya banyak di sini... Saya bahkan melihat satu dengan tanda tangan Lady Hedy di atasnya.",
  str_homestory_817601001_13_dialog_content = "Hei, apakah ini foto pemandangan Gurun Rediesel?",
  str_homestory_817601001_14_dialog_content = "Dia.",
  str_homestory_817601001_15_dialog_content = "Yang satu ini adalah oleh-oleh dari mengunjungi Rediesel Wrench.",
  str_homestory_817601001_16_option_content = "Dan yang ini dari Northland...",
  str_homestory_817601001_17_dialog_content = "Wow, gurun dan salju... Spektakuler!",
  str_homestory_817601001_18_option_content = "Dan ini dari pantai...",
  str_homestory_817601001_19_dialog_content = "Wow, gurun dan pantai... Spektakuler!",
  str_homestory_817601001_20_dialog_content = "Saya sangat iri karena Anda telah mengunjungi begitu banyak tempat, PlayerName!",
  str_homestory_817601001_21_dialog_content = "Apakah kamu tidak bepergian, Beretta?",
  str_homestory_817601001_22_dialog_content = "Tidak, karena pekerjaan saya, saya tidak pernah bisa benar-benar rileks bahkan saat saya tidak bekerja.",
  str_homestory_817601001_23_dialog_content = "Lagi pula, pasien tidak berhenti sakit atau terluka hanya karena Anda sedang berlibur.",
  str_homestory_817601001_24_dialog_content = "Bahkan ketika saya melakukan perjalanan, itu untuk memberikan bantuan medis.",
  str_homestory_817601001_25_dialog_content = "Susah banget jadi dokter...",
  str_homestory_817601001_26_dialog_content = "Itu sulit.",
  str_homestory_817601001_27_dialog_content = "Tetapi ketika saya berpikir tentang bagaimana saya dapat meringankan rasa sakit seseorang atau bahkan menyelamatkan hidup...",
  str_homestory_817601001_28_dialog_content = "Ini tidak sulit lagi!",
  str_homestory_817601001_29_dialog_content = "Belum lagi saya harus bekerja lebih keras untuk menjadi lebih baik.",
  str_homestory_817601001_30_dialog_content = "Dengan begitu, saya dapat membangun tim medis keliling saya sendiri untuk merawat pasien di seluruh benua.",
  str_homestory_817601001_31_dialog_content = "Kemudian, saya tidak hanya akan membantu lebih banyak orang, tetapi saya juga akan melihat pemandangan yang belum pernah saya lihat sebelumnya!",
  str_homestory_817601001_32_dialog_content = "Dua burung dengan satu batu!<sprite=emo_guilian size=60 />",
  str_homestory_817601001_33_dialog_content = "Saya terkesan, Beretta!",
  str_homestory_817601001_34_dialog_content = "Anda memiliki cahaya tertentu tentang Anda ketika Anda berbicara tentang pekerjaan Anda!",
  str_homestory_817601001_35_dialog_content = "Hahaha, tapi jalanku masih panjang!",
  str_homestory_817601001_36_dialog_content = "Cita-cita saya adalah menjadi dokter hebat seperti Lady Raphael atau Mr. John.",
  str_homestory_817601001_37_dialog_content = "Tapi saya masih harus banyak belajar.",
  str_homestory_817601001_38_dialog_content = "Tidak hanya dalam pengobatan tetapi juga dalam stamina fisik dan mental.",
  str_homestory_817601001_39_dialog_content = "Ketika Dr. John mengoperasi saya, dia berdiri di meja operasi selama tiga hari penuh!",
  str_homestory_817601001_40_dialog_content = "Itu tidak mungkin saya lakukan sekarang.",
  str_homestory_817601001_41_dialog_content = "Ah, lebih baik aku berhenti berbicara dan melanjutkan latihanku!",
  str_homestory_817601001_42_dialog_content = "Sampai jumpa, PlayerName.",
  str_homestory_817601001_43_dialog_content = "Saya akan mengirimi Anda kartu pos ketika saya mulai berkeliling merawat orang!",
  str_homestory_817601001_44_dialog_content = "Heh, masih terburu-buru seperti biasa.",
  str_homestory_817601001_45_dialog_content = "Saya menantikan hari itu. Kamu bisa melakukannya, Beretta.",
  str_homestory_817501001_0_dialog_content = "Axelia?",
  str_homestory_817501001_1_dialog_content = "Hai, Axelia.",
  str_homestory_817501001_2_dialog_content = "Halo, PlayerName.",
  str_homestory_817501001_3_dialog_content = "Merasa lebih baik akhir-akhir ini?",
  str_homestory_817501001_4_dialog_content = "Saya cukup sering melihat Anda di Cloud Gardens.",
  str_homestory_817501001_5_dialog_content = "Ya<sprite=emo_chidai size=60 />... setelah saya selesai menjelajahi Cloud Gardens, saya harus kembali ke ruang stasis.",
  str_homestory_817501001_6_dialog_content = "Tetapi ada banyak hal di sini yang menurut saya menarik.",
  str_homestory_817501001_7_dialog_content = "Seperti gendang yang sering kamu kunjungi ini?",
  str_homestory_817501001_8_dialog_content = "*Batuk-batuk*",
  str_homestory_817501001_9_dialog_content = "Apakah Anda telah memperhatikan saya, PlayerName?",
  str_homestory_817501001_10_option_content = "Tentu saja!",
  str_homestory_817501001_11_dialog_content = "Kubus selalu bersama Anda, jadi tidak boleh ada kecelakaan yang terjadi.",
  str_homestory_817501001_12_dialog_content = "Tapi saya merasa saya harus memperhatikan kondisi Anda.",
  str_homestory_817501001_13_dialog_content = "Terima kasih telah peduli.",
  str_homestory_817501001_14_option_content = "Tidak.",
  str_homestory_817501001_15_dialog_content = "Hanya saja setiap kali saya melihat Anda, Anda selalu berkeliaran di drum.",
  str_homestory_817501001_16_dialog_content = "Hmm…",
  str_homestory_817501001_17_dialog_content = "Saya memiliki rasa ingin tahu tertentu tentang drum tersebut.",
  str_homestory_817501001_18_dialog_content = "Benar, saya ingat Anda memiliki minat dalam musik.",
  str_homestory_817501001_19_dialog_content = "Tetapi apakah ada alasan mengapa Anda menyukai techno?",
  str_homestory_817501001_20_dialog_content = "Alasan...",
  str_homestory_817501001_21_dialog_content = "Mungkin karena musik seperti itu tidak ada liriknya. <sprite=emo_sikao size=60 />",
  str_homestory_817501001_22_dialog_content = "Lirik?",
  str_homestory_817501001_23_dialog_content = "Ya.",
  str_homestory_817501001_24_dialog_content = "Tanpa lirik, pendengar memiliki lebih banyak ruang untuk berimajinasi.",
  str_homestory_817501001_25_dialog_content = "Mereka dapat dengan mudah memanjakan diri mereka sendiri dalam irama musik tanpa perlu mencurahkan terlalu banyak emosi mereka ke dalam semacam cerita.",
  str_homestory_817501001_26_dialog_content = "Itu memang jawaban yang sangat mirip Axelia.",
  str_homestory_817501001_27_dialog_content = "Meskipun Ayah akan mencemooh pemikiran itu, saya pikir dibandingkan dengan musik lain...",
  str_homestory_817501001_28_dialog_content = "Techno melambangkan perpaduan rasional dari kreativitas dan nada musik langsung.",
  str_homestory_817501001_29_dialog_content = "Anda tahu, itu masuk akal jika Anda mengatakannya seperti itu.",
  str_homestory_817501001_30_dialog_content = "Jenis musik ini sepertinya tidak membangkitkan emosi yang kuat dalam diriku...",
  str_homestory_817501001_31_dialog_content = "Ya.",
  str_homestory_817501001_32_dialog_content = "Jadi...",
  str_homestory_817501001_33_dialog_content = "Apakah Anda bermain drum karena musik techno biasanya memiliki ketukan drum?",
  str_homestory_817501001_34_dialog_content = "Atau apakah Anda mencoba memasukkan suara drum ke dalam ritme?",
  str_homestory_817501001_35_dialog_content = "Saya hanya ingin mendengarkan suara mereka lebih banyak.",
  str_homestory_817501001_36_dialog_content = "Tapi Anda telah memberi saya ide.",
  str_homestory_817501001_37_dialog_content = "Saya akan terus mengunjungi di masa depan.",
  str_homestory_817501001_38_dialog_content = "Tentu! Beri tahu saya jika ada hal lain yang Anda butuhkan.",
  str_homestory_817501001_39_dialog_content = "Terima kasih, PlayerName.",
  str_homestory_805401001_0_dialog_content = "Nadine?",
  str_homestory_805401001_1_dialog_content = "PlayerName!",
  str_homestory_805401001_2_dialog_content = "Mengapa Anda berdiri di sini sendirian?",
  str_homestory_805401001_3_dialog_content = "Mengapa Anda tidak berada di dalam asrama bersama yang lain, atau memancing di dekat sini?",
  str_homestory_805401001_4_dialog_content = "Karena aku harus menyelesaikan pekerjaanku!",
  str_homestory_805401001_5_dialog_content = "Pekerjaan Anda?",
  str_homestory_805401001_6_dialog_content = "Betul sekali. Sebagai Nightwatch pertama Cloud Gardens...",
  str_homestory_805401001_7_dialog_content = "itu tugas saya untuk waspada selama setiap shift!",
  str_homestory_805401001_8_dialog_content = "Hei, tunggu sebentar—",
  str_homestory_805401001_9_dialog_content = "Saya tidak ingat meminta Anda menjadi Nightwatch untuk Cloud Gardens <sprite=emo_yueliang size=60 />.",
  str_homestory_805401001_10_dialog_content = "Anda mengundang saya untuk nongkrong di Cloud Gardens.",
  str_homestory_805401001_11_dialog_content = "Anda menyediakan penginapan, makanan, dan banyak hal menyenangkan lainnya...",
  str_homestory_805401001_12_dialog_content = "Saya sangat senang!",
  str_homestory_805401001_13_dialog_content = "Saya tidak pernah berpikir saya akan menjadi teman dekat selebriti seperti Anda.",
  str_homestory_805401001_14_dialog_content = "Apalagi meninggalkan Lumopolis ke tempat yang jauh seperti Cloud Gardens.",
  str_homestory_805401001_15_dialog_content = "Tapi aku tidak punya uang atau keahlian khusus... Aku tidak tahu bagaimana membalasmu.",
  str_homestory_805401001_16_dialog_content = "Sepertinya yang saya tahu hanyalah menjadi Nightwatch.",
  str_homestory_805401001_17_dialog_content = "Jadi saya memutuskan bahwa ini adalah bagaimana saya akan menunjukkan rasa terima kasih saya kepada Anda, PlayerName!",
  str_homestory_805401001_18_option_content = "Berterimakasihlah padanya",
  str_homestory_805401001_19_dialog_content = "Terima kasih, Nadine. Menyentuh saya mendengar Anda mengatakan itu.",
  str_homestory_805401001_20_dialog_content = "Tapi saya tidak bisa membiarkan tamu saya bekerja di sini untuk saya.",
  str_homestory_805401001_21_option_content = "Hibur dia",
  str_homestory_805401001_22_dialog_content = "Kebahagiaan Anda adalah balasan terbaik untuk saya!",
  str_homestory_805401001_23_dialog_content = "Anda benar-benar tidak perlu terlalu memaksakan diri.",
  str_homestory_805401001_24_dialog_content = "Jangan khawatir, saya sudah terbiasa. Tidak sulit bagi saya.",
  str_homestory_805401001_25_dialog_content = "Lagi pula...",
  str_homestory_805401001_26_dialog_content = "Cloud Gardens sangat cantik!",
  str_homestory_805401001_27_dialog_content = "Dan Anda selalu mendapatkan furnitur yang sesuai dengan preferensi kami…",
  str_homestory_805401001_28_dialog_content = "Saya secara bertahap merasa betah di sini.",
  str_homestory_805401001_29_dialog_content = "Karena ini rumah, kamu tidak perlu terlalu formal denganku.",
  str_homestory_805401001_30_dialog_content = "Jangan terpaku pada hutang Anda yang belum dibayar.",
  str_homestory_805401001_31_dialog_content = "Yah, saya merasakan kewajiban di sini karena saya menganggapnya sebagai rumah.",
  str_homestory_805401001_32_dialog_content = "Saya ingin melindungi Cloud Gardens, rumah kita, dari segala bahaya!",
  str_homestory_805401001_33_dialog_content = "Bagi saya, ini bukan sekedar pekerjaan.",
  str_homestory_805401001_34_dialog_content = "Itu naluri dan kewajiban!",
  str_homestory_805401001_35_dialog_content = "Oh, Nadine...",
  str_homestory_805401001_36_dialog_content = "Terima kasih, saya kira.",
  str_homestory_805401001_37_dialog_content = "Saya akan mencoba memberikan kompensasi kepada Anda untuk ini dengan cara tertentu.",
  str_homestory_805401001_38_dialog_content = "Apa?!",
  str_homestory_817801001_0_dialog_content = "Hai, Vic.",
  str_homestory_817801001_1_dialog_content = "Tidak setiap hari kami bisa melihatmu bertualang di luar ruangan!",
  str_homestory_817801001_2_dialog_content = "Tidak ingin berbaring di tempat tidur sambil minum hari ini?<sprite=emo_kun size=60 />",
  str_homestory_817801001_3_dialog_content = "Wow, benarkah itu yang kau pikirkan tentangku?",
  str_homestory_817801001_4_dialog_content = "Itu menyakitkan... Saya ahli ekstrozoologi, Anda tahu...",
  str_homestory_817801001_5_dialog_content = "Setiap kali saya berada di kamar saya, saya biasanya memilah-milah materi atau mengerjakan buku baru saya.",
  str_homestory_817801001_6_dialog_content = "Saya selalu memikirkan hal-hal penting — hanya saja minum membantu memperluas pikiran saya!",
  str_homestory_817801001_7_dialog_content = "Oh ya? Jadi, bagaimana buku barumu?",
  str_homestory_817801001_8_dialog_content = "Ahem... Saya katakan, lingkungan di sini benar-benar membaik dari hari ke hari.",
  str_homestory_817801001_9_dialog_content = "Nah, itu salah satu cara untuk mengubah topik pembicaraan.",
  str_homestory_817801001_10_dialog_content = "Tidak, tidak—apakah Anda tahu apa yang telah saya lakukan di sini?",
  str_homestory_817801001_11_dialog_content = "Hmm... Selain berjalan-jalan dalam keadaan linglung?",
  str_homestory_817801001_12_dialog_content = "...",
  str_homestory_817801001_13_dialog_content = "Saya sedang menyelidiki spesies dan jumlah makhluk hidup di hutan Anda.",
  str_homestory_817801001_14_dialog_content = "Untuk apa kamu melakukan itu?",
  str_homestory_817801001_15_dialog_content = "Jangan meremehkan pentingnya informasi ini!",
  str_homestory_817801001_16_dialog_content = "Ini mungkin mengungkapkan fenomena yang sangat penting.",
  str_homestory_817801001_17_dialog_content = "Misalnya, ini akan memberi tahu kita jenis makhluk hidup mana yang cocok dengan lingkungan di sini,",
  str_homestory_817801001_18_dialog_content = "interaksi simbiosis antara hewan dan tumbuhan di sini, dan seterusnya.",
  str_homestory_817801001_19_dialog_content = "Anda tahu apa, itu baru saja terpikir oleh saya<sprite=emo_wuzui size=60 />—",
  str_homestory_817801001_20_dialog_content = "Tempat ini sangat cocok untuk penyelidikan dan penelitian!",
  str_homestory_817801001_21_dialog_content = "Saya berencana untuk memperkenalkan beberapa binatang yang menakjubkan di sini.",
  str_homestory_817801001_22_dialog_content = "Dengan begitu, buku saya akan memiliki lebih banyak...",
  str_homestory_817801001_23_dialog_content = "Tunggu... Kamu mau melakukan apa?",
  str_homestory_817801001_24_dialog_content = "Hah? Kumpulkan informasi dan tulis di buku saya...?",
  str_homestory_817801001_25_dialog_content = "Tidak, maksud saya hal lain.",
  str_homestory_817801001_26_dialog_content = "Anda ingin membesarkan binatang yang menakjubkan di hutan?",
  str_homestory_817801001_27_dialog_content = "Aku sudah memberimu begitu banyak kamar untuk dirimu sendiri, itu tidak cukup!?",
  str_homestory_817801001_28_dialog_content = "Bagaimana itu di mana saja di dekat hal yang sama?",
  str_homestory_817801001_29_dialog_content = "Pemandangan dalam ruangan buatan tidak dapat dibandingkan dengan lingkungan nyata di dunia luar.",
  str_homestory_817801001_30_dialog_content = "Perilaku hewan hanya dapat diamati dalam keadaan sebenarnya ketika subjek berada di habitat aslinya.",
  str_homestory_817801001_31_dialog_content = "Itu bukan poin saya!",
  str_homestory_817801001_32_dialog_content = "Anda sudah membawa begitu banyak binatang buas yang menakjubkan ke Colossus; Saya telah menerima banyak keluhan dari yang lain, Anda tahu!",
  str_homestory_817801001_33_dialog_content = "Belum lagi, Anda belum menemukan saya solusi untuk jeritan binatang buas yang terus-menerus membangunkan semua orang di pagi hari.",
  str_homestory_817801001_34_dialog_content = "Dan Anda tidak pernah sempat membersihkan semua kotoran dan rambut yang mereka tinggalkan di semua tempat.",
  str_homestory_817801001_35_dialog_content = "Sekarang kamu ingin membuat lebih banyak masalah untukku!?",
  str_homestory_817801001_36_dialog_content = "Kamu sangat dingin, PlayerName.",
  str_homestory_817801001_37_dialog_content = "Bagaimana Anda bisa berpikir ini merepotkan?",
  str_homestory_817801001_38_dialog_content = "Pikirkan tentang kontribusi yang akan diberikan kepada organisasi binatang yang luar biasa di seluruh benua!",
  str_homestory_817801001_39_dialog_content = "Kamu konyol!<sprite=emo_shengqi size=60 />",
  str_homestory_817801001_40_dialog_content = "Anda tidak diizinkan membawa malapetaka ekstrozoologi Anda ke hutan ini, dan itulah akhirnya.",
  str_homestory_817801001_41_dialog_content = "Padang rumput, lembah, dan sungai juga terlarang!",
  str_homestory_817801001_42_dialog_content = "Huh... Baik.",
  str_homestory_817801001_43_dialog_content = "Sungguh, anak muda saat ini tidak memiliki kesabaran untuk orang tua mereka.",
  str_homestory_817701001_0_dialog_content = "Goldie!",
  str_homestory_817701001_1_dialog_content = "Ah, akhirnya aku menemukanmu, Goldie! <sprite=emo_yaosu size=60 />",
  str_homestory_817701001_2_dialog_content = "PlayerName, saya baru saja menyanyikan lagu baru saya di atas panggung.",
  str_homestory_817701001_3_dialog_content = "Aduh, aku sangat gugup. Saya ingin tahu apakah semua orang menyukainya ...",
  str_homestory_817701001_4_dialog_content = "Apa yang Anda pikirkan tentang itu?",
  str_homestory_817701001_5_dialog_content = "Kedengarannya luar biasa!",
  str_homestory_817701001_6_dialog_content = "Saya yakin semua orang menyukainya!",
  str_homestory_817701001_7_dialog_content = "Heeee... Terima kasih. Kurasa aku bisa tenang sekarang.",
  str_homestory_817701001_8_dialog_content = "Sejujurnya, ada sesuatu yang ada di pikiranku saat ini.",
  str_homestory_817701001_9_dialog_content = "Saya berharap Anda bisa memberi saya beberapa saran.",
  str_homestory_817701001_10_dialog_content = "Ada apa? Saya jarang melihat Anda berkonflik.",
  str_homestory_817701001_11_dialog_content = "Ini tentang single utama di album baruku...",
  str_homestory_817701001_12_dialog_content = "Ada lagu yang ditulis dengan gayaku yang biasa, penuh sinar matahari <sprite=emo_taiyang size=60 /> dan positif.",
  str_homestory_817701001_13_dialog_content = "Lalu ada lagi yang terdengar lebih keren <sprite=emo_mojing size=60 /> lagu yang sedang saya pikirkan untuk menggantinya, dalam upaya untuk mencoba sesuatu yang baru.",
  str_homestory_817701001_14_dialog_content = "Apakah Anda pikir saya perlu menggantinya, PlayerName?",
  str_homestory_817701001_15_option_content = "Anda harus melakukannya.",
  str_homestory_817701001_16_dialog_content = "Ada baiknya sesekali mencoba gaya baru!",
  str_homestory_817701001_17_option_content = "Tidak perlu menggantinya.",
  str_homestory_817701001_18_dialog_content = "Benar, saya bisa menangani gaya akrab saya dengan lebih percaya diri!",
  str_homestory_817701001_19_dialog_content = "Namun, itu semua tergantung dari tema album secara keseluruhan, bukan?",
  str_homestory_817701001_20_dialog_content = "Benar! Tema album baru ini adalah \"Growing Pains.\"",
  str_homestory_817701001_21_dialog_content = "Perusahaan menghabiskan banyak uang untuk menerbitkan album ini!",
  str_homestory_817701001_22_dialog_content = "Apa pendapat agen Anda?",
  str_homestory_817701001_23_dialog_content = "Agen saya mengatakan saya tidak perlu mengubah apa pun.",
  str_homestory_817701001_24_dialog_content = "Karena beberapa penggemar saya mungkin tidak menerima gaya baru...",
  str_homestory_817701001_25_dialog_content = "Itu saran yang agak konservatif.",
  str_homestory_817701001_26_dialog_content = "Tapi saya pikir penggemar Anda lebih suka Anda jujur pada diri sendiri.",
  str_homestory_817701001_27_dialog_content = "Apakah Anda berubah atau tidak, penggemar Anda akan mendukung Anda seperti yang selalu mereka lakukan!",
  str_homestory_817701001_28_dialog_content = "Jadi, Anda mungkin juga mengikuti kata hati Anda.",
  str_homestory_817701001_29_dialog_content = "Pilih gaya yang benar-benar Anda sukai.",
  str_homestory_817701001_30_dialog_content = "Baiklah!",
  str_homestory_817701001_31_dialog_content = "Itu menyelesaikannya! Saya akan memilih—",
  str_homestory_817701001_32_dialog_content = "Anda akan memilih—",
  str_homestory_817701001_33_dialog_content = "Lagu sinar matahari positif saya!",
  str_homestory_817701001_34_dialog_content = "Eh?",
  str_homestory_817701001_35_dialog_content = "Karena itulah aku sebenarnya!",
  str_homestory_817701001_36_dialog_content = "Itulah yang paling cocok untukku!",
  str_homestory_817701001_37_dialog_content = "Kurasa agenmu memang mengenalmu...",
  str_homestory_818001001_0_dialog_content = "Brandy?",
  str_homestory_818001001_1_dialog_content = "Hmm...? Haruskah saya meletakkan tongkat cahaya ini di sini? Apakah itu aneh?",
  str_homestory_818001001_2_dialog_content = "Sedang apa kau?",
  str_homestory_818001001_3_dialog_content = "Hai! Anda tepat waktu!",
  str_homestory_818001001_4_dialog_content = "Bantu aku melihatnya. Haruskah saya meletakkan light stick ini di kiri atau kanan?",
  str_homestory_818001001_5_option_content = "Kiri.",
  str_homestory_818001001_6_dialog_content = "Itu akan terlihat lebih baik di sebelah kanan.",
  str_homestory_818001001_7_option_content = "Semuanya sama.",
  str_homestory_818001001_8_dialog_content = "Kamu benar. Saya hanya akan meletakkannya di sebelah kanan.",
  str_homestory_818001001_9_dialog_content = "...",
  str_homestory_818001001_10_dialog_content = "Untuk apa kamu melakukan ini?",
  str_homestory_818001001_11_dialog_content = "Saya memotret untuk artikel \"Goldie Takes Cloud Gardens By Storm\" saya.",
  str_homestory_818001001_12_dialog_content = "Saat ini, saya sedang memotret barang dagangan penggemar Goldie.",
  str_homestory_818001001_13_dialog_content = "Ada light stick, lampu neon, stiker, kartu potret mini...",
  str_homestory_818001001_14_dialog_content = "Bahkan ada T-shirt dengan wajah Goldie di atasnya. Itu sangat lucu!",
  str_homestory_818001001_15_dialog_content = "Kalau dipikir-pikir. Saya merasa seperti saya masih kekurangan orang yang berdiri Goldie seukuran aslinya.",
  str_homestory_818001001_16_dialog_content = "Aku hanya perlu mengambil satu dan menyelundupkannya kembali ke kamarku... <sprite=emo_sikao size=60 />",
  str_homestory_818001001_17_dialog_content = "Oh tidak! Bukankah seharusnya ada Goldie seukuran orang yang berdiri di sekitar sini!?",
  str_homestory_818001001_18_dialog_content = "Mungkinkah itu direnggut oleh penggemar yang berpikiran kotor?",
  str_homestory_818001001_19_dialog_content = "Sial! Bagaimana orang bisa melakukan hal seperti itu?",
  str_homestory_818001001_20_dialog_content = "Anda baru saja mengatakan bahwa itulah yang ingin Anda lakukan ...",
  str_homestory_818001001_21_dialog_content = "Lupakan. Saya hanya akan mengambil foto-foto ini dulu.",
  str_homestory_818001001_22_dialog_content = "Dia berdiri tepat di sebelah Anda, mengapa Anda perlu mengambil foto merchandise?",
  str_homestory_818001001_23_dialog_content = "Saya tidak berpikir Anda melakukan ini dengan cara yang benar.",
  str_homestory_818001001_24_dialog_content = "Anda tidak mengerti—ini adalah cara untuk menambahkan tingkat kontras. Itu sepenuhnya dapat mengekspresikan ...",
  str_homestory_818001001_25_dialog_content = "Eh? Tunggu sebentar!",
  str_homestory_818001001_26_dialog_content = "Ada apa?",
  str_homestory_818001001_27_dialog_content = "Gumpalan bayangan dari pepohonan itu mengenai lampu neon di tempat yang tepat.",
  str_homestory_818001001_28_dialog_content = "Cahaya dan bayangan menari di sepanjang papan, menghidupkan pemandangan dengan siluet pepohonan.",
  str_homestory_818001001_29_dialog_content = "Ini adalah waktu yang tepat untuk mengambil beberapa gambar!",
  str_homestory_818001001_30_dialog_content = "Tembakan yang luar biasa! Saya belum pernah melihat foto sesempurna ini sebelumnya!",
  str_homestory_818001001_31_dialog_content = "Ini hanya foto yang dibutuhkan artikel berita saya!",
  str_homestory_818001001_32_dialog_content = "Saya pikir artikel berita Anda membutuhkan foto Goldie yang sebenarnya...",
  str_homestory_818001001_33_dialog_content = "Saya selesai! Saya akan kembali dan mengembangkan foto-foto ini.",
  str_homestory_818001001_34_dialog_content = "Ngomong-ngomong, saya ingat melihat sesuatu di air dalam perjalanan ke sini. Anda harus pergi melihatnya.",
  str_homestory_818001001_35_dialog_content = "Kau tidak mendengarkanku sama sekali, kan...",
  str_homestory_818101001_0_dialog_content = "Zhong Xu?",
  str_homestory_818101001_1_dialog_content = "Lihat-lihat apa kau?",
  str_homestory_818101001_2_dialog_content = "Periksa rak.",
  str_homestory_818101001_3_dialog_content = "Apa istimewanya? <sprite=emo_sikao size=60 />",
  str_homestory_818101001_4_dialog_content = "Tunggu, aku melihat Yixin!",
  str_homestory_818101001_5_dialog_content = "Dia merangkak ke rak sementara aku tidak memperhatikan.",
  str_homestory_818101001_6_dialog_content = "Sungguh kucing yang nakal!",
  str_homestory_818101001_7_dialog_content = "Yimeng dan Yinuo juga ada di sana.",
  str_homestory_818101001_8_dialog_content = "Mereka sangat menyukai rak itu?",
  str_homestory_818101001_9_dialog_content = "Mungkin karena mereka menyukai tempat yang gelap dan sempit.",
  str_homestory_818101001_10_dialog_content = "Itu masuk akal. Rak berlapis, dan bagian dalamnya sangat gelap.",
  str_homestory_818101001_11_dialog_content = "Ini bisa berfungsi sebagai menara kucing jenis baru, mungkin?",
  str_homestory_818101001_12_dialog_content = "Kedengarannya logis.",
  str_homestory_818101001_13_dialog_content = "Saya akan meminta pengrajin untuk membuat model setelah ini.",
  str_homestory_818101001_14_dialog_content = "Tentu saja, Anda dipersilakan kapan saja!",
  str_homestory_818101001_15_dialog_content = "Saya tidak pernah berpikir rak bisa digunakan dengan cara ini.",
  str_homestory_818101001_16_dialog_content = "Terima kasih.",
  str_homestory_818101001_17_dialog_content = "Apakah ini akan merepotkan Anda?",
  str_homestory_818101001_18_option_content = "Sama sekali tidak!",
  str_homestory_818101001_19_option_content = "Sedikit.",
  str_homestory_818101001_20_dialog_content = "Maaf, saya akan pastikan untuk berbicara dengan mereka tentang hal itu.",
  str_homestory_818101001_21_dialog_content = "Sekarang pertanyaannya adalah... bagaimana kita mengeluarkan mereka?",
  str_homestory_818101001_22_dialog_content = "Mereka tidur begitu nyenyak.",
  str_homestory_818101001_23_dialog_content = "Biasanya mereka datang ketika saya memanggil nama mereka, tetapi mereka tidak terlalu responsif hari ini.",
  str_homestory_818101001_24_dialog_content = "Mungkin karena mereka terlalu mengenalmu.",
  str_homestory_818101001_25_dialog_content = "Maksud kamu apa? <sprite=emo_wuzui size=60 />",
  str_homestory_818101001_26_dialog_content = "Biasanya Anda memanggil nama mereka ketika Anda membutuhkan mereka untuk melakukan sesuatu.",
  str_homestory_818101001_27_dialog_content = "Hari ini, Anda hanya mencoba mengeluarkannya dari rak.",
  str_homestory_818101001_28_dialog_content = "Jadi mereka memilih untuk mengabaikan Anda.",
  str_homestory_818101001_29_dialog_content = "Kucing-kucing ini sangat pintar!",
  str_homestory_818101001_30_dialog_content = "... Rak ini tampaknya memiliki kekuatan yang jauh lebih kuat dari yang saya bayangkan.",
  str_homestory_818101001_31_dialog_content = "Saya harus menyiapkan replika untuk mereka.",
  str_homestory_818101001_32_dialog_content = "Apa yang akan kamu lakukan terhadap kucing-kucing itu?",
  str_homestory_818101001_33_dialog_content = "Saya akan menunggu mereka bangun, saya kira.",
  str_homestory_818101001_34_dialog_content = "Kemenangan gemilang untuk kucing!",
  str_homestory_818101001_35_dialog_content = "Sungguh pemandangan yang indah.",
  str_homestory_818101001_36_dialog_content = "Mereka yang tidak tahu apa yang terjadi mungkin berpikir Zhong Xu sedang memikirkan sesuatu yang filosofis lagi ...",
  str_homestory_818301001_0_dialog_content = "Liqing?",
  str_homestory_818301001_1_dialog_content = "Kemana perginya...?",
  str_homestory_818301001_2_dialog_content = "Kau sedang apa?",
  str_homestory_818301001_3_dialog_content = "H-Halo, PlayerName.",
  str_homestory_818301001_4_dialog_content = "Saya mencari Tinytail. Pernahkah kamu melihatnya?",
  str_homestory_818301001_5_dialog_content = "Tidak, apa yang terjadi?",
  str_homestory_818301001_6_dialog_content = "Dia mengendur lagi, itulah yang terjadi! <sprite=emo_shengqi size=60 />",
  str_homestory_818301001_7_dialog_content = "Saya membawanya ke taman untuk memetik beberapa tumbuhan.",
  str_homestory_818301001_8_dialog_content = "Dan kemudian dia pergi, begitu saja!",
  str_homestory_818301001_9_dialog_content = "Ada tumbuhan di Cloud Gardens?",
  str_homestory_818301001_10_dialog_content = "Tentu saja.",
  str_homestory_818301001_11_dialog_content = "Ramuan yang baik biasanya ditemukan di tempat yang paling tidak Anda duga.",
  str_homestory_818301001_12_dialog_content = "Anda hanya perlu sepasang mata yang bagus. <sprite=emo_mojing size=60 />",
  str_homestory_818301001_13_dialog_content = "Itu benar-benar terdengar seperti sesuatu yang akan Anda katakan.",
  str_homestory_818301001_14_dialog_content = "Omong-omong...",
  str_homestory_818301001_15_option_content = "Sudah berapa lama kamu mencarinya?",
  str_homestory_818301001_16_dialog_content = "Um, yah, sekitar tiga puluh menit...",
  str_homestory_818301001_17_dialog_content = "Itu waktu yang lama.",
  str_homestory_818301001_18_dialog_content = "Sebenarnya, mungkin... hanya sepuluh menit?",
  str_homestory_818301001_19_option_content = "Herbal apa yang Anda pilih?",
  str_homestory_818301001_20_dialog_content = "Um, j-hanya... jamu?",
  str_homestory_818301001_21_dialog_content = "Kenapa kau terus terbata-bata?",
  str_homestory_818301001_22_dialog_content = "Tidak!",
  str_homestory_818301001_23_dialog_content = "Mungkinkah itu...",
  str_homestory_818301001_24_dialog_content = "Anda juga mengendur?",
  str_homestory_818301001_25_dialog_content = "NN-Tidak. Tidak memungkinkan. Bukan kesempatan.",
  str_homestory_818301001_26_dialog_content = "Saya datang dengan Tinytail untuk memetik herbal!",
  str_homestory_818301001_27_dialog_content = "Namun…",
  str_homestory_818301001_28_dialog_content = "Tetapi...?",
  str_homestory_818301001_29_dialog_content = "Disini terlalu nyaman...",
  str_homestory_818301001_30_dialog_content = "Aku... mungkin punya <sprite=emo_kun size=60 /> tidur siang. Sebentar saja!",
  str_homestory_818301001_31_dialog_content = "Dan Tinytail sudah pergi saat aku bangun.",
  str_homestory_818301001_32_dialog_content = "Haha, jadi kalian berdua pemalas, begitu.",
  str_homestory_818301001_33_dialog_content = "Tidak, tidak ada!",
  str_homestory_818201001_0_dialog_content = "Sedang apa kau?",
  str_homestory_818201001_1_dialog_content = "Saya menikmati perasaan bernapas air.",
  str_homestory_818201001_2_dialog_content = "Aku tidak terlalu mengerti, tapi... kedengarannya keren.",
  str_homestory_818201001_3_dialog_content = "Pernahkah Anda merasakan pernapasan air sebelumnya?",
  str_homestory_818201001_4_option_content = "Ya.",
  str_homestory_818201001_5_dialog_content = "Benar-benar? Seperti apa rasanya?",
  str_homestory_818201001_6_dialog_content = "Dingin, menyegarkan, pelepas dahaga.",
  str_homestory_818201001_7_dialog_content = "Itu rasanya, bukan nafasnya.",
  str_homestory_818201001_8_option_content = "Tidak.",
  str_homestory_818201001_9_dialog_content = "Jika Anda ingin belajar, saya bisa mengajari Anda.",
  str_homestory_818201001_10_dialog_content = "Oke.",
  str_homestory_818201001_11_dialog_content = "Mari kita mulai sekarang.",
  str_homestory_818201001_12_dialog_content = "Sekarang? Saya tidak punya celana renang...",
  str_homestory_818201001_13_dialog_content = "Gerakan dasar darat bisa kita praktekkan dulu.",
  str_homestory_818201001_14_dialog_content = "Berdiri tegak, tarik napas dalam-dalam dan rasakan air mengalir.",
  str_homestory_818201001_15_dialog_content = "Itu tidak terlalu sulit. Saya pikir saya bisa melakukan itu.",
  str_homestory_818201001_16_dialog_content = "*Menghirup*",
  str_homestory_818201001_17_dialog_content = "*Menghembuskan*",
  str_homestory_818201001_18_dialog_content = "Sampai kapan aku harus berdiri seperti ini?",
  str_homestory_818201001_19_dialog_content = "10.000 jam.",
  str_homestory_818201001_20_dialog_content = "10.000 jam?!",
  str_homestory_818201001_21_dialog_content = "Dibutuhkan 10.000 jam untuk menjadi luar biasa dalam sesuatu.",
  str_homestory_818201001_22_dialog_content = "Aku tahu, tapi ini agak monoton... <sprite=emo_xinsui size=60 />",
  str_homestory_818201001_23_dialog_content = "Anda bisa menyerah sekarang jika Anda mau.",
  str_homestory_818201001_24_dialog_content = "Ada banyak hal yang menyenangkan, tetapi jalan menuju sukses biasanya tidak menyenangkan.",
  str_homestory_818201001_25_dialog_content = "Maaf, saya akan bekerja lebih keras.",
  str_homestory_818201001_26_dialog_content = "Apakah Anda menjalani pelatihan serupa untuk menjadi sangat baik di dalam air?",
  str_homestory_818201001_27_dialog_content = "Tidak, saya lahir dengan kemampuan.",
  str_homestory_818201001_28_dialog_content = "???",
  str_homestory_818201001_29_dialog_content = "Jadi, apakah Anda hanya mencoba menipu saya untuk berdiri di sini selama 10.000 jam?",
  str_homestory_818201001_30_dialog_content = "Tidak, seorang tetua Lin mengajari saya ini ketika saya pertama kali belajar berenang.",
  str_homestory_818201001_31_dialog_content = "Tapi saya terlahir dengan kemampuan beresonansi dengan air, jadi saya tidak perlu berlatih.",
  str_homestory_818201001_32_dialog_content = "Nah, jika sesepuh Lin mengatakannya, itu mungkin benar.",
  str_homestory_818201001_33_dialog_content = "Tetap berdiri saja...",
  str_homestory_818201001_34_dialog_content = "Kakiku sakit, biarkan aku istirahat. <sprite=emo_tanqi size=60 />",
  str_homestory_818201001_35_dialog_content = "Kemudian kita bisa berhenti di sini.",
  str_homestory_818201001_36_dialog_content = "Hah? Tapi tetua Lin berkata...",
  str_homestory_818201001_37_dialog_content = "Penatua tidak bisa berenang, jadi dia mungkin mengarangnya.",
  str_homestory_818201001_38_dialog_content = "!!!",
  str_homestory_818201001_39_dialog_content = "Saya mempertimbangkannya sebentar. Saya rasa Anda tidak dapat beresonansi dengan air meskipun Anda berdiri selama 10.000 jam.",
  str_homestory_818201001_40_dialog_content = "Beberapa hal yang Anda hanya perlu dilahirkan dengan. Anda tidak bisa memaksa mereka.",
  str_homestory_818201001_41_dialog_content = "Anda seharusnya mengatakan itu sebelumnya!",
  str_homestory_818201001_42_dialog_content = "Anda begitu fokus, saya tidak ingin menyela.",
  str_homestory_818201001_43_dialog_content = "Kamu...",
  str_homestory_818201001_44_dialog_content = "Ah... kakiku kram...",
  str_homestory_818201001_45_dialog_content = "Aku akan menggendongmu di punggungku.",
  str_homestory_818201001_46_dialog_content = "Tidak, tidak apa-apa...",
  str_homestory_818201001_47_dialog_content = "Sampai jumpa nanti.",
  str_homestory_818201001_48_dialog_content = "Um, tunggu, bisakah kamu turun?",
  str_homestory_816001001_0_dialog_content = "Michael?",
  str_homestory_816001001_1_dialog_content = "Lihat-lihat apa kau?",
  str_homestory_816001001_2_dialog_content = "(Ah, PlayerName.)",
  str_homestory_816001001_3_dialog_content = "(Saya mengagumi kandilnya.)",
  str_homestory_816001001_4_dialog_content = "Anda pasti sangat menyukainya. Apakah kamu menginginkannya?",
  str_homestory_816001001_5_dialog_content = "(Tidak, tolong izinkan saya untuk membayar. Berapa harganya?)",
  str_homestory_816001001_6_dialog_content = "(Apakah 1.000 Nightium cukup? <sprite=emo_baiyebi size=60 />)",
  str_homestory_816001001_7_dialog_content = "Tidak, Anda tidak perlu membayar sebanyak itu.",
  str_homestory_816001001_8_dialog_content = "Bahkan, saya tidak akan menjualnya kepada Anda jika Anda membayar.",
  str_homestory_816001001_9_dialog_content = "(Bagaimana bisa?)",
  str_homestory_816001001_10_dialog_content = "Mengapa Anda terlihat begitu sedih?",
  str_homestory_816001001_11_dialog_content = "Nah, kamu suka mengoleksi pernak-pernik, kan?",
  str_homestory_816001001_12_dialog_content = "Saya ingat melihat segala macam hal indah di kamar Anda.",
  str_homestory_816001001_13_dialog_content = "(Apakah hobi saya aneh?)",
  str_homestory_816001001_14_option_content = "(Mengonfirmasi)",
  str_homestory_816001001_15_dialog_content = "Banyak barang yang terlihat rusak, namun Anda tetap menyimpannya.",
  str_homestory_816001001_16_dialog_content = "Saya kira itu ... eksentrik.",
  str_homestory_816001001_17_option_content = "(Membantah)",
  str_homestory_816001001_18_dialog_content = "Semua orang punya hobinya masing-masing, menurutku itu tidak aneh.",
  str_homestory_816001001_19_dialog_content = "Saya pikir Anda kebetulan suka mengoleksi berbagai macam barang.",
  str_homestory_816001001_20_dialog_content = "(Saya hanya menganggapnya menarik, jadi saya ingin mengoleksinya.)",
  str_homestory_816001001_21_dialog_content = "(Tapi saya ingin membeli kandil karena alasan lain.)",
  str_homestory_816001001_22_dialog_content = "Alasan apa?",
  str_homestory_816001001_23_dialog_content = "(Lilin itu mudah terbakar, dan saya khawatir itu akan menyalakan api.<sprite=emo_nuhuo size=60 />)",
  str_homestory_816001001_24_dialog_content = "(Banyak bencana dimulai sebagai bahaya kecil yang tidak penting.)",
  str_homestory_816001001_25_dialog_content = "(Apakah itu sulit dimengerti?)",
  str_homestory_816001001_26_dialog_content = "Tidak, tidak juga.",
  str_homestory_816001001_27_dialog_content = "Jadi Anda khawatir tentang keselamatan saya?",
  str_homestory_816001001_28_dialog_content = "(Adalah tugas saya untuk melindungi Lumopolis.)",
  str_homestory_816001001_29_dialog_content = "(Kamu banyak membantuku, jadi melindungimu juga penting.)",
  str_homestory_816001001_30_dialog_content = "Kamu juga banyak membantuku.",
  str_homestory_816001001_31_dialog_content = "Anda tidak hanya mengatakan itu sebagai alasan untuk membeli candlestick, bukan?",
  str_homestory_816001001_32_dialog_content = "(Tentu saja tidak!)",
  str_homestory_816001001_33_dialog_content = "(Anda harus diperlakukan dengan hormat.)",
  str_homestory_816001001_34_dialog_content = "Mengapa kamu tersipu?",
  str_homestory_816001001_35_dialog_content = "(Itu karena... cahaya lilin.)",
  str_homestory_816001001_36_dialog_content = "(Ngomong-ngomong, saya melihat sesuatu yang berkilau di sungai.)",
  str_homestory_816001001_37_dialog_content = "(Sama seperti cahaya lilin.)",
  str_homestory_816001001_38_dialog_content = "Anda terus mengubah topik ...",
  str_homestory_818401001_0_dialog_content = "Hei, Jeriah.",
  str_homestory_818401001_1_dialog_content = "...",
  str_homestory_818401001_2_dialog_content = "Jeriah? Halo...?",
  str_homestory_818401001_3_dialog_content = "Hm? Ah, Caelestite kecil.",
  str_homestory_818401001_4_dialog_content = "Apa yang sedang kamu lakukan? Anda tampaknya benar-benar fokus.",
  str_homestory_818401001_5_dialog_content = "Benar... aku hanya melamun.",
  str_homestory_818401001_6_dialog_content = "Melamun?",
  str_homestory_818401001_7_dialog_content = "Apakah saya memberi tahu Anda bahwa saya pernah ke reruntuhan di dekat sini sebelumnya?",
  str_homestory_818401001_8_dialog_content = "Saat itu, Anda belum kembali.",
  str_homestory_818401001_9_dialog_content = "Hanya ada reruntuhan dan Eclipsites di sini <sprite=emo_kulou size=60 />.",
  str_homestory_818401001_10_dialog_content = "Sobat, aku bahkan tidak ingin berbicara tentang berapa banyak waktu dan usaha yang diperlukan untuk membersihkan tempat ini!",
  str_homestory_818401001_11_dialog_content = "Benar. Itu tidak mudah.",
  str_homestory_818401001_12_dialog_content = "Ngomong-ngomong, aku ingin menanyakan sesuatu padamu.",
  str_homestory_818401001_13_dialog_content = "Apakah menurut Anda merenovasi Cloud Gardens adalah upaya yang berarti?",
  str_homestory_818401001_14_dialog_content = "Itu indah sekarang, tapi jika diserang, atau seratus tahun dari sekarang saat kau pergi...",
  str_homestory_818401001_15_dialog_content = "semua yang ada di sini bisa kembali menjadi reruntuhan.",
  str_homestory_818401001_16_option_content = "Itu bermakna.",
  str_homestory_818401001_17_dialog_content = "Setidaknya sekarang, kita bisa bersenang-senang di sini.",
  str_homestory_818401001_18_dialog_content = "Jika ada musuh yang datang, saya akan mengusir mereka semua.",
  str_homestory_818401001_19_dialog_content = "Jika saya tidak bisa mengurus tempat ini, saya akan menyerahkannya kepada seseorang yang dapat saya percayai.",
  str_homestory_818401001_20_dialog_content = "Akan selalu ada jalan!",
  str_homestory_818401001_21_dialog_content = "Anda tentu optimis.",
  str_homestory_818401001_22_option_content = "Mungkin tidak.",
  str_homestory_818401001_23_dialog_content = "Mungkin tidak ada artinya jika tujuan kami adalah membuat Cloud Gardens ada selamanya.",
  str_homestory_818401001_24_dialog_content = "Aku sadar akan batas kemampuanku...",
  str_homestory_818401001_25_dialog_content = "Tapi setidaknya kami bahagia, untuk saat ini.",
  str_homestory_818401001_26_dialog_content = "Itu cukup bagi saya!",
  str_homestory_818401001_27_dialog_content = "Gagasan hidup di masa sekarang patut dipuji.",
  str_homestory_818401001_28_dialog_content = "Ketika saya pertama kali datang ke Eraveil, saya pikir itu memang tempat yang sangat menyedihkan.",
  str_homestory_818401001_29_dialog_content = "Peralatan makan terbalik, pintu setengah terbuka, tumpukan pakaian berantakan...",
  str_homestory_818401001_30_dialog_content = "Mereka mengingatkan saya bahwa dahulu kala, orang biasa pernah menikmati hidup bahagia di sini.",
  str_homestory_818401001_31_dialog_content = "Hari-hari itu... poof. Seperti dandelion <sprite=emo_pugongying size=60 />, mereka tertiup angin.",
  str_homestory_818401001_32_dialog_content = "Oke…",
  str_homestory_818401001_33_dialog_content = "Tapi dandelion membawa benih harapan ke negeri yang jauh.",
  str_homestory_818401001_34_dialog_content = "Semua ini tidak akan pernah menjadi tidak berarti!",
  str_homestory_818401001_35_dialog_content = "BENAR. Anda sendiri seperti benih kecil, kembali untuk bertunas lagi.",
  str_homestory_818401001_36_dialog_content = "Berbicara dengan Anda selalu merupakan pengalaman unik.",
  str_homestory_818401001_37_dialog_content = "Hehe, saya tersanjung.",
  str_homestory_818401001_38_dialog_content = "Hmm... Sebagai gantinya, izinkan saya memberi tahu Anda sesuatu yang mungkin menarik bagi Anda.",
  str_homestory_818401001_39_dialog_content = "Ketika saya berada di sungai tadi, saya melihat sesuatu yang bersinar di dalam air.",
  str_homestory_818401001_40_dialog_content = "Mungkin Anda bisa pergi dan melihat-lihat. Anggap saja sebagai petualangan!",
  str_homestory_818401001_41_dialog_content = "Kedengarannya menarik... Terima kasih, Jeriah!",
  str_homestory_818501001_0_dialog_content = "Ada apa?",
  str_homestory_818501001_1_dialog_content = "Aku hanya duduk di salah satu cangkir kopi yang berputar itu, dan sekarang aku merasa sedikit pusing <sprite=emo_xuanyun size=60 />...",
  str_homestory_818501001_2_dialog_content = "Pusing? Apakah mesin perlu penyesuaian?",
  str_homestory_818501001_3_dialog_content = "Saya ingat kecepatannya sudah diatur ke pengaturan paling lambat. Aku akan memeriksanya nanti.",
  str_homestory_818501001_4_dialog_content = "Hal-hal itu sangat berbahaya! Tolong hati-hati!",
  str_homestory_818501001_5_dialog_content = "Berbahaya?",
  str_homestory_818501001_6_dialog_content = "Bukankah hal-hal itu dimaksudkan untuk anak-anak berusia empat tahun ke atas?",
  str_homestory_818501001_7_dialog_content = "Aku ragu mereka cocok bahkan untuk anak berusia dua puluh tahun ke atas...",
  str_homestory_818501001_8_dialog_content = "Beberapa orang tidak bisa terbiasa dengan sensasi berputar. Itu sangat normal.",
  str_homestory_818501001_9_dialog_content = "Istirahat yang baik akan membantu.",
  str_homestory_818501001_10_dialog_content = "Oke. Aku akan pergi istirahat. Saya masih harus mengirimkan surat ke utara nanti ...",
  str_homestory_818501001_11_dialog_content = "Tunggu. Utara selatan...",
  str_homestory_818501001_12_dialog_content = "Oh tidak! Saya tidak bisa membedakan arah saya lagi!",
  str_homestory_818501001_13_dialog_content = "Saya dulu sangat bangga dengan indra pengarahan saya! Bagaimana ini bisa terjadi!?",
  str_homestory_818501001_14_dialog_content = "*terisak* <sprite=emo_daku size=60 />Jika saya bahkan tidak bisa mengirim surat, apa jadinya karir saya?",
  str_homestory_818501001_15_dialog_content = "Uh, itu sedikit dramatis...",
  str_homestory_818501001_16_dialog_content = "PlayerName, dapatkah Anda memberi tahu saya arah utara yang mana?",
  str_homestory_818501001_17_option_content = "Pergi ke kiri",
  str_homestory_818501001_18_dialog_content = "Apakah itu? Saya tidak bisa mengatakan sama sekali...",
  str_homestory_818501001_19_option_content = "Saya juga tidak tahu",
  str_homestory_818501001_20_dialog_content = "B-Bahkan kamu...",
  str_homestory_818501001_21_dialog_content = "Apakah kita akan berakhir terjebak di sini?",
  str_homestory_818501001_22_dialog_content = "???",
  str_homestory_818501001_23_dialog_content = "Apakah termasuk terjebak saat masih di rumah sendiri?",
  str_homestory_818501001_24_dialog_content = "Sekarang bahkan saya tidak begitu yakin di mana saya berada ...",
  str_homestory_818501001_25_dialog_content = "Kode Courier Union mengatakan kita harus selalu menjaga arah.",
  str_homestory_818501001_26_dialog_content = "Banyak kurir berakhir dalam situasi berbahaya tanpa tempat untuk lari hanya karena tersesat.",
  str_homestory_818501001_27_dialog_content = "Saya pikir hal semacam itu hanya terjadi ketika Anda berada di alam liar, seperti hutan yang luas.",
  str_homestory_818501001_28_dialog_content = "Kami berada di Cloud Gardens! Anda melihat pintu?",
  str_homestory_818501001_29_dialog_content = "Itu tepat di sana. Hanya mengambil beberapa langkah dan Anda akan keluar dari sini.",
  str_homestory_818501001_30_dialog_content = "Tetapi bagaimana jika saya pergi ke sana ke alam liar dan menjadi pusing seperti saya sekarang?",
  str_homestory_818501001_31_dialog_content = "Apakah ada cangkir kopi di alam liar?",
  str_homestory_818501001_32_dialog_content = "Oh, benar...",
  str_homestory_818501001_33_dialog_content = "Dan bahkan jika ada, jangan mengendarainya.",
  str_homestory_818501001_34_dialog_content = "Ya! Kamu sangat pintar!",
  str_homestory_818501001_35_dialog_content = "Hah, tentu...",
  str_homestory_818501001_36_dialog_content = "Ketika saya kembali, saya akan menambahkan aturan baru ke kode Courier Union—",
  str_homestory_818501001_37_dialog_content = "\"Jika Anda menemukan cangkir kopi berputar di hutan belantara, jangan duduk di dalamnya!\"",
  str_homestory_818501001_38_dialog_content = "Peluang menemukan cangkir kopi berputar di hutan belantara seharusnya cukup rendah...",
  str_homestory_818501001_39_dialog_content = "\"—Kebijaksanaan milik Caelestite.\"",
  str_homestory_818501001_40_dialog_content = "!!!",
  str_homestory_818501001_41_dialog_content = "Berapa banyak yang Anda ingin saya bayar untuk menjaga nama saya keluar dari ini !?",
  str_homestory_818501001_42_dialog_content = "Apa? Ini saran yang sangat berguna! Pokoknya aku libur...",
  str_homestory_818501001_43_dialog_content = "Oh, bagus... Aku akan menjadi bahan tertawaan Serikat Kurir...<sprite=emo_tanqi size=60 />",
  str_homestory_802901001_0_dialog_content = "Jibril?",
  str_homestory_802901001_1_dialog_content = "Apa-apaan ini, sedang apa kau?",
  str_homestory_802901001_2_dialog_content = "Saat ini saya sedang tidur siang di bawah pohon, <sprite=emo_kun size=60 />, hanya dengan santai menghirup nafas pohon.",
  str_homestory_802901001_3_dialog_content = "Nafas pohon?",
  str_homestory_802901001_4_dialog_content = "Betul... Pohon juga makhluk hidup.",
  str_homestory_802901001_5_dialog_content = "Saya bisa merasakan pola pernapasannya yang stabil. Apakah kamu merasakannya, PlayerName?",
  str_homestory_802901001_6_option_content = "Akui",
  str_homestory_802901001_7_dialog_content = "Saat daunnya bergetar, rasanya seperti bernapas lebih cepat.",
  str_homestory_802901001_8_dialog_content = "aku rasa itu hanya angin...",
  str_homestory_802901001_9_option_content = "Bantah",
  str_homestory_802901001_10_dialog_content = "Oh, aku tidak bisa merasakan apa-apa...",
  str_homestory_802901001_11_dialog_content = "Sepertinya kamu satu-satunya yang memiliki kemampuan spesial untuk merasakan tumbuhan, Gabriel...",
  str_homestory_802901001_12_dialog_content = "Setiap pohon berbeda, sama seperti setiap orang.",
  str_homestory_802901001_13_dialog_content = "Selama Anda merasakan dengan hati Anda... Anda bisa mengetahui dunia batin mereka.",
  str_homestory_802901001_14_dialog_content = "Misalnya, pernapasan pohon ini agak tersengal-sengal... Sepertinya agak sakit...",
  str_homestory_802901001_15_dialog_content = "Saya kira itu sebabnya daunnya agak kuning dibandingkan dengan pohon lain.",
  str_homestory_802901001_16_dialog_content = "Memang terlihat sedikit tak bernyawa.",
  str_homestory_802901001_17_dialog_content = "Pohon-pohon di sekitar sini benar-benar subur. Mereka menghalangi sinar matahari... <sprite=emo_taiyang size=60 />",
  str_homestory_802901001_18_dialog_content = "Sepertinya si kecil ini kesulitan melakukan fotosintesis!",
  str_homestory_802901001_19_dialog_content = "Jadi, apa menurutmu kita perlu memindahkan pohon ini ke tempat lain?",
  str_homestory_802901001_20_dialog_content = "Tidak, tanaman memiliki caranya sendiri dalam melakukan sesuatu.",
  str_homestory_802901001_21_dialog_content = "Pohon ini tidak bekerja cukup keras untuk tumbuh tinggi, sehingga pohon lain mencuri sinar matahari...",
  str_homestory_802901001_22_dialog_content = "Itu perlu mengandalkan dirinya sendiri untuk tumbuh lebih besar dan lebih kuat... Kita tidak boleh merusaknya terlalu banyak!",
  str_homestory_802901001_23_dialog_content = "Aku paham... Itu sangat masuk akal, Gabriel!",
  str_homestory_802901001_24_dialog_content = "Heh, aku khawatir mungkin terlalu sulit bagimu untuk mengerti, PlayerName...",
  str_homestory_802901001_25_dialog_content = "Saya mengerti! Tapi, yang membuatku sedikit terkejut adalah—",
  str_homestory_802901001_26_dialog_content = "Kamu biasanya terlihat seperti selalu berjalan dalam keadaan linglung, Gabriel, tapi hari ini kamu terlihat sangat serius.",
  str_homestory_802901001_27_dialog_content = "Saya pikir lebih akurat untuk mengatakan bahwa saya selalu bertindak sesuai dengan lingkungan saya...",
  str_homestory_802901001_28_dialog_content = "Tumbuhan juga punya takdirnya...",
  str_homestory_802901001_29_dialog_content = "Takdir...?",
  str_homestory_802901001_30_dialog_content = "Benar. Bertemu denganmu di bawah pohon ini—adalah bagian dari takdir pohon itu.",
  str_homestory_802901001_31_dialog_content = "Omong-omong, ketika saya sedang berjalan di sepanjang sungai sekarang, saya melihat sesuatu yang bersinar ...",
  str_homestory_802901001_32_dialog_content = "Bisakah Anda melihat apa itu?",
  str_homestory_802901001_33_dialog_content = "Yah, aku baru saja berencana mampir ke hutan untuk tidur sebentar!",
  str_homestory_802901001_34_dialog_content = "Fakta bahwa aku tidak memeriksa apa yang ada di sungai juga merupakan bagian dari rencana takdir!",
  str_homestory_802901001_35_dialog_content = "Saya pikir saya mengerti apa yang Anda maksud tentang takdir ...",
  str_homestory_818901001_0_dialog_content = "Apa yang kau lakukan, Leyn?",
  str_homestory_818901001_1_dialog_content = "Hai! Leyn!",
  str_homestory_818901001_2_dialog_content = "Minuman cokelat, pusat buah <sprite=emo_sikao size=60 />... Hah?",
  str_homestory_818901001_3_dialog_content = "Halo.",
  str_homestory_818901001_4_dialog_content = "Apa yang kamu lihat, Ley? Anda tampak begitu fokus.",
  str_homestory_818901001_5_dialog_content = "Tidak ada apa-apa, saya hanya melihat sekotak coklat ini.",
  str_homestory_818901001_6_dialog_content = "Itu dari Mooncrown Day.",
  str_homestory_818901001_7_dialog_content = "Jika Anda ingin memakannya, Leyn, bantulah diri Anda sendiri!",
  str_homestory_818901001_8_dialog_content = "Tidak, saya tidak ingin memakannya. Saya hanya tertarik dengan proses produksinya.",
  str_homestory_818901001_9_dialog_content = "Saya juga sering membuat makanan penutup cokelat di rumah.",
  str_homestory_818901001_10_dialog_content = "Tapi saya biasanya hanya menggunakan cokelat leleh untuk dekorasi.",
  str_homestory_818901001_11_dialog_content = "Saya tidak menyadari bahwa makanan penutup telah berkembang sejauh ini dalam hal seni.",
  str_homestory_818901001_12_dialog_content = "Saya katakan, apakah Anda suka cokelat?",
  str_homestory_818901001_13_option_content = "Aku suka ini!",
  str_homestory_818901001_14_dialog_content = "Dalam hal ini, segera setelah saya mempelajari beberapa teknik baru, saya akan membiarkan Anda mencobanya.",
  str_homestory_818901001_15_dialog_content = "Masih terlalu dini bagimu untuk minum minuman coklat...",
  str_homestory_818901001_16_dialog_content = "Kalau begitu, aku akan membawakanmu buah-buahan.",
  str_homestory_818901001_17_option_content = "Tidak terlalu suka...",
  str_homestory_818901001_18_dialog_content = "Oh... Sayang sekali.",
  str_homestory_818901001_19_dialog_content = "Lain kali, izinkan saya membawakan Anda makanan lain.",
  str_homestory_818901001_20_dialog_content = "Jika ada yang ingin Anda makan, beri tahu saya. Kapan pun Anda mau.",
  str_homestory_818901001_21_dialog_content = "Manis! Terima kasih, Leyn!",
  str_homestory_818901001_22_dialog_content = "Hmm…",
  str_homestory_818901001_23_dialog_content = "Apa masalahnya? Kenapa kamu masih menatap cokelat itu?",
  str_homestory_818901001_24_dialog_content = "Apakah Anda ... benar-benar ingin makan?",
  str_homestory_818901001_25_dialog_content = "Aku hanya sedikit ingin tahu tentang rasanya! <sprite=emo_hanshui size=60 />",
  str_homestory_818901001_26_dialog_content = "Saya pikir saya akan membeli sendiri sebuah kotak untuk melakukan penelitian lebih lanjut!",
  str_homestory_818901001_27_dialog_content = "Hei, kenapa kamu masih begitu sopan?",
  str_homestory_818901001_28_dialog_content = "Jika Anda ingin memakannya, makan saja!",
  str_homestory_818901001_29_dialog_content = "Setiap orang perlu memanjakan diri sesekali.",
  str_homestory_818901001_30_dialog_content = "Aku... anu...",
  str_homestory_818901001_31_dialog_content = "Terima kasih atas kebaikan Anda. Dalam hal ini, saya hanya akan membantu diri saya sendiri ...",
  str_homestory_818601001_0_dialog_content = "Tina?",
  str_homestory_818601001_1_dialog_content = "Kenapa kalian kemari?",
  str_homestory_818601001_2_dialog_content = "Halo yang disana, PlayerName!",
  str_homestory_818601001_3_dialog_content = "Kursi ini sangat penasaran.",
  str_homestory_818601001_4_dialog_content = "Maksudmu kursi pantai itu?",
  str_homestory_818601001_5_dialog_content = "Benar... Jadi, ini kursi pantai...",
  str_homestory_818601001_6_dialog_content = "Sejujurnya, saya tidak tahu apa-apa tentang pantai. Saya menghabiskan sebagian besar waktu saya di Lumopolis Hall of Justice.",
  str_homestory_818601001_7_dialog_content = "Apakah Anda sering pergi ke pantai, PlayerName?",
  str_homestory_818601001_8_option_content = "Saya pergi sepanjang waktu.",
  str_homestory_818601001_9_dialog_content = "Saya sering pergi ke pantai.",
  str_homestory_818601001_10_dialog_content = "Tepi laut adalah yang terbaik!",
  str_homestory_818601001_11_option_content = "Tidak terlalu.",
  str_homestory_818601001_12_dialog_content = "Sebenarnya, tidak, saya tidak sering pergi.",
  str_homestory_818601001_13_dialog_content = "Tapi pantainya cukup menyenangkan. Saya memiliki beberapa kenangan indah tentang waktu saya di pantai.",
  str_homestory_818601001_14_dialog_content = "Oke!",
  str_homestory_818601001_15_dialog_content = "Jika aku bisa pergi ke pantai bersamamu, PlayerName, itu akan membengkak!",
  str_homestory_818601001_16_dialog_content = "Tapi aku masih punya banyak kasus untuk ditangani di Balai Kehakiman. Saya sangat sibuk!",
  str_homestory_818601001_17_dialog_content = "Mungkin kita akan memiliki kesempatan untuk pergi bersama di masa depan.",
  str_homestory_818601001_18_dialog_content = "Tapi pakaian renang yang dikenakan semua orang di pantai... Apa kau yakin tidak masalah dengan itu?",
  str_homestory_818601001_19_dialog_content = "Baju renang... Aku membaca tentang itu di buku. Mereka cukup minim<sprite=emo_qunzi size=60 />, bukan?",
  str_homestory_818601001_20_dialog_content = "Benar... Pakaian bangsawan Lumopolis mungkin sedikit terlalu pengap untuk pantai...",
  str_homestory_818601001_21_dialog_content = "Saya sepenuhnya memahami bahwa pakaian yang berbeda harus dikenakan pada kesempatan yang berbeda, tetapi saya tidak keberatan sama sekali.",
  str_homestory_818601001_22_dialog_content = "Namun, para tetua mungkin menuduh saya mengabaikan kode etiket mereka. Memikirkan ejekan mereka membuatku merinding...",
  str_homestory_818601001_23_dialog_content = "*uhuk* Kamu tidak perlu berpikir sejauh itu, Tina...",
  str_homestory_818601001_24_dialog_content = "Lagi pula, kita bahkan tidak tahu kapan kita akan pergi ke pantai ...",
  str_homestory_818601001_25_dialog_content = "Kau benar!",
  str_homestory_818601001_26_dialog_content = "Jadi... Apakah Anda ingin mencoba kursi pantai itu, atau apa?",
  str_homestory_818601001_27_dialog_content = "Ya! Saya ingin mencobanya!",
  str_homestory_818601001_28_dialog_content = "Ini tidak selembut kursi malas khusus saya, tapi masih sangat nyaman!",
  str_homestory_818601001_29_dialog_content = "Bahan ini membuatnya lebih praktis untuk pantai.",
  str_homestory_818601001_30_dialog_content = "Hei, Tina! Apakah Anda mendengarkan saya?",
  str_homestory_818601001_31_dialog_content = "Dia tertidur lelap...",
  str_homestory_819001001_0_dialog_content = "Matthieu?",
  str_homestory_819001001_1_dialog_content = "Kau tepat waktu.",
  str_homestory_819001001_2_dialog_content = "Paviliun tua yang telah dipugar ini tidak terlalu lusuh, tidak terlalu lusuh sama sekali... Ini adalah tempat yang sempurna untuk minum teh dan membaca buku yang bagus.",
  str_homestory_819001001_3_dialog_content = "Tapi itu masih membutuhkan sesuatu untuk membuatnya lebih sempurna—",
  str_homestory_819001001_4_dialog_content = "Ada apa?",
  str_homestory_819001001_5_dialog_content = "Agak menjemukan saat ini, bukan begitu?",
  str_homestory_819001001_6_option_content = "Kurasa tidak.",
  str_homestory_819001001_7_option_content = "Saya bisa melakukannya dengan sedikit lebih banyak hiasan.",
  str_homestory_819001001_8_dialog_content = "Saya akan membawa beberapa bantal. Itu seharusnya cukup, bukan?",
  str_homestory_819001001_9_dialog_content = "Saya berencana untuk menghiasinya dengan bunga dan tanaman langka, dan set teh emas dan perak, untuk digunakan para bangsawan di kapal.",
  str_homestory_819001001_10_dialog_content = "Bunga dan tumbuhan langka, perangkat teh emas dan perak... Bukankah itu terlalu mewah?",
  str_homestory_819001001_11_dialog_content = "Apakah Anda khawatir dengan biayanya? <sprite=emo_baiyebi size=60 /> Anda benar-benar Caelestite yang hemat, bukan?",
  str_homestory_819001001_12_dialog_content = "Anda tidak perlu khawatir tentang uang. Aku akan mengurus itu.",
  str_homestory_819001001_13_dialog_content = "Bukan hanya uangnya. Tentu saja, fakta bahwa itu akan menghabiskan banyak uang adalah masalah tersendiri.",
  str_homestory_819001001_14_dialog_content = "Tapi karena Anda bisa mengurusnya, itu bukan masalah. Namun...",
  str_homestory_819001001_15_dialog_content = "Maksudmu apa sih?",
  str_homestory_819001001_16_dialog_content = "Ini adalah Cloud Gardens, tempat semua orang mencoba yang terbaik untuk hidup bersama.",
  str_homestory_819001001_17_dialog_content = "Tidak semua orang tertarik pada hal-hal seperti karangan bunga dan peralatan makan emas dan perak..",
  str_homestory_819001001_18_dialog_content = "Saya tidak ingin membuatnya terlalu mewah, saya juga tidak ingin membuat Aurorian tertentu merasa tidak nyaman.",
  str_homestory_819001001_19_dialog_content = "Apakah Anda memikirkan mereka yang belum menikmati kehidupan sehari-hari?",
  str_homestory_819001001_20_dialog_content = "Dikelilingi oleh bunga dan emas dan perak bukanlah kehidupan sehari-hari...",
  str_homestory_819001001_21_dialog_content = "Bagaimanapun, saya akan mengirim seseorang untuk segera memulai pekerjaan dekorasi.",
  str_homestory_819001001_22_dialog_content = "Tunggu sebentar... Saya yang bertanggung jawab di sini—saya memegang keputusan akhir dalam semua keputusan.",
  str_homestory_819001001_23_dialog_content = "Jika Anda ingin terus tinggal di sini bersama kami, Anda perlu belajar bagaimana hidup dengan orang yang berbeda.",
  str_homestory_819001001_24_dialog_content = "Hmm? Mengapa kata-kata serius seperti itu tiba-tiba?",
  str_homestory_819001001_25_dialog_content = "Tunggu... Apa kau hanya... <size=45>meniru Schwab</size>!?",
  str_homestory_819001001_26_dialog_content = "Hmm? Apa yang kamu bicarakan?",
  str_homestory_819001001_27_dialog_content = "Saya pernah mendengar bahwa Schwab juga suka membaca di paviliun yang penuh dengan bunga, dan selalu ada banyak gadis muda yang berbondong-bondong mendatanginya ketika dia melakukannya.",
  str_homestory_819001001_28_dialog_content = "Jadi, kau mencoba membuat gadis-gadis tergila-gila padamu juga?",
  str_homestory_819001001_29_dialog_content = "Anda ingin sepopuler Schwab, jadi Anda meniru dia.",
  str_homestory_819001001_30_dialog_content = "Oh, begitu…",
  str_homestory_819001001_31_dialog_content = "Apa!? Jangan menatapku seperti itu—seperti kau baru saja memecahkan kasus besar! <sprite=emo_shengqi size=60 />",
  str_homestory_819001001_32_dialog_content = "Bukan itu masalahnya sama sekali! Mengapa saya ingin menjadi orang bodoh seperti itu?",
  str_homestory_819001001_33_dialog_content = "Kata \"bodoh\" terdengar seperti penghinaan pada awalnya.",
  str_homestory_819001001_34_dialog_content = "Tetapi beberapa orang menggunakannya untuk menyamarkan kesukaan mereka pada orang lain.",
  str_homestory_819001001_35_dialog_content = "Aku mulai merasa sakit tiba-tiba...",
  str_homestory_819001001_36_dialog_content = "Saya seorang sarjana terkemuka dari Dawn Academy!",
  str_homestory_819001001_37_dialog_content = "Mengapa saya meniru orang bodoh yang hanya peduli menjaga citranya di depan sekelompok wanita yang berubah-ubah !?",
  str_homestory_819001001_38_dialog_content = "Lalu, mengapa Anda perlu mendekorasi paviliun tua dengan bunga dan peralatan minum teh yang mewah?",
  str_homestory_819001001_39_dialog_content = "Ini hanya masalah kesukaanku sebagai seorang bangsawan, tentu saja!",
  str_homestory_819001001_40_dialog_content = "Lupakan. Hiasi sesuka Anda.",
  str_homestory_819001001_41_dialog_content = "Saya tidak peduli.",
  str_homestory_819001001_42_dialog_content = "(Terlalu banyak protes? Melihat betapa bingungnya dia, dia jelas tidak mungkin menyarankan semua ini hanya karena dia ingin membaca di suatu tempat, bukan?)",
  str_homestory_819101001_0_dialog_content = "Hati?",
  str_homestory_819101001_1_dialog_content = "Kau sedang apa?",
  str_homestory_819101001_2_dialog_content = "Oh, hanya berbicara dengan sebuah buku di rak buku.",
  str_homestory_819101001_3_dialog_content = "Uh... Bagaimana tepatnya caramu berbicara dengan buku?<sprite=emo_yihuo size=60 />",
  str_homestory_819101001_4_dialog_content = "Mudah! Anda cukup mengajukan pertanyaan, dan jawabannya akan muncul di halamannya! Kadang jawabannya terlalu benar sampai merinding.",
  str_homestory_819101001_5_dialog_content = "Jadi apa yang Anda tanyakan itu?",
  str_homestory_819101001_6_dialog_content = "Saya ingin mendengar sebuah cerita, jadi saya memintanya untuk menceritakannya kepada saya.",
  str_homestory_819101001_7_dialog_content = "Cerita seperti apa? Apakah itu menakutkan?",
  str_homestory_819101001_8_dialog_content = "Anda tidak takut?",
  str_homestory_819101001_9_option_content = "Mungkin agak tak nyata...",
  str_homestory_819101001_10_dialog_content = "Tapi tetap saja, aku penasaran.",
  str_homestory_819101001_11_option_content = "Tidak mungkin!",
  str_homestory_819101001_12_dialog_content = "Apa Anda sedang bercanda? Bagaimana mungkin pria tangguh seperti saya takut pada buku?",
  str_homestory_819101001_13_dialog_content = "Kisah yang diceritakannya barusan berjalan seperti ini...",
  str_homestory_819101001_14_dialog_content = "\"Pada malam musim dingin yang dingin, kamu berdiri di depan rak buku, membaca Buku Yang Maha Tahu ...\"",
  str_homestory_819101001_15_dialog_content = "\"Ketika tiba-tiba, kamu melihat sesuatu bergerak di belakangmu. Saat itulah kata-kata perlahan mulai muncul di halaman ...\"",
  str_homestory_819101001_16_dialog_content = "\"Jangan berbalik. <size=45>Seseorang</size> ada di belakangmu.\"",
  str_homestory_819101001_17_dialog_content = "\"Terlepas dari ketakutanmu, kamu tidak bisa tidak berbalik dan melihat.\"",
  str_homestory_819101001_18_dialog_content = "Itu sejauh yang saya dapatkan dalam cerita. Ketika saya berbalik untuk melihat, saat itulah Anda masuk ke kamar.",
  str_homestory_819101001_19_dialog_content = "Ha ha ha! Kedengarannya seperti novel ketegangan yang khas, tetapi dengan sentuhan kehidupan nyata. Apa yang terjadi selanjutnya?",
  str_homestory_819101001_20_dialog_content = "\"Orang di belakangmu tidak lain adalah tuan tanahmu.\"",
  str_homestory_819101001_21_dialog_content = "\"Tapi tidak perlu takut. Tuan tanahmu lemah, dan kamu bisa membuatnya terbang dengan satu pukulan.\"",
  str_homestory_819101001_22_dialog_content = "Tunggu apa?! Sekarang Anda hanya mengada-ada!",
  str_homestory_819101001_23_dialog_content = "Tapi tetap saja, hampir menakutkan betapa pasnya ceritanya! Itu sebabnya saya tidak bisa meletakkan cerita ini!",
  str_homestory_819101001_24_dialog_content = "\"Untuk membalas dendam pada tuan tanah karena mengejutkanmu, kamu memutuskan untuk memberinya pukulan cepat.\"",
  str_homestory_819101001_25_dialog_content = "\"Sayangnya, pukulan ringanmu menjatuhkannya ke tanah. Sebagai pembalasan, dia menendangmu keluar dari rumahmu dan ke jalanan yang membekukan, di mana kamu masuk angin dan mati.\"",
  str_homestory_819101001_26_dialog_content = "Ini menyeramkan, ya? Oh, jangan khawatir, Tuan Pemilik; Aku tidak akan pernah bermimpi memukulmu.",
  str_homestory_819101001_27_dialog_content = "Dan aku juga tidak akan mengusirmu! Tidak, tunggu sebentar—tidak mungkin kau bisa menjatuhkanku dengan satu pukulan!",
  str_homestory_819101001_28_dialog_content = "Ingin mencobanya?",
  str_homestory_819101001_29_dialog_content = "Ayo lakukan!<sprite=emo_dianzan size=60 />",
  str_homestory_819101001_30_dialog_content = "Baiklah, tetapi Anda memintanya! Biarkan saya melonggarkan pergelangan tangan saya.",
  str_homestory_819101001_31_dialog_content = "Aku sedang berbicara tentang Kitab Yang Maha Mengetahui itu!",
  str_homestory_819101001_32_dialog_content = "Oh? Jadi apa yang ingin kau tanyakan itu?",
  str_homestory_819101001_33_dialog_content = "Bisakah itu benar-benar menjawab pertanyaan apa pun?",
  str_homestory_819101001_34_dialog_content = "Anda tahu, saya sedikit terikat sekarang. Vice meminta saya untuk memilah keuangan Colossus untuk bulan ini...",
  str_homestory_819101001_35_dialog_content = "Saya mendengar Anda menyebutkan sesuatu tentang itu di kafetaria, ya.",
  str_homestory_819101001_36_dialog_content = "Jadi itu adalah hal pertama yang saya tanyakan, dan itu menjawab—",
  str_homestory_819101001_37_dialog_content = "\"Saya hanyalah sebuah buku. Saya tidak memiliki aset, jadi saya tidak memiliki cara untuk membantu Anda menyeimbangkan keuangan Anda.\"",
  str_homestory_819101001_38_dialog_content = "Tch... Dan di sini saya pikir itu bisa menjawab pertanyaan apapun!",
  str_homestory_819101001_39_dialog_content = "Tidak perlu menanyakan Kitab Yang Maha Mengetahui. Saya bisa menjawab pertanyaan Anda, tidak masalah.",
  str_homestory_819101001_40_dialog_content = "Ah, benarkah? Mari kita dengarkan kalau begitu.",
  str_homestory_819101001_41_dialog_content = "Pengeluaran Colossus benar-benar di luar kendali, dan Anda berada di ambang kebangkrutan. Akhirnya, Anda akan berakhir di jalan yang membekukan, tempat Anda masuk angin dan mati.",
  str_homestory_819101001_42_dialog_content = "Jangan hanya mencuri dari Kitab Yang Maha Tahu!",
  str_homestory_819101001_43_dialog_content = "Yah, itu jawaban yang cukup pas, bukan begitu?",
  str_homestory_819101001_44_dialog_content = "Bukan yang Anda... harapkan? Huu huu...",
  str_homestory_817702001_0_dialog_content = "Hei, sepertinya aku mendengar Goldie nyanyian!",
  str_homestory_817702001_1_dialog_content = "♪ La-la-laaa! ♪",
  str_homestory_817702001_2_dialog_content = "Oh, PlayerName! Halo yang disana.",
  str_homestory_817702001_3_dialog_content = "Hai, Goldie!",
  str_homestory_817702001_4_dialog_content = "Maaf, saya tidak mengganggu Anda, kan?",
  str_homestory_817702001_5_dialog_content = "Tidak sama sekali, tidak sama sekali!",
  str_homestory_817702001_6_dialog_content = "Saya hanya bisa mulai bernyanyi ketika saya melihat biola di sini!",
  str_homestory_817702001_7_dialog_content = "Sejujurnya, saya sangat terkejut mengetahui Anda memilikinya, PlayerName.",
  str_homestory_817702001_8_dialog_content = "Mungkinkah... Anda tertarik dengan instrumen?",
  str_homestory_817702001_9_option_content = "Saya!",
  str_homestory_817702001_10_dialog_content = "Tentu saja! Saya suka instrumen!",
  str_homestory_817702001_11_dialog_content = "Tapi saya tidak bisa memainkan salah satu dari mereka, jadi itu bukan hobi, heheh...",
  str_homestory_817702001_12_dialog_content = "Tapi itu masih hal yang luar biasa!",
  str_homestory_817702001_13_dialog_content = "Sepertinya kita memiliki kesamaan lain, PlayerName!",
  str_homestory_817702001_14_option_content = "Tidak terlalu.",
  str_homestory_817702001_15_dialog_content = "Yah, aku tidak akan menyebutnya minat, sungguh...",
  str_homestory_817702001_16_dialog_content = "Tetapi jika saya pernah belajar memainkan alat musik, Anda akan menjadi orang pertama yang mendengarnya!",
  str_homestory_817702001_17_dialog_content = "Benar-benar? Heehee... Aku sangat tersanjung! Terima kasih!",
  str_homestory_817702001_18_dialog_content = "Saya harus menyebutkan sesuatu, meskipun ...",
  str_homestory_817702001_19_dialog_content = "Ini bukan sembarang biola biasa.",
  str_homestory_817702001_20_dialog_content = "Itu sebenarnya bagian dari koleksi detektif terkenal!",
  str_homestory_817702001_21_dialog_content = "Seorang detektif?",
  str_homestory_817702001_22_dialog_content = "Itu benar! Rupanya, detektif ini sangat suka memainkannya setiap kali mereka tidak sedang menyelidiki kasus.",
  str_homestory_817702001_23_dialog_content = "Saya tidak benar-benar tahu banyak tentang mereka ...",
  str_homestory_817702001_24_dialog_content = "Tapi seorang detektif dengan hasrat pada seni — kedengarannya romantis <sprite=emo_aixin size=60 />!",
  str_homestory_817702001_25_dialog_content = "Aku setuju!",
  str_homestory_817702001_26_dialog_content = "Seorang detektif yang tenang dan rasional yang menghabiskan malam mereka sendirian, hanya dengan biola untuk menemani mereka...",
  str_homestory_817702001_27_dialog_content = "Tunggu sebentar... Itu dia! Itulah inspirasi yang saya butuhkan!",
  str_homestory_817702001_28_dialog_content = "Inspirasi apa?",
  str_homestory_817702001_29_dialog_content = "Inspirasi untuk saya <sprite=emo_yinfu size=60 /> lagu baru!",
  str_homestory_817702001_30_dialog_content = "Saya harus memesan kostum baru dan membuat koreografi baru juga!",
  str_homestory_817702001_31_dialog_content = "Aku menjadi sangat bersemangat hanya dengan memikirkannya!",
  str_homestory_817702001_32_dialog_content = "Konser idol bertema detektif ya?",
  str_homestory_817702001_33_dialog_content = "Saya yakin itu akan menjadi hit besar!",
  str_homestory_817702001_34_dialog_content = "Jika ada yang bisa melakukannya, itu Anda Goldie!",
  str_homestory_817702001_35_dialog_content = "Heehee! Berharap untuk melihat Anda di penonton ketika hari itu tiba!",
  str_homestory_811602001_0_dialog_content = "Apa Fleur lakukan di sana?",
  str_homestory_811602001_1_dialog_content = "Hai, Fleur! Apa yang sedang kamu lakukan?",
  str_homestory_811602001_2_dialog_content = "Hoi, Navigator!",
  str_homestory_811602001_3_dialog_content = "Saya menyesuaikan ornamen.",
  str_homestory_811602001_4_dialog_content = "Saya mengambilnya untuk bermain dengannya sekarang ...",
  str_homestory_811602001_5_dialog_content = "Dan itu membuat suara aneh.",
  str_homestory_811602001_6_dialog_content = "Suara aneh?",
  str_homestory_811602001_7_dialog_content = "Itu benar. Mungkin salah satu sekrupnya terlalu kencang, atau mungkin hanya perlu sedikit oli...",
  str_homestory_811602001_8_dialog_content = "Roda ini terus mengeluarkan suara mencicit yang mengerikan.",
  str_homestory_811602001_9_option_content = "Oke!",
  str_homestory_811602001_10_dialog_content = "Sekarang setelah Anda menyebutkannya, ornamen ini memang terlihat sedikit aneh...",
  str_homestory_811602001_11_dialog_content = "Jika mengeluarkan suara seperti itu, bukankah itu berarti salah satu bagiannya dalam kondisi buruk?",
  str_homestory_811602001_12_dialog_content = "Benar sekali!",
  str_homestory_811602001_13_dialog_content = "Kebanyakan orang kesulitan memahami sebanyak itu, tetapi sepertinya Anda memiliki keahlian untuk memperbaiki mesin.",
  str_homestory_811602001_14_dialog_content = "K-Kamu pikir begitu? Hehehe...",
  str_homestory_811602001_15_option_content = "aku tidak tahu apa-apa...",
  str_homestory_811602001_16_dialog_content = "Kau pikir begitu...?",
  str_homestory_811602001_17_dialog_content = "Serahkan pada ahli seperti Anda untuk mengetahuinya, Fleur. Saya putus asa ketika datang ke hal semacam ini.",
  str_homestory_811602001_18_dialog_content = "Aku mengerti... Aku berharap untuk berbicara denganmu tentang mesin, tapi kurasa itu diluar pertanyaan.",
  str_homestory_811602001_19_dialog_content = "Jangan khawatir, saya masih bisa memperbaiki hal ini sendiri.",
  str_homestory_811602001_20_dialog_content = "Hmm... Sepertinya aku benar. Sekrup ini terlalu kencang...",
  str_homestory_811602001_21_dialog_content = "Sayang sekali saya tidak memiliki alat untuk melonggarkannya sekarang.",
  str_homestory_811602001_22_dialog_content = "Saya akan kembali dan memperbaikinya setelah saya menemukan alat yang tepat, oke?",
  str_homestory_811602001_23_dialog_content = "Hal yang pasti, Fleur. Terima kasih lagi!",
  str_homestory_811602001_24_dialog_content = "Jangan sebutkan itu. Lagipula itu hanya sekrup kecil.",
  str_homestory_811602001_25_dialog_content = "Tetap saja, satu sekrup kecil bisa sangat berbeda dalam hal mesin, Anda tahu?",
  str_homestory_811602001_26_dialog_content = "Syukurlah itu hanya mainan, jika itu adalah gerobak yang sebenarnya...",
  str_homestory_811602001_27_dialog_content = "Rodanya pasti sudah rusak sekarang! Ha ha ha!",
  str_homestory_811602001_28_dialog_content = "Tidak bercanda. Orang normal seperti kita hanya tahu bahwa ada sesuatu yang perlu diperbaiki ketika akhirnya rusak...",
  str_homestory_811602001_29_dialog_content = "Andai saja semua mesin bisa menunjukkan masalahnya kepada kita seperti Soroz...",
  str_homestory_811602001_30_dialog_content = "Benarkah?",
  str_homestory_811602001_31_dialog_content = "Jika Anda bertanya kepada saya, orang jauh lebih sulit untuk dipahami <sprite=emo_sikao size=60 />...",
  str_homestory_811602001_32_dialog_content = "Jangan salah paham, memberikan kepribadian pada setiap mesin akan menjadi pencapaian yang luar biasa...",
  str_homestory_811602001_33_dialog_content = "Tapi hal terakhir yang saya butuhkan adalah mesin berbohong kepada saya saat saya sedang mengerjakannya!",
  str_homestory_811602001_34_dialog_content = "Hehehe, itu benar.",
  str_homestory_811602001_35_dialog_content = "Jika hari itu tiba, saya yakin Anda akan siap menghadapi masalah.",
  str_homestory_808401001_0_dialog_content = "Anda juga suka teka-teki, Istvan?",
  str_homestory_808401001_1_dialog_content = "Anda tepat waktu, teman muda saya.",
  str_homestory_808401001_2_dialog_content = "Katakan padaku, apa pendapatmu tentang gambar ini?",
  str_homestory_808401001_3_dialog_content = "Apa yang saya dapatkan dari itu? Biarku lihat...",
  str_homestory_808401001_4_option_content = "Terlihat sedikit menantang.",
  str_homestory_808401001_5_dialog_content = "Saya pikir beberapa petunjuk ini terlihat sedikit mencurigakan <sprite=emo_sikao size=60 />.",
  str_homestory_808401001_6_dialog_content = "Saya yakin saya bisa mengetahuinya dengan sedikit lebih banyak waktu!",
  str_homestory_808401001_7_option_content = "Aku tak paham.",
  str_homestory_808401001_8_dialog_content = "Er... Aku bukan yang terbaik dalam memecahkan teka-teki <sprite=emo_tanqi size=60 />.",
  str_homestory_808401001_9_dialog_content = "Aku tidak bisa membungkus kepalaku dengan yang satu ini sama sekali...",
  str_homestory_808401001_10_dialog_content = "Aku tahu.",
  str_homestory_808401001_11_dialog_content = "Permintaan maaf saya. Anda mengajukan pertanyaan kepada saya terlebih dahulu, dan saya menjawabnya dengan pertanyaan lain.",
  str_homestory_808401001_12_dialog_content = "Saya kira saya seharusnya memberi Anda jawaban yang sebenarnya ...",
  str_homestory_808401001_13_dialog_content = "Tidak, temanku. Saya sama sekali tidak menyukai teka-teki.",
  str_homestory_808401001_14_dialog_content = "Hah? Lalu mengapa kamu masih mencoba mencari tahu ?!",
  str_homestory_808401001_15_dialog_content = "Yakinlah, teman mudaku, ada penjelasan yang sangat masuk akal untuk ini.",
  str_homestory_808401001_16_dialog_content = "Menilai dari kata-kata Anda sendiri barusan, Anda berasumsi bahwa gambar ini adalah petunjuk teka-teki.",
  str_homestory_808401001_17_dialog_content = "Artinya, Anda secara tidak sengaja melihatnya dari sudut pandang seorang detektif.",
  str_homestory_808401001_18_dialog_content = "Er... Itu benar, kurasa?",
  str_homestory_808401001_19_dialog_content = "Namun, ada banyak karakter lain yang terlibat dalam kasus ini.",
  str_homestory_808401001_20_dialog_content = "Detektif, pelaku, korban...",
  str_homestory_808401001_21_dialog_content = "Dan, tentu saja, penghasutnya.",
  str_homestory_808401001_22_dialog_content = "Pemicunya?",
  str_homestory_808401001_23_dialog_content = "Memang. Seperti seorang gembala, penghasut bertanggung jawab atas segalanya, dan mendapat manfaat darinya lebih dari siapa pun.",
  str_homestory_808401001_24_dialog_content = "Memelihara domba dengan hati-hati dengan tangan, menggiring mereka dengan anjing yang setia, melindungi mereka dari serigala lapar...",
  str_homestory_808401001_25_dialog_content = "Seorang gembala yang baik tidak pernah menyerahkan kawanannya pada keinginan takdir.",
  str_homestory_808401001_26_dialog_content = "Itulah sebabnya, alih-alih memecahkan teka-teki, penghasut malah memilih jawaban yang paling menguntungkan dirinya.",
  str_homestory_808401001_27_dialog_content = "I-Itu sangat rumit!",
  str_homestory_808401001_28_dialog_content = "Tapi saya pikir saya mengerti apa yang ingin Anda katakan, Istvan...",
  str_homestory_808401001_29_dialog_content = "Untuk seorang pemimpin seperti Anda, terkadang kebenaran tidak sepenting hasil akhir, bukan?",
  str_homestory_808401001_30_dialog_content = "Keterampilan deduksi Anda setajam sebelumnya.",
  str_homestory_808401001_31_dialog_content = "Meskipun Anda masih muda, dan kemungkinan masa depan Anda hampir tidak terbatas.",
  str_homestory_808401001_32_dialog_content = "Saya hanya berharap seorang Navigator seperti Anda belajar bagaimana memindahkan bidak lain untuk keuntungan Anda sendiri.",
  str_homestory_808401001_33_dialog_content = "Untuk menikmati kesenangan biasa-biasa saja banyak domba, bukan gembala.",
  str_homestory_808401001_34_dialog_content = "Heheheh... Terima kasih, tapi saya rasa masih terlalu dini bagi saya untuk memikirkan hal-hal seperti itu...",
  str_homestory_808401001_35_dialog_content = "... Mungkin Anda benar. Terburu-buru hal-hal ini bisa terbukti merugikan dalam beberapa kasus.",
  str_homestory_808401001_36_dialog_content = "Kalau begitu, mengapa saya tidak menawarkan Anda tugas yang lebih sesuai usia?",
  str_homestory_808401001_37_dialog_content = "Saat saya berdiri di tepi sungai, saya melihat koin berkilauan di dalam air <sprite=emo_baiyebi size=60 />.",
  str_homestory_808401001_38_dialog_content = "Saya tidak yakin pada saat itu, tetapi ada kemungkinan itu adalah perhiasan yang cukup langka.",
  str_homestory_808401001_39_dialog_content = "Mengapa Anda tidak pergi melihat-lihat?",
  str_homestory_808401001_40_dialog_content = "Tentu! Terima kasih, Istvan!",
  str_homestory_819301001_0_dialog_content = "Kristen?",
  str_homestory_819301001_1_dialog_content = "Ada apa, Kristen?",
  str_homestory_819301001_2_dialog_content = "Hmm-hmm-hmm! <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_3_dialog_content = "Oh tidak, hanya mendengarkan musik!",
  str_homestory_819301001_4_dialog_content = "Pemutar rekaman Anda sangat cantik, jadi saya harus mencobanya!",
  str_homestory_819301001_5_dialog_content = "Jadi apa yang Anda pikirkan?",
  str_homestory_819301001_6_dialog_content = "Itu mengagumkan! Kualitas suaranya luar biasa... Anda benar-benar memilih yang bagus!",
  str_homestory_819301001_7_dialog_content = "Sudah berapa lama Anda menjadi pecinta musik, PlayerName?",
  str_homestory_819301001_8_dialog_content = "Saya selalu sangat menyukai musik, tetapi saya cenderung mengambil hal-hal menarik selama perjalanan saya... Seperti pemutar rekaman ini!",
  str_homestory_819301001_9_dialog_content = "Meskipun saya yakin itu tidak seberapa dibandingkan dengan koleksi Anda sendiri.",
  str_homestory_819301001_10_dialog_content = "Yah, rumah keluargaku memang memiliki koleksi pemutar musik yang cukup banyak... Salah satunya juga sangat besar!",
  str_homestory_819301001_11_dialog_content = "Saya berani bertaruh...",
  str_homestory_819301001_12_dialog_content = "Mungkin setinggi pintu masuk ke Hall of Justice.",
  str_homestory_819301001_13_dialog_content = "A-Apa?!",
  str_homestory_819301001_14_dialog_content = "Pintu masuk ke Hall of Justice... Luar biasa!",
  str_homestory_819301001_15_dialog_content = "Anda mungkin bisa mengadakan konser untuk sesuatu yang sebesar itu!",
  str_homestory_819301001_16_dialog_content = "Ayahku salah satu bangsawan tipe kolektor, kau tahu? Terkadang itu hanya sedikit di luar kendali!",
  str_homestory_819301001_17_dialog_content = "Tapi kau juga seorang bangsawan, Kristen...",
  str_homestory_819301001_18_dialog_content = "Ya, tapi ayahku dan aku berbeda!",
  str_homestory_819301001_19_dialog_content = "Atau apakah Anda benar-benar berpikir saya seperti salah satu dari bangsawan tua yang pengap itu?",
  str_homestory_819301001_20_option_content = "Kamu bukan!",
  str_homestory_819301001_21_dialog_content = "Anda selalu mencari hal-hal baru dan populer.",
  str_homestory_819301001_22_dialog_content = "Seperti musik, misalnya!",
  str_homestory_819301001_23_option_content = "Mungkin agak tak nyata...",
  str_homestory_819301001_24_dialog_content = "Maksudku, kau benar-benar terpelajar, sama seperti setiap bangsawan yang kutemui.",
  str_homestory_819301001_25_dialog_content = "Heehee! Kamu berpikir seperti itu, PlayerName?",
  str_homestory_819301001_26_dialog_content = "Tidak bisa mengatakan saya tidak setuju.",
  str_homestory_819301001_27_dialog_content = "Ya, kelahiran saya menjadikan saya bagian dari bangsawan dan semua ...",
  str_homestory_819301001_28_dialog_content = "Tapi di lubuk hati saya, saya ingin menjalani hidup saya sendiri, dengan cara saya sendiri!",
  str_homestory_819301001_29_dialog_content = "Dan musik baru ini memberi saya inspirasi yang saya butuhkan untuk terus maju!",
  str_homestory_819301001_30_dialog_content = "Tunggu sebentar!",
  str_homestory_819301001_31_dialog_content = "K-Kau akan tampil di sini, Kristen? Sekarang?!",
  str_homestory_819301001_32_dialog_content = "Itu benar! Lagu ini sangat cocok untuk mencapai nada yang sangat tinggi juga! Laaaa— <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_33_dialog_content = "H-Tunggu!",
  str_homestory_819301001_34_dialog_content = "Oh, maukah kamu melihat waktu? Aku benar-benar lupa aku punya sesuatu yang penting untuk dilakukan! Sampai jumpa!",
  str_homestory_819301001_35_dialog_content = "B-Sekarang?",
  str_homestory_819301001_36_dialog_content = "Ya! Tapi silakan dan bersenang-senanglah dengan pemutar rekaman! Sampai jumpa!",
  str_homestory_819201001_0_dialog_content = "Leo?",
  str_homestory_819201001_1_dialog_content = "Saya baru saja mencari kaca pembesar, dan ini dia.",
  str_homestory_819201001_2_dialog_content = "Apa yang akan kamu gunakan untuk itu?",
  str_homestory_819201001_3_dialog_content = "Untuk melihat peta ini.",
  str_homestory_819201001_4_dialog_content = "Bawahan saya menjelajahi posisi berbagai benteng militer di sepanjang perbatasan baru-baru ini.",
  str_homestory_819201001_5_dialog_content = "Mereka baru saja selesai menggambar peta ini hari ini dan mengirimkannya.",
  str_homestory_819201001_6_dialog_content = "Tapi tulisan tangan di peta ini sangat berantakan dan sangat kecil. Itu membuat kepalaku pusing. <sprite=emo_xuanyun size=60 />",
  str_homestory_819201001_7_dialog_content = "Apakah ada banyak kata yang tertulis di peta?",
  str_homestory_819201001_8_dialog_content = "Lihat sendiri.",
  str_homestory_819201001_9_dialog_content = "\"Tampilan Eksplorasi dan Analisis Benteng Militer Dalam Jarak 80 Kilometer Senja...\"",
  str_homestory_819201001_10_dialog_content = "Ada juga baris kedua.",
  str_homestory_819201001_11_dialog_content = "\"... dan Merinci Informasi Seperti Distribusi Spasial, Kuantitas, dan Karakteristik Kualitatif dan Keterkaitan\"",
  str_homestory_819201001_12_dialog_content = "Huff...huff... <sprite=emo_kun size=60 />",
  str_homestory_819201001_13_dialog_content = "A-Apakah nama semua peta... begitu rumit?",
  str_homestory_819201001_14_dialog_content = "Saya hampir tidak bisa mengatur napas setelah membacanya sekaligus.",
  str_homestory_819201001_15_dialog_content = "Tentu tidak perlu serumit ini, tapi kali ini kartografernya sangat teliti, jadi dia menulis sebanyak yang dia bisa...",
  str_homestory_819201001_16_dialog_content = "Itu benar-benar tidak perlu.",
  str_homestory_819201001_17_dialog_content = "Tidak heran begitu banyak ahli strategi membawa kaca pembesar bersama mereka.",
  str_homestory_819201001_18_dialog_content = "Jika mereka harus mengandalkan kartografer selengkap orang ini, kaca pembesar adalah satu-satunya harapan mereka untuk dapat membaca peta mereka dengan jelas.",
  str_homestory_819201001_19_dialog_content = "(Tetapi bahkan setelah bisa membaca nama konyol ini, Anda mungkin akan menjadi lebih frustrasi.)",
  str_homestory_819201001_20_dialog_content = "Memang banyak pemimpin yang gemar menggunakan kaca pembesar.",
  str_homestory_819201001_21_dialog_content = "Mereka tidak hanya dapat memperbesar teks dan gambar serta membantu pengamatan, tetapi juga dapat membantu membuat api saat matahari bersinar.",
  str_homestory_819201001_22_dialog_content = "Bisa dikatakan itu adalah alat serbaguna, penting untuk pasukan yang sedang berbaris.",
  str_homestory_819201001_23_dialog_content = "Namun, saya ragu tentang kaca pembesar.",
  str_homestory_819201001_24_dialog_content = "Kenapa?",
  str_homestory_819201001_25_dialog_content = "Anda juga, adalah seorang komandan dalam pertempuran. Mungkin Anda bisa menebak alasannya?",
  str_homestory_819201001_26_option_content = "Mereka bergantung pada cahaya.",
  str_homestory_819201001_27_dialog_content = "Mereka sulit digunakan di malam hari atau dalam kegelapan.",
  str_homestory_819201001_28_dialog_content = "Ini memang masalah, tapi selama sumber cahaya tersedia, masalah ini bisa dihindari.",
  str_homestory_819201001_29_option_content = "Mereka dapat membatasi bidang pandang Anda.",
  str_homestory_819201001_30_dialog_content = "Benar.",
  str_homestory_819201001_31_dialog_content = "Kaca pembesar memperbesar suatu area, memungkinkan pengamat untuk melihat detail dengan lebih akurat.",
  str_homestory_819201001_32_dialog_content = "Tetapi pada saat yang sama, bidang pandang pengamat terbatas pada lingkup kaca pembesar.",
  str_homestory_819201001_33_dialog_content = "Ini membuat seseorang tidak dapat mengamati lingkungan yang lebih luas di sekitarnya.",
  str_homestory_819201001_34_dialog_content = "Tetapi peperangan seringkali membutuhkan pengerahan pasukan dari perspektif yang lebih luas.",
  str_homestory_819201001_35_dialog_content = "Saya terkadang sengaja menghindari penggunaan kaca pembesar untuk mencegah bidang pandang saya menjadi terlalu fokus.",
  str_homestory_819201001_36_dialog_content = "Anda benar-benar ahli strategi yang inspirasional.",
  str_homestory_819201001_37_dialog_content = "Itu hanya kebiasaan pribadi. Misalnya, saya tidak punya pilihan selain meminta kaca pembesar dalam situasi kita saat ini.",
  str_homestory_819201001_38_dialog_content = "Anda dapat menggunakan kaca pembesar di sini kapan pun Anda mau.",
  str_homestory_819201001_39_dialog_content = "Tapi tolong pastikan Anda memasukkannya kembali ke dalam kotaknya setelah Anda selesai menggunakannya.",
  str_homestory_819201001_40_dialog_content = "Jika terkena sinar matahari langsung, dapat menyebabkan kebakaran. <sprite=emo_nuhuo size=60 />",
  str_homestory_819201001_41_dialog_content = "Haha, ada baiknya Anda memiliki kesadaran keselamatan kebakaran yang kuat.",
  str_homestory_819201001_42_dialog_content = "Lagipula, aku telah bekerja sangat keras untuk menjadikan ini tempat yang bisa kusebut rumah.",
  str_homestory_819201001_43_dialog_content = "Jika semua uangku habis terbakar... yah, kerja kerasku akan sia-sia.",
  str_homestory_819901001_0_dialog_content = "Yingel?",
  str_homestory_819901001_1_dialog_content = "Oh, PlayerName. Saya baru mau mencoba kopi ini.",
  str_homestory_819901001_2_dialog_content = "Apakah Anda membuatnya sendiri?",
  str_homestory_819901001_3_dialog_content = "Benar.",
  str_homestory_819901001_4_dialog_content = "Saya baru saja melihat cangkir kopi yang indah ini, jadi saya pikir saya akan mencoba menyeduh sendiri.",
  str_homestory_819901001_5_dialog_content = "Baunya luar biasa! <sprite=emo_dianzan size=60 />",
  str_homestory_819901001_6_dialog_content = "Lihat pola di permukaan? Inilah yang mereka sebut seni latte.",
  str_homestory_819901001_7_dialog_content = "Ya, saya melihatnya! Cantiknya!",
  str_homestory_819901001_8_dialog_content = "Bentuknya seperti... Aoha?",
  str_homestory_819901001_9_dialog_content = "Anda bisa tahu itu Aoha? Yah, saya kira saya tidak bisa menyebut upaya ini sebagai kegagalan.",
  str_homestory_819901001_10_dialog_content = "Tentu saja itu bukan kegagalan! Itu luar biasa!",
  str_homestory_819901001_11_dialog_content = "Bagaimana kamu melakukannya, Yingel?",
  str_homestory_819901001_12_dialog_content = "Membuat latte sama sekali tidak sulit, dan bahan-bahannya juga sangat mendasar.",
  str_homestory_819901001_13_dialog_content = "Pertama, Anda perlu menuangkan secangkir kecil espresso ke dalam cangkir kopi...",
  str_homestory_819901001_14_dialog_content = "Kemudian buih sedikit susu segar dan tambahkan ke espresso.",
  str_homestory_819901001_15_dialog_content = "Saat menambahkan buih, sesuaikan bentuknya dengan menggerakkan cangkir susu.",
  str_homestory_819901001_16_dialog_content = "Dan begitu saja, Anda harus memiliki latte dengan pola yang indah.",
  str_homestory_819901001_17_dialog_content = "Anda membuatnya terdengar mudah, tapi saya yakin itu tidak sesederhana kedengarannya...",
  str_homestory_819901001_18_dialog_content = "Latihan membuat sempurna. Coba saja beberapa kali dan Anda akan baik-baik saja.",
  str_homestory_819901001_19_dialog_content = "Setiap kali saya merasa lelah di tempat kerja, saya membuat sendiri latte.",
  str_homestory_819901001_20_dialog_content = "Susu yang lembut dan kopi yang lembut adalah pasangan yang sempurna.",
  str_homestory_819901001_21_dialog_content = "PlayerName, apakah Anda ingin mencobanya?<sprite=emo_yaosu size=60 />",
  str_homestory_819901001_22_option_content = "Ya.",
  str_homestory_819901001_23_dialog_content = "Lagi pula, Anda membuat kopi ini sendiri.",
  str_homestory_819901001_24_option_content = "Tidak.",
  str_homestory_819901001_25_dialog_content = "Jika saya minum kopi sekarang, saya khawatir saya tidak akan bisa tidur.",
  str_homestory_819901001_26_dialog_content = "Ini lebih dari dua pertiga susu, jadi tidak akan membuat Anda terjaga.",
  str_homestory_819901001_27_dialog_content = "Benar-benar? Dalam hal ini, saya ingin mencobanya.",
  str_homestory_819901001_28_dialog_content = "Bagaimana?",
  str_homestory_819901001_29_dialog_content = "Saya memberikannya sepuluh dari sepuluh untuk rasa!",
  str_homestory_819901001_30_dialog_content = "Andai saja aku bisa membuat latte selezat ini.",
  str_homestory_819901001_31_dialog_content = "Anda harus mencoba membuatnya—saya tahu Anda bisa melakukannya.",
  str_homestory_819901001_32_dialog_content = "Namun, sepertinya aku sudah kehabisan susu...",
  str_homestory_819901001_33_dialog_content = "Apa, semuanya sudah hilang?",
  str_homestory_819901001_34_dialog_content = "Saya benar-benar haus sekarang, jadi saya minum semuanya.",
  str_homestory_819901001_35_dialog_content = "erm, Yingel... Anda tidak bisa membuang susu begitu saja seperti air ...",
  str_homestory_820001001_0_dialog_content = "Adalah Anatoli menatap lampu luar itu?",
  str_homestory_820001001_1_dialog_content = "Kamu sedang apa, Anatoli?",
  str_homestory_820001001_2_dialog_content = "Saya mengamati lampu ini.",
  str_homestory_820001001_3_option_content = "Mengamati lampu?",
  str_homestory_820001001_4_dialog_content = "Saya telah menemukan bahwa itu tetap menyala, bahkan di siang hari.",
  str_homestory_820001001_5_dialog_content = "Meskipun cahaya yang dipancarkannya jauh lebih redup dari sinar matahari, ia tidak pernah padam.",
  str_homestory_820001001_6_dialog_content = "Apakah seseorang terus-menerus menambahkan minyak lampu ke dalamnya?",
  str_homestory_820001001_7_dialog_content = "wah saya juga gak tau jawabannya...",
  str_homestory_820001001_8_option_content = "Kenapa?",
  str_homestory_820001001_9_dialog_content = "Karena selalu menyala, siang dan malam.",
  str_homestory_820001001_10_dialog_content = "Meskipun tidak mencolok di siang hari, itu menerangi kegelapan di malam hari. <sprite=emo_taiyang size=60 />",
  str_homestory_820001001_11_dialog_content = "Tentu saja!",
  str_homestory_820001001_12_dialog_content = "Sangat menyenangkan memiliki lampu yang menerangi jalan di malam hari!",
  str_homestory_820001001_13_dialog_content = "Namun... membiarkan lampu menyala di siang hari terasa sedikit boros.",
  str_homestory_820001001_14_dialog_content = "Ya... tentu saja.",
  str_homestory_820001001_15_dialog_content = "Lagi pula, ini bukan Malam Abadi... Benar-benar tidak perlu menyalakan lampu sepanjang waktu.",
  str_homestory_820001001_16_dialog_content = "Kemudian saya akan memadamkannya untuk saat ini dan menyalakannya nanti malam.",
  str_homestory_820001001_17_dialog_content = "Akan lebih baik jika kau tetap memakainya.",
  str_homestory_820001001_18_dialog_content = "Hah? Kenapa?",
  str_homestory_820001001_19_dialog_content = "Kita mungkin tidak tahu siapa yang menambahkan minyak ke lampu ini, tapi mereka pasti punya alasannya.",
  str_homestory_820001001_20_dialog_content = "Akan lebih baik jika kita tidak mengganggu rutinitas mereka.",
  str_homestory_820001001_21_dialog_content = "Kau benar.",
  str_homestory_820001001_22_dialog_content = "Saya benar-benar ingin tahu siapa orang misterius ini!",
  str_homestory_820001001_23_dialog_content = "Nah, coba amati lebih banyak dan mungkin suatu hari Anda akan bertemu dengan mereka.",
  str_homestory_820001001_24_dialog_content = "Saya ingat Anda benar-benar jenius dalam hal penalaran dan analisis...",
  str_homestory_820001001_25_dialog_content = "Apakah Anda punya ide tentang siapa pemantik lampu misteri itu?",
  str_homestory_820001001_26_dialog_content = "Saya memang punya spekulasi.",
  str_homestory_820001001_27_dialog_content = "Misalnya?",
  str_homestory_820001001_28_dialog_content = "Pasti seseorang yang sangat sabar, mampu bertahan dalam melakukan sesuatu untuk waktu yang lama.",
  str_homestory_820001001_29_dialog_content = "Dan mereka harus memiliki ingatan yang baik, karena mereka sepertinya tidak pernah melupakan tugas sepele seperti itu.",
  str_homestory_820001001_30_dialog_content = "Terakhir, mereka tampaknya sangat menyukai objek yang memancarkan cahaya sederhana.",
  str_homestory_820001001_31_dialog_content = "Ya, itu masuk akal...",
  str_homestory_820001001_32_dialog_content = "Itu benar-benar mengingatkan saya pada beberapa orang.",
  str_homestory_820001001_33_dialog_content = "Tunggu, aku mendapatkannya!",
  str_homestory_820001001_34_dialog_content = "Bukankah kamu hanya berbicara tentang dirimu sendiri ?!",
  str_homestory_820001001_35_dialog_content = "Pengurangan yang luar biasa.",
  str_homestory_820001001_36_dialog_content = "Jadi, mengapa Anda membiarkan lampu ini tetap menyala?",
  str_homestory_820001001_37_dialog_content = "Ini jelas siang hari, jadi jelas tidak perlu menggunakan lampu...",
  str_homestory_820001001_38_dialog_content = "Meskipun kedipan api yang paling redup mungkin tampak nyaris tidak terlihat di bawah sinar matahari, masih ada sesuatu yang hanya bisa dilakukan olehnya.",
  str_homestory_820001001_39_dialog_content = "Inilah yang saya yakini.",
  str_homestory_802801001_0_dialog_content = "Aku tahu suara itu...",
  str_homestory_802801001_1_dialog_content = "Dia Raphael!",
  str_homestory_802801001_2_dialog_content = "Suara mendesing! Suara mendesing! Suara mendesing!",
  str_homestory_802801001_3_dialog_content = "PlayerName! Senang bertemu dengan mu!",
  str_homestory_802801001_4_dialog_content = "Hai! Coba pil Brain Booster baru saya!",
  str_homestory_802801001_5_dialog_content = "Hal-hal kecil ini dapat langsung mengisi Anda dengan energi! Mereka bahkan memungkinkan Anda merasakan keberadaan harta karun mistis!",
  str_homestory_802801001_6_dialog_content = "Edisi terbatas! Jangan lewatkan kesempatan sekali seumur hidup ini!",
  str_homestory_802801001_7_option_content = "Saya rasa saya tidak membutuhkannya, terima kasih...",
  str_homestory_802801001_8_dialog_content = "Saya telah mencari tinggi dan rendah untuk sementara waktu sekarang, dan akhirnya saya menemukan Anda!",
  str_homestory_802801001_9_dialog_content = "Anda tidak ingin eksperimen kecil saya gagal, bukan?",
  str_homestory_802801001_10_dialog_content = "Sejujurnya, saya tidak berpikir tentang itu ...",
  str_homestory_802801001_11_option_content = "Biarkan saya memberi mereka mencoba!",
  str_homestory_802801001_12_dialog_content = "Hehe! Anda berada dalam suasana hati yang ceria hari ini, PlayerName!",
  str_homestory_802801001_13_dialog_content = "Aku akan membawakanmu lebih banyak lagi besok!",
  str_homestory_802801001_14_dialog_content = "Erm... Apakah kamu benar-benar tidak ada hal lain yang harus dilakukan hari ini?",
  str_homestory_802801001_15_dialog_content = "Buka mulutmu dan katakan, \"ah\"!",
  str_homestory_802801001_16_dialog_content = "T-Tunggu sebentar!",
  str_homestory_802801001_17_dialog_content = "Bau itu... Bukankah itu masakan Vice?",
  str_homestory_802801001_18_dialog_content = "(Uh, yang terbakar itu... <sprite=emo_hanshui size=60 />)",
  str_homestory_802801001_19_dialog_content = "Hah?! Anda tidak percaya padaku?",
  str_homestory_802801001_20_dialog_content = "Erm... Maksudku adalah... kau lihat...",
  str_homestory_802801001_21_dialog_content = "Saya mengerti, saya mengerti! Anda menyukai teman tepercaya yang dapat Anda andalkan, bukan, PlayerName?",
  str_homestory_802801001_22_dialog_content = "Saya melakukan yang terbaik untuk menjadi pendamping yang tak tertandingi!",
  str_homestory_802801001_23_dialog_content = "Orang yang bisa membuat pil Brain Booster—",
  str_homestory_802801001_24_dialog_content = "Hehe, tapi aku benar-benar tidak boleh menyombongkan diri.",
  str_homestory_802801001_25_dialog_content = "(Dia sangat optimis...)",
  str_homestory_802801001_26_dialog_content = "Bagaimana dengan ini, Raphael—Anda dapat melanjutkan dan menghasilkan lebih banyak, lalu membiarkannya Carleen coba mereka di lain hari!",
  str_homestory_802801001_27_dialog_content = "Dia selalu bekerja sangat keras... Dia mungkin benar-benar menghargai beberapa Penguat Otak.",
  str_homestory_802801001_28_dialog_content = "Hah? Carleen?",
  str_homestory_802801001_29_dialog_content = "Saya kira tidak demikian!",
  str_homestory_802801001_30_dialog_content = "Maksudmu?",
  str_homestory_802801001_31_dialog_content = "Karena jika saya membawa mereka ke Carleen, Aku tahu dia akan berkata—",
  str_homestory_802801001_32_dialog_content = "\"Raphael! Jangan berani-berani mencoba memberiku permen anehmu lagi—dan jangan tanya kenapa.\"",
  str_homestory_802801001_33_dialog_content = "Kenapa?",
  str_homestory_802801001_34_dialog_content = "Aku harap aku tahu! <sprite=emo_sikao size=60 /> Tetapi Carleen bahkan tidak membiarkan saya bertanya.",
  str_homestory_802801001_35_dialog_content = "Oh ya, dan...",
  str_homestory_802801001_36_dialog_content = "Pil ini dibuat khusus untuk Anda dan kemampuan psikis Anda, PlayerName!",
  str_homestory_802801001_37_dialog_content = "Baiklah, saya mengerti... Berikan saja padaku!",
  str_homestory_802801001_38_dialog_content = "(Yah, kalau itu hanya permen...)",
  str_homestory_802801001_39_dialog_content = "Hehe! Aku tahu mereka sempurna untukmu, PlayerName!",
  str_homestory_802801001_40_dialog_content = "Jadi, bagaimana...? Bagaimana itu?! Pernahkah Anda memperhatikan adanya perubahan?",
  str_homestory_802801001_41_dialog_content = "Pernahkah Anda melihat sesuatu yang berkilau? Seperti harta?",
  str_homestory_802801001_42_dialog_content = "Visi saya tampak lebih jelas, dan saya bisa melihat lebih jauh—",
  str_homestory_802801001_43_dialog_content = "Di Sungai! Benar-benar ada sesuatu yang berkilau di sungai!",
  str_homestory_802801001_44_dialog_content = "Ya! Di Sungai! Aku tahu itu!",
  str_homestory_802801001_45_dialog_content = "Eksperimen Brain Booster saya berhasil! <sprite=emo_aixin size=60 />",
  str_homestory_820201001_0_dialog_content = "Sedang apa kau di sini?",
  str_homestory_820201001_1_dialog_content = "Ini dia.",
  str_homestory_820201001_2_dialog_content = "Apakah singgasana ini disiapkan khusus untukku?",
  str_homestory_820201001_3_dialog_content = "Ya...",
  str_homestory_820201001_4_dialog_content = "Saya menyetujui pemikiran itu.",
  str_homestory_820201001_5_dialog_content = "Meskipun tidak setingkat tahta asli di Lumopolis Gardens...",
  str_homestory_820201001_6_dialog_content = "Namun demikian, itu cukup pas untuk status saya.",
  str_homestory_820201001_7_dialog_content = "Senang kamu menyukainya!",
  str_homestory_820201001_8_dialog_content = "Apakah ada hal lain yang Anda butuhkan?",
  str_homestory_820201001_9_dialog_content = "Bagaimana kalau membangun istana Lumopolis baru di sini? <sprite=emo_sikao size=60 />",
  str_homestory_820201001_10_dialog_content = "Karena kita sudah memiliki singgasana, lebih baik membangun istana untuk menyertainya.",
  str_homestory_820201001_11_dialog_content = "Anda ingin membangun istana di sini?",
  str_homestory_820201001_12_dialog_content = "Saya tidak berpikir ada cukup ruang...",
  str_homestory_820201001_13_dialog_content = "Hm, itu benar. Selain mentah, itu tidak cukup besar.",
  str_homestory_820201001_14_dialog_content = "Bagaimana dengan renovasi yang didanai oleh saya?",
  str_homestory_820201001_15_option_content = "Tidak apa-apa",
  str_homestory_820201001_16_dialog_content = "Saya menghargai pemikiran itu.",
  str_homestory_820201001_17_option_content = "Maukah kamu?",
  str_homestory_820201001_18_dialog_content = "Selain bahan, banyak tenaga kerja juga dibutuhkan untuk ekspansi.",
  str_homestory_820201001_19_dialog_content = "Saya rasa proyek ini tidak dijamin jika Anda hanya mampir sesekali.",
  str_homestory_820201001_20_dialog_content = "Ini sepele bagi saya.",
  str_homestory_820201001_21_dialog_content = "Tapi kita bisa melupakannya jika Anda tidak menginginkannya.",
  str_homestory_820201001_22_dialog_content = "Tunggu, sepertinya aku mencium sesuatu... <sprite=emo_wuzui size=60 />",
  str_homestory_820201001_23_dialog_content = "Apa itu? Bau aneh?",
  str_homestory_820201001_24_dialog_content = "Saya tidak mencium bau apa pun.",
  str_homestory_820201001_25_dialog_content = "Itulah tepatnya yang hilang.",
  str_homestory_820201001_26_dialog_content = "Anda harus menambahkan beberapa aroma yang menyenangkan untuk membuat udara berbau lebih bersih dan rapi.",
  str_homestory_820201001_27_dialog_content = "Saya tidak terlalu tertarik dengan aroma...",
  str_homestory_820201001_28_dialog_content = "Jika pengunjung tidak merasakan aura keanggunan saat mereka tiba di sini...",
  str_homestory_820201001_29_dialog_content = "Itu adalah pelanggaran etika yang serius!",
  str_homestory_820201001_30_dialog_content = "Dalam hal ini, saya akan mendapatkan seseorang di atasnya.",
  str_homestory_820201001_31_dialog_content = "Saya berharap untuk melihat perubahan ketika saya mengunjungi lagi.",
  str_homestory_820201001_32_dialog_content = "Tentu saja…",
  str_homestory_820301001_0_dialog_content = "Jakine?",
  str_homestory_820301001_1_dialog_content = "Oh, begitu…",
  str_homestory_820301001_2_dialog_content = "Sedang apa kau?",
  str_homestory_820301001_3_dialog_content = "Apa... Sudah berapa lama kamu di sini?",
  str_homestory_820301001_4_dialog_content = "Apakah Anda melihat bacaan yang baru saja saya lakukan?",
  str_homestory_820301001_5_dialog_content = "Saya baru saja tiba di sini dan tidak melihat apa-apa.",
  str_homestory_820301001_6_dialog_content = "Apakah Anda melakukan pembacaan untuk sesuatu yang sangat pribadi?",
  str_homestory_820301001_7_dialog_content = "Maaf, aku akan pergi sekarang.",
  str_homestory_820301001_8_dialog_content = "Ini untuk sesuatu yang sangat pribadi, namun ...",
  str_homestory_820301001_9_dialog_content = "Itu ada hubungannya dengan Anda.",
  str_homestory_820301001_10_dialog_content = "Dengan saya?",
  str_homestory_820301001_11_dialog_content = "Ya. Saya mendengar percakapan yang Anda lakukan dengan Vice.",
  str_homestory_820301001_12_dialog_content = "Anda mengalami masalah keuangan akhir-akhir ini?",
  str_homestory_820301001_13_dialog_content = "Yah, itu agak ketat.",
  str_homestory_820301001_14_dialog_content = "Saya khawatir, jadi saya membacakan untuk Anda.",
  str_homestory_820301001_15_dialog_content = "Jika Anda tidak ingin tahu, saya akan merahasiakan hasilnya.",
  str_homestory_820301001_16_dialog_content = "Saya tidak keberatan. Jadi apa hasilnya?",
  str_homestory_820301001_17_dialog_content = "Nah, tentang keuangan Anda di masa depan...",
  str_homestory_820301001_18_dialog_content = "Tunggu, saya belum siap secara mental untuk jumlah pemilih yang buruk ...",
  str_homestory_820301001_19_dialog_content = "Dikatakan Anda akan menjadi sangat kaya! Menjalani kehidupan yang bebas stres dan bahagia setiap hari! <sprite=emo_yaosu size=60 />",
  str_homestory_820301001_20_dialog_content = "Benar-benar? Ini benar-benar akan menjadi luar biasa?",
  str_homestory_820301001_21_dialog_content = "Apakah Anda percaya itu?",
  str_homestory_820301001_22_dialog_content = "Hah? Jadi kau berbohong padaku?",
  str_homestory_820301001_23_dialog_content = "Jawab saja saya, apakah Anda percaya itu?",
  str_homestory_820301001_24_option_content = "Saya bersedia",
  str_homestory_820301001_25_dialog_content = "Benar! Itulah sikap terbaik yang harus dimiliki!",
  str_homestory_820301001_26_option_content = "saya tidak",
  str_homestory_820301001_27_dialog_content = "Mengapa tidak? Kau membuatku marah sekarang!",
  str_homestory_820301001_28_dialog_content = "Kekuatan percaya sangat penting!",
  str_homestory_820301001_29_dialog_content = "Ketika Anda percaya pada sesuatu, ke arah itulah segala sesuatu bergerak.",
  str_homestory_820301001_30_dialog_content = "Tapi apa hubungannya dengan meramal?",
  str_homestory_820301001_31_dialog_content = "Karena tujuan membaca adalah...",
  str_homestory_820301001_32_dialog_content = "Untuk merebut hadiah!",
  str_homestory_820301001_33_dialog_content = "Hmm, sepertinya meramal benar-benar omong kosong...",
  str_homestory_820301001_34_dialog_content = "Itu karena hidup adalah jalan yang panjang.",
  str_homestory_820301001_35_dialog_content = "Dan di jalan ini, ada banyak pertigaan.",
  str_homestory_820301001_36_dialog_content = "Yang berarti keputusan Anda akan memengaruhi jalan yang Anda tempuh di masa depan.",
  str_homestory_820301001_37_dialog_content = "Tapi terlepas dari itu, aku melihat masa depan yang cerah untukmu <sprite=emo_taiyang size=60 />.",
  str_homestory_820301001_38_dialog_content = "Aku paham.",
  str_homestory_820301001_39_dialog_content = "Masa depan penuh dengan variabel, tetapi semuanya bergantung pada saat ini dan di sini.",
  str_homestory_820301001_40_dialog_content = "Wow, bagus sekali... Saya harus menuliskannya di jurnal saya.",
  str_homestory_820301001_41_dialog_content = "Haha, ngomong-ngomong, pembicaraan ini membuatku merasa jauh lebih baik.",
  str_homestory_809801001_0_dialog_content = "Cuscuta?",
  str_homestory_809801001_1_dialog_content = "Kau sedang lihat apa, Cuscuta?",
  str_homestory_809801001_2_dialog_content = "Bunga-bunga <sprite=emo_huaduo size=60 />.",
  str_homestory_809801001_3_dialog_content = "Beberapa bunga di semak menyambut matahari, dan beberapa menolak untuk dipandang.",
  str_homestory_809801001_4_dialog_content = "Saya tahu salah satu tipe terakhir yang disebut Black Tail. Pernahkah Anda mendengarnya?",
  str_homestory_809801001_5_option_content = "Ya.",
  str_homestory_809801001_6_dialog_content = "Tapi apa yang Anda maksud dengan \"menolak untuk dipandang\"?",
  str_homestory_809801001_7_option_content = "Tidak.",
  str_homestory_809801001_8_dialog_content = "Jenis bunga apa itu?",
  str_homestory_809801001_9_dialog_content = "Ekor Hitam sangat langka.",
  str_homestory_809801001_10_dialog_content = "Kelopaknya rapuh, berwarna gelap, dan mudah menyerap sinar matahari<sprite=emo_taiyang size=60 />.",
  str_homestory_809801001_11_dialog_content = "Jadi untuk mencegah luka bakar, biasanya bersembunyi di bawah daun.",
  str_homestory_809801001_12_dialog_content = "Oleh karena itu, ia menolak untuk dipandang.",
  str_homestory_809801001_13_dialog_content = "Saya mengerti apa yang kamu maksud...",
  str_homestory_809801001_14_dialog_content = "Anda sangat menyukai Black Tails, bukan, Cuscuta?",
  str_homestory_809801001_15_dialog_content = "Bagaimana saya menentukan apakah saya melakukannya atau tidak?",
  str_homestory_809801001_16_dialog_content = "Nah, memiliki wawasan unik tentangnya dan memahami bagaimana itu tumbuh...",
  str_homestory_809801001_17_dialog_content = "Saya pikir itu hanya seseorang yang tertarik seperti Anda akan mengetahuinya, bukan?",
  str_homestory_809801001_18_dialog_content = "Kau pikir begitu...?",
  str_homestory_809801001_19_dialog_content = "Sebenarnya Black Tail biasanya tumbuh di mayat.",
  str_homestory_809801001_20_dialog_content = "Mayat?!",
  str_homestory_809801001_21_dialog_content = "Ya. Aku percaya...",
  str_homestory_809801001_22_dialog_content = "Di sini, segera, Anda akan melihat Ekor Hitam.",
  str_homestory_809801001_23_dialog_content = "K-Maksudmu... ada mayat... terkubur di bawah sini?!",
  str_homestory_809801001_24_dialog_content = "Jangan khawatir, saya sudah memeriksanya.",
  str_homestory_809801001_25_dialog_content = "Saya mengacu pada tubuh saya yang akan segera layu ini.",
  str_homestory_809801001_26_dialog_content = "Oh, aku akan segera tidur, artinya Ekor Hitam akan muncul.",
  str_homestory_809801001_27_dialog_content = "T-Tidak, Cuscuta!",
  str_homestory_809801001_28_dialog_content = "Chubbs memberitahuku bahwa tanah di Cloud Gardens memiliki mineral khusus.",
  str_homestory_809801001_29_dialog_content = "J-Jadi bukan hal yang aneh jika Ekor Hitam tumbuh.",
  str_homestory_809801001_30_dialog_content = "Mungkin bahkan bunga berwarna-warni pun dimungkinkan!",
  str_homestory_809801001_31_dialog_content = "Warna-warni...",
  str_homestory_809801001_32_dialog_content = "Benarkah itu? <sprite=emo_yundao size=60 />",
  str_homestory_809801001_33_dialog_content = "Ya. Jadi bagaimana kalau kita menanam bunga berwarna-warni bersama?",
  str_homestory_809801001_34_dialog_content = "Tanam bersama... Apa itu... berhasil?",
  str_homestory_809801001_35_dialog_content = "Yah, tidak cukup ...",
  str_homestory_809801001_36_dialog_content = "Kamu juga suka bunga, PlayerName?",
  str_homestory_809801001_37_dialog_content = "Bisa dikatakan begitu.",
  str_homestory_809801001_38_dialog_content = "Saya selalu merasa tidak ada cukup warna di Cloud Gardens.",
  str_homestory_809801001_39_dialog_content = "Anda baru saja mengingatkan saya bahwa kita bisa menanam lebih banyak bunga untuk menambah warna!",
  str_homestory_809801001_40_dialog_content = "Jadi maksudmu menambahkan warna akan membuat orang lebih bahagia?",
  str_homestory_809801001_41_dialog_content = "Tentu saja! Mengapa kita tidak melihat-lihat bunga berwarna-warni?",
  str_homestory_809801001_42_dialog_content = "Tentu, kita bisa melakukannya.",
  str_homestory_809801001_43_dialog_content = "Tapi apakah warna-warni yang Anda sebutkan termasuk emas?",
  str_homestory_809801001_44_dialog_content = "Lihat benda yang bersinar emas di danau itu? Apakah itu bunga?",
  str_homestory_820101001_0_dialog_content = "Apa yang Anda mulai?",
  str_homestory_820101001_1_dialog_content = "Jika...",
  str_homestory_820101001_2_dialog_content = "Apa aku mengganggumu, Mia?",
  str_homestory_820101001_3_dialog_content = "T-Tidak. Aku hanya merenungkan beberapa masalah sulit.",
  str_homestory_820101001_4_dialog_content = "Ada yang bisa saya bantu?",
  str_homestory_820101001_5_dialog_content = "Ya. Dapatkah saya mengajukan pertanyaan?",
  str_homestory_820101001_6_dialog_content = "Tentu.",
  str_homestory_820101001_7_dialog_content = "Jika kamu bisa mengingat suatu hari selamanya, hari apa yang akan kamu pilih?",
  str_homestory_820101001_8_dialog_content = "Selamanya, ya... Aku benar-benar tidak bisa memikirkan satu pun.",
  str_homestory_820101001_9_dialog_content = "Jadi itulah yang mengganggumu.",
  str_homestory_820101001_10_dialog_content = "Itu karena aku melihat pertanyaannya, jadi...",
  str_homestory_820101001_11_dialog_content = "Oke, biarkan aku berpikir.",
  str_homestory_820101001_12_option_content = "Colossus melakukan reboot...",
  str_homestory_820101001_13_dialog_content = "Saya akan memilih untuk mengingat hari ketika Colossus berhasil di-reboot.",
  str_homestory_820101001_14_dialog_content = "Itu adalah pertama kalinya saya melihat seperti apa Astra.",
  str_homestory_820101001_15_dialog_content = "Mungkin Anda bahkan bisa menyebutnya sebagai awal hidup saya.",
  str_homestory_820101001_16_option_content = "Bangkitnya Obelisk of Return...",
  str_homestory_820101001_17_dialog_content = "Saya akan memilih untuk mengingat hari ketika Obelisk of Return naik ...",
  str_homestory_820101001_18_dialog_content = "Kekuatan mental saya bertambah hingga saya merasa dapat melihat setiap sudut Astra.",
  str_homestory_820101001_19_dialog_content = "Perasaan itu luar biasa.",
  str_homestory_820101001_20_dialog_content = "Kedengarannya seperti hari yang luar biasa.",
  str_homestory_820101001_21_dialog_content = "Anda memikirkannya cukup cepat, PlayerName",
  str_homestory_820101001_22_dialog_content = "Sebenarnya, sebelum Colossus di-reboot, setiap hari adalah ulangan dari hari sebelum saya.",
  str_homestory_820101001_23_dialog_content = "Hidup saya hanya menjadi hidup sampai saya bertemu semua orang.",
  str_homestory_820101001_24_dialog_content = "Jadi sekarang saya menghargainya untuk memastikan saya memiliki ingatan yang jelas tentang wajah mereka.",
  str_homestory_820101001_25_dialog_content = "Dan saya akan berusaha untuk mengingat semuanya dan melestarikannya selamanya.",
  str_homestory_820101001_26_dialog_content = "Ah... <sprite=emo_sikao size=60 />",
  str_homestory_820101001_27_dialog_content = "Bagaimana kalau berbagi pemikiran Anda, Mia?",
  str_homestory_820101001_28_dialog_content = "Pikiran saya...",
  str_homestory_820101001_29_dialog_content = "Karena saya lupa beberapa kenangan penting sampai saat ini ...",
  str_homestory_820101001_30_dialog_content = "Saya sangat khawatir kehilangan mereka lagi, jadi saya ingin mempertahankan semuanya...",
  str_homestory_820101001_31_dialog_content = "Tapi sulit untuk memilih antara menyimpan kenangan ibuku, adik...",
  str_homestory_820101001_32_dialog_content = "Mia...",
  str_homestory_820101001_33_dialog_content = "Maaf telah menjatuhkanmu bersamaku...",
  str_homestory_820101001_34_dialog_content = "Tidak, saya harus meminta maaf. Seharusnya aku tidak mengatakan semua itu.",
  str_homestory_820101001_35_dialog_content = "Tidak apa-apa, PlayerName.",
  str_homestory_820101001_36_dialog_content = "Aku sebenarnya lega dengan apa yang kau katakan.",
  str_homestory_820101001_37_dialog_content = "Sungguh?",
  str_homestory_820101001_38_dialog_content = "Ya, daripada khawatir melupakan masa lalu, lebih penting menghargai masa kini <sprite=emo_yaosu size=60 />.",
  str_homestory_820401001_0_dialog_content = "Wanita Joshua?",
  str_homestory_820401001_1_dialog_content = "Sedang apa kau?",
  str_homestory_820401001_2_dialog_content = "Lihat, PlayerName.",
  str_homestory_820401001_3_dialog_content = "Tanaman pot ini tumbuh dengan sangat baik!",
  str_homestory_820401001_4_dialog_content = "Saya mencoba mencari tahu varietas apa itu.",
  str_homestory_820401001_5_dialog_content = "Jadi begitu. Sudahkah Anda mengidentifikasinya?",
  str_homestory_820401001_6_dialog_content = "Sayangnya, sejauh ini saya belum bisa...",
  str_homestory_820401001_7_dialog_content = "Apakah Anda tahu tanaman apa ini?",
  str_homestory_820401001_8_option_content = "Mengangguk",
  str_homestory_820401001_9_dialog_content = "Saya membelinya di Umbraton belum lama ini.",
  str_homestory_820401001_10_dialog_content = "Saya hanya memilih secara acak apa yang tersedia.",
  str_homestory_820401001_11_dialog_content = "Saya yakin penjualnya menyebutnya... tanaman manor?",
  str_homestory_820401001_12_dialog_content = "Ya, itulah namanya.",
  str_homestory_820401001_13_dialog_content = "Namanya agak sederhana, tetapi Anda menyimpannya dengan sangat baik!",
  str_homestory_820401001_14_dialog_content = "Nah, kata penjualnya bisa tumbuh sangat subur jika dirawat.",
  str_homestory_820401001_15_option_content = "Menggelengkan kepala",
  str_homestory_820401001_16_dialog_content = "Yah, aku juga tidak yakin.",
  str_homestory_820401001_17_dialog_content = "Saya hanya ingat penjual mengatakan itu abadi.",
  str_homestory_820401001_18_dialog_content = "Anda juga bisa membesarkannya di dalam ruangan.",
  str_homestory_820401001_19_dialog_content = "Tampaknya menjadi varietas yang mudah dirawat.",
  str_homestory_820401001_20_dialog_content = "Anda memiliki banyak tanaman hijau di sini, PlayerName.",
  str_homestory_820401001_21_dialog_content = "Pernah dianggap memiliki bunga dalam campuran<sprite=emo_huaduo size=60 />?",
  str_homestory_820401001_22_dialog_content = "Maka lingkungan tidak akan monoton.",
  str_homestory_820401001_23_dialog_content = "Hei, itu saran yang bagus!",
  str_homestory_820401001_24_dialog_content = "Tapi aku tidak begitu baik dengan bunga...",
  str_homestory_820401001_25_dialog_content = "Lebih mudah bagi saya untuk tetap berpegang pada tanaman hijau.",
  str_homestory_820401001_26_dialog_content = "Saya akan menanam bunga yang berbeda di taman ketika saya di Lumopolis.",
  str_homestory_820401001_27_dialog_content = "Menyiram dan memangkasnya di waktu senggang...",
  str_homestory_820401001_28_dialog_content = "Itu membuat saya merasa sangat tenang di dalam.",
  str_homestory_820401001_29_dialog_content = "Aku tidak tahu kau menyukainya!",
  str_homestory_820401001_30_dialog_content = "Jadi, maukah Anda mengajari saya cara menanam bunga, Lady Joshua?",
  str_homestory_820401001_31_dialog_content = "Tentu saja!",
  str_homestory_820401001_32_dialog_content = "Menanam bunga tidaklah sulit, tetapi membutuhkan kesabaran.",
  str_homestory_820401001_33_dialog_content = "Bunga sangat halus pada tahap awal pertumbuhannya.",
  str_homestory_820401001_34_dialog_content = "Anda dapat menggunakan pot untuk tanaman ini untuk hal itu.",
  str_homestory_820401001_35_dialog_content = "Setelah Anda menanam benih, pastikan Anda menyiram secara teratur<sprite=emo_hanshui size=60 /> dan menunggu mereka berkembang.",
  str_homestory_820401001_36_dialog_content = "Tapi ingat jangan sampai overwater.",
  str_homestory_820401001_37_dialog_content = "OK saya mengerti. Kemudian?",
  str_homestory_820401001_38_dialog_content = "Setelah benih bertunas, rawatlah selama sebulan.",
  str_homestory_820401001_39_dialog_content = "Beri makan bibit dengan lebih banyak nutrisi untuk sementara!",
  str_homestory_820401001_40_dialog_content = "Saat Anda melihat anakan, pindahkan ke tempat yang lebih besar.",
  str_homestory_820401001_41_dialog_content = "Jadi saya perlu memindahkan mereka, saya mengerti ...",
  str_homestory_820401001_42_dialog_content = "Ya. Ketika Anda berkembang dari seorang anak menjadi remaja yang berani, PlayerName...",
  str_homestory_820401001_43_dialog_content = "Bukankah Anda juga menjelajah dan memperluas wawasan Anda di tempat lain?",
  str_homestory_820401001_44_dialog_content = "Itu bagian dari siklus pertumbuhan.",
  str_homestory_820401001_45_dialog_content = "Y-Yah, justru itulah yang terjadi...",
  str_homestory_820401001_46_dialog_content = "Tapi kau benar-benar membuatku malu.",
  str_homestory_820401001_47_dialog_content = "Kamu anak yang baik, PlayerName.",
  str_homestory_820501001_0_dialog_content = "Nona Blanc?",
  str_homestory_820501001_1_dialog_content = "Aku melihat matamu tertutup. Apakah kamu tertidur<sprite=emo_kun size=60 />?",
  str_homestory_820501001_2_dialog_content = "Tidak, saya sedang bermeditasi.",
  str_homestory_820501001_3_dialog_content = "Bermeditasi?",
  str_homestory_820501001_4_dialog_content = "Ya. Tahukah Anda apa itu meditasi?",
  str_homestory_820501001_5_option_content = "Sedikit",
  str_homestory_820501001_6_dialog_content = "Saya dengar meditasi bisa menenangkan pikiran dan menyembuhkan trauma.",
  str_homestory_820501001_7_dialog_content = "Itu benar, memang bisa melakukan itu.",
  str_homestory_820501001_8_option_content = "Tidak.",
  str_homestory_820501001_9_dialog_content = "Meditasi adalah latihan mental yang dapat menenangkan pikiran dan menyembuhkan trauma.",
  str_homestory_820501001_10_dialog_content = "Apakah Anda memiliki semacam masalah? Merasa gelisah?",
  str_homestory_820501001_11_dialog_content = "Selain bermeditasi sendirian, Anda juga bisa berbicara dengan teman, seperti saya.",
  str_homestory_820501001_12_dialog_content = "Saya pikir Anda terlihat agak kesepian.",
  str_homestory_820501001_13_dialog_content = "Saya menghargai pemikiran itu.",
  str_homestory_820501001_14_dialog_content = "Saya menikmati kebersamaan dengan Anda, tentu saja, tetapi saya tidak dapat memberi tahu Anda alasan meditasi saya.",
  str_homestory_820501001_15_dialog_content = "Sebaliknya, itu tidak akan ada gunanya jika aku memberitahumu.",
  str_homestory_820501001_16_dialog_content = "Apakah ini sesuatu yang serius? saya bisa coba bantu...",
  str_homestory_820501001_17_dialog_content = "Heheh, punya teman sepertimu mungkin bisa membantu.",
  str_homestory_820501001_18_dialog_content = "Karena suasana hatiku meningkat setiap kali aku melihatmu.",
  str_homestory_820501001_19_dialog_content = "Meditasi juga merupakan rahasia untuk terlihat awet muda.",
  str_homestory_820501001_20_dialog_content = "Terlihat awet muda?",
  str_homestory_820501001_21_dialog_content = "Ya. Saya sedang bermeditasi untuk memperlambat penuaan dan mempertahankan penampilan fisik saya.",
  str_homestory_820501001_22_dialog_content = "Anda dapat melakukannya hanya dengan bermeditasi?",
  str_homestory_820501001_23_dialog_content = "Jangan remehkan kekuatan pikiran.",
  str_homestory_820501001_24_dialog_content = "Jadi, apakah Anda ingin mencobanya?",
  str_homestory_820501001_25_dialog_content = "Bisakah itu membuat saya menjadi petarung yang kuat dan perkasa?",
  str_homestory_820501001_26_dialog_content = "Apakah itu yang kamu inginkan?",
  str_homestory_820501001_27_dialog_content = "Ya, maka saya bisa melindungi orang-orang dan hal-hal yang ingin saya lindungi dengan lebih baik.",
  str_homestory_820501001_28_dialog_content = "Saya sangat menyetujui pemikiran itu karena saya juga telah berjuang untuk melindungi.",
  str_homestory_820501001_29_dialog_content = "Tetapi izinkan saya untuk mengingatkan Anda bahwa perlindungan memiliki banyak bentuk.",
  str_homestory_820501001_30_dialog_content = "Ambil saya, misalnya. Bahkan sebagai pemandu, saya membela Lumopolis dengan cara yang berbeda.",
  str_homestory_820501001_31_dialog_content = "Mengapa pengingat? Apakah karena saya tidak dapat mewujudkan apa yang saya inginkan melalui meditasi?",
  str_homestory_820501001_32_dialog_content = "Saya benar-benar tidak tahu apakah meditasi akan meningkatkan dan meningkatkan massa otot.",
  str_homestory_820501001_33_dialog_content = "Anda masih bisa mencobanya.",
  str_homestory_820501001_34_dialog_content = "Yah, saya pikir itu juga tidak akan ...",
  str_homestory_807501001_0_dialog_content = "Odi?",
  str_homestory_807501001_1_dialog_content = "Aku tidak percaya ada yang sebagus ini di sini!",
  str_homestory_807501001_2_dialog_content = "Di mana kunci pas saya? Aku akan mulai membongkar semuanya!",
  str_homestory_807501001_3_dialog_content = "Tunggu, apa yang kamu bongkar sekarang?",
  str_homestory_807501001_4_dialog_content = "Lampu jalan. Mengapa?",
  str_homestory_807501001_5_option_content = "Anda tidak bisa melakukan itu.",
  str_homestory_807501001_6_option_content = "Apakah lampu jalan rusak?",
  str_homestory_807501001_7_dialog_content = "Tidak, saya hanya ingin memisahkannya.",
  str_homestory_807501001_8_dialog_content = "Tidak bisa melakukan itu, kalau begitu.<sprite=emo_shengqi size=60 />",
  str_homestory_807501001_9_dialog_content = "Kenapa kamu! Mengapa saya tidak bisa? Itu hanya lampu jalan tua biasa!",
  str_homestory_807501001_10_dialog_content = "Itu tidak rusak, jadi mengapa Anda mengambilnya?",
  str_homestory_807501001_11_dialog_content = "Untuk mempelajarinya, tentu saja.",
  str_homestory_807501001_12_dialog_content = "Lihat, cahaya ini benar-benar berbeda dari yang lain.",
  str_homestory_807501001_13_dialog_content = "Eh, saya tidak melihat banyak perbedaan sama sekali.",
  str_homestory_807501001_14_dialog_content = "Saya tahu itu memiliki roda gigi internal yang rumit dan kabel di bagian luarnya.",
  str_homestory_807501001_15_dialog_content = "Saya tidak berpikir itu cara kerja lampu jalan di Lumopolis...",
  str_homestory_807501001_16_dialog_content = "Saya katakan, Anda tidak akan mengerti.",
  str_homestory_807501001_17_dialog_content = "Tidak, kamu tidak memberitahuku itu.",
  str_homestory_807501001_18_dialog_content = "Saya melihat Anda menjadi lebih baik dalam sassing.",
  str_homestory_807501001_19_dialog_content = "Oke, Anda memutuskan untuk menjaga cahaya ini, bukan?",
  str_homestory_807501001_20_dialog_content = "Kalau begitu, mari kita mulai.",
  str_homestory_807501001_21_dialog_content = "Dan kita akan melihat apakah saya dapat membuat Anda tidak berfungsi!",
  str_homestory_807501001_22_dialog_content = "Saya bukan mesin, saya tidak bisa rusak!",
  str_homestory_807501001_23_dialog_content = "Kabel Anda satu-satunya hal yang akan mengalami kegagalan fungsi.",
  str_homestory_807501001_24_dialog_content = "Apakah Anda mengancam saya?",
  str_homestory_807501001_25_dialog_content = "Saya hanya menyampaikan fakta...",
  str_homestory_807501001_26_dialog_content = "Apakah Anda tidak memandang rendah kami teknisi. Kamu mungkin seorang Caelestite, tapi aku akan tetap...",
  str_homestory_807501001_27_dialog_content = "???",
  str_homestory_807501001_28_dialog_content = "Ups, saya tidak tahu harus mengancam Anda dengan apa.<sprite=emo_sikao size=60 />",
  str_homestory_807501001_29_dialog_content = "Hahaha…",
  str_homestory_807501001_30_dialog_content = "Hei, tertawakan aku lagi dan aku akan meminta cadangan!",
  str_homestory_807501001_31_dialog_content = "Hahahahaha!",
  str_homestory_807501001_32_dialog_content = "Berhentilah tertawa, atau aku akan mendapatkan Sinsa untuk datang!",
  str_homestory_807501001_33_dialog_content = "Kamu yakin Sinsa akan memihakmu?",
  str_homestory_807501001_34_dialog_content = "Uh... Yah, tidak juga...",
  str_homestory_807501001_35_dialog_content = "Jadi, Anda hanya ingin mempelajari cahaya ini?",
  str_homestory_807501001_36_dialog_content = "Ya. Tampaknya cukup menarik untuk diurai dan dilihat.",
  str_homestory_807501001_37_dialog_content = "Tapi itu bekerja dengan sangat baik sekarang, jadi bagian dalamnya juga harus baik-baik saja.",
  str_homestory_807501001_38_dialog_content = "Mengapa Anda tidak menunggu sampai tidak berhasil? Kemudian saya akan meminta Anda untuk memperbaikinya.",
  str_homestory_807501001_39_dialog_content = "Itu bukan ide yang buruk. Memperbaiki hal-hal adalah apa yang saya lakukan!",
  str_homestory_807501001_40_dialog_content = "Baiklah, aku tidak akan memisahkannya sekarang.",
  str_homestory_807501001_41_dialog_content = "Izinkan saya mengucapkan terima kasih atas nama cahaya.",
  str_homestory_807501001_42_dialog_content = "Berbicara tentang itu, saya baru saja menangkap sinar di air. Itu bisa jadi semacam hal mekanis!",
  str_homestory_807501001_43_dialog_content = "Aku harus menyendoknya dan membongkarnya!",
  str_homestory_807501001_44_dialog_content = "Uh, mungkin aku harus menyelamatkan apapun yang ada di dalam air...",
  str_homestory_820601001_0_dialog_content = "Apa yang sedang dia lakukan?",
  str_homestory_820601001_1_dialog_content = "Lihat apa kau?<sprite=emo_yihuo size=60 />",
  str_homestory_820601001_2_dialog_content = "Pemandangan di sini luar biasa!",
  str_homestory_820601001_3_dialog_content = "Kamu sudah mencari cukup lama. Apakah kamu yakin itu hanya pemandangan?",
  str_homestory_820601001_4_dialog_content = "Jangan khawatir tentang itu. Apakah kamu tertarik untuk bekerja dengan saya?",
  str_homestory_820601001_5_dialog_content = "Kemampuan persepsi Caelestite yang tajam Anda pasti akan membantu saya dalam kompetisi bisnis di masa depan!",
  str_homestory_820601001_6_dialog_content = "Membantu kamu? Kompetisi?",
  str_homestory_820601001_7_dialog_content = "Mereka bilang \"Bisnis itu perang\" dan bakat seperti kamu adalah yang persis aku butuhkan!",
  str_homestory_820601001_8_dialog_content = "Saya menawarkan bonus proyek ditambah opsi saham. Jadi, kamu ikut?",
  str_homestory_820601001_9_dialog_content = "Itu tergantung pada proyek dan berapa banyak stok—",
  str_homestory_820601001_10_dialog_content = "Tunggu, aku belum bilang ya!",
  str_homestory_820601001_11_dialog_content = "Apa itu kompetisi bisnis? Dan apa hubungannya dengan pemandangan di sini?",
  str_homestory_820601001_12_dialog_content = "Sebenarnya, baru saja terpikir ide bisnis yang luar biasa... Jangan beritahu siapa-siapa.",
  str_homestory_820601001_13_dialog_content = "S-Saya tidak akan.",
  str_homestory_820601001_14_dialog_content = "Ini adalah ekspedisi ke laut biru!",
  str_homestory_820601001_15_option_content = "Laut biru?",
  str_homestory_820601001_16_dialog_content = "Samudra, seperti yang dikatakan!",
  str_homestory_820601001_17_dialog_content = "Jadi, kamu ingin terjun ke bisnis pengiriman?",
  str_homestory_820601001_18_option_content = "Industri pengiriman?",
  str_homestory_820601001_19_dialog_content = "Tidak!",
  str_homestory_820601001_20_dialog_content = "Laut biru adalah metafora, sebuah simile!",
  str_homestory_820601001_21_dialog_content = "Untuk apa metaforanya?",
  str_homestory_820601001_22_dialog_content = "Dalam bisnis, itu berarti wilayah yang belum terjamah yang penuh dengan peluang!",
  str_homestory_820601001_23_dialog_content = "Tapi apa hubungannya dengan kamu mengawasi dari menara pengawas?",
  str_homestory_820601001_24_dialog_content = "Saya menyadari pulau-pulau di laut belum benar-benar dikembangkan!",
  str_homestory_820601001_25_dialog_content = "Apakah secara harfiah atau kiasan, keduanya adalah laut biru!",
  str_homestory_820601001_26_dialog_content = "Jika saya bisa menemukan pulau-pulau di lautan dan mengubahnya menjadi resor...",
  str_homestory_820601001_27_dialog_content = "Liburan musim panas, petualangan, berburu harta karun, olahraga, berenang, taman bermain anak-anak...",
  str_homestory_820601001_28_dialog_content = "Saya bisa terus dan terus membahas hanya tentang tema saja!",
  str_homestory_820601001_29_dialog_content = "Jadi kamu ingin mengembangkan pulau-pulau? Ada hal spesifik sekarang?",
  str_homestory_820601001_30_dialog_content = "Belum ada prospek yang cocok. Itulah mengapa saya ingin mendapatkan kapal dan mencari satu.",
  str_homestory_820601001_31_dialog_content = "Sebesar apapun lautan itu, pasti ada pulau yang tidak berpenghuni di suatu tempat!",
  str_homestory_820601001_32_dialog_content = "Kita hanya perlu mengalahkan semua orang untuk mencapainya dan mengklaim pulau itu, lalu kita bisa membangunnya sesuai keinginan kita!",
  str_homestory_820601001_33_dialog_content = "Kita? Aku juga pergi?",
  str_homestory_820601001_34_dialog_content = "Tentu saja! Penglihatan dan pendengaran tajam yang aneh itu akan sangat berguna.",
  str_homestory_820601001_35_dialog_content = "Saya terdengar cukup menakjubkan dalam deskripsi itu.",
  str_homestory_820601001_36_dialog_content = "Jadi, langkah pertama adalah menemukan pulau yang cocok?",
  str_homestory_820601001_37_dialog_content = "Benar. Saya ingin tahu apakah kita bisa melihat lebih jauh jika kita pindahkan menara pengawas ke atas kapal.",
  str_homestory_820601001_38_dialog_content = "Dan karena kamu di sini, mari kita negosiasikan harga.",
  str_homestory_820601001_39_dialog_content = "Saya tidak berniat menjualnya...<sprite=emo_tanqi size=60 />",
  str_homestory_820601001_40_dialog_content = "Kita sebut saja itu sebagai bagian uang benihmu ya? Kamu cukup tertarik dengan usaha ini, aku tahu.",
  str_homestory_820601001_41_dialog_content = "Itu bukanlah apa yang saya maksud.",
  str_homestory_820601001_42_dialog_content = "Butuh waktu lebih lama untuk memikirkannya? Tidak masalah. Belum ada kontrak yang disusun, jadi semuanya bisa dinegosiasikan sebelum menandatangani garis bergaris.",
  str_homestory_820601001_43_dialog_content = "Saya akan menyusun rencana secepat mungkin. Kamu hanya perlu cepat memutuskan!",
  str_homestory_820601001_44_dialog_content = "...B-Baiklah. Sampai jumpa.",
  str_homestory_820701001_0_dialog_content = "Apakah dia mengendarainya?",
  str_homestory_820701001_1_dialog_content = "Sepertinya kamu sedang menikmati waktu yang menyenangkan.",
  str_homestory_820701001_2_dialog_content = "Sangat treni kamu mendapatkan tumpangan baru ke Cloud Gardens! Keren banget!",
  str_homestory_820701001_3_dialog_content = "Tapi aku dengar lebih baik jika ada dua orang.",
  str_homestory_820701001_4_dialog_content = "Saya pernah mendengar bahwa bermain sebagai duo bisa menjadi semacam ujian, terutama untuk pasangan...<sprite=emo_sikao size=60 />",
  str_homestory_820701001_5_dialog_content = "Sebuah tes?",
  str_homestory_820701001_6_dialog_content = "Dua orang yang bersama-sama naik dan berputar beberapa kali...",
  str_homestory_820701001_7_dialog_content = "Dan jika mereka masih bisa bertanya bagaimana keadaan orang lain tepat setelah mereka turun...",
  str_homestory_820701001_8_dialog_content = "Itu berarti hubungannya kokoh. Kalau tidak, ck...",
  str_homestory_820701001_9_dialog_content = "Lalu kenapa kamu naik ini sendirian? Apakah kamu sedang mempersiapkan untuk ujian di masa depan?",
  str_homestory_820701001_10_dialog_content = "Salah, teman!",
  str_homestory_820701001_11_dialog_content = "Ini perjalanan yang membuat pusing dan mual, tetapi juga sangat menarik.",
  str_homestory_820701001_12_dialog_content = "Cukup menggembirakan untuk mengingat kembali di hari-hari itu...",
  str_homestory_820701001_13_dialog_content = "Saya tidak yakin ingin tahu apa yang telah kamu alami, tetapi sepertinya saatnya cerita, bagaimanapun juga.",
  str_homestory_820701001_14_dialog_content = "Dulu saya seorang pemburu, yang mengkhususkan diri dalam mengejar penjahat tertentu.",
  str_homestory_820701001_15_dialog_content = "Maksud kamu seperti sheriff? Tapi bukankah kamu berasal dari Gurun Rediesel?",
  str_homestory_820701001_16_dialog_content = "Tidak mungkin ada hal seperti itu. Hanya geng seperti Rediesel Wrench yang berkeliling tempat itu.",
  str_homestory_820701001_17_dialog_content = "Saya melakukannya sendiri, itulah sebabnya saya mengatakan pemburu dan bukan sheriff.",
  str_homestory_820701001_18_dialog_content = "Jadi, jenis penjahat apa yang kamu kejar? Apakah itu ada hubungannya dengan masa lalumu?",
  str_homestory_820701001_19_dialog_content = "Saya dengar ada desa di Lembah Denuo yang pernah diserang. Apakah mereka terkait?",
  str_homestory_820701001_20_dialog_content = "Dari mana harus saya mulai... Mari kita mulai dengan sebuah cerita.",
  str_homestory_820701001_21_dialog_content = "Apa?",
  str_homestory_820701001_22_dialog_content = "Pada suatu waktu, ada seorang nelayan hebat dengan keterampilan memancing yang tak tertandingi.",
  str_homestory_820701001_23_dialog_content = "Intinya, jaring yang dibuatnya sangat kokoh dan rapat, sehingga tidak ada ikan yang bisa lolos.",
  str_homestory_820701001_24_dialog_content = "Dia mendapatkan hasil tangkapan besar setiap kali pergi ke laut, sehingga menjadi kaya.",
  str_homestory_820701001_25_dialog_content = "Tapi kemudian dia mulai menangkap ikan semakin sedikit...",
  str_homestory_820701001_26_dialog_content = "Kehabisan ikan?",
  str_homestory_820701001_27_dialog_content = "Benar! Jaringannya begitu rapat, bahkan yang muda pun tidak ketinggalan.",
  str_homestory_820701001_28_dialog_content = "Jadi populasi ikan menyusut hingga hampir tidak ada, sampai suatu hari...",
  str_homestory_820701001_29_dialog_content = "Aku melihat ada plot twist yang akan datang.<sprite=emo_yaosu size=60 />",
  str_homestory_820701001_30_dialog_content = "Anak nelayan itu melihat ikan yang indah di terumbu karang tersembunyi!",
  str_homestory_820701001_31_dialog_content = "Ukurannya menunjukkan bahwa ia masih muda, tetapi benar-benar indah.",
  str_homestory_820701001_32_dialog_content = "Anak itu tak bisa menahan diri untuk menceritakan kepada ayahnya, sang nelayan, saat tiba di rumah.",
  str_homestory_820701001_33_dialog_content = "Saya yakin nelayan itu langsung mengejarnya.",
  str_homestory_820701001_34_dialog_content = "Kali ini, dia membawa jaring terkuat dan paling rapat yang dimilikinya, bersumpah untuk menangkap ikan itu.",
  str_homestory_820701001_35_dialog_content = "Karena dia tahu itu adalah ikan aquarium yang berharga yang bisa mendapatkan uang yang sangat baik.",
  str_homestory_820701001_36_dialog_content = "Dibimbing oleh putranya, ia mencapai terumbu karang yang terpencil...",
  str_homestory_820701001_37_dialog_content = "Saya yakin inilah saat masalah dimulai.",
  str_homestory_820701001_38_dialog_content = "Benar! Mereka melihat ikan lagi, kecuali kali ini lebih besar dan lebih cantik!",
  str_homestory_820701001_39_dialog_content = "Apakah itu orang tua dari ikan yang dilihat oleh anak itu?",
  str_homestory_820701001_40_dialog_content = "Mungkin.",
  str_homestory_820701001_41_dialog_content = "Ketika ikan besar yang indah melihat perahu, ia mulai menghindar dan bergerak lincah di terumbu karang.",
  str_homestory_820701001_42_dialog_content = "Nelayan itu mengejarnya dalam pengejaran yang panas...",
  str_homestory_820701001_43_dialog_content = "Hanya untuk menabrakkan perahu ke karang.",
  str_homestory_820701001_44_dialog_content = "Perahu tenggelam. Baik nelayan dan anaknya meninggal.",
  str_homestory_820701001_45_dialog_content = "Oh...",
  str_homestory_820701001_46_dialog_content = "Jadi siapa penjahat yang kamu bicarakan sejak nelayan dan anaknya meninggal dalam cerita itu?",
  str_homestory_820701001_47_dialog_content = "Itulah mengapa itu hanya cerita. Jangan membaca terlalu banyak ke dalamnya.",
  str_homestory_820801001_0_dialog_content = "Dia terobsesi sejak lama...",
  str_homestory_820801001_1_dialog_content = "Sedang apa kau?",
  str_homestory_820801001_2_dialog_content = "Apa? Oh, kamu rupanya! Kamu menyadari aku?!<sprite=emo_wuzui size=60 />",
  str_homestory_820801001_3_dialog_content = "Itu karena kamu sudah lama menatap monumen itu. Apakah mata kamu tidak lelah?",
  str_homestory_820801001_4_dialog_content = "Saya merasakannya sekarang setelah kamu menyebutkannya...",
  str_homestory_820801001_5_dialog_content = "Tunggu sebentar, intinya adalah kamu menyadari keberadaan saya!",
  str_homestory_820801001_6_dialog_content = "Apakah ini kekuatan monumen, membuat orang lain memperhatikan mereka yang tidak signifikan?",
  str_homestory_820801001_7_dialog_content = "Tidak, ini benar-benar karena kamu sudah berdiri di sini terlalu lama.",
  str_homestory_820801001_8_dialog_content = "Lihat gambar-gambarnya! Bisakah kamu mengerti maksudnya, PlayerName?",
  str_homestory_820801001_9_dialog_content = "Tidak juga... Sepertinya ini kuno.",
  str_homestory_820801001_10_dialog_content = "Ini sangat tua, saya tidak yakin siapa pun bisa tahu apa yang ingin disampaikan.",
  str_homestory_820801001_11_dialog_content = "Benarkah? Mendesah...",
  str_homestory_820801001_12_dialog_content = "Mengapa wajahmu murung sekarang? Kamu terlihat agak sedih...",
  str_homestory_820801001_13_dialog_content = "Itu karena saya sedang memikirkan masa depan Rediesel Wrench.",
  str_homestory_820801001_14_option_content = "Maksud kamu, masa depan?",
  str_homestory_820801001_15_dialog_content = "Saya belum memutuskan, tetapi saya tahu itu harus menjadi tujuan jangka panjang, bukan main-main seperti yang kita lakukan sekarang.",
  str_homestory_820801001_16_dialog_content = "Tapi itu gaya Rediesel! Banyak orang bergabung karena hal itu.",
  str_homestory_820801001_17_dialog_content = "Benar, tapi memiliki rencana itu selalu menyenangkan! Saya belum bisa memikirkan apa-apa, tapi kita harus punya satu!",
  str_homestory_820801001_18_option_content = "Kamu tidak terlalu memikirkannya?",
  str_homestory_820801001_19_dialog_content = "...",
  str_homestory_820801001_20_dialog_content = "Bopper?",
  str_homestory_820801001_21_dialog_content = "Aku tidak tahu mengapa, tapi aku merasa seseorang harus melakukannya!",
  str_homestory_820801001_22_dialog_content = "Berkeliling dan menggelandang setiap hari dengan tujuan acak dalam pikiran... Itu hanya tidak disiplin.",
  str_homestory_820801001_23_dialog_content = "Sepertinya kamu sudah memikirkannya dengan serius...",
  str_homestory_820801001_24_dialog_content = "Saya tidak pikir itu bahkan ada di agenda Sinsa.",
  str_homestory_820801001_25_dialog_content = "Saya mengerti bahwa sebagai bos, dia hanya perlu menjadi pemimpin yang keren.",
  str_homestory_820801001_26_dialog_content = "Sedangkan tugas saya untuk menyusun rencana sebagai ahli strategi.",
  str_homestory_820801001_27_dialog_content = "Tapi apa hubungannya dengan monumen-monumen itu?",
  str_homestory_820801001_28_dialog_content = "Lebihkan pada spontanitas!",
  str_homestory_820801001_29_dialog_content = "Saya dengar ada monumen seperti ini di Lumopolis, Federasi Illumina, dan bahkan Northland.",
  str_homestory_820801001_30_dialog_content = "Dibangun untuk memperingati orang terkenal, jasa, atau prestasi!",
  str_homestory_820801001_31_dialog_content = "Tapi kami Rediesel Wrench tidak memiliki sesuatu seperti itu...",
  str_homestory_820801001_32_dialog_content = "Selain itu, kita tidak memiliki wilayah sendiri seperti mereka...",
  str_homestory_820801001_33_dialog_content = "Jadi apa yang akan terjadi jika masa depan menjadi kacau atau semua orang terlibat dalam pertengkaran besar dan pergi ke jalannya masing-masing?",
  str_homestory_820801001_34_dialog_content = "Itu memang terdengar seperti kepedulian yang sah.",
  str_homestory_820801001_35_dialog_content = "Lihat!",
  str_homestory_820801001_36_dialog_content = "Tapi, apakah kamu sudah memikirkan bentuk monumen yang seharusnya?",
  str_homestory_820801001_37_dialog_content = "Bentuk?",
  str_homestory_820801001_38_dialog_content = "Tidak harus berupa monumen, cukup sesuatu yang mewakili Rediesel Wrench.",
  str_homestory_820801001_39_dialog_content = "Maksud kamu misalnya...",
  str_homestory_820801001_40_dialog_content = "Graffiti di mobil?",
  str_homestory_820801001_41_dialog_content = "Jika itu gayamu, kamu selalu bisa tahu itu Rediesel Wrench di mana pun kamu berada.",
  str_homestory_820801001_42_dialog_content = "Atau seperti jika kita membunuh seekor sandworm, kita bisa menggambar satu dengan tanda X di atasnya.",
  str_homestory_820801001_43_dialog_content = "Ya, itu ide yang bagus!",
  str_homestory_820801001_44_dialog_content = "Belum lagi Rediesel Wrench penuh dengan seniman grafiti yang luar biasa!",
  str_homestory_820801001_45_dialog_content = "Saya harus mencari tahu rencana untuk Kontes Grafiti Mobil Rediesel Wrench yang Hebat! <sprite=emo_yaosu size=60 />",
  str_homestory_820901001_0_dialog_content = "Dia lihat apa, sih?",
  str_homestory_820901001_1_dialog_content = "Komandan Wrath... Apa yang sedang kamu lakukan di sini?",
  str_homestory_820901001_2_dialog_content = "Aku tidak melakukan apa-apa. Baru saja melihat sesuatu yang sangat menarik.",
  str_homestory_820901001_3_dialog_content = "Jadi beginilah cara Illumina merekrut orang-orang saat ini...",
  str_homestory_820901001_4_dialog_content = "Bukankah kamu Grand Marshal? Kenapa rasanya seperti kamu baru menyadarinya sekarang...?",
  str_homestory_820901001_5_dialog_content = "Karena Grand Marshal tidak bertanggung jawab untuk mengawasi rekrutmen eksternal...",
  str_homestory_820901001_6_dialog_content = "Itulah yang saya duga... Apa pendapatmu?",
  str_homestory_820901001_7_option_content = "Benar.",
  str_homestory_820901001_8_dialog_content = "Saya rasa Grand Marshal sebenarnya tidak punya waktu untuk hal-hal seperti itu.",
  str_homestory_820901001_9_option_content = "Kenapa kau tanya padaku?!",
  str_homestory_820901001_10_dialog_content = "Kamu adalah Grand Marshal! Namun, kamu masih menebak apa tanggung jawabmu seharusnya?",
  str_homestory_820901001_11_dialog_content = "Hal pertama yang kulakukan setelah menjadi Grand Marshal adalah memimpin sebuah ekspedisi.",
  str_homestory_820901001_12_dialog_content = "Tapi sekarang... Sudah saatnya untuk menangani masalah lain.",
  str_homestory_820901001_13_dialog_content = "Misalnya—di mana kalian menemukan benda ini?",
  str_homestory_820901001_14_dialog_content = "Itu di Umbraton... Saat itu kami sedang syuting film.",
  str_homestory_820901001_15_dialog_content = "Film? Aku mengerti... <sprite=emo_sikao size=60 />",
  str_homestory_820901001_16_dialog_content = "Apa yang terlintas di pikiranmu?",
  str_homestory_820901001_17_dialog_content = "Iklan wajib militer ini... Bagaimana mereka mengharapkan orang-orang terbaik dan pemberani di negara ini untuk mendaftar di tentara dengan papan yang menyedihkan itu?",
  str_homestory_820901001_18_dialog_content = "Selama aku memimpin, aku ingin membuat Illumina lebih kuat dari sebelumnya.",
  str_homestory_820901001_19_dialog_content = "Jadi?",
  str_homestory_820901001_20_dialog_content = "Bagaimana kalau kita membuat film tentang prajurit Illumina? Sebuah karya propaganda untuk membantu merekrut generasi pahlawan bangsa ini selanjutnya...",
  str_homestory_820901001_21_option_content = "Kamu serius sekarang?",
  str_homestory_820901001_22_dialog_content = "Meskipun kamu mengatakannya seperti itu... Membuat film tetap tidak terdengar seperti hal yang dilakukan Illumina.",
  str_homestory_820901001_23_dialog_content = "Memang benar bahwa pendekatan Illumina terhadap pendidikan lebih condong ke teknologi dan seni perang daripada seni itu sendiri...",
  str_homestory_820901001_24_dialog_content = "Aku akan menjadi orang pertama yang mengakui itu.",
  str_homestory_820901001_25_dialog_content = "Itulah mengapa aku ingin kamu menembak benda ini.",
  str_homestory_820901001_26_option_content = "Ayo kita coba!",
  str_homestory_820901001_27_dialog_content = "Menggugah dan inspiratif sekalipun semua slogan itu, mereka tidak akan pernah bisa dibandingkan dengan sebuah film.",
  str_homestory_820901001_28_dialog_content = "Jika kita bisa menunjukkan keberanian seorang pahlawan Illumina sejati di layar lebar, kita akan mengirim gelombang kejut ke seluruh benua.",
  str_homestory_820901001_29_dialog_content = "Aku tidak sabar untuk mewujudkan ini!",
  str_homestory_820901001_30_dialog_content = "Baik, sudah beres! Urusan film ini sepenuhnya ada di tanganmu sekarang. Aku akan mencari dana dan menyiapkan gaji kalian.",
  str_homestory_820901001_31_dialog_content = "Tapi... Saya sama sekali tidak tahu tentang cara membuat film!",
  str_homestory_820901001_32_dialog_content = "Aku pikir kamu tipe yang kreatif, bukan? Aku ingat kamu bahkan menulis beberapa puisi dulu.",
  str_homestory_820901001_33_dialog_content = "Menulis puisi dan membuat film adalah dua hal yang sangat berbeda! Selain itu, puisi saya bahkan tidak begitu bagus...",
  str_homestory_820901001_34_dialog_content = "Menurut pemahamanku, seni itu pada dasarnya saling terhubung, bukan?",
  str_homestory_820901001_35_dialog_content = "Bukan itu masalahnya di sini!",
  str_homestory_820901001_36_dialog_content = "Selain itu, bahkan tidak ada satu pun bioskop di seluruh Illumina!",
  str_homestory_820901001_37_dialog_content = "Nah, kami punya ruang pemutaran, tapi hanya buka di hari libur.",
  str_homestory_820901001_38_dialog_content = "Jadi orang-orang bahkan tidak akan mendapatkan kesempatan untuk menonton film...",
  str_homestory_820901001_39_dialog_content = "Illumina mendaftarkan semua warga negaranya sendiri. Kampanye rekrutmen seperti ini jelas ditujukan untuk calon rekrut di luar federasi.",
  str_homestory_820901001_40_dialog_content = "Tapi sekarang setelah kamu menyebutkannya, membiarkan orang Illumina melihat federasi melalui lensa direktur mungkin bisa meningkatkan semangat mereka, mungkin.",
  str_homestory_820901001_41_dialog_content = "Dan jika itu memang kasusnya... ini akan menjadi kesempatan langka. Lalu—saya harus membintangi hal ini.",
  str_homestory_820901001_42_dialog_content = "Bagaimana kalau kita bawa Reinhardt ke sini dan lihat siapa yang memiliki kehadiran layar terbanyak, ya?",
  str_homestory_820901001_43_dialog_content = "Hei, jika kita tampilkan beberapa komandan di layar, mungkin bisa memicu persaingan di antara legiun-legiun.",
  str_homestory_820901001_44_dialog_content = "Kamu benar-benar terbawa suasana di sini...",
  str_homestory_820901001_45_dialog_content = "Oh ya, dan kamu juga bisa berakting dan mengarahkan hal ini secara bersamaan.",
  str_homestory_820901001_46_dialog_content = "Sebagai satu-satunya Caelestite dan sutradara, tentu saja kamu seharusnya memiliki peran utama.",
  str_homestory_820901001_47_dialog_content = "Kamu sama sekali tidak mendengarkanku, ya? Mungkin aku harus menyerah saja... <sprite=emo_yundao size=60 />",
  str_homestory_820901001_48_dialog_content = "Oh, benar. Baru saja terpikirkan nama yang sempurna untuk film ini.",
  str_homestory_820901001_49_dialog_content = "\"Menyelamatkan Caelestite PlayerName\"... Apa pendapatmu?",
  str_homestory_821001001_0_dialog_content = "Joselyne sedang berdoa di depan bendera...",
  str_homestory_821001001_1_dialog_content = "Joselyne?",
  str_homestory_821001001_2_dialog_content = "Tidak perlu berdiri menunggu sepanjang waktu itu. Kamu bisa saja memanggilku.",
  str_homestory_821001001_3_dialog_content = "Aku takut mungkin aku mengganggumu.",
  str_homestory_821001001_4_dialog_content = "Dewa Cahaya tidak mempertanyakan keimanan kita hanya karena doa kita terganggu.",
  str_homestory_821001001_5_dialog_content = "Dan saya tidak akan pernah marah karena masalah sepele seperti itu. Apakah kamu membutuhkan bantuan saya untuk sesuatu?",
  str_homestory_821001001_6_dialog_content = "Tidak, aku hanya melihatmu berdiri di depan bendera ini dan berpikir untuk mendekat.",
  str_homestory_821001001_7_dialog_content = "Barusan kamu berdoa ke bendera ini?",
  str_homestory_821001001_8_dialog_content = "Berdoa? Memang benar, jika seseorang berdoa melalui media tertentu, doa mereka akan terdengar lebih jelas.",
  str_homestory_821001001_9_option_content = "Sebuah bendera dengan ukuran medium seperti ini?",
  str_homestory_821001001_10_dialog_content = "Umm. Kepercayaan pada Dewa Cahaya selalu menjadi bagian tak terpisahkan dari kehidupan Lumopolis yang konvensional...",
  str_homestory_821001001_11_dialog_content = "Jadi, saya rasa masuk akal jika kamu menggunakan bendera Lumopolis sebagai media untuk berdoa.",
  str_homestory_821001001_12_option_content = "Maksud kamu seperti relik suci?",
  str_homestory_821001001_13_dialog_content = "Sejauh yang saya pahami, orang yang mencari persekutuan dengan tuhan mereka sering mencoba melakukannya dengan menggunakan relik suci, benar?",
  str_homestory_821001001_14_dialog_content = "Dengan cara ini, mereka mungkin bisa berkomunikasi langsung dengan yang ilahi. Terdengar sangat efektif!",
  str_homestory_821001001_15_dialog_content = "Sebenarnya, objek apa pun dapat digunakan sebagai media untuk mencapai efek yang sama.",
  str_homestory_821001001_16_dialog_content = "Kasih karunia Cahaya <sprite=emo_taiyang size=60 /> menyebar ke seluruh negeri. Segala yang ada di bawah matahari terhubung dengan cahaya Tuhan.",
  str_homestory_821001001_17_dialog_content = "Seringkali aku berdoa pada bunga tomat saat merawat kebun sayur.",
  str_homestory_821001001_18_dialog_content = "Yang benar?",
  str_homestory_821001001_19_dialog_content = "Namun, penting untuk memilih subjek yang sesuai saat melakukan doa khusus.",
  str_homestory_821001001_20_dialog_content = "Lalu untuk apa kamu berdoa saat menatap bendera Lumopolis?",
  str_homestory_821001001_21_dialog_content = "...",
  str_homestory_821001001_22_dialog_content = "Maaf, aku hanya penasaran.",
  str_homestory_821001001_23_dialog_content = "Jika saya bicara di luar giliran, tolong abaikan saja saya, Joselyne.",
  str_homestory_821001001_24_dialog_content = "Tidak, tidak... Bagaimanapun, tugasku adalah menyebarkan anugerah Dewa Cahaya kepada semua orang.",
  str_homestory_821001001_25_dialog_content = "Mengenai keyakinan, aku akan membagikan apa pun yang aku tahu.",
  str_homestory_821001001_26_dialog_content = "Tapi barusan, aku...",
  str_homestory_821001001_27_dialog_content = "Kamu apa...?",
  str_homestory_821001001_28_dialog_content = "Saya hanya ingin melihat lebih dekat jahitan pada bendera itu.",
  str_homestory_821001001_29_dialog_content = "Lumopolis benar-benar bersinar dalam bidang pembuatan barang-barang yang berkaitan dengan agama.",
  str_homestory_821001001_30_dialog_content = "Terutama bendera seperti ini. Mereka adalah penunjuk arah yang membimbing semua orang yang melihatnya. Tentu saja, mereka harus cukup tangguh.",
  str_homestory_821001001_31_dialog_content = "Jika aku bisa menemukan cara untuk meningkatkan keterampilan menjahitku, aku bisa melakukan lebih banyak untuk membantu orang-orang yang membutuhkan di sana.",
  str_homestory_821001001_32_dialog_content = "Hah, dan sekarang aku tidak bisa menghilangkan bayangan dirimu mengibarkan bendera secara heroik dari kepalaku...",
  str_homestory_821001001_33_dialog_content = "Kamu tidak akan menemukan aku mengibarkan bendera. Ini tidak semudah yang terlihat, tahu?",
  str_homestory_821001001_34_dialog_content = "Meskipun penduduk setempat menyebutku \"Santo Perempuan,\" aku jauh dari menjadi pemimpin spiritual yang mereka butuhkan.",
  str_homestory_821001001_35_dialog_content = "Untuk saat ini, saya perlu memulai dengan menjahit bendera Ksatria Ironthorn.",
  str_homestory_821001001_36_dialog_content = "Benar. Membuat bendera yang layak untuk memimpin serangan pertempuran sama pentingnya dengan mengibarkannya. Saya akan membantu juga, jika kamu mau.",
  str_homestory_821001001_37_dialog_content = "Apakah kamu juga tahu cara menjahit?",
  str_homestory_821001001_38_dialog_content = "Nah, aku belajar beberapa trik kecil dari Soroz saat masih kecil...",
  str_homestory_821001001_39_dialog_content = "Aku akan mengajari kamu semua yang telah aku pelajari. Ini seharusnya juga memperkuat dan meningkatkan keterampilanku.",
  str_homestory_821001001_40_dialog_content = "Yang pertama—bawalah semua bajumu kepadaku.",
  str_homestory_821001001_41_dialog_content = "A-Semua mereka?",
  str_homestory_821001001_42_dialog_content = "Satu-satunya cara untuk menguasai dasar-dasar adalah melalui latihan yang ekstensif.",
  str_homestory_821001001_43_dialog_content = "Hanya bicara tanpa tindakan akan semakin membawa kita ke dalam kegelapan, di mana bahkan Dewa Cahaya pun tidak bisa menyelamatkan kita.",
  str_homestory_821001001_44_dialog_content = "Aku percaya kamu bukan Caelestite jenis itu, 'kan?",
  str_homestory_821001001_45_dialog_content = "Tentu saja tidak! Aku akan segera mengambil pakaian itu!",
  str_homestory_821201001_0_dialog_content = "Antony?",
  str_homestory_821201001_1_dialog_content = "Antony, kamu sudah berdiri di Jagged Corridor selama setengah jam.",
  str_homestory_821201001_2_dialog_content = "Apa kau tertarik dengan benda ini?",
  str_homestory_821201001_3_dialog_content = "Oh... Halo, PlayerName.",
  str_homestory_821201001_4_dialog_content = "Sejujurnya, saya benar-benar cukup tertarik dengan itu.",
  str_homestory_821201001_5_dialog_content = "Pertama kali kulihat itu, aku yakin tentang satu hal—",
  str_homestory_821201001_6_dialog_content = "Tidak bisa dipungkiri nilai penelitiannya!",
  str_homestory_821201001_7_dialog_content = "May Aku bertanya, tulang-tulang ini sebenarnya berasal dari makhluk apa?",
  str_homestory_821201001_8_dialog_content = "Nah, itu pertanyaan yang bahkan membuat aku bingung...",
  str_homestory_821201001_9_dialog_content = "Saat ini, juri belum memutuskan tentang poin khusus itu. Ada berbagai macam pendapat mengenai tulang-tulang ini.",
  str_homestory_821201001_10_dialog_content = "Menurut pendapat pribadimu, tulang jenis apa yang kamu pikir mereka itu?",
  str_homestory_821201001_11_dialog_content = "Aku percaya pada penilaianmu.",
  str_homestory_821201001_12_dialog_content = "Biarkan aku berpikir<sprite=emo_sikao size=60 />... Mungkin mereka...",
  str_homestory_821201001_13_option_content = "Tulang-tulang dari hewan tertentu.",
  str_homestory_821201001_14_dialog_content = "Tulang hewan?",
  str_homestory_821201001_15_dialog_content = "Saya telah bepergian ke banyak tempat dan belum pernah melihat tulang seperti ini.",
  str_homestory_821201001_16_dialog_content = "Kalau begitu, ini mungkin adalah sisa-sisa makhluk yang sudah punah!",
  str_homestory_821201001_17_dialog_content = "Benarkah…?",
  str_homestory_821201001_18_option_content = "Ini adalah rusuk dari Colossus.",
  str_homestory_821201001_19_dialog_content = "Apa?!",
  str_homestory_821201001_20_dialog_content = "Kau serius?",
  str_homestory_821201001_21_dialog_content = "B-Benarkah ini tulang yang dulu digunakan untuk membuat Colossus?!",
  str_homestory_821201001_22_dialog_content = "Ini hanya tebakan, itu saja.",
  str_homestory_821201001_23_dialog_content = "Tidak, tidak, kamu Caelestite! Kamu tidak bisa salah!",
  str_homestory_821201001_24_dialog_content = "Pokoknya, aku harus mempelajari Koridor Bergerigi ini dengan cermat!",
  str_homestory_821201001_25_dialog_content = "Bolehkah aku memindahkan sebagian ke kamarku untuk membantu risetku?!",
  str_homestory_821201001_26_dialog_content = "Hei, kamu jangan pindahkan apa pun ke kamarmu, ya?!",
  str_homestory_821201001_27_dialog_content = "Bagaimanapun, ini adalah properti publik...",
  str_homestory_821201001_28_dialog_content = "Meskipun begitu, aku sedikit penasaran tentang apa sebenarnya kebenaran itu.",
  str_homestory_821201001_29_dialog_content = "Baiklah, Anda bisa melakukan penelitian di sini, dan jika Anda membutuhkan bantuan, saya yakin Anda akan dapat menemukan seseorang yang bersedia membantu Anda.",
  str_homestory_821201001_30_dialog_content = "Jangan khawatir!",
  str_homestory_821201001_31_dialog_content = "Aku tahu aku akan sampai ke dasar ini!<sprite=emo_dianzan size=60 />",
  str_homestory_821101001_0_dialog_content = "Zarya, apa yang sedang kamu lakukan?",
  str_homestory_821101001_1_dialog_content = "Oh, PlayerName, kamu punya ide apa ini?",
  str_homestory_821101001_2_dialog_content = "Tulisan \"Mobil Detektif\" ada di situ.",
  str_homestory_821101001_3_dialog_content = "Apa itu... mobil?",
  str_homestory_821101001_4_dialog_content = "Nah, pada dasarnya, ini adalah moda transportasi yang nyaman.",
  str_homestory_821101001_5_dialog_content = "Ini adalah moda transportasi?",
  str_homestory_821101001_6_dialog_content = "Orang-orang tidak lagi menggunakan kereta kuda...?",
  str_homestory_821101001_7_dialog_content = "Di beberapa tempat mereka masih menggunakan kereta kuda, tetapi Anda akan menemukan bahwa orang kaya di sebagian besar daerah, umumnya mengendarai mobil.",
  str_homestory_821101001_8_dialog_content = "Oh...",
  str_homestory_821101001_9_dialog_content = "Kamu tertarik dengan kereta kuda, Zarya?",
  str_homestory_821101001_10_dialog_content = "Saya tertarik melihat bagaimana ini adalah sesuatu yang belum pernah kulihat sebelumnya.",
  str_homestory_821101001_11_dialog_content = "Bisakah kamu mengajakku melihat yang asli nanti?",
  str_homestory_821101001_12_option_content = "Tentu.",
  str_homestory_821101001_13_dialog_content = "Tapi kau harus berjanji akan duduk di kursi belakang dan menjaga sikapmu.",
  str_homestory_821101001_14_dialog_content = "Dalam situasi apa pun Anda tidak boleh mengemudi.",
  str_homestory_821101001_15_option_content = "Kurasa tidak.",
  str_homestory_821101001_16_dialog_content = "Hah? Kenapa tidak...?<sprite=emo_yihuo size=60 />",
  str_homestory_821101001_17_dialog_content = "Aku merasa seperti kamu selalu hanya beberapa saat lagi sebelum melakukan sesuatu yang sangat berbahaya.",
  str_homestory_821101001_18_dialog_content = "Seperti mengambil alih kereta kuda, misalnya.",
  str_homestory_821101001_19_dialog_content = "Mengesankan, PlayerName.",
  str_homestory_821101001_20_dialog_content = "Bagaimana kamu tahu aku ingin mencobanya?",
  str_homestory_821101001_21_dialog_content = "Naik?",
  str_homestory_821101001_22_dialog_content = "Bukankah Anda bilang itu adalah mode transportasi... seperti kereta lainnya?",
  str_homestory_821101001_23_dialog_content = "Jadi prinsipnya seharusnya sama, bukan?",
  str_homestory_821101001_24_dialog_content = "Yang perlu kamu lakukan hanyalah mengayunkan cambuk sedikit dan itu akan membawa kamu ke tempat yang kamu inginkan.",
  str_homestory_821101001_25_dialog_content = "Atau apakah kamu harus memberikan perintah?",
  str_homestory_821101001_26_dialog_content = "Mungkin saya bukan yang terbaik dalam mengendalikan Luminatics, tapi saya tahu cara mengurus kuda!",
  str_homestory_821101001_27_dialog_content = "...",
  str_homestory_821101001_28_dialog_content = "Hah? Kucing menangkap lidahmu?",
  str_homestory_821101001_29_dialog_content = "Kuasa rasa kamu benar-benar perlu meningkatkan pengetahuan tentang dunia modern...",
  str_homestory_821101001_30_dialog_content = "Hah?",
  str_homestory_821301001_0_dialog_content = "No. 33?",
  str_homestory_821301001_1_dialog_content = "Apakah kamu berencana untuk pergi piknik?",
  str_homestory_821301001_2_dialog_content = "Ya, seperti yang kaulihat.",
  str_homestory_821301001_3_dialog_content = "Oleh karena alasan ini, saya sedang melakukan persiapan yang diperlukan.",
  str_homestory_821301001_4_dialog_content = "Jangan bilang kamu berencana pergi sendirian?",
  str_homestory_821301001_5_dialog_content = "Sepertinya kamu salah paham padaku.",
  str_homestory_821301001_6_dialog_content = "Tentu saja, aku akan mengundang teman-teman Aurorianku yang lain untuk bergabung denganku.",
  str_homestory_821301001_7_dialog_content = "Tentu saja, itu termasuk kamu.",
  str_homestory_821301001_8_dialog_content = "Ini akan menjadi kehormatan saya.",
  str_homestory_821301001_9_dialog_content = "...",
  str_homestory_821301001_10_dialog_content = "Ngomong-ngomong, kenapa kamu tidak mengundang Vice dan yang lainnya?",
  str_homestory_821301001_11_dialog_content = "Saya sedang melakukan pekerjaan analisis yang penting.",
  str_homestory_821301001_12_dialog_content = "Dengan menanyakan orang-orang di sekitarku, aku telah mengetahui standar makanan di piknik-piknikmu sebelumnya.",
  str_homestory_821301001_13_dialog_content = "Berdasarkan makanan piknik yang sejauh ini diterima dari teman-teman Aurorianku, aku sampai pada kesimpulan yang mengejutkan:",
  str_homestory_821301001_14_dialog_content = "Kelebihan kalori dapat berdampak buruk pada kesehatan seseorang.",
  str_homestory_821301001_15_dialog_content = "Hah?",
  str_homestory_821301001_16_dialog_content = "Bagaimana menurutmu, PlayerName?",
  str_homestory_821301001_17_option_content = "Kau benar.",
  str_homestory_821301001_18_dialog_content = "Jika dilihat dari sudut pandang gizi saja, memang, jenis makanan ini memiliki kalori yang terlalu banyak.",
  str_homestory_821301001_19_dialog_content = "Jarang sekali kau setuju sepenuhnya dengan sudut pandangku.",
  str_homestory_821301001_20_dialog_content = "Namun…",
  str_homestory_821301001_21_option_content = "Itu tidak benar.",
  str_homestory_821301001_22_dialog_content = "Mengenai pernyataan Anda \"itu tidak benar,\" pendekatan analitis apa yang Anda gunakan untuk mencapai kesimpulan seperti itu?",
  str_homestory_821301001_23_dialog_content = "Saya menganggap penilaian yang saya bagikan dengan Anda sepenuhnya mantap.",
  str_homestory_821301001_24_dialog_content = "Saat kita pergi piknik, tujuan utama kita tentu saja untuk melepas penat.",
  str_homestory_821301001_25_dialog_content = "Kamu tidak akan mencapai tujuan itu jika menghabiskan waktu memikirkan hal-hal kecil.",
  str_homestory_821301001_26_dialog_content = "Mengkhawatirkan hal-hal kecil? Melepas penat?",
  str_homestory_821301001_27_dialog_content = "Aku tahu niatmu baik, No. 33, tapi terkadang kau perlu bersantai.",
  str_homestory_821301001_28_dialog_content = "Kamu bisa tegas saat saatnya untuk tegas, dan coba bersantai saat saatnya untuk bersantai. Dengan begitu, orang-orang akan lebih menyukaimu.",
  str_homestory_821301001_29_dialog_content = "Informasi diterima. Menganalisis informasi...",
  str_homestory_821301001_30_dialog_content = "Aku mengerti.",
  str_homestory_821301001_31_dialog_content = "Maka saya akan menyesuaikan kembali resep piknik saya.",
  str_homestory_821301001_32_dialog_content = "Tunggu undangan dari saya, ya.",
  str_homestory_821401001_0_dialog_content = "Rebecca?",
  str_homestory_821401001_1_dialog_content = "Navigator…",
  str_homestory_821401001_2_dialog_content = "Mau duduk di kursi gantung?",
  str_homestory_821401001_3_dialog_content = "Tidak... Aku hanya merasa sedikit bernostalgia...",
  str_homestory_821401001_4_dialog_content = "Dulu... di halaman rumahku ada kursi gantung yang serupa.",
  str_homestory_821401001_5_dialog_content = "Dulu, aku dan kakak perempuanku, Eleanor, sering bermain bersama di kursi gantung.",
  str_homestory_821401001_6_dialog_content = "Tapi hanya dua orang yang bisa bermain di situ karena kursi gantungnya terlalu kecil dan memiliki ruang yang terbatas...",
  str_homestory_821401001_7_dialog_content = "Yang berarti salah satu dari kami akan selalu kehilangan kesempatan...",
  str_homestory_821401001_8_dialog_content = "Benarkah? Jadi bagaimana Anda memutuskan siapa yang akan terlewatkan?",
  str_homestory_821401001_9_dialog_content = "Kami main batu-gunting-kertas.",
  str_homestory_821401001_10_dialog_content = "Aneh jika aku pikirkan sekarang. Aku tidak pernah kalah saat itu. Bahkan tidak satu kali pun.",
  str_homestory_821401001_11_dialog_content = "Mungkin mereka sudah membahas hal ini di antara mereka?",
  str_homestory_821401001_12_dialog_content = "Mungkin saja. Sejujurnya, hubungan antara kakak perempuanku dan Eleanor... memang tidak pernah begitu baik...",
  str_homestory_821401001_13_dialog_content = "Aku ingat dulu ada saatnya ketika aku turun dari kursi gantung untuk mengayunkannya...",
  str_homestory_821401001_14_dialog_content = "Pada akhirnya, kakak perempuan saya dan Eleanor hampir saja bertengkar di kursi gantung.",
  str_homestory_821401001_15_dialog_content = "Mereka hampir memecahkannya juga saat itu...",
  str_homestory_821401001_16_dialog_content = "Sepertinya kamu benar-benar merindukan masa-masa itu <sprite=emo_sikao size=60 />.",
  str_homestory_821401001_17_dialog_content = "Mau duduk di atasnya?",
  str_homestory_821401001_18_dialog_content = "Hah? Aku? Yah...",
  str_homestory_821401001_19_dialog_content = "Saya pikir saya akan lulus.",
  str_homestory_821401001_20_option_content = "Kenapa?",
  str_homestory_821401001_21_option_content = "Cobalah.",
  str_homestory_821401001_22_dialog_content = "Sebenarnya... racun ku sedikit gelisah akhir-akhir ini...",
  str_homestory_821401001_23_dialog_content = "Kalau aku tak sengaja tertidur saat duduk di atasnya, aku takut racunnya akan tumpah dan merusak kursi gantungnya.",
  str_homestory_821401001_24_dialog_content = "Jadi, aku akan melihatnya saja.",
  str_homestory_821401001_25_dialog_content = "Jika aku berdiri di dekatnya dan menutup mata, rasanya seperti segalanya kembali seperti di masa lalu...",
  str_homestory_821401001_26_dialog_content = "Jangan khawatir. Aku di sini.",
  str_homestory_821401001_27_dialog_content = "Aku akan langsung membangunkanmu jika kamu tertidur.",
  str_homestory_821401001_28_dialog_content = "Apakah ini akan sangat merepotkan bagimu...?",
  str_homestory_821401001_29_dialog_content = "Itu akan baik-baik saja.",
  str_homestory_821401001_30_dialog_content = "Um... Bisakah kamu menunggu sedikit lebih lama untukku?",
  str_homestory_821401001_31_dialog_content = "Ada beberapa urusan yang harus diselesaikan di klinik. Aku akan datang segera setelah selesai.",
  str_homestory_821401001_32_dialog_content = "Terima kasih, Navigator.",
  str_homestory_821501001_0_dialog_content = "Isa?",
  str_homestory_821501001_1_dialog_content = "Oh, ternyata kau.",
  str_homestory_821501001_2_dialog_content = "Apakah ada yang salah dengan mobil ini? Kamu terus memandanginya.",
  str_homestory_821501001_3_dialog_content = "Aha! Pertanyaan bagus.",
  str_homestory_821501001_4_dialog_content = "Kamu tidak berpikir mobil ini... sangat keren?",
  str_homestory_821501001_5_option_content = "Tidak terlalu.",
  str_homestory_821501001_6_dialog_content = "Saya rasa kamu bisa bilang itu indah.",
  str_homestory_821501001_7_option_content = "Ya, benar.",
  str_homestory_821501001_8_dialog_content = "Dalam arti tertentu, itu bisa dianggap keren.",
  str_homestory_821501001_9_dialog_content = "Pokoknya, mobil ini persis gayaku!",
  str_homestory_821501001_10_dialog_content = "Jika aku mengendarai mobil ini untuk menjemput Rebecca...",
  str_homestory_821501001_11_dialog_content = "Dia pasti akan sangat bersemangat!",
  str_homestory_821501001_12_dialog_content = "Apakah kamu berpikir untuk menjemput Rebecca dengan mobil ini?",
  str_homestory_821501001_13_dialog_content = "Ya, Rebecca sedang tidak sehat.",
  str_homestory_821501001_14_dialog_content = "Tapi dia masih harus berjalan ke tempat kerja setiap hari. Apakah menurutmu dia terlalu keras pada dirinya sendiri?",
  str_homestory_821501001_15_dialog_content = "Memang kedengarannya sulit.",
  str_homestory_821501001_16_dialog_content = "Benar kan? Inilah yang saya dapatkan setelah mempertimbangkan dengan hati-hati.",
  str_homestory_821501001_17_dialog_content = "Rebecca selalu bilang bahwa aku tidak tahu apa yang dia inginkan. Hehe, kali ini dia pasti membutuhkan alat transportasi ini.",
  str_homestory_821501001_18_dialog_content = "Tapi... mobil ini terlalu mencolok. Rebecca tidak akan menyukainya.",
  str_homestory_821501001_19_dialog_content = "Jangan khawatir. Aku memahaminya dengan baik. Aku yakin aku tahu apa yang dia suka.",
  str_homestory_821501001_20_dialog_content = "Rebecca menyukai bunga. Lihat bunga-bunga di seluruh mobil. Tidak mungkin dia akan membencinya.",
  str_homestory_821501001_21_dialog_content = "... Eh, coba saja ya?",
  str_homestory_821501001_22_dialog_content = "Oke, aku akan memberitahu Rebecca sekarang.",
  str_homestory_821501001_23_dialog_content = "Dia pasti akan senang.",
  str_homestory_821501001_24_dialog_content = "Semoga berhasil, ya.",
  str_homestory_821601001_0_dialog_content = "Apa yang salah dengan mesin ini, Xuan Ji?",
  str_homestory_821601001_1_dialog_content = "Ini digunakan oleh Caelestites di masa lalu. Tertarik?",
  str_homestory_821601001_2_dialog_content = "Ini adalah mesin tenun mekanik, bukan?",
  str_homestory_821601001_3_dialog_content = "Ya. Ada catatan tentang itu di Soroz.",
  str_homestory_821601001_4_dialog_content = "Eraveil pernah menggunakan mesin seperti itu untuk memproduksi tekstil, mencapai gaya hidup yang mandiri.",
  str_homestory_821601001_5_dialog_content = "Mungkin memerlukan pemeliharaan rutin, tapi sudah lama tidak digunakan...",
  str_homestory_821601001_6_dialog_content = "Kamu ingin menggunakannya, Xuan Ji?",
  str_homestory_821601001_7_dialog_content = "Tidak terlalu.",
  str_homestory_821601001_8_dialog_content = "Bagiku, ini terlihat sangat bernostalgia.",
  str_homestory_821601001_9_dialog_content = "Membangkitkan nostalgia?",
  str_homestory_821601001_10_dialog_content = "Ini mengingatkan saya pada mesin untuk tujuan pembelajaran yang saya gunakan saat saya kecil.",
  str_homestory_821601001_11_dialog_content = "Para guru akan memulai kami, murid-murid muda, dengan model prototipe.",
  str_homestory_821601001_12_dialog_content = "Alat tenun seperti ini umum. Bahkan bisa dibilang ini guru keduaku.",
  str_homestory_821601001_13_dialog_content = "Tidak heran kamu menemukannya menarik.",
  str_homestory_821601001_14_dialog_content = "Juga, prototipe biasanya sangat rapuh.",
  str_homestory_821601001_15_dialog_content = "Itu juga yang terjadi pada yang diberikan kepadaku, dengan beberapa struktur yang identik juga...",
  str_homestory_821601001_16_dialog_content = "Mereka juga melakukan itu agar kita menghargai keahlian kerajinan mereka.",
  str_homestory_821601001_17_dialog_content = "Aku juga ingin menjaganya, tapi seringkali malah rusak!",
  str_homestory_821601001_18_option_content = "Karena kamu mencoba mengutak-atiknya?",
  str_homestory_821601001_19_dialog_content = "Tepat.",
  str_homestory_821601001_20_option_content = "Sangat rapuh",
  str_homestory_821601001_21_dialog_content = "Tidak, itu karena aku mengutak-atiknya banyak...",
  str_homestory_821601001_22_dialog_content = "Jadi, itu tidak bertahan sampai aku lulus.",
  str_homestory_821601001_23_dialog_content = "Ketika akhirnya saya cukup mahir, itu sudah tidak bisa diperbaiki.",
  str_homestory_821601001_24_dialog_content = "Aku tahu.",
  str_homestory_821601001_25_dialog_content = "Jadi, mau aku perbaiki alat tenun ini?",
  str_homestory_821601001_26_dialog_content = "Untuk versi diriku yang sekarang, ini seharusnya sangat mudah.",
  str_homestory_821601001_27_dialog_content = "Saya bahkan bisa meningkatkan desain agar perangkat tersebut dapat bekerja dan merawat dirinya sendiri sebaik mungkin.",
  str_homestory_821601001_28_dialog_content = "Uh<sprite=emo_sikao size=60 />, itu tidak perlu, sih.",
  str_homestory_821601001_29_dialog_content = "Bahkan jika diperbaiki, akan sulit menemukan bahan-bahan untuk prosesnya.",
  str_homestory_821601001_30_dialog_content = "Belum lagi kita sekarang bisa dengan mudah mendapatkan kain yang murah namun cantik dari toko-toko.",
  str_homestory_821601001_31_dialog_content = "Benar, sama di Longzhou.",
  str_homestory_821601001_32_dialog_content = "Bagi orang biasa, guild saat ini lebih penting daripada pengrajin.",
  str_homestory_821601001_33_dialog_content = "Itu kemajuan, kan?",
  str_homestory_821601001_34_dialog_content = "Umm, tidak bisa menyangkal itu. Mesin ini sudah melewati masa tujuannya.",
  str_homestory_821601001_35_dialog_content = "Jadi, lebih baik biarkan itu beristirahat dalam damai.",
  str_homestory_818702001_0_dialog_content = "Tianxian? Master Li?",
  str_homestory_818702001_1_dialog_content = "Kenapa kamu bisa tertidur sambil berdiri?",
  str_homestory_818702001_2_dialog_content = "Bangun dan kembali ke kamarmu.",
  str_homestory_818702001_3_dialog_content = "Hei!",
  str_homestory_818702001_4_dialog_content = "Baru saja tadi aku berada di surga, mengobrol dengan para malaikat.",
  str_homestory_818702001_5_dialog_content = "Seberapa cepat aku jatuh kembali ke bumi...",
  str_homestory_818702001_6_dialog_content = "Kurasa jalanku masih panjang.",
  str_homestory_818702001_7_dialog_content = "Aku menyerah. Kamu tidak menyadarinya?",
  str_homestory_818702001_8_dialog_content = "Hal yang kamu tidur di sebelah dan hampir bersandar padanya...",
  str_homestory_818702001_9_dialog_content = "Ini jam.",
  str_homestory_818702001_10_dialog_content = "Tak bisa dipercaya! Bagaimana bisa kamu tidur begitu nyenyak di samping jam besar seperti itu...",
  str_homestory_818702001_11_dialog_content = "Sebaliknya, saudaraku.",
  str_homestory_818702001_12_dialog_content = "Sejauh yang saya tahu, banyak orang di Astra menyimpan jam alarm di samping bantal mereka.",
  str_homestory_818702001_13_dialog_content = "Namun, saya lebih suka langit sebagai selimutku, tanah sebagai tempat tidurku, dan jam matahari sebagai alarmku.",
  str_homestory_818702001_14_dialog_content = "Jadi dalam kasus ini, saya beradaptasi dengan apa yang dilakukan penduduk setempat.",
  str_homestory_818702001_15_dialog_content = "Tapi mereka melakukannya untuk bangun tepat waktu, dan kamu hanya mencoba tidur siang<sprite=emo_kun size=60 />!",
  str_homestory_818702001_16_dialog_content = "Kamu tidak merasa waktu berlalu begitu cepat sama sekali?",
  str_homestory_818702001_17_dialog_content = "Karena waktu berlalu dan hidup singkat, seseorang harus memanfaatkan kesempatan saat itu datang.",
  str_homestory_818702001_18_dialog_content = "Kamu harus tidur saat merasa mengantuk, jangan menunggu sampai menguap.",
  str_homestory_818702001_19_dialog_content = "Kenapa kamu tidak bersandar dan tidur siang? Nanti kamu akan mengerti.",
  str_homestory_818702001_20_option_content = "Tidak.",
  str_homestory_818702001_21_dialog_content = "Masih muda dan belum berpengalaman, ya.",
  str_homestory_818702001_22_dialog_content = "Saya telah melihat cukup banyak dunia dan tidak akan pernah melewatkan kesempatan untuk tidur sejenak.",
  str_homestory_818702001_23_option_content = "Aku akan mencobanya.",
  str_homestory_818702001_24_dialog_content = "Akhirnya kamu sadar juga!",
  str_homestory_818702001_25_dialog_content = "Tapi meskipun aku akan menabrak di sini, aku harus bersiap-siap.",
  str_homestory_818702001_26_dialog_content = "Aku harus membawa kantong tidurku, selimut piknik, dan segala perlengkapannya.",
  str_homestory_818702001_27_dialog_content = "Kamu pasti tahu cara menikmati hidup. Aku hampir tidak punya apa-apa untuk kenyamanan.",
  str_homestory_818702001_28_dialog_content = "Huh, saya rasa jam bayangan matahari mungkin yang paling beruntung dari semuanya.",
  str_homestory_818702001_29_dialog_content = "Fungsinya sama saja, baik di Longzhou maupun Astra.",
  str_homestory_818702001_30_dialog_content = "Ia memiliki waktu luang selama matahari tidak bersinar.",
  str_homestory_818702001_31_dialog_content = "Apakah kamu sampai sejauh iri pada batu?",
  str_homestory_818702001_32_dialog_content = "Jangan meremehkan batu. Bahkan ada pahlawan legendaris yang lahir dari batu!",
  str_homestory_818702001_33_dialog_content = "Sayangnya, aku hanya bisa berubah menjadi batu dalam mimpiku.",
  str_homestory_818702001_34_dialog_content = "Ngomong-ngomong, aku merasa ingin tidur siang lagi.",
  str_homestory_818702001_35_dialog_content = "Masih belum ada rasa urgensi, ya...",
  str_homestory_818702001_36_dialog_content = "Jangan terlalu serius menghadapi segalanya, PlayerName.",
  str_homestory_818702001_37_dialog_content = "Apa salahnya melambatkan kerja dan menikmati hidup sejenak?<sprite=emo_qingsong size=60 />",
  str_homestory_818702001_38_dialog_content = "Benar... Itulah Li Tianxian yang saya kenal.",
  str_homestory_818802001_0_dialog_content = "Dantang?",
  str_homestory_818802001_1_dialog_content = "Pengerjaan pada layang-layang ini cukup unik.",
  str_homestory_818802001_2_dialog_content = "Pola sudut dan skema warna yang sederhana...",
  str_homestory_818802001_3_dialog_content = "Ini sangat mirip dengan varietas yang paling umum ditemui di Longzhou.",
  str_homestory_818802001_4_dialog_content = "Apakah Caelestite juga menyukai keanggunan yang serupa? Itu cukup langka.",
  str_homestory_818802001_5_option_content = "Orang-orang di Longzhou suka menerbangkan layang-layang?",
  str_homestory_818802001_6_dialog_content = "Memang.",
  str_homestory_818802001_7_option_content = "Pernahkah kamu menerbangkan layang-layang sebelumnya, Dantang?",
  str_homestory_818802001_8_dialog_content = "Ya, aku sangat suka layang-layang.",
  str_homestory_818802001_9_dialog_content = "Di Longzhou, bermain layang-layang adalah salah satu kegiatan favorit anak-anak.",
  str_homestory_818802001_10_dialog_content = "Saat saya masih muda, menerbangkan layang-layang bersama saudara perempuan saya adalah kebahagiaan yang langka.",
  str_homestory_818802001_11_dialog_content = "Dulu, layang-layang kami sering kusut.",
  str_homestory_818802001_12_dialog_content = "Terkadang, hal itu bahkan menyebabkan pertengkaran.",
  str_homestory_818802001_13_dialog_content = "Meskipun pada akhirnya kami selalu berbaikan,",
  str_homestory_818802001_14_dialog_content = "Jenis layang-layang apa yang kamu terbangkan, Dantang?",
  str_homestory_818802001_15_dialog_content = "Layang-layangku? Oh, aku telah menerbangkan banyak layang-layang.",
  str_homestory_818802001_16_dialog_content = "Saudara-saudaraku lebih suka layangan berbentuk burung, tetapi untukku, bunga adalah pilihan.",
  str_homestory_818802001_17_dialog_content = "Aku belum pernah melihat layang-layang seperti itu.",
  str_homestory_818802001_18_dialog_content = "Nah, layang-layang di Longzhou memiliki berbagai gaya yang sangat beragam.",
  str_homestory_818802001_19_dialog_content = "Ambil contoh Kerajaan Ye. Mereka suka melampirkan perangkat pada layang-layang.",
  str_homestory_818802001_20_dialog_content = "Yang akan membuat setiap bagian bergerak dan menari.",
  str_homestory_818802001_21_dialog_content = "Semua layang-layang yang saya terbangkan saat itu dibuat oleh pengrajin istana.",
  str_homestory_818802001_22_dialog_content = "Dekorasi mewah dengan keanggunan yang megah.",
  str_homestory_818802001_23_dialog_content = "Aku sangat merindukannya... Aku ingin menerbangkan layang-layang lagi.",
  str_homestory_818802001_24_dialog_content = "Layang-layang ini sepertinya tidak sebanding dengan yang kamu miliki, sayangnya.",
  str_homestory_818802001_25_dialog_content = "Tidak apa-apa. Yang aku rindukan adalah momen-momen bebas beban di masa lalu.",
  str_homestory_818802001_26_dialog_content = "Menerbangkan layang-layang sebenarnya adalah kegiatan sampingan.",
  str_homestory_818802001_27_dialog_content = "Hmm, aku kehabisan tugas dan urusan yang harus dikerjakan.",
  str_homestory_818802001_28_dialog_content = "Aku bisa menyempatkan istirahat, dan ini adalah waktu yang sempurna untuk menerbangkan layang-layang ini.",
  str_homestory_818802001_29_dialog_content = "Jadi, maukah kamu menerbangkan layang-layang bersamaku?",
  str_homestory_818802001_30_dialog_content = "Tidak menyenangkan terbang sendirian.",
  str_homestory_818802001_31_dialog_content = "Sayangnya kita hanya punya satu di sini...",
  str_homestory_818802001_32_dialog_content = "Itu bukan masalah. Kita bisa bergantian, atau saya bisa membuatnya sendiri.",
  str_homestory_822001001_0_dialog_content = "Vergil?",
  str_homestory_822001001_1_dialog_content = "Kenapa kau terus menatap orang-orangan sawah itu, Vergil?",
  str_homestory_822001001_2_dialog_content = "Orang-orangan sawah ini...<sprite=emo_sikao size=60 />",
  str_homestory_822001001_3_dialog_content = "Bagaimana dengan itu? Jangan bilang orang-orangan sawah ini adalah barang antik!",
  str_homestory_822001001_4_dialog_content = "Pada pandangan pertama, sepertinya memang begitu...",
  str_homestory_822001001_5_dialog_content = "Benarkah? Apa yang istimewa dari orang-orangan sawah itu?",
  str_homestory_822001001_6_dialog_content = "Aksesoris di situ... Mungkin itu barang antik.",
  str_homestory_822001001_7_dialog_content = "Barang antik? Sungguh?",
  str_homestory_822001001_8_dialog_content = "Ya. Rompi ini seharusnya merupakan rilisan terbatas dari merek Umbraton.",
  str_homestory_822001001_9_dialog_content = "Itu sedang tren lima puluh tahun yang lalu.",
  str_homestory_822001001_10_dialog_content = "Fitur terbesar dari penawaran terbatas ini adalah...",
  str_homestory_822001001_11_dialog_content = "Pola putih-di-atas-hitamnya adalah garis putih yang dicelup pada kain hitam.",
  str_homestory_822001001_12_dialog_content = "Daripada yang konvensional, dengan garis-garis hitam dicetak pada kain putih.",
  str_homestory_822001001_13_dialog_content = "Dan ada nomor yang dijahit di belakang kerah dengan benang emas.",
  str_homestory_822001001_14_dialog_content = "Aku memang melihatnya...<sprite=emo_wuzui size=60 />",
  str_homestory_822001001_15_dialog_content = "Juga, jika Anda melihat dengan seksama, mata orang-orangan sawah ini terbuat dari obsidian.",
  str_homestory_822001001_16_dialog_content = "Kilau dan warna keduanya berkualitas batu permata.",
  str_homestory_822001001_17_dialog_content = "Para bangsawan di Lumopolis seringkali membuat batu permata tersebut menjadi kancing beberapa dekade yang lalu.",
  str_homestory_822001001_18_dialog_content = "Kedua ini tidak jauh berbeda dari itu.",
  str_homestory_822001001_19_dialog_content = "Aku bahkan tidak menyadarinya sampai kamu menyebutkannya.",
  str_homestory_822001001_20_dialog_content = "Terakhir, batang kayu yang menopang orang-orangan sawah...",
  str_homestory_822001001_21_dialog_content = "Tampaknya itu adalah gaharu.",
  str_homestory_822001001_22_dialog_content = "Meskipun lebih tipis, kamu masih bisa mencium aroma samar saat mendekatinya.",
  str_homestory_822001001_23_dialog_content = "Tongkat gaharu sangat berharga.",
  str_homestory_822001001_24_dialog_content = "Wow, apakah itu berarti orang-orangan sawah ini tak ternilai harganya?",
  str_homestory_822001001_25_dialog_content = "Nah, barang antik dinilai dari keseluruhan.",
  str_homestory_822001001_26_dialog_content = "Sebuah set lengkap akan sangat berharga, tapi harganya jauh berkurang jika bahkan satu komponen saja yang hilang.",
  str_homestory_822001001_27_dialog_content = "Dan sebaliknya, sama seperti orang-orangan sawah ini, sebuah kompilasi dari objek-objek yang sama sekali tidak berhubungan.",
  str_homestory_822001001_28_dialog_content = "Bahkan dari perspektif sebuah karya seni...",
  str_homestory_822001001_29_dialog_content = "Paling-paling cuma kelas tiga, sekarang tidak ada nilainya.",
  str_homestory_822001001_30_dialog_content = "Itu sangat disayangkan...<sprite=emo_tanqi size=60 />",
  str_homestory_822001001_31_dialog_content = "Kecuali…",
  str_homestory_822001001_32_dialog_content = "Kecuali apa?",
  str_homestory_822001001_33_dialog_content = "Kecuali jika kamu membongkarnya. Apakah kamu ingin melakukan itu?",
  str_homestory_822001001_34_dialog_content = "Yah, tidak.",
  str_homestory_822001001_35_dialog_content = "Saya lebih suka bagaimana kita bisa menikmatinya apa adanya di sini.",
  str_homestory_822001001_36_dialog_content = "Aku tahu kamu akan bilang itu, PlayerName.",
  str_homestory_821901001_0_dialog_content = "Ada apa?",
  str_homestory_821901001_1_dialog_content = "Cara kamu tampak... Mungkinkah...",
  str_homestory_821901001_2_dialog_content = "Anda pasti sangat menyukai jam ini, bukan?",
  str_homestory_821901001_3_dialog_content = "Ini gaya yang belum pernah aku lihat sebelumnya.",
  str_homestory_821901001_4_dialog_content = "Apakah ini jam Caelestite?",
  str_homestory_821901001_5_dialog_content = "Kurasa begitu.",
  str_homestory_821901001_6_dialog_content = "Semuanya di Soroz adalah Caelestite.",
  str_homestory_821901001_7_dialog_content = "Bukan mesin, tetapi menggunakan pantulan sinar matahari.",
  str_homestory_821901001_8_dialog_content = "Konsep yang luar biasa...",
  str_homestory_821901001_9_dialog_content = "Bisa disebut Seni Bayangan.",
  str_homestory_821901001_10_dialog_content = "Anda benar-benar menyukai jam tersebut, saya lihat.",
  str_homestory_821901001_11_dialog_content = "Saya terpesona oleh waktu yang berlalu begitu cepat.",
  str_homestory_821901001_12_dialog_content = "Oleh karena itu, saya juga suka mengoleksi jam dari berbagai jenis.",
  str_homestory_821901001_13_dialog_content = "Apa? Kamu maksud ada banyak jenis jam di dunia luar?",
  str_homestory_821901001_14_dialog_content = "Jam di Lumopolis adalah klasik dan elegan.",
  str_homestory_821901001_15_dialog_content = "Jam Northland sederhana dan praktis.",
  str_homestory_821901001_16_dialog_content = "Jam di Gurun Rediesel penuh dengan trik dan gadget.",
  str_homestory_821901001_17_dialog_content = "Dan jam Umbraton adalah sederhana namun indah.",
  str_homestory_821901001_18_dialog_content = "Mengerti. Kamu memang penggemar koleksi.",
  str_homestory_821901001_19_dialog_content = "Saya tidak pernah berpikir bahwa barang biasa bisa memiliki begitu banyak manfaat.",
  str_homestory_821901001_20_dialog_content = "Anda telah membuka mata saya.",
  str_homestory_821901001_21_dialog_content = "Jam yang saya sebutkan semuanya adalah produk dari zaman modern.",
  str_homestory_821901001_22_dialog_content = "Sedangkan jam Caelestite membuatku menyadari betapa beratnya masa lalu.",
  str_homestory_821901001_23_dialog_content = "Perasaan itu spesial dan unik.",
  str_homestory_821901001_24_dialog_content = "Jika itu yang kamu rasakan...<sprite=emo_sikao size=60 />",
  str_homestory_821901001_25_dialog_content = "Aku ingin memberikannya padamu.",
  str_homestory_821901001_26_dialog_content = "Kenapa kamu ingin melakukan itu?",
  str_homestory_821901001_27_option_content = "Karena kita berteman.",
  str_homestory_821901001_28_dialog_content = "Ini karena persahabatan, bukan?",
  str_homestory_821901001_29_dialog_content = "Itu adalah pernyataan yang tulus.",
  str_homestory_821901001_30_option_content = "Sepertinya kamu sangat menyukainya.",
  str_homestory_821901001_31_dialog_content = "Meski begitu, aku tidak ingin hanya mengambilnya.",
  str_homestory_821901001_32_dialog_content = "Aku sangat menghargai pemikirannya, meski begitu.",
  str_homestory_821901001_33_dialog_content = "Tapi kenapa kita tidak biarkan saja itu tetap \"di rumah\"?",
  str_homestory_821901001_34_dialog_content = "Aku tidak mengerti. Apakah kamu tidak menyukainya?",
  str_homestory_821901001_35_dialog_content = "Saya punya jam lain di sini, jadi...",
  str_homestory_821901001_36_dialog_content = "Saya sangat senang mengetahui bahwa kamu mau berbagi apa saja dengan seorang teman.",
  str_homestory_821901001_37_dialog_content = "Namun, aku rasa memang seharusnya tidak di tempat lain selain di sini.",
  str_homestory_821901001_38_dialog_content = "Masa lalu mewakili kenangan, dan kenangan terdiri dari sejarah.",
  str_homestory_821901001_39_dialog_content = "Semua tentang Caelestite ada di sini, PlayerName.",
  str_homestory_821901001_40_dialog_content = "Semua ini memiliki arti bagi Anda.",
  str_homestory_821901001_41_dialog_content = "Aku tidak ingin mengambil apa pun darinya.",
  str_homestory_821901001_42_dialog_content = "Istvan...",
  str_homestory_821901001_43_dialog_content = "Selamat tinggal, semoga bayangan menjagamu.",
  str_homestory_821801001_0_dialog_content = "Lady Sheol?",
  str_homestory_821801001_1_dialog_content = "Senang bertemu denganmu di sini! Ini pertanda bahwa sesuatu yang baik akan terjadi hari ini.",
  str_homestory_821801001_2_dialog_content = "Kau setuju, 'kan, PlayerName?",
  str_homestory_821801001_3_dialog_content = "Ini bukan hal yang tak terduga, Lady Sheol. Kamu tahu kita berada di Cloud Gardens, kan...",
  str_homestory_821801001_4_dialog_content = "Tentu saja.",
  str_homestory_821801001_5_dialog_content = "Tapi kamu memerlukan kebetulan sesekali, baik dalam bisnis maupun dalam kehidupan.",
  str_homestory_821801001_6_dialog_content = "Maaf, aku masih tidak mengerti.",
  str_homestory_821801001_7_dialog_content = "Tak apa. Biar kujelaskan.",
  str_homestory_821801001_8_dialog_content = "Misalnya, kamu perlu merenovasi Cloud Gardens dan Cloudrover Guild...",
  str_homestory_821801001_9_dialog_content = "Kebetulan punya rencana untuk itu.",
  str_homestory_821801001_10_dialog_content = "Bukankah itu kebetulan?",
  str_homestory_821801001_11_dialog_content = "Dan dengan itu, maksudmu...?",
  str_homestory_821801001_12_dialog_content = "Cloud Gardens memang istimewa, tapi bukankah asramanya terlalu kusam?",
  str_homestory_821801001_13_option_content = "Apakah mereka?",
  str_homestory_821801001_14_dialog_content = "Tentu saja, kenapa lagi aku sebutkan itu?",
  str_homestory_821801001_15_dialog_content = "Kamu mungkin sudah terbiasa jadi kamu tidak merasa seperti itu.",
  str_homestory_821801001_16_dialog_content = "Tapi saya pikir asrama biasa saja tidak cocok untuk Cloud Gardens.",
  str_homestory_821801001_17_option_content = "Aku juga merasakan hal yang sama",
  str_homestory_821801001_18_dialog_content = "Sudah kuduga!",
  str_homestory_821801001_19_dialog_content = "Kalau begitu, bukankah menurutmu ada yang harus dilakukan untuk mengatasinya?",
  str_homestory_821801001_20_dialog_content = "Seperti merenovasi mereka?",
  str_homestory_821801001_21_dialog_content = "Yang saya maksud adalah, kita bisa membuat asrama menjadi lebih menarik.",
  str_homestory_821801001_22_dialog_content = "Lebih menarik?",
  str_homestory_821801001_23_dialog_content = "Bukan ide yang buruk, tetapi anggaran<sprite=emo_baiyebi size=60 /> sangat ketat...",
  str_homestory_821801001_24_dialog_content = "Jangan khawatir! Kamu bisa mempercayakan proyek ini kepada Guild Cloudrover saya!",
  str_homestory_821801001_25_dialog_content = "Aku akan merenovasi asrama agar sesuai dengan keagungan Cloud Gardens secara gratis!",
  str_homestory_821801001_26_dialog_content = "Gratis? Semuanya?!",
  str_homestory_821801001_27_dialog_content = "Aku tidak yakin soal itu...",
  str_homestory_821801001_28_dialog_content = "Aku tahu kita adalah teman, tapi ini terlalu memanfaatkanmu, Lady Sheol.",
  str_homestory_821801001_29_dialog_content = "Seperti yang kamu tahu, saya tidak membuat kesepakatan yang merugikan.",
  str_homestory_821801001_30_dialog_content = "Ketika asrama selesai dibangun, kita akan mengubah Cloud Gardens menjadi resor hotel.",
  str_homestory_821801001_31_dialog_content = "Resor hotel?!",
  str_homestory_821801001_32_dialog_content = "Cukup duduk santai dan serahkan semuanya kepadaku.",
  str_homestory_821801001_33_dialog_content = "Atau biar saya katakan seperti ini, saya jamin kamu akan menghitung uang sampai kamu bosan!",
  str_homestory_821801001_34_dialog_content = "Menghitung uang sampai aku muak?!",
  str_homestory_821801001_35_dialog_content = "Apakah ini proyek yang Anda sebutkan sebelumnya?",
  str_homestory_821801001_36_dialog_content = "Ini benar-benar proposal yang tidak bisa saya tolak<sprite=emo_aixin size=60 />!",
  str_homestory_821801001_37_dialog_content = "Sempurna, sudah beres kalau begitu...",
  str_homestory_821801001_38_dialog_content = "Tunggu, Nona Sheol!",
  str_homestory_821801001_39_dialog_content = "Maaf, tapi aku hanya ingin menjaga Cloud Gardens tetap seperti ini untuk saat ini.",
  str_homestory_821801001_40_dialog_content = "Aku tidak yakin bagaimana penduduk Cloud Gardens akan menerima berita ini...",
  str_homestory_821801001_41_dialog_content = "Jadi jika kita langsung terburu-buru dalam proyek ini...",
  str_homestory_821801001_42_dialog_content = "Oh, begitu. Aku mengerti.",
  str_homestory_821801001_43_dialog_content = "Itu berarti kita memiliki kesempatan untuk menjadikan pariwisata sebagai hal yang penting di masa depan, 'kan?",
  str_homestory_821801001_44_dialog_content = "Pariwisata?",
  str_homestory_821801001_45_dialog_content = "Kemudian, saya menantikan kabar dari Anda!",
  str_homestory_822101001_0_dialog_content = "Tertarik?",
  str_homestory_822101001_1_dialog_content = "Aku melihat kamu memandanginya sepanjang waktu, tampaknya sangat bersemangat.",
  str_homestory_822101001_2_dialog_content = "Apakah ini<sprite=emo_sikao size=60 />...",
  str_homestory_822101001_3_dialog_content = "Sebuah tempat sampah yang mampu memilah sampah daur ulang secara otomatis?",
  str_homestory_822101001_4_dialog_content = "Wow! Bagaimana kamu tahu itu?!",
  str_homestory_822101001_5_dialog_content = "Ini adalah tempat sampah gaya Caelestite, berbeda dari jenis biasanya.",
  str_homestory_822101001_6_dialog_content = "Tapi, saya masih berpikir itu tidak akan begitu mudah dikenali.",
  str_homestory_822101001_7_dialog_content = "Heh, kau meremehkanku lagi, ya?",
  str_homestory_822101001_8_dialog_content = "Lalu, saya akan menjelaskan analisis saya.",
  str_homestory_822101001_9_dialog_content = "Pertama-tama, saya meretas program pengendalinya dan melirik sebentar...",
  str_homestory_822101001_10_dialog_content = "Apa? Kenapa kau melakukan itu pada furnitur orang lain?!",
  str_homestory_822101001_11_dialog_content = "Ini adalah dalam bahasa pemrograman lain yang canggih dan ringkas. Pasti sebuah mahakarya teknologi tinggi Caelestite!",
  str_homestory_822101001_12_dialog_content = "Tapi dalam hal fungsi, saya bisa melihat persamaannya dengan sistem pengurutan otomatis di Kafetaria Illumina.",
  str_homestory_822101001_13_dialog_content = "Yang berarti benda ini juga memiliki fitur kategorisasi yang sama.",
  str_homestory_822101001_14_dialog_content = "Ngomong-ngomong, aku yang menulis program untuk Kafetaria Illumina.",
  str_homestory_822101001_15_dialog_content = "Ini bisa mengurutkan dan mengeluarkan makanan berdasarkan tingkat nutrisinya!",
  str_homestory_822101001_16_dialog_content = "Bagus.",
  str_homestory_822101001_17_dialog_content = "Saya bertanya-tanya apakah ada bahan makanan yang bergizi yang bisa mengurangi keinginan untuk mengacaukan furnitur teman.",
  str_homestory_822101001_18_dialog_content = ".... Pokoknya, tidak buruk bagimu untuk menghubungkan \"penyortiran\" dengan tempat sampah.",
  str_homestory_822101001_19_dialog_content = "Yah, ada alasan yang lebih meyakinkan untuk itu.",
  str_homestory_822101001_20_dialog_content = "Oh?",
  str_homestory_822101001_21_dialog_content = "Ada gambar besar sampah di situ.",
  str_homestory_822101001_22_dialog_content = "...",
  str_homestory_822101001_23_dialog_content = "Sederhana luar biasa!",
  str_homestory_822101001_24_dialog_content = "Pengurutan otomatis bukanlah hal terbaik sejak roti diiris.",
  str_homestory_822101001_25_dialog_content = "Tapi untuk memasukkan sistem ke dalam volume yang begitu kompak...",
  str_homestory_822101001_26_dialog_content = "Dengan fitur pengurutan yang begitu detail di atas... Itu adalah sesuatu yang teknologi Illumina saat ini hanya bisa impikan.",
  str_homestory_822101001_27_dialog_content = "Bangsa Caelestite benar-benar orang-orang yang hebat!",
  str_homestory_822101001_28_dialog_content = "Um…",
  str_homestory_822101001_29_option_content = "Apa? Kalian serius?",
  str_homestory_822101001_30_dialog_content = "Ini hanya tempat sampah.",
  str_homestory_822101001_31_dialog_content = "\"Hanya sebuah tempat sampah\" adalah yang membuatnya luar biasa.",
  str_homestory_822101001_32_option_content = "Aku tidak menyangka kamu akan begitu tertarik dengan \"tempat sampah daur ulang otomatis\" ini.",
  str_homestory_822101001_33_dialog_content = "Itu bahkan membuatku sangat bersemangat!",
  str_homestory_822101001_34_dialog_content = "Kamu harusnya begitu!",
  str_homestory_822101001_35_dialog_content = "Teknologi mutakhir selalu diterapkan untuk keperluan militer terlebih dahulu.",
  str_homestory_822101001_36_dialog_content = "Hanya ketika mereka menjadi lebih umum daripada kotoran, orang-orang biasa dapat mengaksesnya.",
  str_homestory_822101001_37_dialog_content = "Dalam hal ini, hanya karena tempat sampah daur ulang otomatis ini adalah tempat sampah...",
  str_homestory_822101001_38_dialog_content = "Itu menunjukkan kehebatan budaya Caelestite!",
  str_homestory_822101001_39_dialog_content = "Ah! Itu masuk akal, sekarang setelah saya pikirkan!",
  str_homestory_822101001_40_dialog_content = "Meski masih menggangguku bahwa kamu telah meretas program itu...",
  str_homestory_822101001_41_dialog_content = "Tapi saya selalu belajar sesuatu saat berbicara dengan Anda. Saya benar-benar maksud itu.",
  str_homestory_822101001_42_dialog_content = "Terima kasih, Algol.",
  str_homestory_822101001_43_dialog_content = "Jangan sebut itu! Meski saya lebih suka jika Anda memberi saya izin untuk membongkar tempat sampah untuk dipelajari secara menyeluruh...",
  str_homestory_822101001_44_dialog_content = "Lupakan itu!",
  str_homestory_822301001_0_dialog_content = "Patung batu ini...",
  str_homestory_822301001_1_dialog_content = "Saya jarang melihat hal-hal seperti ini di gua Anda, PlayerName.",
  str_homestory_822301001_2_dialog_content = "Apakah patung ini memiliki arti khusus bagi Anda?",
  str_homestory_822301001_3_dialog_content = "Kamu menebaknya... Ini adalah patung seorang gadis Caelestite.",
  str_homestory_822301001_4_dialog_content = "Seorang Caelestite... Salah satu dari orang-orangmu dari waktu yang lama, 'kan?",
  str_homestory_822301001_5_dialog_content = "Aku bisa merasakan hembusan waktu yang datang dari setiap retakan dan goresan pada patung ini.",
  str_homestory_822301001_6_dialog_content = "Cerita mengatakan bahwa dia adalah seorang pelancong, seseorang yang mengunjungi setiap landmark terkenal di benua kita.",
  str_homestory_822301001_7_dialog_content = "Dan kamu benar, Chen'ni. Patung ini berasal dari waktu yang sangat lama lalu...",
  str_homestory_822301001_8_dialog_content = "Sangat berbahaya bagi seorang Caelestite untuk bepergian sendiri di dunia kita yang dipenuhi Eclipsite <sprite=emo_kulou size=60 /> sekarang...",
  str_homestory_822301001_9_dialog_content = "Dengan aku di sisimu, apa yang perlu ditakutkan?",
  str_homestory_822301001_10_dialog_content = "Mungkin suatu hari nanti, sebuah patung akan didirikan untuk mengenang Anda juga?",
  str_homestory_822301001_11_dialog_content = "Hah? A-Aku?! Tidak mungkin, aku tidak istimewa sama sekali...",
  str_homestory_822301001_12_dialog_content = "Kenapa tidak? Misalnya, bagaimana jika ada kekeringan yang parah di dunia, dan saya memanggil hujan lebat untuk membawa keselamatan bagi semua orang...",
  str_homestory_822301001_13_dialog_content = "Dan kemudian setelah itu, kamu membawaku untuk membeli beberapa melon gula...",
  str_homestory_822301001_14_dialog_content = "Kemudian semua orang akan melihat kamu bersamaku, dan membuat patung dari kita berdua!",
  str_homestory_822301001_15_dialog_content = "Itu contoh yang sangat spesifik, hampir seolah-olah itu benar-benar terjadi pada suatu saat...",
  str_homestory_822301001_16_dialog_content = "Atau mungkin suatu musim dingin, aku menyelamatkan tiga puluh delapan orang dari kecelakaan kapal di laut dalam satu kali usaha!",
  str_homestory_822301001_17_dialog_content = "Dan begitu mereka mendarat di pantai, kamu menyalakan api dan menyediakan selimut untuk mereka bertahan dari dingin yang keras...",
  str_homestory_822301001_18_dialog_content = "Mereka akan meletakkan patungmu tepat di samping patungku, dan orang-orang akan menyalakan dupa untuk menghormati kita berdua selama berbagai generasi!",
  str_homestory_822301001_19_dialog_content = "...",
  str_homestory_822301001_20_dialog_content = "Apa masalahnya? Bukankah cerita-cerita ini terdengar menarik bagi kamu?",
  str_homestory_822301001_21_option_content = "Benar.",
  str_homestory_822301001_22_dialog_content = "Tapi mereka juga terdengar sangat sedih.",
  str_homestory_822301001_23_option_content = "Sulit untuk mengatakannya...",
  str_homestory_822301001_24_dialog_content = "Saya merasa itu bukan cara yang baik untuk mempertimbangkan mereka.",
  str_homestory_822301001_25_dialog_content = "Sebagian besar karena mereka bukan hanya cerita, 'kan?",
  str_homestory_822301001_26_dialog_content = "Ketika saya berada di Longzhou, saya melihat begitu banyak patung kamu di berbagai tempat.",
  str_homestory_822301001_27_dialog_content = "Saya bayangkan Anda telah membantu banyak orang di seluruh Longzhou, meninggalkan legenda dan cerita seperti yang baru saja Anda sebutkan.",
  str_homestory_822301001_28_dialog_content = "Mengenai orang-orang dalam ceritamu, seperti orang yang membelikanmu semangka atau orang yang membantumu menyelamatkan orang-orang itu...",
  str_homestory_822301001_29_dialog_content = "Mereka mungkin bukan bagian dari dunia ini lagi... Kamu satu-satunya yang masih tersisa.",
  str_homestory_822301001_30_dialog_content = "Apakah kamu kasihan padaku, PlayerName?",
  str_homestory_822301001_31_dialog_content = "Aku hanya merasa sedih bahwa kamu harus terus mengucapkan selamat tinggal pada orang-orang di sekelilingmu...",
  str_homestory_822301001_32_dialog_content = "Salahkah jika aku merasa begitu terhadap dewi naga?",
  str_homestory_822301001_33_dialog_content = "Sebagai makhluk yang berdarah daging, sangat wajar bagi kamu untuk merasa seperti ini.",
  str_homestory_822301001_34_dialog_content = "Aku juga merasa begitu terhadapmu.",
  str_homestory_822301001_35_dialog_content = "Waktu adalah sesuatu yang tak terukur panjangnya, dan membawa segala sesuatu ke akhirnya.",
  str_homestory_822301001_36_dialog_content = "Meski umurku panjang, keberadaanku hanyalah sekejap mata dibandingkan dengan dunia.",
  str_homestory_822301001_37_dialog_content = "Namun sifat kita yang fana ini lah yang membuat pertemuan kita berharga. Dapat berjalan bersama adalah cara kita merajut takdir kita.",
  str_homestory_822301001_38_dialog_content = "Akan sangat arogan jika saya merasa kasihan pada manusia karena umur mereka yang pendek.",
  str_homestory_822301001_39_dialog_content = "Itu memang masuk akal... Entah kenapa, sekarang rasanya aku jauh lebih baik.",
  str_homestory_822301001_40_dialog_content = "\"Persahabatan tidak takut dengan berlalunya waktu.\" Bukankah itu yang mereka katakan di Longzhou?",
  str_homestory_822301001_41_dialog_content = "Betul sekali! Kamu benar-benar telah belajar banyak akhir-akhir ini.",
  str_homestory_822301001_42_dialog_content = "Waktu bisa jadi kejam, tapi juga memiliki sisi baiknya.",
  str_homestory_822301001_43_dialog_content = "<sprite=emo_qingsong size=60 /> Heehee... Kayaknya aku nggak bisa buang-buang waktu dengan duduk-duduk di satu tempat!",
  str_homestory_822301001_44_dialog_content = "Lagipula, jika bukan karena perjalanan waktu, kita mungkin tidak akan pernah bertemu...",
  str_homestory_822301001_45_dialog_content = "Dan saya tidak akan pernah bisa menghabiskan begitu banyak hari bahagia di sini bersama semua orang.",
  str_homestory_822401001_0_dialog_content = "Luo Song?",
  str_homestory_822401001_1_dialog_content = "Mau menggunakan ini?",
  str_homestory_822401001_2_dialog_content = "Tentu saja! Lagipula, ini dibuat dengan sangat baik!",
  str_homestory_822401001_3_dialog_content = "Akhirnya... Berhasil?",
  str_homestory_822401001_4_dialog_content = "Ya! Lihat saja bagaimana ekspresinya membangkitkan keinginan untuk konfrontasi!",
  str_homestory_822401001_5_dialog_content = "Dan rangkanya juga tidak terlalu keras atau terlalu lembut!",
  str_homestory_822401001_6_dialog_content = "Tidak peduli sekeras apa kamu memukulnya, ia selalu kembali ke posisi semula...",
  str_homestory_822401001_7_dialog_content = "Ini adalah alat latihan yang sempurna untuk tinjuku!",
  str_homestory_822401001_8_option_content = "Aku mengerti.",
  str_homestory_822401001_9_dialog_content = "Aku tahu<sprite=emo_guilian size=60 /> kamu akan mengerti, PlayerName.",
  str_homestory_822401001_10_option_content = "Aku tak begitu paham...",
  str_homestory_822401001_11_dialog_content = "Saya juga tidak bisa menjelaskannya dengan baik <sprite=emo_sikao size=60 />. Mungkin Anda bisa menyebutnya intuisi seorang pejuang?",
  str_homestory_822401001_12_dialog_content = "Selama perjalanan saya di Longzhou, saya memaksakan diri untuk berlatih keras setiap hari.",
  str_homestory_822401001_13_dialog_content = "Membangun kekuatan, meditasi, tinju bayangan, sebut saja.",
  str_homestory_822401001_14_dialog_content = "Bahkan sehari tanpa latihan bisa membuat seseorang berkarat.",
  str_homestory_822401001_15_dialog_content = "Namun, tujuan dari latihan seperti ini adalah untuk memperkuat tubuh seseorang.",
  str_homestory_822401001_16_dialog_content = "Beberapa orang terbawa oleh bagian \"pahit\" dari itu, dan akhirnya melukai diri sendiri sebagai hasilnya.",
  str_homestory_822401001_17_dialog_content = "Dan itu benar-benar mengalahkan tujuannya.",
  str_homestory_822401001_18_dialog_content = "Benar sekali!",
  str_homestory_822401001_19_dialog_content = "Ini seperti beberapa orang yang berulang kali menabrak pohon saat berlatih teknik \"Iron Mountain Lean\".",
  str_homestory_822401001_20_dialog_content = "Karena risiko cedera pribadi yang tinggi, cara berlatih gerakan itu sangat tidak bijaksana.",
  str_homestory_822401001_21_dialog_content = "Begitu rupanya. Semakin banyak yang kamu tahu, ya...",
  str_homestory_822401001_22_dialog_content = "Selama perjalanan saya, saya juga harus menggunakan pohon untuk berlatih karena saya tidak bisa menemukan cara yang lebih baik.",
  str_homestory_822401001_23_dialog_content = "Mungkin karena aku masih muda, tapi aku hampir tidak merasakan sakit atau ketidaknyamanan sama sekali.",
  str_homestory_822401001_24_dialog_content = "Tapi kemudian, aku mulai melatih Ah Ding dan yang lainnya.",
  str_homestory_822401001_25_dialog_content = "Dan saya cepat menyadari bahwa mengikuti rutinitas saya adalah cara mudah bagi mereka untuk terluka.",
  str_homestory_822401001_26_dialog_content = "Saya juga menyadari bahwa metode dan peralatan latihan yang saya gunakan di masa lalu sangat kasar.",
  str_homestory_822401001_27_dialog_content = "Itulah sebabnya saya mulai lebih memperhatikan keselamatan selama latihan, dan termasuk hal-hal seperti perlengkapan pelindung.",
  str_homestory_822401001_28_dialog_content = "Bahkan, saya telah membuat peralatan latihan khusus hanya untuk Ah Ding dan fiendling lainnya...",
  str_homestory_822401001_29_dialog_content = "Butuh banyak waktu dan usaha untuk merancang perlengkapan dengan mempertimbangkan kebutuhan mereka.",
  str_homestory_822401001_30_dialog_content = "Terutama pilar bunga plum itu. Butuh banyak percobaan untuk membuat sesuatu yang cocok dengan kaki-kaki pendek dan kecil mereka!",
  str_homestory_822401001_31_dialog_content = "Kamu adalah pria yang cukup perhatian.",
  str_homestory_822401001_32_dialog_content = "Tentu saja. Lagi pula, aku tidak benar-benar memiliki hobi selain berlatih.",
  str_homestory_822401001_33_dialog_content = "Jadi, secara alami saya akan melakukan yang terbaik untuk pelatihan teman-teman saya juga.",
  str_homestory_822401001_34_dialog_content = "Saat aku punya waktu, pasti akan kubuatkan beberapa desain untukmu juga!",
  str_homestory_822501001_0_dialog_content = "Lentera itu di sana...",
  str_homestory_822501001_1_dialog_content = "Kamu suka dengan lentera halaman itu, Tiare?",
  str_homestory_822501001_2_dialog_content = "Jangan ragu untuk melihat lebih dekat, jika kamu mau.",
  str_homestory_822501001_3_dialog_content = "Ini jarak yang sempurna, sebenarnya.",
  str_homestory_822501001_4_dialog_content = "Ini mengingatkan saya pada beacon di Northland dari sini.",
  str_homestory_822501001_5_dialog_content = "Aku mengerti apa yang kamu katakan, sekarang setelah kamu menyebutkannya.",
  str_homestory_822501001_6_dialog_content = "Sayang sekadar lentera biasa dan tidak mengawasi makhluk di Northland seperti beacon.",
  str_homestory_822501001_7_dialog_content = "...",
  str_homestory_822501001_8_dialog_content = "Dulu, ketika saya masih kecil, saya biasa duduk di puncak pohon cedar dan menonton beacon.",
  str_homestory_822501001_9_dialog_content = "Sungguh terang sekali...",
  str_homestory_822501001_10_dialog_content = "Cahayanya bisa mencapai mana saja, tidak peduli seberapa gelap dan seberapa banyak kabut.",
  str_homestory_822501001_11_dialog_content = "Cahaya menjaga Hutan Snowpine tetap tenang dan diam.",
  str_homestory_822501001_12_dialog_content = "Tidak ada Eclipsite yang berteriak, tidak ada Aurorian yang menjerit... Ketentraman itu tak ternilai.",
  str_homestory_822501001_13_dialog_content = "Hanya kami orang Northland yang memiliki beacon khusus itu.",
  str_homestory_822501001_14_dialog_content = "Aku bisa melihat betapa kalian semua menghargai dan memujanya.",
  str_homestory_822501001_15_dialog_content = "Sebenarnya, yang kita hargai dan hormati bukanlah beacon...",
  str_homestory_822501001_16_dialog_content = "Suatu kali, saya terlalu sibuk mengejar mangsa yang licik sampai saya tidak menyadari seberapa jauh saya telah pergi.",
  str_homestory_822501001_17_dialog_content = "Sampai teriakan Eclipsites mengejutkanku! Saat itu, aku terlalu jauh dari rumah.",
  str_homestory_822501001_18_dialog_content = "Itulah saat aku melihat lampu dari suatu mercusuar.",
  str_homestory_822501001_19_dialog_content = "Bisa masih melihatnya sejauh itu dari rumah?",
  str_homestory_822501001_20_dialog_content = "Tidak, yang saya lihat bukanlah beacon yang melindungi kita.",
  str_homestory_822501001_21_dialog_content = "Tapi sebuah mercusuar biasa di tepi laut.",
  str_homestory_822501001_22_dialog_content = "Ini akan berubah menjadi tempat persembunyian Eclipsite setelah senja.",
  str_homestory_822501001_23_dialog_content = "Astaga!",
  str_homestory_822501001_24_dialog_content = "Saya bersembunyi di hutan, tidak berani bergerak.",
  str_homestory_822501001_25_dialog_content = "Cahaya terus menerus melintas di depanku.",
  str_homestory_822501001_26_dialog_content = "Aku melihatnya sementara Eclipsite bergerak di bawahnya.",
  str_homestory_822501001_27_dialog_content = "Tahu kah kamu apa yang aku sadari saat itu?",
  str_homestory_822501001_28_dialog_content = "Apa?",
  str_homestory_822501001_29_dialog_content = "Mercusuar itu persis sama dengan beacon yang saya hargai dan kagumi.",
  str_homestory_822501001_30_dialog_content = "...",
  str_homestory_822501001_31_dialog_content = "Ini memiliki cahaya yang sama yang bisa menembus malam tergelap dan kabut terpadat...",
  str_homestory_822501001_32_dialog_content = "Namun, itu tidak bisa melindungiku. Sepanjang malam, jika saja aku bergerak sedikit...",
  str_homestory_822501001_33_dialog_content = "Eclipsite pasti akan merobekku menjadi berkeping-keping.",
  str_homestory_822501001_34_dialog_content = "Tiare...",
  str_homestory_822501001_35_dialog_content = "Akhirnya aku mengerti malam itu.",
  str_homestory_822501001_36_dialog_content = "Beacon itu sendiri tidak ada yang istimewa.",
  str_homestory_822501001_37_dialog_content = "Seperti lentera biasa yang kita lihat ini, itu hanyalah bangunan biasa.",
  str_homestory_822501001_38_dialog_content = "Tidak akan ada apa-apa jika tidak ada yang menyalakannya, merawatnya, dan memberikan tekad di baliknya.",
  str_homestory_822501001_39_dialog_content = "Yang selama ini melindungi penduduk Northland bukanlah beacon...",
  str_homestory_822501001_40_dialog_content = "Tapi Queen Bethlehem.",
  str_homestory_822501001_41_dialog_content = "...",
  str_homestory_822501001_42_option_content = "Keteguhan hati Yang Mulia Ratu benar-benar tak tergoyahkan.",
  str_homestory_822501001_43_dialog_content = "Bahkan tanpa Beacon, dia akan melakukan segala yang dia bisa untuk melindungi rakyatnya.",
  str_homestory_822501001_44_option_content = "Itu pasti malam yang penting dalam hidupmu.",
  str_homestory_822501001_45_dialog_content = "Malam itu adalah saat kamu membentuk tekadmu sendiri.",
  str_homestory_822501001_46_dialog_content = "Benar.",
  str_homestory_822501001_47_dialog_content = "Bahkan jika saya tidak bisa menyamai Yang Mulia Ratu, saya akan mengikutinya sampai akhir yang pahit.",
  str_homestory_822501001_48_dialog_content = "Aku telah mengabdikan hidupku untuk membela dan melindungi kaumku, seperti dia.",
  str_homestory_822501001_49_dialog_content = "Itu juga yang saya rasakan.",
  str_homestory_822501001_50_dialog_content = "Terutama bagian tentang \"tidak bisa menyamai Yang Mulia Ratu.\"",
  str_homestory_822501001_51_dialog_content = "Haha, siapa yang bisa menandinginya juga?",
  str_homestory_822501001_52_dialog_content = "Tapi selama dia ada di sana, aku tak akan pernah tersesat.",
  str_homestory_822601001_0_dialog_content = "Eh...",
  str_homestory_822601001_1_dialog_content = "Kamu tidak berpikir bahwa kuda-kudaan ini cukup menarik, Rachel?",
  str_homestory_822601001_2_dialog_content = "Saya tahu ini sedikit kekanak-kanakan, tapi ternyata asyik juga untuk menungganginya.",
  str_homestory_822601001_3_dialog_content = "Ingin mencobanya? Lanjutkan!",
  str_homestory_822601001_4_dialog_content = "Lebih baik tidak...",
  str_homestory_822601001_5_dialog_content = "Tidak peduli apa yang kamu katakan, saya terlalu tua untuk hal-hal seperti ini.",
  str_homestory_822601001_6_dialog_content = "Untukmu, aku tidak tahu kalau kau adalah penggemar besar kuda-kudaan.",
  str_homestory_822601001_7_dialog_content = "A-aku tidak akan menyebut diriku seorang \"penggemar\" mereka atau apapun...",
  str_homestory_822601001_8_dialog_content = "(Aku pikir dia terlalu malu untuk menaikinya, tapi sekarang rahasiaku terbongkar!)",
  str_homestory_822601001_9_dialog_content = "Namun, ini adalah mainan yang cukup baik pembuatannya.",
  str_homestory_822601001_10_dialog_content = "Ketika Anda melihat lebih jauh dari penampilan sederhananya, desain dan kerajinan tangan keduanya sangat luar biasa.",
  str_homestory_822601001_11_dialog_content = "Kombinasi kuat antara ergonomi dan mekanika struktural.",
  str_homestory_822601001_12_dialog_content = "Bahkan aku sedikit terpikat olehnya.",
  str_homestory_822601001_13_dialog_content = "Wow... Aku tidak pernah menyadari semua itu sendiri.",
  str_homestory_822601001_14_dialog_content = "Maksudmu, kamu bisa mengetahui semua hal itu hanya dengan melihat sesuatu?",
  str_homestory_822601001_15_dialog_content = "Ya. Ini adalah keterampilan dasar untuk setiap insinyur.",
  str_homestory_822601001_16_dialog_content = "Kemampuan untuk menggambar representasi tiga dimensi dari suatu objek hanya dengan sekali pandang sangat penting.",
  str_homestory_822601001_17_dialog_content = "Sebenarnya, aku punya ide bagus tentang cara meniru kuda-kudaan ini sekarang.",
  str_homestory_822601001_18_dialog_content = "Itu terdengar seperti kekuatan super bagi saya...",
  str_homestory_822601001_19_dialog_content = "Baiklah, kalau begitu aku serahkan padamu!",
  str_homestory_822601001_20_dialog_content = "Hah?",
  str_homestory_822601001_21_option_content = "Kamu bisa membawanya pulang untuk tujuan penelitian.",
  str_homestory_822601001_22_dialog_content = "Saya mengerti. Kamu ingin saya pergi, jadi saya bisa berhenti mengganggumu, benar?",
  str_homestory_822601001_23_dialog_content = "Sama sekali tidak!",
  str_homestory_822601001_24_option_content = "Sepertinya kamu sangat menyukainya.",
  str_homestory_822601001_25_dialog_content = "Ya, tapi aku lebih suka Colossus-mu daripada apa pun.",
  str_homestory_822601001_26_dialog_content = "Soroz tidak ada di meja!",
  str_homestory_822601001_27_dialog_content = "Heh... Hanya bercanda.",
  str_homestory_822601001_28_dialog_content = "Terima kasih atas tawaranmu, tetapi…",
  str_homestory_822601001_29_dialog_content = "Aku ingin membuat hadiah untuk saudaraku dengan kedua tangan ku sendiri.",
  str_homestory_822601001_30_dialog_content = "... Saudari?",
  str_homestory_822601001_31_dialog_content = "Ya. Saat aku melihat kuda-kudaan ini, aku memutuskan untuk membuat satu yang sama persis untuk adik perempuanku.",
  str_homestory_822601001_32_dialog_content = "Saya tidak pernah memiliki kesempatan untuk bermain dengan mainan seperti ini saat masih kecil, tetapi setidaknya adik saya akan...",
  str_homestory_822601001_33_dialog_content = "Mungkin ini hanya cara saya untuk menebus masa lalu saya sendiri.",
  str_homestory_822601001_34_dialog_content = "Rachel...",
  str_homestory_822601001_35_dialog_content = "Barusan aku sedang serius.",
  str_homestory_822601001_36_dialog_content = "Kuda-kudaan ini... Jauh lebih seru dari yang kamu pikirkan!",
  str_homestory_822601001_37_dialog_content = "H-Hah?",
  str_homestory_822601001_38_dialog_content = "Jadi, coba saja! Kamu tidak bisa membuat replika sempurna untuk sistermu kecuali kamu sudah mencoba yang asli sendiri, bukan?",
  str_homestory_822601001_39_dialog_content = "Ayo, jangan malu!",
  str_homestory_822601001_40_dialog_content = "Uh... Baiklah kalau begitu... Tapi sekali ini saja, ya.",
  str_homestory_822601001_41_dialog_content = "Saya yakin kamu juga akan ketagihan!",
  str_homestory_822701001_0_dialog_content = "Zeta?",
  str_homestory_822701001_1_dialog_content = "Apa sebenarnya ini?",
  str_homestory_822701001_2_dialog_content = "Sayap yang menggemaskan ini, keterampilan ahli ini...",
  str_homestory_822701001_3_dialog_content = "Jika kamu bertanya padaku, ini pasti semacam harta tak ternilai dari masa lalu yang jauh.",
  str_homestory_822701001_4_dialog_content = "Ini adalah Boneka Windelion.",
  str_homestory_822701001_5_dialog_content = "Nah, kalau bukan Caelestite Terakhir! Kamu datang pada waktu yang tepat.",
  str_homestory_822701001_6_dialog_content = "Karena kamu tahu namanya, pasti kamu sangat mengenal ciptaan luar biasa ini.",
  str_homestory_822701001_7_dialog_content = "Ini hanya hiasan untuk Windelion.",
  str_homestory_822701001_8_dialog_content = "Windelion?",
  str_homestory_822701001_9_dialog_content = "Ini adalah hari libur Caelestite. Seseorang pernah memberitahu saya bahwa ini mirip dengan bagaimana Aurorian memperingati para santo mereka dan Dewa Cahaya.",
  str_homestory_822701001_10_dialog_content = "Santo? God of Light? Itu terdengar luar biasa!",
  str_homestory_822701001_11_dialog_content = "Saya tidak tahu dunia ini memiliki liburan yang begitu keren!",
  str_homestory_822701001_12_dialog_content = "Seorang teman saya juga belajar tentang Windelion dari buku.",
  str_homestory_822701001_13_dialog_content = "Bagi kami, kaum Caelestite, ini adalah hari libur yang sangat penting.",
  str_homestory_822701001_14_dialog_content = "Setiap tahun pada Windelion, kami mengucapkan terima kasih kepada alam dengan mengadakan pesta besar.",
  str_homestory_822701001_15_dialog_content = "Oh... Itu tidak terdengar banyak berbeda dari hari libur lainnya.",
  str_homestory_822701001_16_dialog_content = "Ahem... Bagaimanapun, boneka ini hanyalah hiasan lain yang digunakan untuk merayakan Windelion.",
  str_homestory_822701001_17_dialog_content = "Kami mengisi perut boneka dengan permen dan harapan.",
  str_homestory_822701001_18_dialog_content = "Apakah kamu bilang... permen dan harapan?",
  str_homestory_822701001_19_dialog_content = "Ayo lakukan! Saya ingin merayakan Windelion sekarang juga!",
  str_homestory_822701001_20_dialog_content = "Mengapa kamu tiba-tiba begitu bersemangat?",
  str_homestory_822701001_21_dialog_content = "Aku juga ingin membuat Boneka Windelion!",
  str_homestory_822701001_22_option_content = "Kamu juga bisa membuatnya di luar hari libur, tahu kan.",
  str_homestory_822701001_23_dialog_content = "Begitu ya? Kalau begitu, tunjukkan cara membuatnya.",
  str_homestory_822701001_24_option_content = "Tentu, saya tidak melihat alasan mengapa tidak.",
  str_homestory_822701001_25_dialog_content = "Benarkah? Kamu yang terbaik!",
  str_homestory_822701001_26_dialog_content = "Heehee, dan setelah saya selesai, saya akan mengisi perutnya dengan mahakarya terbaru saya...",
  str_homestory_822701001_27_dialog_content = "Ketika semua orang mulai penasaran apa yang ada di dalam...",
  str_homestory_822701001_28_dialog_content = "Duarr! Pop! Whoosh! Banyak asap dan permen akan terbang keluar!",
  str_homestory_822701001_29_dialog_content = "Hah? Kamu tidak akan meletakkan bom di dalamnya, kan?",
  str_homestory_822701001_30_dialog_content = "Ya, saya memang begitu, tapi jangan khawatir! Saya hanya akan menggunakan cukup banyak untuk mengirim permen terbang ke segala arah!",
  str_homestory_822801001_0_dialog_content = "Batia",
  str_homestory_822801001_1_dialog_content = "Akhirnya kamu datang ke luar!",
  str_homestory_822801001_2_dialog_content = "Oh, hai...",
  str_homestory_822801001_3_dialog_content = "Ada yang bisa kubantu?",
  str_homestory_822801001_4_dialog_content = "Tidak, hanya saja kamu terus menghabiskan sepanjang hari di tendamu bermain game.",
  str_homestory_822801001_5_dialog_content = "Aku hampir saja menyuruhmu keluar dan mencari udara segar.",
  str_homestory_822801001_6_dialog_content = "Ah... Fiuh...",
  str_homestory_822801001_7_dialog_content = "Lihat, selesai. Sampai jumpa.",
  str_homestory_822801001_8_dialog_content = "T-Tunggu! Setidaknya kamu harus jalan-jalan sebelum kembali ke dalam, bukan begitu?",
  str_homestory_822801001_9_dialog_content = "Aduh, di luar...",
  str_homestory_822801001_10_dialog_content = "Mengapa kamu sangat membenci keluar rumah, Batia?",
  str_homestory_822801001_11_dialog_content = "Apakah kamu... tidak suka di sekitar sini?",
  str_homestory_822801001_12_dialog_content = "Sama sekali tidak! Bukan berarti aku tidak suka tempat ini atau apa...",
  str_homestory_822801001_13_dialog_content = "S-Sebenarnya, aku lebih suka ini daripada jalan-jalan di Umbraton!",
  str_homestory_822801001_14_dialog_content = "Oh... Jadi selama ini kamu membandingkan tempat ini dengan Umbraton...",
  str_homestory_822801001_15_dialog_content = "M-maaf, aku tidak bermaksud seperti itu!",
  str_homestory_822801001_16_dialog_content = "A-Aku hanya benar-benar familiar dengan jalan-jalan Umbraton...",
  str_homestory_822801001_17_dialog_content = "Yang menjadi alasan lebih untuk mengunjungi tempat-tempat yang berbeda!",
  str_homestory_822801001_18_option_content = "Jadi, kemana kita harus pergi?",
  str_homestory_822801001_19_dialog_content = "Di tepi sungai.",
  str_homestory_822801001_20_dialog_content = "Kita bisa memancing di salah satu sungai terdekat?",
  str_homestory_822801001_21_dialog_content = "Oh, jadi seperti versi nyata dari Fishing Master!",
  str_homestory_822801001_22_dialog_content = "Aku tidak yakin bisa menangkap ikan sungguhan, sih...",
  str_homestory_822801001_23_dialog_content = "Hahaha, baiklah, aturannya sedikit berbeda dari permainanmu.",
  str_homestory_822801001_24_option_content = "Hutan itu.",
  str_homestory_822801001_25_dialog_content = "Ayo berkemah di hutan. Kita bisa menyalakan api unggun, mencari buah-buahan liar, dan memasak di alam bebas!",
  str_homestory_822801001_26_dialog_content = "Oh, itu terdengar seperti game gaya manajemen.",
  str_homestory_822801001_27_dialog_content = "Merencanakan pengembangan kamp kita dan mengikuti berbagai proses crafting untuk memastikan efisiensi maksimal...",
  str_homestory_822801001_28_dialog_content = "Berkemah tidak memiliki poin atau pencapaian, kamu tahu.",
  str_homestory_822801001_29_dialog_content = "Oh, oke. Saya rasa saya bisa mencobanya.",
  str_homestory_822801001_30_dialog_content = "Tapi, bisakah saya setidaknya membawa tenda saya jika kita akan pergi?",
  str_homestory_822801001_31_dialog_content = "Jika kita merasa lelah, kita bisa masuk dan bermain game.",
  str_homestory_822801001_32_dialog_content = "Yah, kurasa tidak ada ruginya.",
  str_homestory_822901001_0_dialog_content = "Lady Victoria, kenapa kau terus menatap kursi gantung itu?",
  str_homestory_822901001_1_dialog_content = "Apakah ada yang salah dengan itu?",
  str_homestory_822901001_2_dialog_content = "Ini hanya mengingatkan saya pada kursi gantung serupa di True Order.",
  str_homestory_822901001_3_dialog_content = "Ini kursi favorit mereka.",
  str_homestory_822901001_4_dialog_content = "Apa yang terjadi?",
  str_homestory_822901001_5_dialog_content = "Delapan dari sepuluh kali saya melewatinya, saya akan melihat Beryl duduk membaca di dalamnya.",
  str_homestory_822901001_6_dialog_content = "Sedangkan dua lainnya, dia tertidur di atas salah satu bukunya.",
  str_homestory_822901001_7_dialog_content = "Maka dia mengambilnya untuk dirinya sendiri!",
  str_homestory_822901001_8_dialog_content = "Terkadang, saya melihat Eicy berputar-putar di sekitarnya.",
  str_homestory_822901001_9_dialog_content = "Dan dia selalu bergumam tentang hal-hal yang kebanyakan orang tidak akan pernah mengerti, seperti...",
  str_homestory_822901001_10_dialog_content = "Ini akan menjadi alat penyiksaan yang sempurna dengan beberapa paku besi ditambahkan ke kursi dan sandaran!",
  str_homestory_822901001_11_dialog_content = "Kamu harus melindungi kursi gantung itu dengan baik sebelum dia mendapatkan tangannya di atasnya... Dan Beryl juga!",
  str_homestory_822901001_12_dialog_content = "Kamu tidak bisa menyalahkan Eicy karena berpikir seperti itu.",
  str_homestory_822901001_13_dialog_content = "Memang terlihat cukup mirip dengan instrumen penyiksaan saat ditutupi dengan darah Nails.",
  str_homestory_822901001_14_dialog_content = "Bahkan Nails?!",
  str_homestory_822901001_15_dialog_content = "Kamu tidak bisa menyalahkan Nails untuk itu. Ini adalah kursi yang sangat nyaman.",
  str_homestory_822901001_16_dialog_content = "Bahkan pertapa kita yang taat pun kadang-kadang ingin duduk di sana.",
  str_homestory_822901001_17_dialog_content = "...",
  str_homestory_822901001_18_dialog_content = "Jadi... Apakah Anda satu-satunya yang belum duduk di atasnya?",
  str_homestory_822901001_19_dialog_content = "Sekarang setelah saya memikirkannya, kamu benar.",
  str_homestory_822901001_20_dialog_content = "Mungkin aku menghindarinya.",
  str_homestory_822901001_21_dialog_content = "Menghindari... sebuah kursi?",
  str_homestory_822901001_22_dialog_content = "Ini berasal dari rumah Varaki tua dan pernah menjadi milik ayahku.",
  str_homestory_822901001_23_dialog_content = "Saya tidak tahu apa yang dipikirkan Faust saat dia membawanya kembali kepadaku.",
  str_homestory_822901001_24_dialog_content = "Melihatnya membuatku teringat akan orang tua saya, masa kecil saya, dan nasib Varaki yang tak berdaya.",
  str_homestory_822901001_25_dialog_content = "Aku... tidak ingin terus mengingat semua itu.",
  str_homestory_822901001_26_dialog_content = "Faust harus belajar bagaimana menjaga tangan mereka untuk diri sendiri.",
  str_homestory_822901001_27_dialog_content = "Mungkin dia mencoba mengingatkan saya bahwa menghadapi takdir adalah bagian dari Truth.",
  str_homestory_822901001_28_dialog_content = "Kursi gantung itu adalah kenangan dari masa kecilmu.",
  str_homestory_822901001_29_dialog_content = "Kenangan-kenangan itu mungkin menyakitkan, tetapi ada kebahagiaan di dalamnya juga, bukan?",
  str_homestory_822901001_30_dialog_content = "Heh, kurasa begitu. Ayah pernah memelukku di pangkuannya sambil membaca di kursi gantung. Itu adalah kenangan yang indah.",
  str_homestory_822901001_31_dialog_content = "Namun, setelah mengalami peristiwa terkini, akhirnya aku paham sekarang.",
  str_homestory_822901001_32_dialog_content = "Rasa sakit masa lalu hanya ada di hatiku.",
  str_homestory_822901001_33_dialog_content = "Jika saya bisa mengatasinya, maka kursi gantung hanyalah kursi gantung.",
  str_homestory_822901001_34_dialog_content = "Seperti yang ditunjukkan oleh kebijaksanaan alamiahmu.",
  str_homestory_822901001_35_dialog_content = "Seharusnya aku tidak menatapnya, aku harus duduk dengan nyaman di atasnya.",
  str_homestory_822901001_36_dialog_content = "Y-Ya! Itulah yang coba saya katakan kepada kamu!",
  str_homestory_822901001_37_dialog_content = "Silakan duduk. Kamu selalu diterima untuk duduk di kursi gantungku.",
  str_homestory_822901001_38_dialog_content = "Terima kasih atas pelayananmu, PlayerName.",
  str_homestory_823001001_0_dialog_content = "Rumah ini terlihat aneh, bukan?",
  str_homestory_823001001_1_dialog_content = "Tapi penampilannya menipu karena sangat nyaman di dalamnya!",
  str_homestory_823001001_2_dialog_content = "Aneh? Sama sekali tidak...",
  str_homestory_823001001_3_dialog_content = "Struktur menara dan penempatan jendelanya membuatnya tampak seperti kastil mini.",
  str_homestory_823001001_4_dialog_content = "Jika Anda mengizinkan, saya ingin berlatih di sini sesekali.",
  str_homestory_823001001_5_dialog_content = "Bukan masalah!",
  str_homestory_823001001_6_dialog_content = "Gunakan tempat ini kapan pun Anda mau.",
  str_homestory_823001001_7_dialog_content = "Sama sekali tidak...",
  str_homestory_823001001_8_dialog_content = "Jika kamu dapat menjamin tidak ada darah yang akan tumpah di sini...",
  str_homestory_823001001_9_dialog_content = "Saya selalu berterima kasih atas kemurahan hati Anda.",
  str_homestory_823001001_10_dialog_content = "Ngomong-ngomong, Pak Wilhelm sedang berlatih secara terpencil di sebuah kastil, kan?",
  str_homestory_823001001_11_dialog_content = "Oh! Y-Ya... Kenapa kamu tiba-tiba membicarakan tentang mentor saya?",
  str_homestory_823001001_12_dialog_content = "Aku hanya berpikir... Apakah kamu ingin berlatih di rumah yang seperti kastil...",
  str_homestory_823001001_13_dialog_content = "Karena pengaruh Mr. Wilhelm?",
  str_homestory_823001001_14_dialog_content = "...",
  str_homestory_823001001_15_dialog_content = "Berbohong adalah dosa. Karena kamu telah melihat niatku, aku hanya bisa mengakuinya.",
  str_homestory_823001001_16_dialog_content = "Saya memang memiliki keinginan kecil untuk... meniru mentor saya.",
  str_homestory_823001001_17_dialog_content = "Meski aku berjanji padanya aku tidak akan melakukannya.",
  str_homestory_823001001_18_dialog_content = "Seorang makhluk sekecil diriku mencoba menjadi seperti mentorku adalah dosa yang mengerikan! Aku...",
  str_homestory_823001001_19_dialog_content = "Itu tidak benar! Bukankah sangat normal memiliki keinginan untuk meniru seseorang yang kamu hormati?",
  str_homestory_823001001_20_dialog_content = "Apa yang telah kau coba tiru?",
  str_homestory_823001001_21_dialog_content = "Aku…",
  str_homestory_823001001_22_dialog_content = "Aku mencoba... memanjangkan rambutku.",
  str_homestory_823001001_23_dialog_content = "...",
  str_homestory_823001001_24_dialog_content = "Tapi rambutku tampaknya tidak cocok untuk itu. Sepasang burung pipit mengira kepala saya adalah sarang mereka...",
  str_homestory_823001001_25_dialog_content = "Ketika aku selesai bertobat, seekor ayam sudah menetas di kepalaku.",
  str_homestory_823001001_26_dialog_content = "Kamu benar-benar bertobat untuk waktu yang lama...",
  str_homestory_823001001_27_dialog_content = "Setelah memotong rambut saya, saya mencoba untuk tetap terjaga dan membaca sepanjang malam seperti mentor saya.",
  str_homestory_823001001_28_dialog_content = "Tapi aku tertidur saat berjalan dan terguling di tangga...",
  str_homestory_823001001_29_dialog_content = "Hei, hei!",
  str_homestory_823001001_30_dialog_content = "Pedang mentor saya, Crimson Flow, sangatlah keren.",
  str_homestory_823001001_31_dialog_content = "Tapi mentor saya menghentikan saya ketika saya mencoba meniru Aliran Merah dengan darah saya sendiri.",
  str_homestory_823001001_32_dialog_content = "Oh! Dia pasti sudah menyuruhmu untuk menjadi dirimu sendiri, 'kan?",
  str_homestory_823001001_33_dialog_content = "Mentorku bertanya padaku dengan lembut, \"Nails, lihat ke atas dan katakan padaku apa yang kamu lihat.\"",
  str_homestory_823001001_34_dialog_content = "Aku menjawab, \"Langit, Mentor. Tuhan Kebenaran sedang mengawasi kita dari sana.\"",
  str_homestory_823001001_35_dialog_content = "Mentorku bertanya, \"Apakah kamu tahu mengapa kita bisa melihat langit?\"",
  str_homestory_823001001_36_dialog_content = "Aku menjawab, \"Karena Tuhan yang menciptakannya.\"",
  str_homestory_823001001_37_dialog_content = "Mentorku berkata, \"Itu karena Crimson Flow-mu baru saja memotong atap kita.\"",
  str_homestory_823001001_38_dialog_content = "...",
  str_homestory_823001001_39_dialog_content = "Aku sangat menyesali dosa-dosaku.",
  str_homestory_823001001_40_dialog_content = "Kemudian saya menyadari bahwa saya belum mempelajari hal yang paling berharga dari mentor saya.",
  str_homestory_823001001_41_dialog_content = "Mentor saya tidak pernah menyimpang dari keyakinannya.",
  str_homestory_823001001_42_dialog_content = "Dan aku harus melakukan hal yang sama. Aku harus hidup seperti saat aku dilahirkan.",
  str_homestory_823001001_43_dialog_content = "Jika kamu bisa mencapai kesimpulan itu dari rentetan bencana... maksudku insiden...",
  str_homestory_823001001_44_dialog_content = "Kamu pasti sangat peka.",
  str_homestory_823001001_45_dialog_content = "Terima kasih atas kata-kata baikmu, PlayerName.",
  str_homestory_823001001_46_dialog_content = "Sebagai balasannya, aku selalu senang mendengarkan pengakuanmu di istana kecil ini.",
  str_homestory_823001001_47_dialog_content = "Ahem, ayo lakukan setelah aku mengerti!",
  str_homestory_823101001_0_dialog_content = "Pak Wilhelm, kenapa kamu menatap paviliun itu? Tidak ada apa-apa di sana.",
  str_homestory_823101001_1_dialog_content = "Aku bertanya-tanya apakah paviliun milikmu ini memiliki teka-teki yang terpendam di bawahnya.",
  str_homestory_823101001_2_dialog_content = "Sebuah teka-teki? S-Serius...? Apa yang membuatmu berpikir begitu?",
  str_homestory_823101001_3_dialog_content = "Sebuah paviliun terpencil di hutan belantara memiliki afinitas alami dengan petualangan dan teka-teki.",
  str_homestory_823101001_4_dialog_content = "Hal-hal serupa telah terjadi dalam banyak legenda.",
  str_homestory_823101001_5_dialog_content = "Terinspirasi oleh ini, aku pernah mengajukan sebuah pertanyaan kepada Victoria.",
  str_homestory_823101001_6_dialog_content = "D-Di paviliun?",
  str_homestory_823101001_7_dialog_content = "Aku mulai dengan cara mengganggunya...",
  str_homestory_823101001_8_dialog_content = "Kenapa kamu ingin melakukan itu?!",
  str_homestory_823101001_9_dialog_content = "Ini adalah tugas yang mudah karena dia selalu memiliki rasa permusuhan terhadapku.",
  str_homestory_823101001_10_dialog_content = "Tapi dari cara dia berteriak \"Pergi ke neraka! Iblis!\" dan lari dengan mata yang merah...",
  str_homestory_823101001_11_dialog_content = "Mungkin saya telah melangkah terlalu jauh.",
  str_homestory_823101001_12_dialog_content = "Lady Victoria sangat... enerjik waktu itu, ya?",
  str_homestory_823101001_13_dialog_content = "Setelah itu, saya sengaja meninggalkan berbagai macam petunjuk untuk membuatnya berpikir bahwa Varaki memiliki harta karun leluhur.",
  str_homestory_823101001_14_dialog_content = "Dan jika dia menemukannya, dia bisa menggulingkan saya dan merebut kembali posisi kepala keluarga.",
  str_homestory_823101001_15_dialog_content = "Hubunganmu sangat rumit...",
  str_homestory_823101001_16_dialog_content = "Dia tidak mengecewakan. Dia berhasil menguraikan petunjuk dan sampai pada kesimpulan yang benar.",
  str_homestory_823101001_17_dialog_content = "Lokasi harta karun leluhur ditulis di paviliun yang terletak jauh di dalam taman.",
  str_homestory_823101001_18_dialog_content = "Terus bagaimana?",
  str_homestory_823101001_19_dialog_content = "Tentu saja, menemukan paviliun bukanlah akhir dari semuanya.",
  str_homestory_823101001_20_dialog_content = "Dia harus memecahkan teka-teki yang terukir pada lempengan batu paviliun dan mengungkap lokasi sebenarnya dari harta karun itu.",
  str_homestory_823101001_21_dialog_content = "Saya harus menyebutkan bahwa penuaan buatan saya pada lempengan batu itu sempurna.",
  str_homestory_823101001_22_dialog_content = "...",
  str_homestory_823101001_23_dialog_content = "Jadi... Apakah kamu yang membuat teka-teki tersebut? Apa saja itu?",
  str_homestory_823101001_24_dialog_content = "Mereka bukan apa-apa. Hanya beberapa pertanyaan pengetahuan umum tentang sejarah, mitos dan dongeng, serta beberapa soal matematika.",
  str_homestory_823101001_25_dialog_content = "Dia hanya perlu belajar selama seminggu untuk melalui semuanya dengan mudah.",
  str_homestory_823101001_26_dialog_content = "Aku punya perasaan itu tidak berakhir dengan baik...",
  str_homestory_823101001_27_dialog_content = "Tergantung cara kamu melihatnya. Dia berhasil, seperti yang aku pikirkan dia akan lakukan.",
  str_homestory_823101001_28_dialog_content = "Tapi aku benar-benar tidak bisa memahami kenapa dia begitu marah setelah menemukan harta itu...",
  str_homestory_823101001_29_dialog_content = "Biarkan aku bertanya sekarang. Apa yang kau kubur sebagai harta karun?",
  str_homestory_823101001_30_dialog_content = "Madu favorit Victoria. Sebotol penuh yang baru saja dipanen tahun itu.",
  str_homestory_823101001_31_dialog_content = "Itu dia?!",
  str_homestory_823101001_32_dialog_content = "Bukankah itu sudah cukup? Jelas tertulis dalam \"Cara Menghadapi Gadis Remaja yang Pemberontak\"—",
  str_homestory_823101001_33_dialog_content = "\"Siapkan sesuatu yang dia suka. Kamu tidak akan pernah salah dengan hal-hal manis.\"",
  str_homestory_823101001_34_dialog_content = "Aku benar-benar tidak mengerti apa masalahnya.",
  str_homestory_823101001_35_dialog_content = "Mengapa kamu tidak langsung memberikannya madu?!",
  str_homestory_823101001_36_dialog_content = "Ingat bagaimana dia bersikap bermusuhan padaku?",
  str_homestory_823101001_37_dialog_content = "Menghasut satu sama lain tidak terlalu membosankan, tapi sungguh melelahkan.",
  str_homestory_823101001_38_dialog_content = "Jadi, aku tidak keberatan mengalihkan perhatiannya dengan hal lain.",
  str_homestory_823101001_39_dialog_content = "Dia menghabiskan seminggu memeras pikirannya dan mempelajari sejarah, dongeng, dan matematika sambil penuh antisipasi...",
  str_homestory_823101001_40_dialog_content = "Namun pada akhirnya, yang dia temukan hanyalah sebotol madu baru. Itu tidak berbeda dengan kamu yang mengejeknya karena telah tertipu...",
  str_homestory_823101001_41_dialog_content = "Apakah kamu masih tidak mengerti kenapa dia marah?",
  str_homestory_823101001_42_dialog_content = "Kau benar.",
  str_homestory_823101001_43_dialog_content = "Tapi, itu bukan alasan untuk menuangkan madu di kursiku sebelum pertemuan kepala keluarga...",
  str_homestory_823101001_44_dialog_content = "Saya tidak punya pilihan selain duduk di atas madu dan berpura-pura seolah-olah tidak ada yang salah selama pertemuan berlangsung!",
  str_homestory_823101001_45_dialog_content = "Bagaimana menurutmu?",
  str_homestory_823101001_46_dialog_content = "Kamu layak mendapatkannya.",
  str_homestory_823101001_47_dialog_content = "Kamu mendapatkan apa yang pantas kamu dapatkan.",
  str_homestory_823101001_48_dialog_content = "Ck..."
}
return config
